INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4a8e9c73-edfe-4eb8-96d5-f010ea31bc95', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'How do you perform a full-text search in Elasticsearch?', N'Junior', N'You use a query, such as the match query, which evaluates the relevance of documents based on the provided search terms. Elasticsearch analyzes the query string and matches it against the inverted index to return the most relevant documents based on scoring algorithms.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'35c6fe52-f2bf-4256-a83f-f011e24bd801', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'Explain the role of the ''Config Servers'' in a sharded cluster architecture.', N'Senior', N'Config servers store the cluster''s metadata, including shard key ranges and the mapping of data to specific shards. Without the config servers, the mongos instances cannot route queries correctly, making them a single point of failure that must be deployed as a high-availability replica set.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6ddbf7c3-97ae-474d-b8bf-f0122d00118d', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'How does Lit facilitate communication between parent and child components?', N'Middle', N'Parent-to-child communication is handled via properties passed down through attributes or DOM properties. Child-to-parent communication is typically achieved by dispatching standard DOM events, which allows for decoupled architecture and adheres to native browser event bubbling mechanisms.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9002954a-872b-4b1f-a719-f012cbcf685f', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'Does Qwik support traditional client-side routing?', N'Middle', N'Yes, Qwik includes a built-in router that supports both server-side and client-side navigation. It integrates with the resumability model to prefetch data and code for upcoming routes, ensuring a seamless user experience during transitions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2ba39bed-375e-4d3d-a2a1-f012e4591d33', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'How do you approach the trade-off between synchronous and asynchronous communication in a system?', N'Middle', N'Synchronous communication is easier to reason about and provides immediate feedback, but it creates tight coupling and potential bottlenecks if one service is slow. Asynchronous communication via message queues improves system decoupling and fault tolerance, but it adds complexity in error handling, monitoring, and debugging distributed state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cd1a4026-709b-4f9b-9ed2-f01421739c92', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'How do you handle a production incident where logs are insufficient or missing?', N'Middle', N'I would leverage existing observability signals like metric dashboards and distributed tracing to infer the state of the system during the incident. If possible, I would enable dynamic logging or increase log verbosity for the affected components in real-time if the platform allows. Simultaneously, I would perform a comparative analysis between the last known good state and the current configuration or deployment metadata to identify recent changes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'422a209b-36b7-4b93-8ce2-f0157a26c22f', N'a000805c-e41f-42a9-af12-66b45348f77b', N'What is AdonisJS and how is it classified?', N'Fresher', N'AdonisJS is a Node.js web framework that follows the Model-View-Controller (MVC) architectural pattern. It is designed to be a complete, opinionated framework that provides all the necessary tools out of the box to build scalable web applications.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'05d9f4c0-3cf5-4479-8646-f0167b45aea8', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What is a Conditional Type and what is its use case?', N'Middle', N'A conditional type acts like a ternary operator for types, choosing between two possible types based on a condition. It is primarily used to create complex, reusable utility types that adapt their output based on the input type provided.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'57906a68-25d8-4577-95f7-f01be022fd4d', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'How do you handle graceful shutdowns in an Express server to ensure active requests are completed?', N'Senior', N'To perform a graceful shutdown, you must stop accepting new connections using the server''s close method while allowing existing connections to finish their current cycles. This usually involves listening for termination signals, notifying the load balancer to stop sending traffic, and waiting for active requests to drain before exiting the process.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'be59c110-1cd1-487b-a971-f01c05f425d4', N'fcd5873e-c89a-47d6-bb4c-c60b57c2ede1', N'What is the difference between monolithic and microservices architecture?', N'Middle', N'A monolithic architecture is built as a single, unified unit, which is simpler to develop initially but becomes difficult to scale and maintain as it grows. Microservices break the application into small, independent, and loosely coupled services, facilitating independent scaling and deployment at the cost of increased operational complexity.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'906a9b59-68d0-4d66-8bda-f01ef78fc5d1', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'How does Axum facilitate graceful shutdown of a server process?', N'Senior', N'Axum integrates with tokio signals, allowing developers to listen for system signals like SIGINT or SIGTERM. By orchestrating a shutdown trigger, the application can stop accepting new connections while allowing existing in-flight requests to complete, ensuring data consistency and preventing disruption to clients.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f8eca377-a9cf-45b9-8137-f021b25fbaf3', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'What is the purpose of the ''Router'' in Axum?', N'Intern', N'The Router is the core component used to define the API surface of an application. It maps HTTP paths and methods, such as GET or POST, to specific handler functions that process the incoming requests.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f649427a-2abf-4f4d-80f0-f022e08f9e51', N'f2e963ff-7635-4429-a389-4d92535fb972', N'How does the browser handle invalid HTML structure during the parsing phase?', N'Senior', N'Browsers use a complex error-handling algorithm defined in the HTML specification to auto-correct malformed markup. While this allows pages to render despite errors, relying on it leads to unpredictable rendering across different browsers, as each engine may interpret the correction slightly differently.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b8a46de3-3eca-447e-b439-f0243660ab63', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'How does Spring Boot resolve the ''Fat JAR'' classloading issue?', N'Senior', N'Spring Boot uses a custom ClassLoader called JarLauncher that understands how to load nested JARs inside the main archive. This allows the application to run as a single executable file while maintaining a clear separation of internal and external dependencies.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4eadf652-48f0-44db-a71d-f02594ff9f3d', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'What is the purpose of the ''ShouldBind'' method in Gin?', N'Intern', N'The ''ShouldBind'' method is used to map request data into a struct while returning an error if the binding fails. This allows the developer to handle validation errors gracefully rather than immediately terminating the request.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1b71f0dc-8f8f-41a0-b598-f0259721467c', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'How would you explain the purpose of a database index to a non-technical stakeholder?', N'Fresher', N'An index is like the index at the back of a textbook that lets you find specific information without reading every single page. In a database, it allows the system to quickly locate specific rows of data instead of scanning the entire table. This significantly speeds up search operations at the cost of requiring more storage space.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'89f6fc66-fdff-40fa-a065-f02923c4343e', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'How does Hono''s design handle the limitations of the Event Loop in single-threaded runtimes?', N'Senior', N'Hono is designed to be non-blocking, ensuring that all I/O operations are handled asynchronously via Promises. By avoiding CPU-intensive synchronous operations within the request cycle, it prevents the event loop from stalling under heavy concurrency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c1bf410a-6b17-481b-a346-f0295727948e', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'How does NestJS manage circular dependencies, and what is the recommended architectural approach to resolve them?', N'Senior', N'NestJS provides a ''forwardRef'' utility to resolve circular dependencies by deferring the resolution of a provider until it is needed. The architectural recommendation is to refactor the code to extract shared logic into a third module or service, as circular dependencies are often a symptom of poor domain boundary definition.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'64ee86f4-4553-4c96-a97b-f02ce98be687', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'Why is ''hidden class'' optimization critical for high-performance JavaScript?', N'Senior', N'Engines like V8 create hidden classes to track object shapes and property offsets. If an object''s structure changes dynamically by adding or deleting properties after initialization, the engine must transition to a new hidden class, which can invalidate previous optimizations and slow down access times.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8e0ca10f-31f5-44c6-a5cf-f02dadd35e09', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'What is the purpose of the ''native-image'' build process?', N'Intern', N'The native-image build process is the stage where GraalVM analyzes the application code to remove unused classes and methods. This optimization significantly reduces the final size of the executable and improves runtime performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd973423c-9009-45b5-8f57-f0347265df21', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'How do blocks, procs, and lambdas interact with the ''yield'' keyword?', N'Middle', N'The ''yield'' keyword is used within a method to invoke a block that was implicitly passed to it. Procs and lambdas are explicit objects that can be stored and passed around as arguments, whereas blocks are temporary, anonymous pieces of code. While ''yield'' only works with implicit blocks, Procs and lambdas can be invoked using the ''call'' method.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
