INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'86d5d8d1-f8a1-4849-9267-f03f8ad5b3b7', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'What does the term ''schema'' mean in database design?', N'Intern', N'A schema is the blueprint or formal structure that defines how data is organized and related within a database. It describes the tables, fields, data types, and the constraints applied to the data. In relational databases, the schema is usually fixed before data is stored.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
