INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd8f2f690-0bd5-44fe-8be9-f045670662ab', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'What are the trade-offs of using Native Image compilation versus running on a standard JVM?', N'Senior', N'Native images offer superior startup speed and lower memory usage but require longer build times and lack support for some dynamic Java features like aggressive reflection or dynamic class loading. Standard JVMs provide better peak throughput and mature JIT optimization, making them preferable for long-running, compute-intensive workloads.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5e9b55fd-7661-4f86-b056-f04868146e0a', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'How does SolidJS ensure SSR performance is superior to traditional frameworks?', N'Senior', N'SolidJS SSR streams HTML directly from the server as it is generated, without needing to perform a full virtual DOM render on the server. This reduces server-side memory consumption and time-to-first-byte, as the server treats the component as a series of string concatenations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9f81588f-6242-42a0-8997-f049264ff501', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'Describe the benefits and drawbacks of Multi-Datacenter replication.', N'Senior', N'Multi-DC replication provides disaster recovery and allows local reads/writes for global users, reducing latency significantly. However, it increases the complexity of managing consistency and requires careful configuration of replication factors to ensure data availability during regional outages.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'88ea6eed-6194-46c9-b173-f04a864559a6', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'What is the benefit of using Server Actions for form submissions?', N'Middle', N'Server Actions allow you to define server-side logic that can be invoked directly from your components without needing a separate API route. This simplifies the data mutation flow and provides a type-safe way to handle form data and database updates.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2fe5b1de-8341-40bf-96ba-f04ae8806c55', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'How does Litestar manage state across different components of the application?', N'Senior', N'Litestar uses a structured State object that can be passed through the application, allowing for safe sharing of configuration, database engines, or common utilities. This approach prevents global variable usage and makes the application state explicit and traceable throughout the request lifecycle.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ca43d1e9-8118-401f-95a6-f04c26bac1b7', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'Why is Rocket considered ''type-safe'' for web development?', N'Junior', N'It is type-safe because it uses Rust''s compiler to verify that your routes, parameters, and return types match the definitions provided in your code. This prevents common bugs like passing an incorrect variable type or returning an unsupported response format.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'975ccfc6-4e65-4f27-ac3b-f0507f78e141', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'What is the primary difference between Preact''s ''h'' function and React''s ''createElement'' in terms of overhead?', N'Senior', N'Preact''s ''h'' function is designed to be a direct, minimal mapper to the virtual DOM structure without the complex validation or prop-normalization layers found in React. This design minimizes CPU cycles during the creation of virtual node objects, resulting in faster render cycles.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a9e4fce8-d7c1-45e6-84c2-f05318263551', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'Describe the mechanism Micronaut uses to implement Aspect-Oriented Programming (AOP) without dynamic proxies.', N'Senior', N'Micronaut uses compile-time transformation to generate interceptor classes that wrap bean methods. By generating these wrappers at build time, the framework avoids the performance cost of reflection-based dynamic proxies typically found in runtime-heavy frameworks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'28b1d9a8-bea1-43dd-b093-f0579fc873bd', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'What is a graph database primarily used for?', N'Intern', N'Graph databases are designed to store and navigate relationships between data entities. They use nodes to represent entities and edges to represent the connections between them, making them ideal for social networks or recommendation engines.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
