INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b4e00e83-65e0-4b6c-816c-f0630ab15d8e', N'9a0e3785-3b73-4abc-ab01-df75bf097dff', N'What is Service Discovery and why is it necessary in a dynamic microservices environment?', N'Middle', N'In microservices, instances are ephemeral and their IP addresses change frequently due to scaling or failure. A service discovery mechanism, like Consul or Eureka, maintains a real-time registry of active service instances so that other services can dynamically locate them without hardcoding endpoints.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
