INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6fabd31e-210f-4739-8cca-f074e08c6e3c', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'How do you approach the trade-off between strict interface design and flexibility?', N'Fresher', N'Strict interfaces enforce clear contracts and reduce integration errors, making the system easier to test and use by others. Overly flexible interfaces can be easier to implement initially but often lead to ambiguous behavior and ''spaghetti'' code that is difficult to support later.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4866952d-80c8-48e1-906c-f075af494e40', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'What is the purpose of the ''key'' block in Svelte?', N'Fresher', N'The key block is used to tell Svelte to re-render a component or a piece of DOM whenever the value of a specific key changes. It is useful for resetting the state of a component when its data inputs change significantly.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'41d1d84a-b4e4-42ad-85be-f079ae765a6c', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'Why is it important to disable swap on nodes running Elasticsearch?', N'Senior', N'If the operating system swaps parts of the JVM heap to disk, it causes massive latency spikes that can trigger false negatives in node health checks. Since Elasticsearch is designed to manage its own memory efficiency, relying on OS-level swapping leads to unpredictable performance degradation and potential cluster instability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5edc3c13-97ad-49a5-81a6-f080aa0d9578', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'What architectural benefits does Rocket''s ''Responder'' trait provide?', N'Senior', N'The Responder trait allows any type to be returned from a handler as long as it can be converted into an HTTP response. This promotes high levels of code reusability and clean architectural separation, as business logic types can be transformed into diverse response formats like JSON, HTML, or raw bytes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
