INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1bee410e-6b56-426e-88e1-f083ed91d9c8', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'How do you implement rate limiting in a Chi environment?', N'Senior', N'Rate limiting is typically implemented as a middleware that wraps the Mux or specific groups. By using a token bucket or fixed-window algorithm in the middleware, you can inspect request headers or client IPs to decide whether to proceed or return a 429 status code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b234204b-ed52-4f15-ba0b-f085e598c900', N'8d34dfc0-4a64-4128-b41a-cafa62ddad41', N'How do you securely handle user passwords in a database?', N'Middle', N'Passwords should never be stored in plain text; they must be hashed using a slow, cryptographically secure algorithm like Argon2 or bcrypt. Additionally, a unique salt should be added to each password before hashing to protect against rainbow table attacks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'89c6e20a-5b82-4e41-974b-f08798aa004c', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'How can you effectively manage shared state in a multi-instance NestJS deployment?', N'Senior', N'Shared state should be moved out of the NestJS application memory and into an external, distributed store like Redis or a database. Managing state within the application memory in a multi-instance setup leads to inconsistency and prevents horizontal scaling.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1d9fe945-3c85-4068-a800-f089ace6b9f2', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'How does Express handle large numbers of concurrent connections in terms of resource consumption?', N'Senior', N'Express relies on Node.js''s underlying libuv and non-blocking I/O to handle thousands of concurrent connections. However, since it is single-threaded, each request must be lightweight; heavy processing or blocking calls will cause the event loop to lag, reducing the effective concurrency capacity of the server.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9e37d67e-a4f6-4257-bbca-f089b46e520f', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'What is the benefit of using Chi''s context-based routing?', N'Fresher', N'By using the Go context package, Chi allows developers to pass request-scoped values through the handler chain. This is useful for storing metadata like user authentication information or request IDs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1e4d7cc9-c7cb-449e-b1a8-f08e3d5971b4', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'What is the purpose of implementing rate limiting on a public API?', N'Junior', N'Rate limiting protects your infrastructure from being overwhelmed by too many requests, whether from malicious attackers or malfunctioning clients. It ensures fair usage among all users and maintains the stability and availability of the service.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e57d1f6c-d855-4256-b099-f08e76bfcda4', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'What is the difference between a GET and POST request?', N'Junior', N'GET requests send data as part of the URL, making them visible and bookmarkable but less secure for sensitive data. POST requests send data in the body of the HTTP request, which is more secure and supports larger amounts of data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a7816111-bffe-4cfb-894e-f095d1b6cf32', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'You are tasked with fixing a bug, but you cannot reproduce it consistently. What steps should you take to narrow down the cause?', N'Fresher', N'I would begin by gathering as much context as possible, such as specific user actions, timestamps, and the state of the application leading up to the issue. I would then systematically attempt to trigger the bug by varying inputs, sequence of operations, and environmental conditions to find a pattern. Documenting these attempts helps determine if the issue is tied to specific edge cases, timing dependencies, or intermittent system state changes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a53c460d-a220-407c-a733-f09687099f76', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'What is the primary architectural benefit of Litestar''s dependency injection system compared to traditional middleware?', N'Middle', N'Litestar''s dependency injection allows for type-safe, scoped dependencies that are resolved at the route level. This reduces boilerplate code and improves testability by allowing dependencies to be easily mocked without modifying the route handler logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'05088fe2-52b7-4db4-87b9-f0980d216800', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'Describe the internal mechanism of InnoDB''s Doublewrite Buffer and its role in crash recovery.', N'Senior', N'The Doublewrite Buffer protects against partial page writes caused by power failure or OS crashes. Before writing a page to the actual data file, InnoDB writes it to a contiguous area on disk; if a crash occurs, the original page can be reconstructed from this stable copy during recovery.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
