INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'64f587d5-cda1-4280-b67d-f0a28651138d', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'What is the purpose of the Unit type in Kotlin?', N'Intern', N'While some languages use "void" to indicate functions or expressions with no useful return value, Kotlin leverages the Unit type. Why Kotlin Introduced ''Unit'' The driving principle behind introducing the Unit type was to provide a unified approach to functions across the object-oriented and functional programming paradigms. Key Characteristics of Unit - Singleton Element: Unit is a singleton, meaning there''s only one instance of it. This allows functions with no explicit return to be understood as returning a single, distinct value. - Immutable State: As a singleton, Unit is inherently immutable, ensuring that every function call returning Unit produces the same fixed value. Use Cases 1.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
