INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ee19426b-aa05-44c7-ba17-f0ab735b6a42', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'How does Ruby''s Method Lookup Path (MRO) function when dealing with multiple included modules and class inheritance?', N'Senior', N'Ruby uses a linear inheritance chain where modules are inserted into the ancestor chain. When a module is included, it is placed immediately above the class in the chain, and subsequent inclusions move previous modules further up. This ensures a predictable, flat hierarchy that avoids the diamond problem inherent in languages with multiple inheritance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ece43c32-b016-43b0-a75f-f0b14f9796c9', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'What is the ''context'' in a Fastify plugin?', N'Intern', N'The context refers to the specific instance of the Fastify server within a plugin where you can register routes or add decorations. Each plugin receives its own encapsulated instance, allowing for safe development without interfering with other parts of the application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e0ae4e99-6484-4ff9-91c9-f0b1e9691c95', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'How does Django’s ORM handle database-level constraints versus application-level validation?', N'Senior', N'Database-level constraints ensure data integrity at the storage layer, protecting the data from corruption regardless of the application state. Application-level validation in Django forms and serializers provides a user-friendly feedback mechanism but does not guarantee absolute data integrity on its own.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c6b4ef37-925e-4ee2-941a-f0b2811c6ab0', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'What is a distributed search?', N'Intern', N'A distributed search is an operation where a query is sent to a coordinating node, which then broadcasts the request to all nodes containing relevant shards. The results are collected, merged, and returned to the client as a single response.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9d41200c-3afe-4799-9b37-f0b36399382d', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'How does FastAPI handle path parameters vs. query parameters?', N'Middle', N'Path parameters are defined as part of the URL path string and are marked as required, while query parameters are appended to the URL and can be optional or have default values. FastAPI automatically infers the location of these parameters based on their presence in the path string versus function arguments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0e57f0f3-95d5-46b0-890d-f0b389218a58', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'What is the advantage of using ''virtual modules'' in a Vite plugin?', N'Senior', N'Virtual modules allow plugins to generate code dynamically that does not exist as a physical file on disk. This is useful for injecting configuration, environment data, or generated boilerplate into the bundle without cluttering the project structure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'66d29d1a-f5c5-4fa9-8bc0-f0b7ab10bca5', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'How does Micronaut simplify the implementation of distributed tracing?', N'Senior', N'Micronaut provides seamless integration with tracing libraries like Zipkin or Jaeger via built-in instrumentation. It automatically intercepts outgoing and incoming requests to propagate span and trace IDs, ensuring visibility across microservice boundaries without manual overhead.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'40b2fb01-81e8-41fd-82f4-f0b7d9cdc2b3', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'What is the purpose of ''speculative retry'' in read requests?', N'Senior', N'Speculative retry allows the coordinator to send a redundant read request to an additional replica if the original replicas do not respond within a configured threshold. This helps mitigate latency spikes caused by slow or overloaded nodes, improving the tail latency of the system.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3ed9fb86-b091-4cc4-8d5d-f0b9bab66bbf', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'How does Preact handle component lifecycle updates compared to React''s Fiber reconciler?', N'Senior', N'Preact uses a synchronous, recursive reconciliation process that is generally faster for standard UI updates but lacks the interruption capabilities of React''s Fiber reconciler. This means that while Preact is more efficient for typical web tasks, it cannot pause rendering work to prioritize high-priority user interactions as effectively as React.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'68692413-7623-4824-8ff3-f0bfd8f51dc2', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'What is the best way to manage dependencies and versioning for a Flask application?', N'Middle', N'The best practice is to use a virtual environment to isolate dependencies and a requirements file or a lock file system to pin exact versions of all packages. This ensures that the application behaves identically in development, staging, and production environments, preventing issues caused by dependency drift.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a7b7a3b8-4a46-4c27-9a50-f0c1232251a7', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'Why is synchronization often simpler in fiber-based systems compared to multi-threaded systems?', N'Middle', N'Because fibers only yield control at defined points, you can often avoid complex synchronization primitives like mutexes for logic that happens between yield points. This reduces the risk of data races and deadlocks since the execution flow is more predictable within a single scheduler loop.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'49c86ad0-513d-4453-8f9c-f0c14d809d71', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'What should you do if you accidentally commit sensitive data to a repository?', N'Junior', N'Notify the security team immediately and rotate the compromised credentials, such as API keys or passwords. Then, follow the team''s procedure for removing the sensitive data from the version control history, ensuring it is permanently purged.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4a8a0875-2420-4da3-89d1-f0caaf1ba568', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'What is the purpose of the ''TracePoint'' API in the Ruby VM, and how is it used in tooling?', N'Senior', N'TracePoint provides hooks into the VM''s internal events, such as method calls, line execution, and class creation. It is the architectural foundation for profilers, debuggers, and coverage tools, allowing external code to monitor VM internals without requiring modifications to the source code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9e4da668-6d5a-46fe-80c9-f0cafda65861', N'91fb4eff-ac6a-48b9-8ba4-2bbdf6237429', N'How does ''Backpressure'' contribute to system reliability?', N'Senior', N'Backpressure is a feedback mechanism where a system component signals its inability to handle incoming load, forcing upstream services to throttle their request rate. This prevents internal buffers from overflowing and avoids cascading failures caused by resource exhaustion like memory leaks or thread pool saturation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
