INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5e85ca36-d5e9-422b-9905-f0ccba78ae4a', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'What is the difference between a struct and a class in Swift?', N'Intern', N'Structs are value types, meaning they are copied when assigned to a new variable, while classes are reference types, meaning they point to the same instance in memory. Structs do not support inheritance, whereas classes do.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'67ee108c-350e-43b5-a520-f0ccc55c96c2', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is the importance of ''Object.freeze'' vs ''Object.seal''?', N'Senior', N'Object.seal prevents new properties from being added and marks existing properties as non-configurable, but values can still be changed. Object.freeze goes further by making all properties non-writable, effectively creating an immutable object.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
