INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'176c2969-a0c9-476c-bbb1-f0ce75d9576d', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'What is a session in PHP?', N'Intern', N'A session is a way to store information to be used across multiple pages for a specific user. It works by creating a unique ID for each visitor and storing data on the server, which prevents the need to pass data through URLs or forms.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'229f6bd1-722c-4465-9dec-f0d284f5270f', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'You have a microservice that is experiencing high latency due to a downstream dependency. How do you mitigate this?', N'Middle', N'I would implement the circuit breaker pattern to stop requests from reaching the failing service, preventing resource exhaustion in the calling service. Additionally, I would introduce a fallback mechanism, such as serving cached data or a default response, to maintain partial system availability while the dependency recovers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ec8572a0-e95e-468c-887d-f0d2d7196d68', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'How do you handle API requests in Next.js?', N'Fresher', N'Next.js allows you to create API routes or Route Handlers that run on the server. These act as backend endpoints where you can handle requests, interact with databases, and return data to your frontend components.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'91b4267b-c187-4acb-acd4-f0d494bea872', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'What are the trade-offs of using jQuery UI versus modern web components?', N'Senior', N'jQuery UI provides a suite of pre-built widgets but is highly monolithic and difficult to customize without deep dependency on the library. Web components offer a native, encapsulated way to build reusable UI elements that work across any framework or without one, promoting better long-term interoperability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ed6a41d8-1242-4a01-9746-f0d5e68abfd2', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'How does Lit handle memory management for event listeners attached to the host element?', N'Senior', N'Lit handles event listeners via standard Web Component APIs. Because Lit components are standard classes, developers should ensure listeners are managed or removed if they are added manually, although declarations via decorators are generally handled by the browser''s DOM lifecycle.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f8048308-1a95-4097-8ba4-f0d74e8b4535', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'How does the MongoDB Oplog influence replica set member lag and state transitions?', N'Senior', N'The Oplog is a capped collection that records all operations that modify data. If a secondary falls behind the primary''s Oplog tail, it enters the ''recovering'' state and may eventually require a full resync if the Oplog rolls over before the secondary can catch up.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'35cb93c8-716c-451c-9cf9-f0d79d106fb7', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'Why is it generally better to use local variables instead of global variables?', N'Junior', N'Local variables are faster to access and make code easier to debug and maintain by keeping the scope of data limited. Global variables can be modified from anywhere, which often leads to hidden bugs and side effects that are difficult to track. Using local scope promotes encapsulation and cleaner, more predictable function behavior.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b5b1be59-9364-4332-8885-f0d9124156fb', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'What is status code 404?', N'Intern', N'A 404 Not Found status code indicates that the server cannot find the requested resource. This usually happens when the client requests a URL that does not correspond to any defined route in the application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'42eafa71-4965-47cb-91a6-f0da904d6f05', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'Explain Index Properties in MongoDB?', N'Fresher', N'1. TTL Indexes: TTL ( Time To Live ) is a special option that we can apply only to a single field index to permit the automatic deletion of documents after a certain time. During index creation, we can define an expiration time. After that time, all the documents that are older than the expiration time will be removed from the collection. This kind of feature is very useful when we are dealing with data that don''t need to persist in the database ( eg. session data ). Example: In this case, MongoDB will drop the documents from the collection automatically once half an hour (1800 seconds) has passed since the value in lastUpdateTime field.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e5ffdf1b-b4ad-4d49-9c00-f0dd3df8484c', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'How does DynamoDB manage partition-level throughput limitations and what are the architectural implications of a ''hot partition'' scenario?', N'Senior', N'DynamoDB distributes data across partitions based on the partition key, and throughput is allocated per partition. A hot partition occurs when a specific key range experiences disproportionately high traffic, leading to request throttling even if the overall table capacity is not exceeded. To mitigate this, architects must design partition keys with high cardinality to ensure uniform data distribution and prevent bottlenecks caused by uneven access patterns.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'043af960-04bf-4e37-9992-f0dd945a3c43', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'Describe the internal architecture of the Dart Virtual Machine regarding garbage collection.', N'Senior', N'The Dart VM employs a generational garbage collector that optimizes for short-lived objects. It frequently collects the young generation space while performing less frequent, more intensive scans on the old generation space, effectively minimizing garbage collection pauses during application execution.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'201d01a4-7a9c-48eb-abc7-f0de117aeba6', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'What is the trade-off between choosing a monolithic architecture and a microservices architecture?', N'Intern', N'A monolith is simpler to develop and deploy initially but becomes difficult to maintain as it grows. Microservices offer better scalability and independent deployment but introduce significant complexity in networking, data consistency, and service orchestration.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd02bee00-3c9e-4673-b1ee-f0dedb953580', N'a000805c-e41f-42a9-af12-66b45348f77b', N'What is the purpose of the ''Ace'' CLI tool?', N'Fresher', N'Ace is the command-line interface for AdonisJS used to perform repetitive development tasks. It helps generate boilerplate files, run database migrations, start the development server, and execute custom console commands.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cc423150-e9b9-4cc3-8173-f0df5652cddf', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'Explain the trade-offs between using checked and unchecked exceptions in Java.', N'Middle', N'Checked exceptions force developers to handle anticipated error conditions, which improves API robustness but can lead to verbose boilerplate code. Unchecked exceptions provide cleaner code by allowing errors to propagate naturally, but they risk runtime crashes if developers do not explicitly document or handle them. Modern Java design often favors unchecked exceptions for internal logic and checked ones for recoverable external failures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'260935c5-c8ad-4904-b233-f0e1f5eb5424', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'What is the role of replication in NoSQL?', N'Junior', N'Replication is the process of copying data from one node to one or more other nodes. This serves to improve read performance by distributing the query load and ensures data safety in case of a node failure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
