INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7c168703-4a42-4b97-afd1-f0ea122af10e', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'What is CAP theorem?', N'Intern', N'The CAP theorem states that a distributed data store can only provide two of three guarantees: Consistency, Availability, and Partition Tolerance. It is a fundamental concept used to understand the trade-offs in distributed database systems.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'52397f5a-b1cf-4143-98af-f0eb0b053836', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'Why is it important to consider ''technical debt'' when estimating a new feature?', N'Junior', N'Technical debt can make the system harder to modify, meaning that what seems like a simple feature might require extra time for refactoring or cleanup. Ignoring it leads to inaccurate estimates and brittle systems that break easily.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
