INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b51ff012-c3d1-4317-b9c3-f0f4f3ec2ac2', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'What is the primary advantage of using jQuery over vanilla JavaScript?', N'Fresher', N'The main advantage is cross-browser compatibility, as jQuery handles browser differences internally. It also offers a concise syntax that allows developers to write less code to achieve complex DOM manipulations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e69d112e-ecd9-4391-a893-f0f634920c41', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'What is the significance of the ''ExecutionContext'' in Scala''s asynchronous programming?', N'Middle', N'The ExecutionContext acts as a thread pool, defining where and how asynchronous tasks are executed. By isolating the execution policy from the task logic, it allows developers to swap between different strategies, such as blocking I/O versus CPU-bound computation, without changing the business logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4ad3b3a0-7abf-4182-849f-f0f6f54f9a89', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'Describe the role of ''Utility Types'' like Pick, Omit, and Partial.', N'Middle', N'Utility types are built-in transformations that allow you to create new types based on existing ones without duplication. Partial makes all properties optional, Pick allows you to select specific fields, and Omit allows you to exclude fields, significantly reducing boilerplate code when managing complex state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a329e0cf-944e-429f-9f3b-f0fac28fef50', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'What is the purpose of the ''main.ts'' file in a NestJS project?', N'Fresher', N'The main.ts file acts as the entry point of the application. It is responsible for bootstrapping the Nest application instance using the NestFactory class and starting the HTTP server to listen for incoming requests.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7e94570b-129f-4ec8-b789-f0fc9a8d0949', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is the difference between microtasks and macrotasks, and why does it matter?', N'Fresher', N'The distinction between microtasks and macrotasks determines when callbacks run relative to each other and to rendering. Getting this wrong causes subtle ordering bugs, laggy UIs, and starvation scenarios. Microtask sources: - Promise.then() / .catch() / .finally() - async/await continuations (desugars to .then()) - queueMicrotask() - MutationObserver callbacks Macrotask sources: - setTimeout / setInterval - setImmediate (Node.js only) - I/O callbacks (Node.js) - UI event callbacks (click, input, etc.) - MessageChannel.postMessage() - requestAnimationFrame (browser — runs before paint, after microtasks) Critical difference: After each macrotask, the entire microtask queue is drained before the next macrotask or render.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'61662ee5-50d2-4477-ba46-f0ffc70bd707', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'How do ''Access Control'' modifiers affect the compiler''s ability to optimize code?', N'Senior', N'Access control modifiers like ''private'' or ''fileprivate'' allow the compiler to prove that a symbol is not used outside a specific scope. This enables ''dead code elimination'' and ''internal inlining'' because the compiler can safely assume no external module will attempt to access the code, leading to smaller and faster binaries.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f9261723-8821-4bcc-947b-f0ffcaec0f1c', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'How does Micronaut achieve non-blocking I/O, and what is its relationship with Netty?', N'Middle', N'Micronaut uses Netty as its default embedded server, which is an event-driven, non-blocking networking framework. This allows the application to handle thousands of concurrent connections with a small number of threads, significantly improving throughput for I/O-bound tasks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b3970496-668b-4c60-998a-f101e65a236c', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'What is an attribute in database design?', N'Intern', N'An attribute is a characteristic or property of an entity. For example, if the entity is a student, attributes might include the student''s name, age, and email address, which are stored as columns in a table.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'525e899f-007e-4f32-97a6-f1037c893872', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'What is the role of Gin''s ''Engine'' object?', N'Middle', N'The Engine is the core instance that holds the routing tree, middleware stacks, and configuration settings. It acts as the central orchestrator that dispatches incoming HTTP requests to the appropriate handler functions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd45ae4c4-d00f-43e1-a032-f1041864dfe8', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'What is meant by serverless in DynamoDB?', N'Intern', N'Serverless means that users do not need to provision, patch, or manage any physical or virtual servers. AWS handles all the infrastructure, hardware, and software maintenance automatically.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c48eab5c-a399-4a58-b604-f10579732968', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'How does Cassandra handle ''Read Repair''?', N'Middle', N'Read Repair is a consistency mechanism where the coordinator node compares the data returned from multiple replicas during a read request. If a discrepancy is found, the coordinator updates the inconsistent replicas to match the latest version.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8e484029-8216-49e0-9766-f105a560e78b', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'Can you use standard JavaScript to update the DOM in SolidJS?', N'Fresher', N'While you can technically manipulate the DOM directly, it is highly discouraged. SolidJS expects you to use its reactive system so that it can maintain control over the DOM and ensure that state and view remain in sync.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cacb10fd-09e6-4f0f-a2b1-f10672440a22', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'What is the difference between ''process.env'' and a configuration file?', N'Intern', N'process.env is used to access environment variables set by the operating system or host environment, which is ideal for sensitive data like API keys. Configuration files are static files within the project used for non-sensitive application settings.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'468b0642-d3d6-4edb-a9ae-f1097e767582', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'What are the advantages of using ''opaque return types'' (some T) in Swift?', N'Middle', N'Opaque types allow a function to hide the specific concrete type it returns while still guaranteeing that it conforms to a protocol. This improves API design by keeping internal implementation details private and allows the compiler to optimize the code better than using type erasure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e65f4a26-c748-4302-9a1d-f10b20cb82ca', N'210c7148-726e-4e8b-bf12-40be36e55130', N'How do you create a reference in Rust?', N'Fresher', N'In Rust, a reference represents an indirect borrowed view of data. It doesn''t have ownership or control, unlike a smart pointer. A reference can also be mutable or immutable. Key Concepts - Ownership Relation: Multiple immutable references to data are allowed, but only one mutable reference is permitted. This ensures memory safety and avoids data races. - Lifetime: Specifies the scope for which the reference remains valid. Code Example: Creating a Reference Here is the Rust code: Borrow Checker Rust''s Borrow Checker ensures that references are only used within their designated lifetime scopes, essentially reducing potential memory risks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7430d695-f41b-4e01-a9bc-f10cd3e1c0fa', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'What are enumerations in Swift and how do they support associated values?', N'Intern', N'Enumerations, commonly referred to as enums, are a powerful feature of Swift that provide a way to define a common type for a group of related values. Enums can be enhanced with associated values to present more detailed data records. For example, consider a pizza delivery app. An order can be in one of several states, and different states may have associated data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'00435cc9-ebf0-4782-a458-f10df474c412', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'What is the primary trade-off when deciding between synchronous and asynchronous processing for a user notification system?', N'Junior', N'Synchronous processing provides immediate feedback to the user but blocks the main thread, potentially leading to timeouts if the service is slow. Asynchronous processing decouples the service and improves responsiveness, but it introduces complexity in handling failures and tracking the status of the background task.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'04fd0d59-d143-4280-9f27-f10ecdbdeb34', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'How does the Qwik Optimizer affect the build process?', N'Middle', N'The Qwik Optimizer is a build-time transformation tool that automatically breaks the application code into small, lazy-loadable chunks. It handles the extraction of complex logic into separate files, ensuring the developer can write clean code while the framework optimizes it for production.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2329a242-6e9b-40c6-a16e-f10f7e985e63', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'How do you approach observability in a complex, multi-service environment?', N'Senior', N'Establish a unified strategy for logs, metrics, and distributed tracing across all services. Ensure that all services expose standardized health checks and utilize correlation IDs to track requests across service boundaries.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'61afa7f9-f46e-4283-8012-f11092ae8483', N'954a0331-deff-4399-b588-96f39fec001d', N'What is a module?', N'Intern', N'Modules are logical boundaries in your application and the application is divided into separate modules to separate the functionality of your application. Lets take an example of app.module.ts root module declared with @NgModule decorator as below, The NgModule decorator has five important (among all) options: 1. The imports option is used to import other dependent modules. The BrowserModule is required by default for any web based angular application. 2. The declarations option is used to define components in the respective module. 3. The bootstrap option tells Angular which Component to bootstrap in the application. 4. The providers option is used to configure a set of injectable objects that are available in the injector of this module. 5.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9e8f3903-eba6-4150-98fe-f111182638da', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'What is the role of the ''Action Filter'' in ASP.NET Core?', N'Middle', N'Action Filters allow you to run code before and after an individual action method is executed. They are commonly used for tasks like logging, model validation, or performing specific transformations on the result returned by an action.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b77d627a-afa3-436c-8e42-f113ce8fc610', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'What is the purpose of the ''index.html'' file in a Vite project?', N'Intern', N'In Vite, the index.html file is treated as the entry point of the application. Vite processes this file to inject scripts and styles, allowing it to act as a proper part of the dependency graph.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e008a947-0f3a-4e7a-a2c7-f114747ec44d', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is a first class function', N'Intern', N'In JavaScript, first-class functions(first-class citizens) mean that functions are treated like any other variable. That means: 1. You can assign a function to a variable. 2. You can pass a function as an argument to another function. 3. You can return a function from another function. This capability enables powerful patterns like callbacks, higher-order functions, event handling, and functional programming in JavaScript. For example, the handler function below is assigned to a variable and then passed as an argument to the addEventListener method.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ba3af131-e61f-4fb6-815f-f114d29d70ab', N'8d34dfc0-4a64-4128-b41a-cafa62ddad41', N'How does mTLS enhance security in a microservices architecture compared to standard TLS?', N'Senior', N'mTLS ensures mutual authentication by requiring both the client and the server to present valid X.509 certificates to each other. This prevents unauthorized services from communicating within the internal network, effectively mitigating man-in-the-middle attacks and enforcing zero-trust service-to-service communication.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'86d1f7dc-59c1-4d63-bce6-f116060da744', N'd5b12859-0c9f-4e2f-9b3a-1ccb6c5080e5', N'How does a caching layer help in scaling a database?', N'Middle', N'A cache sits in front of the database to store frequently accessed data in memory, significantly reducing the number of queries reaching the database. This decreases database load and improves response times for read-heavy applications.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a8987cad-9639-4d4e-ad66-f117638e3cd7', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'How to enable production mode in React?', N'Senior', N'You should use Webpack''s DefinePlugin method to set NODE_ENV to production, by which it strip out things like propType validation and extra warnings. Apart from this, if you minify the code, for example, Uglify''s dead-code elimination to strip out development only code and comments, it will drastically reduce the size of your bundle.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'594e32d2-0d2c-4b7a-9f4f-f117dc1dc89f', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'Can you use Gin without middleware?', N'Fresher', N'Yes, you can initialize a Gin engine using the New method instead of Default. The Default method automatically includes Logger and Recovery middleware, whereas New creates an engine with no pre-configured middleware.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd2b56c4f-aa24-478b-889d-f118d17dab53', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'What is the difference between Route Groups and standard route definition in Gin?', N'Middle', N'Route Groups allow you to organize routes under a common path prefix and apply specific middleware to that subset of routes. This improves code maintainability and allows for granular security and logging policies across different modules of the application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7002bd1f-2c46-4cd7-a25f-f1191fe0b0d6', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'What is the Method Resolution Order (MRO) in Python?', N'Middle', N'MRO is the specific order in which Python searches for methods in a hierarchy of classes, particularly when using multiple inheritance. Python uses the C3 Linearization algorithm to ensure a consistent, monotonic order that respects both local precedence and global inheritance structure. You can view this order by accessing the class attribute __mro__.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ed9d051d-24b1-4709-9a40-f120952c4301', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'What is the difference between a synchronous and asynchronous request in Litestar?', N'Intern', N'An asynchronous request allows the server to handle other tasks while waiting for I/O operations, whereas a synchronous request blocks the execution thread until the operation completes. Using asynchronous handlers is preferred for performance in high-concurrency environments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
