INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'46024e7e-a3ea-48f7-98c8-f121ad90fc70', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'What does the .once modifier do in event handling?', N'Junior', N'The .once modifier ensures that an event listener is only executed the very first time the event is triggered. After that, the listener is removed, which is useful for actions that should only happen once, such as loading a resource.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a6208adf-8acb-4e62-8f39-f122b8b9cd6b', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'What is a View Component or a Presenter, and why use them in Rails?', N'Middle', N'Presenters and View Components are used to encapsulate display logic that would otherwise clutter Rails views. They help keep views simple and testable by transforming raw model data into a format suitable for the UI without relying on complex helper methods.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9b981da4-c6e5-488a-bcb5-f124f30629a2', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'What are ''loaders'' in the context of Webpack''s asset management?', N'Middle', N'Loaders are transformation tools that allow Webpack to treat non-JavaScript files—such as images, fonts, or CSS—as modules. By configuring loaders, you can import these assets directly into your code, and Webpack will handle them, move them to the output directory, or inline them based on your settings.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b3b8ed06-a1c6-42cc-9e07-f1255d384e11', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'What is the impact of using @Transactional(propagation = Propagation.REQUIRES_NEW)?', N'Senior', N'This setting suspends the current transaction and starts a completely new, independent transaction. If the new transaction fails, it does not roll back the original transaction, which is useful for logging or audit operations that must persist even if the primary business process fails.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'09eae58c-6089-4cb7-8ae7-f126c1f7fef2', N'8d34dfc0-4a64-4128-b41a-cafa62ddad41', N'Why is ''Security by Design'' important in software development?', N'Middle', N'Security by design means integrating security considerations into every phase of the software development lifecycle, rather than treating it as an afterthought. This approach helps identify and mitigate vulnerabilities early, significantly reducing the cost and impact of potential flaws.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
