INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd93b56c1-bc6d-467a-8062-f1385be27870', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'What is a segmentation fault and what are common causes?', N'Middle', N'A segmentation fault occurs when a program attempts to access a memory location it does not have permission to access. Common causes include dereferencing a null or uninitialized pointer, buffer overflows, or attempting to write to read-only memory segments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6986d03e-f9b3-4c20-94cc-f13a4a1908fb', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'Why does Rocket use macros for routing?', N'Junior', N'Macros are used in Rocket to reduce boilerplate code and provide a clean, declarative syntax for defining routes. They allow the framework to perform compile-time checks on the route definitions, ensuring they are valid before the application starts.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3d6014b4-d422-4114-a206-f13e5317277e', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'What is polymorphism in C++ and how is it achieved?', N'Fresher', N'Polymorphism allows objects of different classes to be treated as objects of a common base class, enabling a single interface to represent different underlying forms. It is primarily achieved through function overloading at compile-time and through virtual functions in inheritance hierarchies at runtime.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2af9ec1b-7f8d-4243-a99e-f13f9ec7fb29', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'What is the role of a Gossip Protocol in Cassandra?', N'Intern', N'The gossip protocol is a peer-to-peer communication mechanism used by nodes to discover information about other nodes in the cluster. It allows nodes to share state information and detect failures without a central master.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4b6db360-8a30-4db1-a99d-f1416266ccbc', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What are Sets and Maps and how are they used?', N'Intern', N'Sets and Maps are built-in JavaScript objects that help manage collections of data. A Set is a collection of unique values, while a Map is a collection of key-value pairs where keys can be of any type. Sets are useful for storing unique items, and Maps are useful for associating values with keys. ↑ &nbsp;&nbsp;/&nbsp;&nbsp; ✏️ Edit answer', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c259bff0-17eb-4390-927c-f141b6b2ec94', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'When designing an API for a high-traffic mobile application, how do you decide between REST and GraphQL?', N'Senior', N'I choose REST when I need strong caching semantics, simpler caching mechanisms, and standard HTTP behavior for public-facing or inter-service communication. I prefer GraphQL when the client needs to minimize payload size and request round-trips by requesting only specific fields across multiple nested resources.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
