INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd3db4a67-852f-44ee-891d-f1459a507ce6', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'What is the difference between ''cluster health'' states (Green, Yellow, Red)?', N'Middle', N'Green indicates all primary and replica shards are allocated. Yellow indicates all primary shards are active, but some replicas are missing. Red indicates that one or more primary shards are missing, meaning data is not fully available.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'41724b29-a2cd-4f63-968c-f14782a062f5', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'How does Rails manage database schema changes, and why are migrations versioned?', N'Middle', N'Migrations provide a structured way to evolve the database schema over time while keeping the database definition in sync with application code. Versioning allows teams to track changes chronologically and ensures that all environments can be updated to the same state by applying migrations sequentially.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
