INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'04ca1ac4-9228-41f9-ad2f-f14a1b9fc360', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'What is the risk of over-engineering a solution?', N'Fresher', N'Over-engineering adds complexity for future scenarios that may never happen, wasting time and making the system harder to understand. The trade-off is prioritizing hypothetical flexibility over current efficiency and simplicity.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
