INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'22737ccd-7c69-4233-afc2-f14c560da5d6', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'What are the risks of using the ''SELECT *'' statement in production environments?', N'Middle', N'Using ''SELECT *'' fetches all columns, which increases network traffic and memory usage if large or unnecessary columns are retrieved. It also prevents the database from using covering indexes and makes the application code more brittle if the underlying table schema changes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'06be166b-5974-463e-9457-f14dcd5471a4', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'What is the purpose of the Gemfile in a Rails application?', N'Intern', N'The Gemfile in a Ruby on Rails application acts as a manifest of all required gems for the project. It serves as the foundation for the Bundler tool, which automates the process of managing and versioning gem dependencies. Bundler: Gem Management and Version Control Bundler tracks gem versions to ensure project consistency across different environments and team members. It also keeps a record of specific gem versions in the project''s Gemfile.lock. Mechanism of Gemfile.lock When Bundler installs or updates gems, it incorporates them into the project with precision according to the versions recorded in Gemfile.lock. This feature is particularly beneficial for collaboration, as it preserves a consistent gem "snapshot" for all contributors.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'34f615f8-93d2-4b86-a1a5-f15106aefefc', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'What is the difference between jQuery''s .prop() and .attr() methods?', N'Middle', N'The .attr() method retrieves the initial attribute value as defined in the HTML markup, while .prop() retrieves the current property value based on the element''s state. Using .prop() is generally preferred for boolean attributes like checked or disabled, which change dynamically during the user session.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a6947147-b1a3-492d-aeaf-f15113c94a28', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'What is a query operation in DynamoDB?', N'Intern', N'A query operation retrieves items based on the primary key values. It is highly efficient because it uses the partition key to find the exact location of the data, making it the preferred way to read items.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
