INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'52680e9b-2509-4162-b9bb-f156710ab801', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'Why might you choose to use Flask''s ''current_app'' rather than importing the app instance directly?', N'Senior', N'Using ''current_app'' ensures the code remains decoupled from the specific application instance, facilitating easier unit testing and support for the application factory pattern. Importing the app instance directly creates circular dependencies and ties your logic to a single global instance, which hinders modularity.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7e4fd14d-84d2-4549-b9de-f157b8df54c1', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'How does a document-oriented database differ from a key-value store?', N'Middle', N'A key-value store provides simple, high-speed access to data using a unique key, treating the value as an opaque blob. In contrast, a document-oriented database understands the internal structure of the data, allowing for complex queries, indexing, and filtering based on fields within the document.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'05027d33-6bcd-46b8-8f81-f158f4f2fe72', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'Does Vite support TypeScript out of the box?', N'Intern', N'Yes, Vite provides built-in support for TypeScript. It uses esbuild to transpile TypeScript into JavaScript, which is very fast, though it does not perform type-checking during the transformation process.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7381cca8-d64a-486b-9cac-f15dc541d99f', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'What is the concept of ''scalability'' in software systems?', N'Intern', N'Scalability is the ability of a system to handle increased demand, such as more users or data, without failing or losing performance. A scalable system can grow efficiently by adding more resources or distributing tasks effectively. This is crucial for businesses that expect their user base to expand over time.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f7600ecf-6f2a-47e5-bc10-f15f806cebf8', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'Explain the difference between weak and strong symbols in the context of the linker.', N'Senior', N'Strong symbols are typically initialized global variables or functions, while weak symbols are often uninitialized globals or specifically marked with linker attributes. If a linker encounters both, the strong symbol takes precedence, which is a mechanism used to allow users to override default library implementations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'55b793b0-18d6-42f3-982f-f16202e2729f', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'What is the difference between a mixin and an extend?', N'Intern', N'A mixin copies the code block into every place it is used, which can increase the CSS file size. An @extend directive groups selectors together in the compiled CSS, which is often more efficient for grouping shared styles.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7920e726-7fe5-4aed-9945-f164d0cefaeb', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'Describe how to achieve graceful shutdown in a Spring Boot application and why it is necessary for Kubernetes.', N'Senior', N'By enabling server.shutdown=graceful, the application stops accepting new requests while allowing current ones to complete within a timeout period. This is vital in Kubernetes to prevent dropped connections during rolling updates, ensuring that traffic is drained from the pod before it is terminated.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f1d4089b-289e-4337-adb8-f166a9c2a2dc', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'What is an HTTP status code?', N'Intern', N'An HTTP status code is a three-digit number sent by the server in response to a client''s request to indicate the outcome. For example, 200 indicates success, 404 indicates the resource was not found, and 500 indicates a server error.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c7a5acc4-84e2-40e2-bd90-f16a87fa4937', N'55404b9c-91b6-4b62-9dc7-63248e8ea1df', N'What is the difference between vertical and horizontal scalability?', N'Middle', N'Vertical scaling involves adding more power, such as CPU or RAM, to an existing server, whereas horizontal scaling involves adding more nodes to a system to distribute the load. Vertical scaling is limited by hardware capacity, while horizontal scaling allows for theoretically infinite growth by adding more machines.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5b8c6e9a-3bdc-47ff-b14f-f16af491b377', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'What are the implications of using ''Plug'' for authentication compared to manual controller-level checks?', N'Senior', N'Plugs provide a standardized, composable pipeline for request processing, allowing authentication to be injected globally or per-route. This promotes the ''Don''t Repeat Yourself'' principle and ensures security logic is consistently applied before the request reaches the controller, reducing the risk of bypass vulnerabilities.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c5a1489c-a293-442e-8487-f16b2fd69c2b', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'What is the benefit of nested routing in Remix?', N'Junior', N'Nested routing allows you to break your UI into smaller, logical pieces that map directly to your URL structure. When the URL changes, Remix only reloads the specific segments of the page that need to update, rather than the entire application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6f1e5f50-04ec-4464-b4d2-f16be709b0fc', N'210c7148-726e-4e8b-bf12-40be36e55130', N'What is the purpose of match statements in Rust?', N'Intern', N'In Rust, match statements are designed as a robust way of handling multiple pattern scenarios. They are particularly useful for enumerations, though they can also manage other data types. Benefits of match Statements - Pattern Matching: Allows developers to compare values against a series of patterns and then carry out an action based on the matched pattern. It is a foundational component in Rust''s error handling, making it more structured and concise. - Exhaustiveness: Rust empowers developers by compelling them to define how to handle each possible outcome, leaving no room for error. - Conciseness and Safety: Mathcing is done statically at compile-time, ensuring type safety and guardig against null-pointer errors.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'524bf97d-0e1b-4e1d-9d70-f16f21fe9fbc', N'075b8862-431c-4678-9767-f55359758a4a', N'How does Vue''s compiler-informed VDOM optimization work during build time?', N'Senior', N'The compiler analyzes templates and identifies static vs. dynamic nodes, generating ''patch flags'' that inform the runtime exactly which parts of the DOM need updating. This allows the renderer to skip static tree traversal entirely, drastically improving re-render speeds compared to naive VDOM implementations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7826032f-6f88-454c-a005-f1719dae3762', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'What does the ''nuxt generate'' command do?', N'Junior', N'The generate command creates a static version of your application by pre-rendering every page into HTML files. This is perfect for hosting on static site platforms where a Node.js server is not required.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ba332df8-f461-4dec-96a8-f1722d501335', N'075b8862-431c-4678-9767-f55359758a4a', N'How does Vue''s ''nextTick'' relate to the DOM update cycle?', N'Senior', N'Vue updates the DOM asynchronously; when you change state, Vue waits until the next ''tick'' to batch all changes together for efficiency. ''NextTick'' provides a mechanism to execute code after the DOM has been updated, ensuring that you are interacting with the latest rendered state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0d1281d0-0d75-408c-a089-f17266d23ad0', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'What is the benefit of using ''BoxError'' in Axum middleware?', N'Middle', N'Using ''BoxError'' allows middleware to handle various error types from different sources in a unified way. It simplifies the type signatures of complex middleware chains by erasing specific error types, which is particularly useful when composing services from different crates.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c9c85d38-4a62-4f60-ba67-f172ce727a7f', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'What is the Durability property in ACID?', N'Intern', N'Durability guarantees that once a transaction has been committed, it will remain saved even in the event of a system crash or power loss. The changes are permanently recorded in the non-volatile memory of the database system.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cbce3716-6f7b-4277-95a3-f176636876ec', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'What are the trade-offs of using slots in a class definition?', N'Senior', N'Defining slots prevents the creation of a dynamic __dict__ for each instance, significantly reducing memory consumption for classes with many objects. However, this restricts the ability to add arbitrary attributes to instances at runtime and adds complexity when dealing with multiple inheritance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'28f25b8f-74d7-485b-bd6c-f178d6199ee6', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'Why is it important to use a persistent connection pooler like PgBouncer with Rails in high-traffic environments?', N'Senior', N'Rails opens a database connection per process, which can quickly exhaust the database''s connection limit when scaling horizontally. PgBouncer sits between the application and the database to pool and reuse connections, drastically reducing the overhead of creating new database processes for every request.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e0ee1105-4429-450d-8ab5-f17ab00eaf4c', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'How does Node.js interact with the underlying Operating System kernel for asynchronous I/O?', N'Senior', N'Node.js utilizes kernel-level primitives like epoll (Linux), kqueue (macOS), or IOCP (Windows) through libuv. These mechanisms allow the OS to notify the event loop when I/O operations are complete, enabling the single-threaded process to handle thousands of concurrent connections efficiently without blocking on each individual I/O call.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f9aea296-22a9-40db-afce-f17c90c3068f', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What are the different types of testing in software development?', N'Fresher', N'In software development, there are several types of testing to ensure the quality and functionality of the application. These include unit testing, integration testing, system testing, and acceptance testing. Unit testing focuses on individual components, integration testing checks the interaction between components, system testing evaluates the entire system, and acceptance testing ensures the software meets user requirements. ↑ &nbsp;&nbsp;/&nbsp;&nbsp; ✏️ Edit answer Explain the difference between unit testing, integration testing, and end-to-end testing Unit testing focuses on testing individual components or functions in isolation to ensure they work as expected. Integration testing checks how different modules or services work together.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c4abd9b5-a24a-40ac-8811-f17f77070e72', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'What is the ''Template Inheritance'' feature?', N'Junior', N'Template inheritance allows you to build a base skeleton template that contains common elements like headers, footers, and sidebars. Child templates can then inherit from this base and override only the specific content blocks they need.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'211edd15-abcb-4563-a1c1-f1804b004dc2', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'Explain the strategy for implementing graceful shutdowns in a Flask application running in a containerized environment.', N'Senior', N'Graceful shutdown requires capturing SIGTERM signals and allowing the WSGI server to stop accepting new requests while finishing existing ones. In a container orchestrator like Kubernetes, this prevents dropped connections and ensures that worker processes have sufficient time to complete active transactions before the container is terminated.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1a090bca-92f4-46d4-ad8b-f18395de4ad9', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'What is an entity in database design?', N'Intern', N'An entity is a real-world object, person, or concept that is represented in a database. In a relational database, entities are usually mapped to tables, and their characteristics are mapped to columns.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2aa8079f-0add-40b3-820f-f18433f412da', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'Does Go support inheritance?', N'Intern', N'No, Go does not support type inheritance. It promotes code reuse through composition, where structs contain other structs or implement interfaces.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2c0f6d46-972d-4c04-a4e3-f1861b1cbcd7', N'8d34dfc0-4a64-4128-b41a-cafa62ddad41', N'How does implementing ''Defense in Depth'' change the design of a public-facing web application?', N'Senior', N'It requires layering security controls at every level: WAF at the edge, rate limiting at the API gateway, input validation at the service layer, and strict IAM roles at the database level. Each layer acts as an independent barrier, so that the failure of one component does not result in a total system breach.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'60465859-3401-4390-aa6c-f186c3bd9865', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'What is the role of the ''inline'' keyword in Kotlin and when should it be avoided?', N'Middle', N'The inline keyword instructs the compiler to copy the function body directly to the call site to reduce overhead from lambda object creation. It should be avoided for very large functions, as it can cause significant code bloat and negatively impact instruction cache performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'56d229c6-d13d-4c8b-8896-f1872f36149d', N'210c7148-726e-4e8b-bf12-40be36e55130', N'What is the distinction between shadowing and mutability?', N'Junior', N'Mutability allows you to change the value of a variable, while shadowing allows you to declare a new variable with the same name as a previous one. Shadowing can also change the type of the value, whereas mutability cannot.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'056799d1-ecc5-4d70-846c-f1899344b594', N'954a0331-deff-4399-b588-96f39fec001d', N'What is interpolation?', N'Intern', N'Interpolation is a special syntax that Angular converts into property binding. It’s a convenient alternative to property binding. It is represented by double curly braces({{}}). The text between the braces is often the name of a component property. Angular replaces that name with the string value of the corresponding component property. Let''s take an example, In the example above, Angular evaluates the title and url properties and fills in the blanks, first displaying a bold application title and then a URL.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'826b933c-fe30-418d-a231-f18acacdeb67', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'What is the advantage of using Astro''s middleware?', N'Middle', N'Middleware allows you to intercept requests and responses globally to perform tasks like logging, authentication, or modifying headers. It provides a centralized location for cross-cutting concerns before the page is rendered or the API route is called.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'74ba8a9c-4a62-4c53-88a8-f1908c2f283f', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'Why would you choose a Wide-Column store over a Document store for a specific project?', N'Middle', N'A Wide-Column store is typically chosen when you need to handle massive amounts of data across distributed clusters with high write throughput and flexible schema requirements. While document stores are excellent for nested data structures, wide-column stores excel at analytical queries and aggregating data across very large, sparse datasets.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5e135e1e-f417-4d1f-ac16-f196eedcffde', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'How do you handle dependency injection in a Nuxt application to keep services testable?', N'Senior', N'You can use Nuxt plugins to inject services into the Nuxt context, making them available throughout the application. To maintain testability, these services should be designed as independent, framework-agnostic classes that can be unit-tested without requiring the full Nuxt runtime environment.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'119c461a-d6ae-4c93-8b52-f19a95e3bc94', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'What is the difference between ''createResource'' and standard signal usage for data fetching?', N'Middle', N'createResource is specifically designed for handling asynchronous data loading. It manages the state of the request, including loading, error, and data states, and integrates seamlessly with Solid''s Suspense and Transition features.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1da34a64-7510-46f9-9a54-f19cbf75c8d8', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'Describe the internal architecture of Swift''s ''Value Witness Table'' (VWT).', N'Senior', N'The VWT is a hidden structure that provides the runtime with the necessary information to manipulate a type, such as its size, alignment, and how to perform lifecycle operations like copying or destroying. It allows the runtime to handle types of unknown size generically without hard-coding specific memory management rules.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'44b098bf-bdb8-4699-83ce-f19cc00827de', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'Can Qwik be used for static sites?', N'Intern', N'Yes, Qwik is excellent for static site generation. It can pre-render pages into static HTML files at build time, providing all the benefits of fast loading and SEO while still allowing for interactive features when needed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e1eb9c9a-6116-4a64-8cc9-f19e2bae0c9c', N'210c7148-726e-4e8b-bf12-40be36e55130', N'Explain the trade-offs between using Box and Rc for heap allocation.', N'Middle', N'Box provides unique ownership and is used for recursive types or moving large data off the stack with minimal overhead. Rc allows multiple ownership via reference counting, enabling shared data, but it incurs a runtime performance cost due to atomic or non-atomic counter updates and does not support interior mutability on its own.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'59b0416b-bc55-4935-8edb-f19f18f16635', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'What is the purpose of the x-effect directive?', N'Intern', N'The x-effect directive runs a piece of code whenever its dependencies change. It is useful for side effects that need to be re-executed automatically whenever a specific state variable updates.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'54568302-939f-4fd8-8a85-f1a0725de406', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'Discuss the strategy for handling memory leaks in Node.js when dealing with closures.', N'Senior', N'Closures can cause memory leaks if they retain references to large objects that are no longer needed, preventing them from being garbage collected. To avoid this, developers should explicitly nullify references, use weak maps where appropriate, or ensure that event listeners are properly removed once they are no longer required.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cbc42bad-ff27-449e-a9bf-f1a3d0f50a73', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'How does Micronaut handle HTTP routing?', N'Intern', N'Micronaut uses annotations like @Get, @Post, and @Put to map HTTP methods and URI paths to specific controller methods. These routes are pre-calculated at compile-time for efficient request dispatching.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c194901f-0c88-48b8-be97-f1a4e3e0ae14', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'Explain the trade-offs between G1GC and ZGC regarding heap management and pause times.', N'Senior', N'G1GC uses a region-based heap architecture that manages objects in generations to balance throughput and latency, but it often suffers from longer stop-the-world pauses during major collections. ZGC is designed for ultra-low latency by performing concurrent marking and compaction, which trades off some overall application throughput and memory overhead for sub-millisecond pause times.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'35b027da-75ab-4be2-92f2-f1a62d69e83d', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'Explain the significance of ''Compaction'' in maintaining read efficiency.', N'Senior', N'Compaction merges multiple SSTables into a single, larger table, discarding obsolete data and tombstones. This process is essential for reclaiming disk space and reducing read amplification, as it limits the number of files the coordinator must search to satisfy a read query.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'63b5e376-743f-404b-8db9-f1a8404b9728', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'What is the role of the ''actix-web'' crate?', N'Fresher', N'The actix-web crate is the primary package that provides the framework''s core features, including routing, request handling, and server management. It is the dependency that must be included to start building an Actix-web application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ab500770-2993-4c75-a06f-f1a8fad45f4c', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'How does Vite handle polyfilling, and what is its stance on legacy browser support?', N'Senior', N'Vite focuses on modern browser standards by default, assuming ESM support. For legacy browsers, Vite provides the @vitejs/plugin-legacy, which generates dual-builds with polyfills and systemjs fallbacks to ensure compatibility.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'23cd018f-06f8-4e82-be4c-f1aaf28189d2', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'What are the trade-offs of using checked versus unchecked exceptions?', N'Middle', N'Checked exceptions force developers to handle anticipated error conditions, which can lead to more robust code but often results in verbose, boilerplate-heavy try-catch blocks. Unchecked exceptions are intended for programming errors that cannot be programmatically recovered from, allowing for cleaner code but requiring disciplined documentation and testing to avoid unexpected crashes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5c9a1cbc-ad9b-4ddb-aba0-f1ab1673e1a2', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'How do you determine if a problem is too complex to solve on your own?', N'Intern', N'I determine complexity by setting a time-box for personal research. If I have exhausted standard documentation and my own logical brainstorming without making progress, I reach out to a mentor or teammate to avoid wasting time.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dfef3f5d-9660-4921-9217-f1afcdf7902f', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'If a user reports a bug that you cannot reproduce, what is your next action?', N'Intern', N'I would ask the user for more specific details, such as their browser, device, and the exact steps they took before the issue occurred. Then, I would try to simulate their exact environment to see if I can trigger the same behavior. If I still cannot reproduce it, I would document the findings and monitor for similar reports.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'63c72c16-fc05-4da9-81ad-f1aff43c31b2', N'f2e963ff-7635-4429-a389-4d92535fb972', N'What is the function of the ''autofocus'' attribute in single-page applications and how does it conflict with UX?', N'Senior', N'Autofocus moves the user''s focus to a specific element upon page load, which can be disorienting if the user is not expecting it or if it interrupts screen reader flow. In SPAs, it can cause issues if the element is not yet rendered, leading to unpredictable focus behavior that requires programmatic management.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f00493cb-4210-4440-a169-f1b05d54f4dc', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'What do you do if you notice a security vulnerability in the code you are working on?', N'Junior', N'I would prioritize it immediately and report it to my supervisor or the security lead. I would not commit the vulnerable code and would work with the team to implement a secure solution as soon as possible.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'31bf5e37-ec84-4693-bec1-f1b0e6046140', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'How does the For component differ from a standard JavaScript map function?', N'Junior', N'The For component is a reactive primitive that optimizes list rendering. By tracking individual items, it ensures that if an item in the list changes or moves, only that specific DOM node is updated, rather than re-rendering the entire list.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9db2282b-9d33-45d2-94ec-f1b116d980bf', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'When should you use ''Scoped'' services in an ASP.NET Core application?', N'Middle', N'Scoped services are ideal for database contexts or unit-of-work patterns where you need to share a single instance across multiple components within the context of a single HTTP request. This ensures data consistency and transaction integrity throughout the request lifecycle.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4da765e6-3cb5-460d-bcf3-f1b3d4b1dc9e', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'How do you mitigate the ''Select N+1'' problem specifically within the context of PostgreSQL''s query execution?', N'Senior', N'The N+1 problem is primarily an application layer issue, but it can be mitigated using PostgreSQL''s CTEs or lateral joins to fetch related data in a single round-trip. Using these features allows the engine to retrieve and join dependent data sets efficiently within one execution plan.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'11250637-a1f8-4e9f-95f4-f1ba04d80512', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'Explain the architectural rationale behind Go''s error handling model compared to exceptions.', N'Senior', N'Go uses explicit return values for error handling to force developers to acknowledge and handle failures at the call site, which improves code readability and predictability. This approach avoids the hidden control flow and stack unwinding overhead associated with exceptions, making the execution path easier to trace and debug.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2388f532-eaa2-437c-8f19-f1ba5eb80166', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'What is middleware in the context of Gin?', N'Intern', N'Middleware in Gin consists of functions that execute before or after the main request handler. These are used for tasks like logging, authentication, error recovery, or modifying the request and response.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8d021280-fef7-4b22-b48f-f1bbf1be5616', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'Why would you choose to use ''Spring Cloud Config'' over standard environment variables in a microservices environment?', N'Senior', N'Spring Cloud Config provides centralized, versioned configuration management that supports dynamic updates without restarting services. This is crucial in large-scale systems where managing thousands of environment variables across dozens of services becomes error-prone and operationally heavy.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'57da56e2-df55-49cc-a6ea-f1bcb361b827', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'Describe the performance implications of using ActiveModel::Serializers versus Jbuilder in a high-traffic API.', N'Senior', N'Jbuilder is a template-based system that can become slow due to string building and object allocation overhead. ActiveModel::Serializers or faster alternatives like Fast JSON API use a more object-oriented approach that can be optimized for throughput, though they require more boilerplate code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cc044bb5-47d2-498d-98d9-f1bcc14b32da', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'What are the security concerns regarding the ''event-loop-freeze'' attack?', N'Senior', N'An attacker can send a request that triggers a computationally expensive operation, forcing the event loop to block. By sending multiple such requests, an attacker can freeze the process entirely, leading to a Denial of Service. This is mitigated by validating inputs and offloading heavy computations to separate processes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'91d06928-41c3-409c-a75f-f1bd7dc65f8e', N'075b8862-431c-4678-9767-f55359758a4a', N'What are filters?', N'Intern', N'Filters can be used to apply common text formatting. These Filters should be appended to the end of the JavaScript expression, denoted by the "pipe" symbol. You can use them in two specific cases: 1. mustache interpolations 2. v-bind expressions For example, Let''s define a local filter named capitalize in a component''s options Now you can use the filter in either mustache interpolation or v-bind expression,', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'22f166da-34b4-4d66-91cf-f1be9b4cd166', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'What are Properties in C#?', N'Intern', N'Properties are a specialized mechanism that provides a flexible way to read, write, or compute the values of private fields. They use get and set accessors to encapsulate class data while maintaining a clean syntax.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6f16c4f7-8e23-4d8f-adc4-f1bef0c121f9', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'Describe the concept of ''duck typing'' in Ruby.', N'Middle', N'Duck typing is a design philosophy where an object''s suitability for a task is determined by the presence of certain methods rather than its explicit class hierarchy. If an object responds to the required method calls, the program treats it as a valid type regardless of its actual lineage.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'aa50d13f-4915-408c-9036-f1c1ba0aa756', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'How does Fastify manage the Node.js event loop during high-load scenarios?', N'Senior', N'Fastify is designed to minimize the performance tax of the framework itself, leaving more event loop cycles for application business logic. By avoiding unnecessary middleware execution chains and utilizing efficient asynchronous patterns, it reduces latency spikes and maintains a more stable event loop latency under heavy concurrent request traffic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b78ddaf0-be01-4715-9434-f1c397171253', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'What is the purpose of the ''uvicorn'' server?', N'Intern', N'Uvicorn is a lightning-fast ASGI server implementation that is used to run FastAPI applications. It is responsible for receiving HTTP requests and passing them to the FastAPI application to process.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9f03dca5-77b2-497d-b043-f1c43cc0e200', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'Does Preact support React''s Concurrent Mode or Server Components?', N'Middle', N'Preact does not implement React''s Concurrent Mode or Server Components exactly as React does, as these are highly specific architectural features of the React core. However, Preact provides its own solutions for performance optimization and supports server-side rendering, though the implementation details differ significantly.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dfb6cfc5-174b-4da5-8a77-f1c4839319ab', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'How do you define a default value for a parameter in FastAPI?', N'Intern', N'Default values are defined using standard Python function parameter syntax. If the client does not provide a value for that parameter, FastAPI will automatically use the default value defined in the function signature.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9ed11a66-3b96-4546-8821-f1c4a8c89bd9', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'Explain the concept of ''Islands Architecture'' in the context of Astro.', N'Middle', N'Islands Architecture allows developers to isolate interactive UI components within static HTML pages. Each island is hydrated independently, meaning non-interactive parts of the page remain as lightweight static HTML, significantly improving the initial load performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'36c41b1e-5b20-46aa-86c2-f1c4bcd558fa', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'Explain the concept of ''callback hell'' and how to avoid it.', N'Junior', N'Callback hell occurs when multiple nested asynchronous functions make code difficult to read and maintain. It is avoided by using Promises, the async/await syntax, or by modularizing code into smaller, reusable functions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'682e9595-8360-4040-823d-f1c8751b60b4', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'What role does monitoring play in the debugging process?', N'Middle', N'Monitoring provides the baseline for ''normal'' behavior, which is essential for detecting deviations that signify a bug. It allows engineers to identify which components are failing, the impact of the failure on users, and whether a fix has actually resolved the issue after deployment.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5acd1b93-07ae-4fd0-8865-f1cc7233d834', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'Explain the performance implications of the ''prototype chain'' versus ''class-based'' inheritance in modern JavaScript engines.', N'Senior', N'While both mechanisms ultimately rely on the same underlying prototype system, class syntax allows engines to better optimize object instantiation and property access patterns via hidden classes. Deep prototype chains can negatively impact performance because the engine must traverse the chain to resolve properties, potentially leading to cache misses in the inline caches used by high-performance JIT compilers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8396939d-c7e2-4e8a-b9a5-f1ce45f7dccd', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'What is the purpose of the Bloom Filter in Cassandra?', N'Middle', N'A Bloom Filter is a space-efficient, probabilistic data structure used to determine if a row exists in an SSTable before performing a disk read. It prevents unnecessary disk I/O by skipping SSTables that definitely do not contain the requested partition key.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9c3f4706-c39a-473f-8edc-f1d00b87ffa9', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'What is the Repeatable Read isolation level?', N'Intern', N'This level ensures that if a transaction reads a row, subsequent reads of that same row will return the same data. It prevents both dirty reads and non-repeatable reads, though phantom reads may still be possible.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9ff0db4d-dca3-4e44-9ba8-f1d073c9432f', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'What is your approach for resolving a conflict between engineering teams regarding architectural direction?', N'Senior', N'I facilitate a collaborative session focused on objective data, such as performance benchmarks, cost projections, and maintainability metrics. If a consensus isn''t reached, I push for a ''disagree and commit'' outcome based on which solution best serves the long-term strategic goals of the organization.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'30dcbf3d-2d17-47b2-8b7d-f1d29fe8fc90', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'What is the purpose of Rocket''s ''catchers''?', N'Intern', N'Catchers are handlers used to manage error conditions, such as 404 Not Found or 500 Internal Server Error. They allow developers to define custom responses when the framework encounters an error while processing a request.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8f8767fa-d9c3-4e9b-beb5-f1d9b665e0d4', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'Why might a NoSQL database choose to avoid ACID transactions in favor of BASE semantics?', N'Senior', N'BASE (Basically Available, Soft state, Eventual consistency) prioritizes system uptime and throughput over strict transaction guarantees. In massive-scale distributed environments, the cost of coordinating ACID transactions across hundreds of nodes is prohibitive, making BASE a more pragmatic choice for high-volume, global applications.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
