INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5f6eba23-ad68-49ae-9555-f1de9dcdb669', N'074508f7-35bd-405f-8cc6-b41377b2d92c', N'Explain the concept of backpressure in a messaging system.', N'Middle', N'Backpressure occurs when a consumer cannot keep up with the rate of incoming messages from the producer. The system handles this by signaling the producer to slow down or by buffering messages until the consumer''s capacity increases, preventing system resource exhaustion.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8866d329-320f-4c23-94bb-f1ded484f138', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'How do coroutines manage concurrency differently than traditional threads?', N'Middle', N'Coroutines are lightweight abstractions that use cooperative multitasking, allowing thousands of coroutines to run on a small number of threads. Unlike threads, which are managed by the operating system and involve heavy context-switching overhead, coroutines are managed by the Kotlin runtime.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
