INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0df07bad-13e9-45c1-a073-f1e1b7edd8cc', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'What is a docstring in Python?', N'Junior', N'A docstring is a string literal used to document a module, function, class, or method, placed immediately after the definition. It provides a way to associate documentation with a code block, which can then be accessed programmatically using the help() function. It is considered good practice to write docstrings to explain the purpose and usage of your code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
