INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd2efa3fe-3f81-403e-a194-f1e912c0ab38', N'074508f7-35bd-405f-8cc6-b41377b2d92c', N'Explain the architectural impact of a ''noisy neighbor'' on a shared message broker cluster.', N'Senior', N'A noisy neighbor can saturate the broker''s CPU, disk I/O, or network bandwidth, causing latency degradation for all other users of the cluster. Mitigation strategies include implementing strict resource quotas, rate limiting at the producer level, or dedicated clusters for critical workloads.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
