INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'85ad1b80-97fa-43c1-a3ea-f1ecc4b08ab0', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'How does the ''gossip protocol'' prevent the ''split-brain'' scenario during network partitions?', N'Senior', N'The gossip protocol maintains a shared view of the cluster membership and node states. While it cannot prevent split-brain entirely, it allows nodes to quickly identify unreachable peers and adjust their replica-awareness, ensuring that requests are routed only to the partition that can satisfy the requested consistency level.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'75a26489-12f8-4e6c-83b8-f1edec1c3932', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'Why is TypeScript’s ''Discriminated Union'' pattern preferred over inheritance for domain modeling?', N'Senior', N'Discriminated unions offer a clean, exhaustive way to handle variant data types while enabling the compiler to narrow types precisely within switch statements. This approach avoids the fragility of deep class hierarchies and provides better support for functional programming patterns like pattern matching.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0901f301-15c8-4e01-9537-f1f4a4959a72', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'What is the purpose of the ''operator'' keyword in Kotlin?', N'Middle', N'The ''operator'' keyword allows you to overload standard operators like plus, minus, or index access by implementing specific convention-based function names. It enables more readable and idiomatic syntax for custom types while ensuring the code remains type-safe.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'89161c14-25d5-415a-b4aa-f1f5b5f47204', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'How does Django’s transaction management work, and what are the hazards of using `transaction.atomic` in long-running requests?', N'Senior', N'Django uses a database-level transaction wrapper, but wrapping long-running operations in `transaction.atomic` keeps database connections open and locks rows for extended periods. This drastically reduces concurrency and can lead to connection pool exhaustion and deadlocks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'07245d28-50cb-422c-9367-f1f5f4056852', N'a000805c-e41f-42a9-af12-66b45348f77b', N'How does Lucid ORM handle connection pooling and transaction management in high-concurrency environments?', N'Senior', N'Lucid leverages Knex.js to manage a configurable connection pool, allowing for fine-tuned control over maximum and minimum idle connections. For transactions, it uses a scoped transaction object that ensures all queries within the block share the same connection, preventing race conditions and ensuring ACID compliance across distributed database operations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'96576800-0b73-4dcc-b6ac-f1f929103e69', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'How does Redis handle data expiration?', N'Intern', N'Redis allows you to set a Time To Live (TTL) on keys. Once the time expires, Redis automatically deletes the key, which is particularly useful for managing cache entries that are only valid for a short duration.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8bca6f35-c5bb-443e-b90a-f1f9aed8f3f8', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'How does Qwik improve SEO?', N'Fresher', N'Qwik improves SEO by delivering fully populated HTML from the server instantly. Search engine crawlers can read the content immediately without needing to execute complex JavaScript, which is beneficial for indexation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e1d6e917-ca71-4690-a535-f1fb895ed3de', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'What is the benefit of using SvelteKit''s built-in form actions?', N'Junior', N'Form actions allow you to handle form submissions on the server without writing custom API routes. They simplify the process of validating inputs and updating the page state after a submission.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3bed358d-b4ce-4590-9d3e-f1fec38cc0a6', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'How does Next.js facilitate SEO for dynamic content compared to traditional SPAs?', N'Senior', N'Next.js provides full server-rendered HTML for search engines to crawl, unlike SPAs which rely on client-side execution to generate content. This ensures that meta tags, structured data, and content are immediately available to bots, resulting in better indexing and search ranking.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e15dcc4e-c049-445a-a78f-f1ffcd271c1e', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'What is the Garbage Collector and how does it work?', N'Intern', N'The Garbage Collector is an automatic memory management feature in C# that reclaims memory occupied by objects that are no longer in use. It periodically scans the managed heap to identify and remove unreachable objects to prevent memory exhaustion.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
