INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5def1822-dd79-43e9-b39e-f2083ef97f8d', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'What does the term ''Normalization'' mean in databases?', N'Intern', N'Normalization is the process of organizing data in a database to reduce redundancy and improve data integrity. It involves dividing large tables into smaller, related tables and defining relationships between them.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6f6c3430-0a7c-43dc-b67e-f208c76d614c', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'How does Python manage memory?', N'Fresher', N'CPython uses a three-layer memory management system: 1. Reference Counting — Every object has a ob_refcnt field. When it drops to zero, memory is freed immediately. Handles ~99% of objects. 2. Cyclic Garbage Collector (gc module) — Handles reference cycles (e.g., a.ref = b; b.ref = a). Uses generational collection across 3 generations (thresholds: 700, 10, 10 by default). 3. PyMalloc Arena Allocator — For objects ≤ 512 bytes, CPython uses its own allocator (bypassing malloc) organized as: Arenas (256 KB) → Pools (4 KB) → Blocks (8–512 bytes in 8-byte increments). Use Case: A long-running data processing service tuned gc.set_threshold(1000, 15, 15) to reduce GC pauses on throughput-sensitive workloads, and used slots on hot objects to reduce per-instance memory from ~264 bytes to ~56 bytes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c38042c9-2320-463d-aa34-f209547120eb', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'How does Gin manage memory allocation for request contexts, and why is this important for high-throughput systems?', N'Senior', N'Gin uses a sync.Pool to reuse Context objects across requests, which significantly reduces garbage collection pressure by avoiding frequent allocations and deallocations. This pooling strategy is critical for maintaining low tail latency in systems handling high volumes of concurrent requests.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e94e1f56-3760-44c6-ad93-f20ba91019f6', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'What is the trade-off between using gRPC and REST for inter-service communication?', N'Middle', N'gRPC offers high performance through binary serialization and HTTP/2 multiplexing, making it ideal for internal service communication. REST is easier to implement, has better browser support, and is more human-readable, which makes it a better choice for public-facing APIs where interoperability is key.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ed3467f4-6762-4491-9c1e-f20c73a654aa', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'What is ''Write Skew'' and why is it often overlooked in standard isolation levels?', N'Senior', N'Write skew occurs when two transactions read the same data and make decisions based on that data, then perform writes that collectively violate a constraint, even though each individual write is valid. It is often overlooked because it is permitted under Snapshot Isolation, which is the default in many modern relational databases.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ce7edd43-560a-4364-bfbe-f20ed8cc2e8a', N'a2838158-7305-480a-b22b-4dc35776b400', N'What is the impact of replication lag on read-your-writes consistency in a distributed database?', N'Senior', N'Replication lag can lead to scenarios where a client reads stale data from a follower node after performing a write to the leader. To ensure read-your-writes consistency, the system must either route read requests to the leader or implement session-based consistency tracking to force reads from a node that has caught up with the write.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'65dcdfc0-4589-45f4-ab81-f20f4726c1b5', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'How are if expressions used in Kotlin as compared to Java?', N'Fresher', N'While both Kotlin and Java use if expressions to conditionally execute code, Kotlin offers more power and flexibility with its if expression. Key Differences - Return Type: In Java, you can only use if to conditionally execute statements. In contrast, Kotlin''s if can also return a value, similar to the Ternary Operator in Java. - Immutability: Kotlin''s if is an expression that produces a value, and that value is immutable once assigned. However, in Java, variables assigned within each if block can have different values outside the block. - When to Use: In Kotlin, the standard recommendation is to use if for simple or limited cases and use when for more complex and multifaceted scenarios.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7d866d34-fe32-402b-960e-f21040642c5e', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'How does Micronaut handle multi-tenancy at the architectural level?', N'Senior', N'Micronaut supports multi-tenancy through a tenant resolver abstraction that identifies the current tenant from request headers, cookies, or database patterns. It integrates with data sources to dynamically switch connections, ensuring that tenant isolation is maintained without hardcoding logic into business services.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
