INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'95086058-185b-41aa-bace-f211ebcf6755', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'What is the difference between a writable store and a readable store?', N'Fresher', N'A writable store allows both reading and updating the state from anywhere in the application. A readable store, on the other hand, is designed for data that should only be updated by the store itself, preventing components from manually modifying the state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'63f8c760-ae80-4dc4-95b9-f2170bc30086', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'What makes Rocket''s type-based design ''ergonomic''?', N'Middle', N'Rocket''s design is considered ergonomic because it reduces the need for manual type casting, error checking, and boilerplate code by leveraging Rust''s powerful type system. The framework infers intent from function signatures, allowing the developer to focus on the business logic rather than the plumbing of HTTP.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'57490f5a-d528-43c4-917e-f2190a84f43f', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'Why is Tailwind CSS considered ''opinionated'' about design systems?', N'Fresher', N'It provides a default, constrained design system that encourages consistency. By offering a pre-defined set of spacing, colors, and font sizes, it helps developers build cohesive interfaces without needing to make arbitrary decisions for every property.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3a25b52e-4025-40af-ab46-f219e9dec6d7', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'What is a ''DispatchQueue'' and how does it relate to concurrency?', N'Middle', N'A DispatchQueue is a FIFO queue to which your application can submit tasks in the form of blocks or functions. It manages the execution of these tasks either serially or concurrently across system-managed threads to perform background work without blocking the main thread.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'520c35f3-4ae0-4754-af4c-f21af383c028', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'When faced with an ''Error 500'' on a specific endpoint, what is your systematic approach to finding the cause?', N'Middle', N'I would begin by examining the server-side error logs to find the specific stack trace or error message associated with the timestamp. If logs are insufficient, I would check the application''s configuration and environment variables for mismatches. Finally, I would use a debugger or logging to inspect the request payload and headers to see if invalid input is triggering an unhandled exception.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'33ecebd5-d6ff-4191-a0d8-f21bca6ed06d', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'Why does changing ''display: none'' trigger a reflow while ''visibility: hidden'' does not?', N'Senior', N'Setting an element to display: none removes it from the render tree entirely, necessitating a full recalculation of the layout for neighboring elements. Visibility: hidden only affects the paint phase, as the element remains in the layout box model, occupying space despite being invisible.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'92881ea5-9335-401c-9ad9-f21bf9c9e231', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'When would you prefer to use Parallel Routes over standard nested routing?', N'Senior', N'Parallel Routes are ideal for complex dashboards or sites where multiple independent views need to be rendered simultaneously within the same page layout. They allow for independent loading states and error handling for each slot, which provides a more robust architecture for modular UI features.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'86d13a84-e5be-4eb5-991e-f22114ea1ee1', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'How does Nuxt optimize image loading?', N'Middle', N'Nuxt uses the ''nuxt-image'' module, which provides automated image resizing, format optimization, and lazy loading. It offloads the processing to an image provider, ensuring that users receive images sized appropriately for their device.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9dd54f87-00c8-4237-b90b-f222ecf8ea84', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'What is the difference between a query parameter and a path parameter in Echo?', N'Intern', N'A path parameter is part of the URL structure itself, used to identify a specific resource, while a query parameter is appended to the URL after a question mark and is typically used for filtering or sorting data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6b9f6e96-2564-4b7b-9a4f-f226ed9aa1d6', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'How does Astro''s build process leverage Vite, and what does this mean for plugin compatibility?', N'Senior', N'Astro uses Vite as its underlying bundler, which means any standard Vite plugin can be utilized for tasks like code minification or environment variable injection. This architecture ensures that developers can leverage the vast existing ecosystem of Vite tools without needing custom Astro-specific solutions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'01468b5b-7a6a-4f2a-92b4-f22b2b7e2911', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'What does a ''Left Join'' do?', N'Fresher', N'A Left Join returns all records from the left table and the matched records from the right table. If there is no match in the right table, the result will contain null values for those columns.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'41692fd5-aecd-480b-86fc-f22dd3b0218e', N'55404b9c-91b6-4b62-9dc7-63248e8ea1df', N'What is a circuit breaker pattern and why is it useful for scalability?', N'Middle', N'The circuit breaker pattern detects if a service is failing and prevents the application from repeatedly trying to call it, which would otherwise waste resources and increase latency. This prevents a cascading failure where one failing service causes the entire system to crash.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
