INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'83fd2507-dfd3-4fb0-9a3b-f2350546e4db', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'How would you optimize a Node.js application for high-throughput JSON parsing and serialization?', N'Senior', N'For large payloads, parsing JSON synchronously can block the event loop, so one should use streaming parsers or offload parsing to worker threads. Additionally, using optimized serialization libraries or moving data processing to a sidecar process can prevent the main application thread from becoming a bottleneck.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e283cc69-e094-4a94-806d-f2352862975d', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'What is the benefit of Lit''s ''batching'' updates?', N'Junior', N'Lit batches updates to ensure that even if multiple properties change at once, the component only re-renders a single time. This prevents unnecessary DOM churn and significantly improves application performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3191f5f9-3e75-4a92-8e15-f237fd5f890f', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'What is the role of an ASGI server like Uvicorn when running a FastAPI app?', N'Junior', N'ASGI stands for Asynchronous Server Gateway Interface, and it acts as the bridge between the web server and your Python application. Uvicorn is the server that listens for incoming HTTP requests, translates them into a format FastAPI understands, and sends the responses back to the client.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'85635a58-f7b5-40cd-8c71-f239240688c1', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'What is the purpose of the Eloquent ORM in Laravel?', N'Intern', N'Eloquent is an Object-Relational Mapper that allows you to interact with your database using PHP syntax instead of writing raw SQL queries. It treats database tables as classes and table rows as object instances, making data manipulation more intuitive and readable. This abstraction layer simplifies common tasks like creating, reading, updating, and deleting records.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'813fa736-b0ac-4e11-b79e-f239d71e044c', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'How does Ruby''s object model maintain memory efficiency despite everything being an object?', N'Senior', N'Ruby uses a ''Small Integer'' optimization (Fixnum) where integers are stored directly in the object reference pointer rather than allocating a separate heap object. This prevents excessive object creation for common operations, significantly reducing the pressure on the garbage collector.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'42bd425c-cf0f-4979-9c81-f23a7f88dcff', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'What is the function of the WAL receiver and sender processes?', N'Middle', N'In replication, the sender process on the primary node reads the WAL logs and streams them to the receiver process on the standby node. The standby then replays these changes to keep its data files synchronized with the primary node.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
