INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'974da173-b28d-4855-bc38-f23e413100dc', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'What is the ''CAP theorem'' in the context of distributed systems trade-offs?', N'Intern', N'The CAP theorem states that a distributed system can only guarantee two out of three properties: Consistency, Availability, and Partition Tolerance. Engineers must choose which two are most critical for their specific use case, as they cannot achieve all three simultaneously during a network failure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a6614eef-e1a0-46fb-8548-f23ea2402320', N'a2838158-7305-480a-b22b-4dc35776b400', N'How does the saga pattern manage distributed transactions across microservices without relying on distributed locks?', N'Senior', N'A saga manages a sequence of local transactions where each step publishes an event to trigger the next one. If a step fails, the saga executes a series of compensating transactions to undo the changes made by previous steps, ensuring eventual consistency instead of immediate atomicity.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
