INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'84a9b53d-54b7-4b92-aecb-f2531206818d', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'What is the impact of excessive dependencies in FastAPI routes?', N'Senior', N'While dependency injection is powerful, excessive nesting or redundant dependencies can lead to performance overhead due to repeated execution of the dependency tree. It is crucial to cache dependencies where appropriate using the ''use_cache'' parameter to avoid re-computing logic that does not need to run for every sub-dependency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fb5f3308-5b53-4bf3-959f-f256e98c7b7d', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'What is the purpose of the Eloquent ORM in Laravel, and how does it simplify database interactions?', N'Fresher', N'Eloquent ORM is an object-relational mapper that allows developers to interact with database tables using PHP classes rather than writing raw SQL queries. It maps database records to model objects, enabling you to perform CRUD operations through intuitive methods. This approach makes code more readable and abstracts away the complexities of different database systems.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'60cc6928-148d-4025-ae54-f25830eb782e', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'What are the trade-offs of using a custom routing key for indexing documents?', N'Senior', N'Custom routing allows queries to be directed to a specific shard, bypassing the need for a scatter-gather approach across all shards. While this significantly improves search performance for large clusters, it increases the risk of data skew, where some shards become much larger than others, leading to imbalanced resource usage.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a405ef7a-9413-4d41-a61b-f259b0941373', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'What is the significance of the ''onReady'' hook in production-grade Fastify apps?', N'Senior', N'The onReady hook ensures that all asynchronous plugin initialization is complete before the server starts accepting traffic. This is vital for microservices that depend on database connections or external caches being ready to prevent connection failures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
