INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0b8bb314-c9b5-4f25-a379-f277d38d20cf', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'What is ''Exclusive Access'' in Swift, and how does it prevent memory corruption?', N'Senior', N'Exclusive access is a runtime check that ensures no two parts of an application are modifying the same memory location simultaneously. If the compiler cannot prove exclusive access at compile-time, it inserts runtime checks to detect simultaneous read-write or write-write access. This prevents data corruption and undefined behavior that would otherwise occur in a multi-threaded environment.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
