INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'744b47c4-6714-4a38-be7d-f284fd90c66e', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'What is the risk of choosing an ''all-in-one'' framework compared to using a set of smaller, specialized tools?', N'Fresher', N'An all-in-one framework provides a standardized approach and many built-in features, which speeds up development. Using specialized tools provides more flexibility and prevents vendor lock-in, but requires more effort to integrate and configure correctly.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c0752659-2bdc-4136-b0fb-f285516bc557', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'How do ''Context Receivers'' change the architectural pattern of dependency injection?', N'Senior', N'Context receivers allow functions to declare implicit dependencies that must be provided in the calling scope without passing them as explicit arguments. This enables a more functional approach to dependency injection, reducing signature bloat, although it necessitates careful management to avoid hidden dependencies and maintain testability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'453b079f-35d9-485f-a03e-f28674a7ff60', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'Explain the impact of ''Type Tags'' and ''Class Tags'' on runtime type introspection.', N'Senior', N'Class tags provide access to the erased runtime class of a type, allowing for basic pattern matching on generic types. Type tags carry full type information, including nested generic arguments, which are otherwise lost due to erasure. Type tags are significantly heavier, as they involve capturing and passing around complex type metadata structures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'93b800d6-144d-4e14-bbf3-f2888d1a6bc6', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'What is ''loading.js'' in Next.js?', N'Intern', N'The loading file is a built-in feature that automatically creates a React Suspense boundary around your page content. It allows you to easily display a loading UI, such as a spinner or skeleton screen, while the page content is being fetched.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'123e5408-368d-4877-8f15-f28b5cefc77c', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'How does Gin compare to the standard library ''net/http'' package?', N'Junior', N'While the standard library is sufficient for basic tasks, Gin adds a layer of abstraction that simplifies routing, parameter parsing, and middleware management. It is designed to be significantly faster due to its custom HTTP router based on Radix trees.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5b23cf31-ce1d-475d-a1b8-f28d5ffce0e3', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'Describe the architecture of a ''Distributed Transaction'' using the Two-Phase Commit (2PC) protocol.', N'Senior', N'2PC involves a coordinator node asking participants to prepare their transaction and then instructing them to commit or abort. While it ensures atomicity across nodes, it creates a blocking situation if the coordinator fails, making it sensitive to network latency and node availability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3de6a41f-55bd-4eb7-80f5-f294d663b7e6', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'What is the ''Nothing'' type in Scala?', N'Intern', N'Nothing is a special type that is a subtype of every other type, but it has no instances. It is typically used to represent the return type of methods that never terminate normally, such as those that throw an exception.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7c3dc964-d03b-472d-9eb9-f2978553ae59', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'If you notice a bug in a piece of code written by a senior developer, how do you handle it?', N'Junior', N'I would first verify the bug by reproducing it in a controlled environment to ensure my understanding is correct. Then, I would politely bring it to the developer''s attention, explaining my findings clearly and offering to help fix it if appropriate.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'35e8b379-882c-4921-bda1-f29cef8f715c', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'What does Vite''s dependency pre-bundling achieve?', N'Middle', N'Pre-bundling converts CommonJS or UMD dependencies into ESM for browser consumption and collapses many small files into a single module. This reduces the number of network requests the browser makes during development, preventing page load bottlenecks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'393424ff-302a-4edb-a3c3-f2a1bb511da1', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'What is a ''404'' error in Express?', N'Intern', N'A 404 error occurs when a request is made to a route or resource that has not been defined in the Express application. It signifies that the server could not find the requested URL.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'48bf1f4d-0398-4733-bb82-f2a3f667c2b3', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'Can Preact be used without a build step?', N'Fresher', N'Yes, Preact can be loaded directly in the browser via a CDN link. This makes it very accessible for small experiments or quick prototyping without needing complex build tools.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
