INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4eb38580-9253-456b-b009-f2aea3f3e706', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'What is the role of the Program.cs file in ASP.NET Core?', N'Intern', N'The Program.cs file serves as the entry point for the application. It is responsible for configuring the host, setting up dependency injection, and building the request pipeline that handles incoming HTTP requests.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'515fe940-4b93-4345-8216-f2b034a9471c', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'What is the purpose of implementing a circuit breaker pattern in a distributed system?', N'Junior', N'The circuit breaker pattern prevents a service from repeatedly trying to execute an operation that is likely to fail. By failing fast when a downstream dependency is down, it protects the system from cascading failures and allows time for the failing service to recover.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6f3492a1-45c6-414b-85b0-f2b20df1fdd1', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'How does Phoenix PubSub facilitate horizontal scaling across multiple nodes in a distributed cluster?', N'Senior', N'Phoenix PubSub acts as a distributed message distribution system that can be configured with different adapters, such as Redis or PG, to propagate messages across nodes. This allows processes on one node to broadcast events that are seamlessly received by subscribers on other nodes, maintaining consistency in a distributed architecture.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fa3da34a-83be-43ae-8114-f2b6a2efd6a9', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'Why is avoiding global scope pollution critical for large-scale application scalability?', N'Senior', N'Global variables can lead to naming collisions, unpredictable state changes, and difficulty in tracking dependencies. Encapsulating code within modules or closures ensures that internal logic remains isolated, making the codebase easier to test, debug, and maintain as the application grows.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
