INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'539b53c8-3597-4a89-8335-f2b94f91bfe7', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'What are the advantages of using Async Hooks in a production monitoring context?', N'Senior', N'Async Hooks provide an API to track the lifetime of asynchronous resources, enabling deep observability into request tracing and context propagation. While powerful for building APM tools, they impose significant performance overhead due to the tracking of every asynchronous call. They should be used sparingly and with a deep understanding of their impact on the event loop.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
