INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7168038c-e7d4-4e47-82a5-f2c48feb02ec', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'Explain the architectural concept of ''Isolates'' in the context of V8 embedding.', N'Senior', N'An Isolate is an independent instance of the V8 engine, complete with its own heap and garbage collector. This architectural design allows developers to run multiple, isolated JavaScript execution environments within a single process, enabling safe concurrency without cross-talk between memory spaces.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1fbbd6ee-e430-441b-9de9-f2cab47667de', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'What is the main advantage of SolidJS for a developer?', N'Fresher', N'The main advantage is the combination of high performance and a simple mental model. By removing the Virtual DOM and using transparent, fine-grained reactivity, developers can write code that is both fast and easy to reason about.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a772e082-a2a9-4f25-9fb9-f2d0951e036e', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'What is the purpose of an EXPLAIN plan in MySQL?', N'Middle', N'The EXPLAIN command provides information about how the MySQL optimizer executes a query, including index usage, join order, and the number of rows scanned. It is a critical tool for identifying inefficient queries and optimizing database performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'65a8eca6-bdf4-4d4b-9afa-f2d2d1042799', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'Why might you prefer ''constexpr'' over ''const'' in C++?', N'Middle', N'While ''const'' only signifies that a variable cannot be changed after initialization, ''constexpr'' guarantees that the value can be evaluated at compile-time. This allows for better performance optimizations and the ability to use the value in contexts requiring constant expressions, such as array sizes or template arguments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'944233db-a979-4f1b-a543-f2d2ef3393fe', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'Explain the primary difference between Dart''s JIT and AOT compilation modes.', N'Middle', N'JIT compilation is used during development to enable fast cycles through hot reload by recompiling code on the fly. AOT compilation is used for production builds, converting Dart code into machine code to provide faster startup times and better performance on end-user devices.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b7f02de3-5bda-4bff-bccb-f2d356845d44', N'd5b12859-0c9f-4e2f-9b3a-1ccb6c5080e5', N'How does write-ahead logging (WAL) impact performance in large-scale databases?', N'Senior', N'WAL ensures data durability by recording changes to a log before updating the main data files, which is essential for crash recovery. While it adds sequential write overhead, it significantly improves performance by allowing the database to perform bulk asynchronous commits to the actual data storage.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ee3cc0b9-3f02-4530-90de-f2d401cab3a8', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'How to declare a class as a controller in Nest.js', N'Fresher', N'In Nest.js we can declare a class as a controller by using the @Controller() decorator. Here is a basic example. In this example the ExampleController is a controller class. @Controller(''example'') decorator tells Nest.js that this class is a controller that should handle requests to the example route. The @Get() decorator on the getHello method indicates that this method should handle HTTP GET requests.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'929914f1-d2de-4420-b6bf-f2d8a2aba903', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'Describe the lifecycle of an Ember component and how it interacts with the Glimmer render pipeline.', N'Senior', N'A component''s lifecycle moves through initialization, rendering, and destruction phases. During these phases, the Glimmer VM manages the insertion and removal of DOM elements, ensuring that hooks are triggered at the correct time to allow for efficient integration with third-party libraries.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1946a841-5d1e-4a51-a642-f2d92bc3ba8f', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'Can you perform joins in NoSQL databases?', N'Fresher', N'Most NoSQL databases do not support complex joins like SQL does. Instead, data is often denormalized, meaning related data is nested or embedded within a single document to avoid the need for joins during read operations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4e12124b-fe22-44a5-bba6-f2d9e61c3789', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'What is the advantage of using ''Transition'' in SolidJS for navigation?', N'Senior', N'Transitions allow for concurrent state transitions, meaning the UI can remain responsive while a new state is being calculated in the background. It effectively prevents the UI from showing a partial or loading state until the transition is ready, enhancing perceived performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8938f1b3-bf84-4c38-88db-f2da975795b6', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'How do you document your work so it is useful to others?', N'Junior', N'I document the ''why'' behind decisions, not just the ''what,'' to help others understand the reasoning behind a solution. I keep documentation up-to-date in a central location, such as a wiki or README, and ensure it includes clear instructions on how to set up and run the system.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c4bd17fc-c362-4cf4-8e73-f2dd33894596', N'8d34dfc0-4a64-4128-b41a-cafa62ddad41', N'What is the role of a Content Security Policy (CSP) in web application architecture?', N'Middle', N'CSP is an HTTP header that allows site operators to restrict the resources, such as scripts or images, that a browser is allowed to load for a given page. It acts as a defense-in-depth layer to mitigate Cross-Site Scripting (XSS) attacks by preventing the execution of unauthorized malicious code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2d52d96d-5f59-427b-a23d-f2e08a1802b8', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'How does Gin''s router handle path parameters like '':name''?', N'Middle', N'Gin uses the colon syntax to denote named path parameters, which the router parses and stores in the Context. These parameters can then be easily retrieved by name within the handler, allowing for dynamic URL patterns without complex regex parsing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'652f8c51-2478-4f9b-85a3-f2e389c53c9f', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'Does Preact support props validation?', N'Fresher', N'Preact does not have built-in props validation like some other libraries. However, developers can use external tools or TypeScript to enforce type safety and props validation in their components.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6c55e6f1-9806-4485-85ff-f2e4752d8f56', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'How does Fiber support streaming responses?', N'Middle', N'Fiber supports streaming by allowing developers to set a response body as an io.Reader or by using a custom stream handler. This enables the server to send data in chunks to the client, which is essential for large file downloads or long-running server-sent events.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3612d7e0-3a9c-47fb-b13c-f2e88fd3c188', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'How does Tree Shaking work, and what are the requirements to enable it?', N'Middle', N'Tree shaking is an optimization technique that removes dead code by analyzing the static structure of ES modules. To enable it, your project must use ES module syntax (import/export) and ensure that your minifier, such as Terser, is configured to identify and prune unused exports.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4df84a92-e795-4732-95a6-f2e93ae4a612', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'What does ''platform-agnostic'' mean in the context of NestJS?', N'Intern', N'Platform-agnostic means that the NestJS core is decoupled from the underlying HTTP server framework. This allows the same application code to run on different platforms, such as Express or Fastify, without requiring significant changes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ff664d3f-88df-4622-b128-f2ec7d34ceda', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'What are the trade-offs of using Tailwind in a project that requires heavy dynamic theming?', N'Senior', N'Tailwind is built around static configuration, so changing themes at runtime requires either CSS variables or toggling class names on a parent container. While effective, it requires a clear strategy for mapping design tokens to CSS custom properties to ensure that the utility classes remain functional across all theme states.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3175543c-cbb5-4e27-8603-f2ec974b065a', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'What is the primary benefit of Quarkus''s ''Build Time'' optimization?', N'Intern', N'Quarkus performs much of its configuration and dependency injection processing during the build phase rather than at runtime. This shifts the computational load away from startup, allowing the application to start significantly faster.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0fac5312-1c68-438a-8214-f2f082f53fd9', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'What is the significance of the ''Engine'' concept in Ember?', N'Middle', N'Engines are a way to isolate parts of an application into distinct, independently deployable or lazy-loadable modules. They allow large teams to work on separate features with their own routing, services, and components while sharing a common application infrastructure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ce4dc497-bbc1-4059-9a64-f2f239adc6d9', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'What are the major features of React?', N'Intern', N'React offers a powerful set of features that have made it one of the most popular JavaScript libraries for building user interfaces: Core Features: - Component-Based Architecture: React applications are built using components - independent, reusable pieces of code that return HTML via a render function. This modular approach enables better code organization, reusability, and maintenance. - Virtual DOM: React creates an in-memory data structure cache, computes the resulting differences, and efficiently updates only the changed parts in the browser DOM. This approach significantly improves performance compared to direct DOM manipulation. - JSX (JavaScript XML): A syntax extension that allows writing HTML-like code in JavaScript.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c2d8054e-0a1c-4180-8737-f2f23b73af28', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'How does FastAPI handle Dependency Injection (DI) and what are the benefits for system scalability?', N'Senior', N'FastAPI''s DI system allows for the decoupling of business logic from infrastructure concerns like database sessions or authentication providers. This promotes testability by enabling the easy swapping of production dependencies with mocks and improves maintainability by centralizing shared resources, ensuring that components remain modular as the application architecture grows.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'edd7aa1c-77e0-4c07-b539-f2f2c4095333', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'Discuss the mechanism and risks associated with dynamic memory allocation in C.', N'Senior', N'Dynamic allocation uses the heap to provide memory with a lifetime controlled by the programmer, rather than the function call stack. The primary risks involve memory leaks, double-frees, and heap fragmentation, as C provides no automated garbage collection or RAII-style scope management.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'83cbd591-5045-4260-a11a-f2f3d1bf25ff', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'What are the memory implications of high fiber concurrency?', N'Middle', N'While fibers are lightweight, each one still consumes some memory for its stack and control block. If an application spawns an unbounded number of fibers without proper resource limits, it can still lead to memory pressure or out-of-memory errors.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7b68cea2-4a1f-4b86-80fb-f2fc059858e9', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'What is the role of an AWS Region in DynamoDB?', N'Intern', N'DynamoDB data is replicated across multiple Availability Zones within a single AWS Region to ensure high availability and durability. This protects against the failure of any single data center.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
