INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cf5ba910-35ba-4f6f-b019-f2fe9be22750', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'What is a PHP constant?', N'Intern', N'A constant is an identifier for a simple value that cannot be changed during the execution of a script. Once defined, a constant remains the same throughout the entire program.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0e6bd237-e3a1-44af-97d0-f3013a014de5', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'How does Nuxt 3''s hybrid rendering strategy improve scalability for content-heavy sites?', N'Senior', N'Hybrid rendering allows developers to define rendering strategies per route, such as static site generation for blog pages and server-side rendering for dynamic user dashboards. This approach optimizes server resources and improves performance by serving static assets from the CDN while reserving expensive compute for pages that require real-time data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9bb5783c-099e-422d-8b97-f301506763f5', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'What is the purpose of the Django admin interface?', N'Intern', N'The Django admin interface is an out-of-the-box feature that provides a ready-to-use web interface for managing your application''s data. It allows authorized users to create, read, update, and delete records directly from the database through a graphical interface.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5e966a24-f487-4d57-bb9e-f3020f0ad74d', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'How do you approach estimating the time impact of introducing a new third-party dependency into your system?', N'Middle', N'I evaluate the dependency''s documentation, community support, and integration complexity. I add time for vetting the security and stability of the package, and I include a buffer for handling potential integration issues or unexpected behavior that might deviate from our system''s standards.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b5e01053-8282-4d96-b48a-f30594c90778', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'What is an index in MySQL?', N'Intern', N'An index is a database structure that improves the speed of data retrieval operations on a table. It works similarly to an index in a book, allowing the database engine to find specific rows without scanning every row in the table.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd9c13317-d14a-4b36-a457-f307debd2965', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'What does ''near real-time'' search mean in Elasticsearch?', N'Intern', N'It means there is a slight latency between the time a document is indexed and the time it becomes searchable. Typically, this latency is one second, after which the document is refreshed and available for search.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'78da0a87-3800-4e8a-9c73-f30858fcbce8', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'What is the difference between Read Committed and Serializable isolation levels?', N'Junior', N'Read Committed prevents dirty reads but allows non-repeatable reads and phantom reads. Serializable is the highest level of isolation, which prevents all of these issues by ensuring transactions act as if they are executed in a strictly sequential order.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0d9fe02a-3293-499b-9898-f30be71820b8', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'If a user says ''the system is broken,'' how do you get actionable information?', N'Fresher', N'I would ask clarifying questions to understand what the user was trying to do, what they expected to happen, and what actually occurred. I would also ask for screenshots, time stamps, or any error messages they may have encountered to narrow down the scope.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'51e8e261-0265-4361-af44-f30e928ed5a4', N'075b8862-431c-4678-9767-f55359758a4a', N'What is a Vue plugin?', N'Junior', N'A plugin is a self-contained code module that adds global-level functionality to a Vue application. Plugins can add global methods, directives, or mixins, and are typically installed using the app.use method.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b53701f3-73f7-4258-9ad3-f310620361d4', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'What is the ''app.config'' object used for?', N'Fresher', N'The app.config object is used to store configuration variables for your application, such as secret keys, database connection strings, or debug flags. It allows you to keep settings separate from your application logic, making it easier to manage different environments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'75e72590-8e10-4b1e-a7ca-f310f943aa58', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'What is the impact of ''hot partitions'' on DynamoDB performance?', N'Middle', N'Hot partitions occur when a specific partition receives a disproportionately high volume of read or write traffic compared to others. This leads to request throttling even if the overall table capacity is not exceeded, usually caused by poor partition key design.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd559bd79-cd8d-4b95-8aec-f31197722041', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'What is the benefit of using Gin''s ShouldBind methods over Bind?', N'Senior', N'ShouldBind methods return an error instead of automatically calling c.AbortWithError, which gives the developer more control over the response format. This allows for cleaner, more idiomatic error handling in scenarios where you want to return a specific JSON error structure to the client.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'eca32462-47c0-47a9-be05-f311a1bd7b0e', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'What is the ''super'' keyword?', N'Intern', N'The super keyword is used to refer to the immediate parent class object. It allows a subclass to call methods or access constructors defined in its parent class.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'753fe603-0507-4ebd-af99-f3154ef0d097', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'Why should you use an interface instead of a concrete class in your design?', N'Fresher', N'Using an interface decouples the implementation from the abstraction, allowing for greater flexibility and easier testing. It enables you to swap different implementations of the same logic without changing the client code that depends on the interface.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8e61cac9-6afb-4e17-a8d0-f31652186eb3', N'd5b12859-0c9f-4e2f-9b3a-1ccb6c5080e5', N'Why is ''eventual consistency'' an acceptable trade-off for many web applications?', N'Middle', N'Eventual consistency allows systems to remain highly available and performant by not requiring immediate synchronization of all data copies. For many applications, such as social media feeds, a delay of a few milliseconds in data propagation is acceptable for the gains in system throughput.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6c8f7371-4a0d-46a6-9ce0-f3177002e97d', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'Why would you use an Ecto Query instead of raw SQL?', N'Junior', N'Ecto Queries provide a type-safe and composable way to interact with the database. They prevent SQL injection vulnerabilities by design and allow developers to build complex database queries using Elixir syntax that is easier to maintain and test.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'93508659-1619-42ae-91db-f319cc786c58', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'What is a pure virtual function?', N'Fresher', N'A pure virtual function is a function declared in a base class with no implementation, indicated by assigning it to zero. It mandates that any non-abstract derived class must provide its own implementation for that function.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'27989352-2094-4f0a-9d12-f31e605548af', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'What are the scalability risks of using Preact''s ''render'' function on large existing DOM structures?', N'Senior', N'If Preact is injected into a massive, non-Preact managed DOM tree, the reconciliation process may struggle to reconcile existing nodes effectively. This can lead to unexpected DOM recreation if the existing structure does not match the expected virtual DOM tree, causing unnecessary browser layout cycles.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'508c3aac-d158-421d-9279-f31e92012504', N'8d34dfc0-4a64-4128-b41a-cafa62ddad41', N'What role does a Hardware Security Module (HSM) play in cloud architecture?', N'Middle', N'An HSM provides a physically secure environment for performing cryptographic operations and managing sensitive keys. It is used to ensure that master keys are never exposed in memory or plain text, providing high-assurance security for data encryption.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'96c23d47-926f-42ee-9c8c-f31eb7df2fa3', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'How does Dart achieve interop with foreign code (FFI) without sacrificing type safety?', N'Senior', N'Dart FFI uses a bridge that maps C-style data structures to Dart objects while enforcing strict type definitions at the boundary. The runtime ensures that memory management and calling conventions are handled correctly, often requiring manual memory management for heap-allocated foreign objects to prevent memory leaks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'142a80da-205c-421d-8d5d-f31f73219e32', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'What is the role of the Dart VM?', N'Fresher', N'The Dart Virtual Machine (VM) is the runtime environment that executes Dart code. It manages memory, garbage collection, and provides the JIT compiler used during the development cycle.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'59faa0f8-b647-4cdf-b441-f31ff905886d', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'You are tasked with a new feature that has a tight deadline, but you realize the current technical debt will make implementation difficult. What do you do?', N'Junior', N'I would communicate the risks to my manager immediately, highlighting the trade-off between speed and long-term maintainability. I would propose a phased approach where we implement a functional MVP first and schedule a dedicated follow-up task to refactor the technical debt.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2322608e-6863-4ae7-ac76-f3209f81f375', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'Explain the concept of ''Utility-First'' architecture and its impact on development speed.', N'Middle', N'Utility-first architecture involves building interfaces by composing small, single-purpose classes directly in the markup. This eliminates the need to invent class names or manage separate CSS files, significantly speeding up the prototyping process and reducing context switching between files.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cc569b97-4757-4eff-a4f5-f320af320b4a', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'What is meant by vectorization in R?', N'Intern', N'Vectorization is the ability of R to perform operations on an entire vector at once without needing to write explicit loops. This makes code more concise and significantly faster by leveraging optimized internal routines.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b28c3ef8-41c3-4dc4-9d01-f321bd3c13e0', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'What is the ''components'' directory auto-import feature?', N'Junior', N'Nuxt automatically scans the components directory and registers components globally. This means you do not have to manually import components into your pages or other components to use them.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'aa76dfe5-464a-4d19-95b0-f32342a05b10', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'How do you handle timeouts in Actix-web?', N'Junior', N'Timeouts can be configured at the server level using the client_timeout or server_timeout properties. This prevents slow clients or stalled requests from holding onto worker threads indefinitely.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'58e96392-4050-431c-a09a-f3261e0d7763', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'Explain the performance implications of using Shadow DOM in Lit components.', N'Senior', N'Shadow DOM provides CSS encapsulation, which prevents global styles from leaking into components and improves performance by reducing the scope of style recalculations. However, it can complicate global theme integration and requires specific mechanisms like CSS variables or adoptedStyleSheets for cross-boundary styling.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'66a6b6fe-b859-44c9-808d-f326ecabcf16', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'How do Litestar''s ''After Request'' and ''Before Request'' hooks differ from standard middleware?', N'Middle', N'Hooks are specifically tied to route handlers or controllers, providing a more targeted execution context than middleware. They are ideal for cross-cutting concerns like logging or modification of responses that only apply to specific subsets of the application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b8153849-0996-4baf-a56b-f32706afeabe', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'Discuss the trade-offs of using a large number of indexes on a single collection.', N'Senior', N'While indexes speed up read operations, every write operation must update every index associated with the collection. Too many indexes lead to increased write latency, higher memory consumption, and a larger working set, which can eventually force the database to page data in and out of disk frequently.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1c84a4d8-def1-452e-a054-f3274c4f4578', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'How do you perform optional binding in Swift?', N'Fresher', N'Optional binding is performed using ''if let'' or ''guard let'' syntax to check if an optional contains a value. If the optional has a value, it is unwrapped and assigned to a temporary non-optional constant, allowing safe access.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b0ffed7c-10f0-47de-bbfe-f3288056682d', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is a Progressive Web App (PWA)?', N'Intern', N'A Progressive Web App (PWA) is a highly optimized website built with modern web technologies that delivers a native-like app experience directly through a web browser. It bridges the gap between the reach of traditional websites and the advanced functionality of platform-specific mobile or desktop applications It uses modern web APIs and progressive enhancement strategies to deliver an app-like experience — including offline support, push notifications, and home-screen installation — directly through a browser, without an app store.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'60301fc2-5435-4bfe-ad63-f329e9f03970', N'f2e963ff-7635-4429-a389-4d92535fb972', N'What is the <base> tag in HTML and how does it affect URLs?', N'Intern', N'The element specifies the base URL for all relative URLs in a document. It must be placed inside and there can only be one per page. Syntax: How it affects relative URLs: target attribute on : Sets the default target for all links on the page: Important caveats: - Fragment-only links (href="#id") are affected — they resolve relative to the base URL, not the current page. To avoid this, use full URLs for fragment links when is set. - Only one tag is allowed per document.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a5545bf1-5a1f-436d-aa06-f32f658b559e', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'Explain the concept of database sharding and its primary challenges.', N'Middle', N'Sharding is a horizontal partitioning strategy that splits data across multiple physical database instances to improve scalability. The main challenges include managing cross-shard joins, maintaining data consistency, and rebalancing data as the cluster grows.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3e9858aa-abe8-4377-9857-f33276d4134e', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'Does Hono support static file serving?', N'Fresher', N'Yes, Hono includes a dedicated middleware for serving static assets like images, CSS, or client-side JavaScript files. This allows the framework to serve a complete web application including frontend resources.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd5edabd5-21d4-4e8e-89bd-f332b57c4c65', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'What is hydration in the context of SvelteKit?', N'Intern', N'Hydration is the process where the client-side JavaScript attaches to the server-rendered HTML. This makes the static page interactive by enabling event listeners and Svelte''s reactivity.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7ecd0a2b-1585-46e9-9efb-f33480539507', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'When should you use ''readonly'' properties in an interface?', N'Middle', N'The ''readonly'' modifier should be used when you want to enforce immutability for specific properties after an object is initialized. It helps prevent accidental state mutation, which is particularly beneficial in architecture patterns like Redux or when passing configuration objects that should not be altered.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ef91508d-c93a-4623-8125-f33620627a69', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'What is the primary benefit of transaction management?', N'Intern', N'The primary benefit is data integrity. By ensuring that operations are grouped correctly, transactions prevent partially completed updates that could lead to inaccurate reports, lost data, or system errors.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd83d2cca-257f-4182-a956-f3381bd3782e', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'What is a ''Tombstone'' in the context of NoSQL storage engines?', N'Middle', N'A tombstone is a marker placed on a data record during a delete operation in systems like LSM-tree based engines. Since data files are often immutable, the system cannot physically delete the record immediately, so it uses the tombstone to indicate that the record is logically deleted until the next compaction cycle.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'884e82ec-bdf8-453f-89de-f33979b083a1', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'Explain the trade-offs of using Eager Loading versus Lazy Loading in Active Record.', N'Senior', N'Eager loading prevents N+1 query problems by fetching associated records in advance, which reduces database round-trips but increases memory consumption. Lazy loading is more memory-efficient for small datasets but can cause significant latency if it triggers numerous individual queries during object traversal.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1e731e86-a562-46e8-993e-f342a2601653', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'How does the Svelte compiler handle ''unused'' code?', N'Middle', N'The compiler performs static analysis during the build process to identify and remove unused code from the final output. This tree-shaking is more effective in Svelte because the framework knows exactly which parts of its own library are needed based on the component''s requirements.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'57f7c468-7982-4d01-8fcc-f3473ffd3110', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'Why shouldn''t you destructure props in SolidJS?', N'Fresher', N'Destructuring props in SolidJS breaks the reactivity connection. Because props are getter functions, accessing them directly through the props object is required to track changes correctly.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4c19490f-f513-4038-b872-f347684d228c', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'How does Dart achieve platform interoperability with C or C++?', N'Middle', N'Dart uses ''dart:ffi'' (Foreign Function Interface) to call into native C libraries directly. This allows developers to leverage existing high-performance native code or system-level APIs without needing to write custom platform-specific wrappers for every call.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ece6e667-a07a-4dd2-9f57-f34849384ee2', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'How does Preact''s internal architecture differ from React''s regarding the virtual DOM implementation?', N'Senior', N'Preact utilizes a lightweight virtual DOM implementation that prioritizes minimal memory footprint and fast diffing over the extensive feature set found in React. By using a more direct approach to component mounting and updates, Preact avoids the complex Fiber architecture, focusing on a flatter structure that reduces object allocation overhead.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'201ec6ee-6fc9-45e5-8cf2-f34b8059b86f', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'Is Hono a full-stack framework?', N'Intern', N'Hono is primarily a backend web framework. While it can be used to serve HTML and interact with frontend assets, it does not manage client-side state or complex frontend rendering like a full-stack framework such as Next.js.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'020a0590-9177-49b5-8835-f34c17efad6c', N'f2e963ff-7635-4429-a389-4d92535fb972', N'Why is character encoding important?', N'Junior', N'Character encoding defines how the computer translates binary data into readable text. Specifying UTF-8 in the head ensures that characters from different languages and special symbols are rendered correctly across all browsers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'52047e74-9017-46f8-b5fd-f34d50bfd3af', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'How does the CAP theorem influence the design of a distributed database?', N'Middle', N'The CAP theorem states that a distributed system can only guarantee two out of three properties: Consistency, Availability, and Partition Tolerance. Architects must decide if they prioritize data correctness in the face of network failures or system uptime.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'66daf655-6aab-494d-b57a-f34dc0f3c23c', N'fcd5873e-c89a-47d6-bb4c-c60b57c2ede1', N'How does cache invalidation impact system complexity?', N'Middle', N'Cache invalidation is the process of removing or updating stale data in the cache to ensure consistency with the source of truth. It is considered one of the hardest problems in computer science because ensuring that all caches are synchronized after a write without sacrificing performance is extremely difficult.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cdfa058c-1e99-4e8a-b681-f34fd6fc1c03', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'What is the purpose of a Controller?', N'Intern', N'A controller serves as the intermediary between the incoming HTTP request and the business logic of your application. Its main job is to process the request, interact with models if necessary, and return a response to the user.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e3b9d1f8-f2bc-435f-9ac4-f3502854def9', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'What is the ''c.Next()'' method used for in middleware?', N'Junior', N'The ''c.Next()'' method allows middleware to pause its execution, pass control to the next handler or middleware in the chain, and then resume execution once the downstream tasks are finished.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b59cb771-8beb-4c8f-b1c9-f3520fed7797', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'If a task involves learning a new tool, how does that affect your estimate?', N'Fresher', N'Learning a new tool introduces a ''learning curve'' factor that increases the initial effort. I would add time for exploration, reading documentation, and potentially creating a small proof-of-concept. It is important to communicate that the first instance of using a tool will always take longer than subsequent uses.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e26afad5-b33b-44fe-bcee-f35361634ec5', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'What is the difference between a constant and a variable?', N'Fresher', N'A variable can change its value during script execution, whereas a constant remains fixed once defined. Constants are defined using the define function and do not start with a dollar sign.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7bc5c662-6fe5-4ad8-9b58-f355a1b08045', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'Why do you not need error boundaries for event handlers?', N'Fresher', N'Error boundaries do not catch errors inside event handlers. React doesn’t need error boundaries to recover from errors in event handlers. Unlike the render method and lifecycle methods, the event handlers don’t happen during rendering. So if they throw, React still knows what to display on the screen. If you need to catch an error inside an event handler, use the regular JavaScript try / catch statement: Note that the above example is demonstrating regular JavaScript behavior and doesn’t use error boundaries.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'877da3a5-345f-4531-9e9b-f35688eccebd', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'How does the ''Fragment'' component work in Preact?', N'Middle', N'Fragments allow you to group multiple children without adding an extra node to the DOM tree. Preact implements this as a simple wrapper that the reconciler ignores during the rendering process, which helps keep the DOM structure clean and semantic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dbd5c72c-5d3d-486a-8a35-f357b59d5aeb', N'24c74bdc-c63e-4370-b1ac-bd560cb834d6', N'How do you handle API security in the context of service-to-service communication?', N'Senior', N'Use mTLS (mutual TLS) to ensure both authentication and encryption between services, often managed by a service mesh. Additionally, propagate identity tokens (like JWTs) through the request chain so downstream services can enforce fine-grained authorization based on the original user context.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'952a0a1d-58d9-4298-8316-f3590c650cbe', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'What is the purpose of an alias in SQL?', N'Fresher', N'An alias is a temporary name given to a table or a column for the duration of a specific query. It makes the output more readable and simplifies queries involving multiple tables.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5d8af6a6-4c6b-4bd7-9742-f3600858194d', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'How do Generics improve type safety in Java?', N'Middle', N'Generics allow developers to specify the type of objects a collection will hold at compile-time. This eliminates the need for manual type casting and catches potential type-mismatch errors during compilation instead of at runtime.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ee96e361-243d-4ad0-b66e-f361f973ad9d', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'What are the trade-offs of using asynchronous messaging over synchronous HTTP communication in a microservices environment?', N'Senior', N'Asynchronous messaging decouples services, increasing system availability and throughput by buffering requests, though it introduces complexity in error handling and observability. Synchronous communication is simpler to implement and debug but creates tight coupling and potential latency bottlenecks if dependencies fail.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd0217108-8249-4d91-b77b-f363db41d707', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'How does the ''Doublewrite Buffer'' protect data integrity in MySQL?', N'Middle', N'The Doublewrite Buffer is a storage area where InnoDB writes pages before flushing them to the actual data files. If a crash occurs during a partial page write, InnoDB can recover the page from the doublewrite buffer to prevent data corruption.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'50b99eb3-5075-428f-a6f6-f364fd60a6a8', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'Can you describe the main difference between a .forEach loop and a .map() loop and why you would pick one versus the other?', N'Fresher', N'To understand the differences between the two, Let us look at what each function does. 1. Array.forEach(): * Iterates through the elements in an array. * Executes a callback for each element. * Does not return a value. 2. Array.map(): * Iterates through the elements in an array. * "Maps" each element to a new element by calling the function on each element, creating a new array as a result. The main difference between .forEach and .map() is that .map() returns a new array. If you need the result, but do not wish to mutate the original array, .map() is the clear choice. If you simply need to iterate over an array, forEach is a fine choice. &#9885; Try this example on CodeSandbox', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ae96e46c-6229-4e37-b961-f3677509570e', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is a first order function', N'Intern', N'A first-order function is a function that doesn’t accept another function as an argument and doesn’t return a function as its return value. i.e, It''s a regular function that works with primitive or non-function values.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'087dc028-abcf-43eb-8b46-f36c7e8d7e7c', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'What are API Resources and why should they be used in a RESTful API?', N'Middle', N'API Resources provide a transformation layer between your Eloquent models and the JSON responses returned to the client. They allow you to control the structure of the output, hide sensitive fields, and ensure consistent API responses across the entire application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7e473fca-78df-4674-ad90-f36e80479b48', N'075b8862-431c-4678-9767-f55359758a4a', N'What is the difference between computed properties and watchers in Vue?', N'Middle', N'Computed properties are cached based on their reactive dependencies and are used for calculating derived state. Watchers are more suited for performing side effects, such as asynchronous operations or manual DOM manipulations, in response to data changes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3e582ae0-1e3e-4717-8982-f36fb24e34be', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'Why should you avoid using ''window'' or ''document'' directly in Nuxt components?', N'Senior', N'These browser APIs do not exist in the Node.js server environment used for SSR, which will cause the build or execution to fail. You must either guard these calls with an ''if (process.client)'' check or use the ''onMounted'' hook to ensure they only execute after the component is rendered in the browser.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e0ef8880-6731-4c51-9f7d-f36fd960cac1', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'What is a cluster state in Elasticsearch?', N'Intern', N'The cluster state is a data structure that keeps track of the entire cluster''s configuration and metadata. This includes information about indices, shards, and the current nodes participating in the cluster.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3065d256-59c7-43dc-910a-f36fe7d38e4c', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'What is the difference between a serial type and a generated identity column?', N'Junior', N'The SERIAL type is an older PostgreSQL feature that creates a sequence automatically linked to a column. A generated identity column is the modern, SQL-standard compliant way to achieve the same result, offering better control and cleaner syntax.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6f7780a1-4fb2-4afb-b689-f372f1beb4d5', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'What is the role of the Service Container in Laravel and why is it important?', N'Middle', N'The Service Container is a powerful tool for managing class dependencies and performing dependency injection. It allows for decoupling components, making the application easier to test, maintain, and extend by managing the instantiation of objects.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0bf3ed65-85cf-4fa1-92aa-f3735f211f6f', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'What are the architectural advantages of using Fiber in a microservices environment?', N'Senior', N'Fiber''s low footprint and high throughput make it ideal for microservices that need to handle high traffic with minimal resource allocation. Its modular middleware system allows for easy standardization of observability and security patterns across multiple independent services.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'66b9900b-6803-4797-afa9-f378e73a59e8', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'Why might you choose a cache over querying a database directly for every request?', N'Fresher', N'Caching reduces latency and lowers the load on the database by serving frequently accessed data directly from memory. This approach improves application responsiveness and protects the database from being overwhelmed by repetitive read operations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5a80fde8-41f0-45d8-bbe6-f37969096734', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'How do you decide between deploying to a container orchestration platform versus serverless functions?', N'Middle', N'I use serverless functions for event-driven, sporadic, or short-lived tasks to minimize costs and operational management. I choose containers for long-running services, predictable workloads, and applications requiring complex environment configurations or specific runtime dependencies.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
