INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3798f241-2eee-4517-903e-f37fe5052b14', N'210c7148-726e-4e8b-bf12-40be36e55130', N'What is a lifetime and how does it relate to references?', N'Intern', N'Lifetimes define the scopes in which references are valid. The Rust compiler uses this information to ensure that references outlive the data to prevent dangerous scenarios such as dangling pointers. Each Rust value and its associated references have a unique lifetime, calculated based on the context in which they are used. Three Syntax Ways to Indicate Lifetimes in Rust 1. ''static: Denotes a reference that lives for the entire duration of the program. This is commonly used for string literals and certain static variables. 2. &''a T: Here, ''a is the lifetime annotation. It signifies that the reference is valid for a specific duration, or lifetime, denoted by ''a. This is often referred to as explicit annotation. 3.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5bf1b8a3-48ef-449f-ac76-f38054f2eb11', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'Why is Node.js considered single-threaded?', N'Intern', N'Node.js is single-threaded because it runs all JavaScript code on a single main thread. It offloads heavy operations, such as file system access or network requests, to the system kernel or a worker pool to maintain responsiveness.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'da6d38e7-7a3b-4450-9ee4-f382206c45ec', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'How do you weigh the benefits of caching against the complexity of cache invalidation?', N'Middle', N'Caching provides massive performance gains by reducing database load and latency, but it introduces the ''cache invalidation'' problem, which is notoriously difficult to solve. The trade-off involves deciding if the performance gain is worth the risk of serving stale data or the engineering effort required to maintain cache consistency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'acb122c7-b717-421b-8682-f3835850cdc3', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'What is the difference between an Exception Filter and Middleware?', N'Intern', N'Exception filters are specific to MVC actions and are used to handle errors within the controller layer. Middleware runs for all requests entering the application pipeline, making it a more global way to handle errors.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ae1b81e7-3d76-4f83-a0dd-f384c0a2819f', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'What is the purpose of the UNION operator?', N'Fresher', N'The UNION operator is used to combine the result sets of two or more SELECT statements into a single result set. It removes duplicate rows by default, whereas UNION ALL includes all duplicates.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'da4531f0-68d9-49ba-bccc-f387b6fe7d47', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'What approach do you take when troubleshooting a performance regression discovered after a new release?', N'Middle', N'I compare metrics from before and after the deployment to isolate the scope, such as increased latency in a specific endpoint or memory growth. I would examine diffs in the codebase related to resource-heavy operations and utilize profiling tools to identify the specific logic causing the slowdown.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'752dfb7e-07fd-403e-beb2-f387b96e9bc4', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What are the trade-offs of using prototype-based inheritance versus class-based inheritance?', N'Middle', N'Prototype-based inheritance is more memory-efficient because methods are shared across all instances via a shared object rather than being duplicated. Class-based syntax provides better readability and familiarity for developers coming from static languages, though it is ultimately syntactic sugar over the prototype chain.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dc404571-48aa-4a4f-a455-f38bb49e9e8d', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'What is the purpose of the ''GetItem'' operation?', N'Junior', N'The GetItem operation retrieves a single item from a table using its primary key. It is the most efficient and cost-effective way to retrieve a specific record when you know its unique identifier.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'19d9b719-7778-4df2-bdc2-f38e1180f0a6', N'24c74bdc-c63e-4370-b1ac-bd560cb834d6', N'What is the difference between authentication and authorization in API design?', N'Middle', N'Authentication verifies the identity of the user or client making the request, typically via tokens or API keys. Authorization determines what resources that authenticated entity is allowed to access or modify, ensuring the principle of least privilege is maintained.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ac5a9e70-915f-4e5c-b758-f38e6d71e86e', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'What is the difference between ''var'' and ''final''?', N'Junior', N'Var is used for variables whose values can be changed later, with the type inferred by the compiler. Final is used for variables that are assigned once and cannot be reassigned after their initial value is set.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3cc626e3-a29c-4ae7-8d81-f39071053823', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'How do Axum''s ''IntoResponse'' trait implementations affect API design?', N'Senior', N'The IntoResponse trait allows developers to define custom types that automatically convert into valid HTTP responses, including headers and status codes. This enables a domain-driven design where domain errors can be mapped to specific HTTP responses centrally, keeping handlers clean and focused on business rules.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f4d35b4b-0c97-42f0-8944-f3928f979d03', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'Discuss the implications of the ''Garbage Collection'' pause time on high-frequency trading or real-time UI applications.', N'Senior', N'GC pauses block the main event loop, causing frames to be dropped in UIs or latency spikes in time-sensitive tasks. Senior developers mitigate this by reducing object churn, reusing objects, and preferring stack-allocated structures to keep the heap pressure low and pauses infrequent.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'256ccd72-f4e8-42e0-abb7-f393a46ce400', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'What is the benefit of using Echo''s built-in JSON renderer?', N'Intern', N'The built-in JSON renderer simplifies the process of serializing Go structs into JSON format. It handles the marshaling process and sets the correct headers, reducing the amount of boilerplate code required.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'91656740-b784-4caf-be86-f3952d693b26', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'How does Ruby''s method lookup path (ancestors chain) function when modules are included versus prepended?', N'Middle', N'When a module is included, it is placed in the lookup chain immediately after the class itself. If a module is prepended, it is placed before the class, allowing it to override methods defined within the class. This mechanism provides a powerful way to implement decorators or intercept method calls without modifying the original class source.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c2f62571-6039-4e00-9ff8-f396ebb96801', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'What is a Global Secondary Index?', N'Intern', N'A Global Secondary Index (GSI) can have a different partition key and sort key than the base table. It can be created at any time and allows you to query data across all partitions of the table.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c4cd4e1b-87e3-4e44-b479-f396f2abcf37', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'How does TypeScript handle type assertions?', N'Fresher', N'Type assertions are a way for the developer to tell the compiler to treat a value as a specific type, overriding the compiler''s inference. It is used when you know more about the type of a value than the compiler does, but it does not perform any actual runtime type conversion.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'38847306-9f57-47f3-a0a9-f39759bbe9be', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'How does Remix handle ''Loader'' revalidation, and can it be customized?', N'Senior', N'By default, Remix revalidates all active loaders after any action is triggered to ensure the UI remains in sync with the server state. Developers can customize this behavior by using the shouldRevalidate function, which allows for granular control over when a loader should be triggered based on navigation or form submission contexts.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
