INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'502931dd-5694-4b09-8577-f39a20121f5f', N'18ebabb7-555b-4ba1-beb6-844b8ee55dbd', N'What is ''Cache Invalidation Storm'' and how do you prevent it?', N'Senior', N'An invalidation storm happens when a global event triggers the deletion of a massive number of cache keys, causing a sudden surge in database load. This is mitigated by implementing phased invalidation or using background refreshes that update keys asynchronously rather than deleting them.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a191ca2d-1535-4a6c-b43e-f39b45095b24', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'What is meant by a schema-less database?', N'Fresher', N'Schema-less means that the database does not require a fixed structure before inserting data. You can add new fields to individual documents or records without modifying the entire database structure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
