INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'11d1855f-5999-4f1f-a1a6-f39ece73d60e', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'What is the primary difference between Redis and a traditional relational database like MySQL?', N'Junior', N'Redis is a key-value store that keeps data in memory for speed, whereas relational databases store data on disk in tables with rigid schemas. Relational databases are better for complex queries and data consistency, while Redis excels at high-performance caching and simple data retrieval.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9b793742-aded-4141-bad3-f39f41d821c8', N'954a0331-deff-4399-b588-96f39fec001d', N'How do you add web workers in your application?', N'Fresher', N'You can add web worker anywhere in your application. For example, If the file that contains your expensive computation is src/app/app.component.ts, you can add a Web Worker using ng generate web-worker app command which will create src/app/app.worker.ts web worker file. This command will perform below actions, 1. Configure your project to use Web Workers 2. Adds app.worker.ts to receive messages 3. The component app.component.ts file updated with web worker file Note: You may need to refactor your initial scaffolding web worker code for sending messages to and from.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
