INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'511c696e-7450-4b03-9afd-f3acb4839466', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'What is a common trade-off when using a graph database?', N'Junior', N'While graph databases are excellent at traversing deep relationships, they can be more memory-intensive and harder to scale horizontally than simpler key-value or document stores. They are specialized tools meant for specific tasks rather than general-purpose storage.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'df2ca0ca-2ff7-4199-ba97-f3ae09c63b1f', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'What are the architectural benefits of using Group Replication?', N'Senior', N'Group Replication provides high availability through a distributed state machine with automatic failover and built-in conflict detection. It ensures that all nodes in the cluster eventually reach the same state, providing strong consistency compared to asynchronous replication.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1b642b40-0531-47c5-a7ed-f3ae618833d1', N'a2838158-7305-480a-b22b-4dc35776b400', N'Why is the CAP theorem important when designing distributed databases?', N'Middle', N'The CAP theorem states that a distributed system can only provide two of three guarantees: Consistency, Availability, and Partition tolerance. Since network partitions are inevitable in distributed systems, designers must choose whether to prioritize consistency or availability during a partition event.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1c953654-bf23-4371-98a1-f3b1fca4149c', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'How does an interface differ from an abstract class in Kotlin?', N'Junior', N'An interface can contain abstract methods and default implementations but cannot store state, whereas an abstract class can hold state via properties. Additionally, a class can implement multiple interfaces but can inherit from only one abstract class.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd8f67b8a-b762-47cc-9632-f3b2c1326399', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'How can FastAPI manage database connection pooling efficiently?', N'Senior', N'FastAPI should utilize a connection pooler, typically managed by an ORM like SQLAlchemy or an async driver like asyncpg, injected via a dependency. By initializing the pool at the application''s startup and closing it at shutdown, the system avoids the latency overhead of establishing new TCP connections for every incoming request.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f523c089-0ac1-460b-b617-f3b3a67a8d4d', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'Explain the difference between interface inheritance and class inheritance in Java.', N'Middle', N'Class inheritance allows a subclass to inherit state and behavior from a single parent, establishing an ''is-a'' relationship that promotes code reuse. Interface inheritance supports multiple inheritance of behavior, allowing a class to implement multiple contracts and establish ''can-do'' capabilities. Interfaces are preferred for defining loose coupling, while class inheritance is meant for hierarchical specialization.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'86e7520d-1e89-404f-a226-f3b654b27ddc', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What are the challenges of using TypeScript with third-party JavaScript libraries that lack type definitions?', N'Senior', N'The primary challenge is the lack of compile-time safety, often requiring the manual creation of declaration files or the use of ''any''. This can lead to ''type rot'' where the manual definitions drift from the actual library behavior, necessitating careful maintenance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
