INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'75167930-0901-4971-bb62-f3c3d747d7f4', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'What is the architectural purpose of Laravel''s Event and Listener system, and how does it prevent tight coupling in a monolith?', N'Senior', N'Events decouple the business logic that triggers an action from the side effects that must follow, allowing the core domain to remain agnostic of external integrations. This facilitates an event-driven architecture where new functionality can be added by simply attaching new listeners without modifying existing core services.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
