INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0862089d-7e3b-4a7f-bb27-f3cd0b830056', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'Explain the difference between mutable and immutable objects?', N'Fresher', N'A mutable object is an object whose state can be modified after it is created. An immutable object is an object whose state cannot be modified after it is created. In JavaScript numbers, strings, null, undefined and Booleans are primitive types which are immutable. Objects, arrays, functions, classes, maps, and sets are mutable. Example 01: Immutable (Primitives) Example 02: Mutable (Objects and arrays)', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'87b1919a-d491-46b4-b6be-f3ce36387496', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'Explain the role of the ''createEffect'' primitive in SolidJS.', N'Middle', N'createEffect is used for side effects that depend on reactive state. It automatically tracks any signals accessed within its scope and re-runs whenever those signals change, making it ideal for interacting with external APIs or performing manual DOM manipulations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'aebd0147-46fb-4d63-a45b-f3d04a9fb936', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'How can you secure your HTTP cookies against XSS attacks?', N'Fresher', N'1. When the web server sets cookies, it can provide some additional attributes to make sure the cookies won''t be accessible by using malicious JavaScript. One such attribute is HttpOnly. HttpOnly makes sure the cookies will be submitted only to the domain they originated from. 2. The "Secure" attribute can make sure the cookies are sent over secured channel only. 3. The web server can use X-XSS-Protection response header to make sure pages do not load when they detect reflected cross-site scripting (XSS) attacks. 4. The web server can use HTTP Content-Security-Policy response header to control what resources a user agent is allowed to load for a certain page. It can help to prevent various types of attacks like Cross Site Scripting (XSS) and data injection attacks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0c5bca8d-8023-4d4b-a313-f3d5af28a647', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'What happens when the memory limit is reached in Redis?', N'Fresher', N'When the memory limit is reached, Redis can be configured to use an eviction policy, such as Least Recently Used (LRU). This policy automatically removes old or less frequently used keys to free up space for new data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'286cb32d-7639-42f0-9257-f3d6be989b5b', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'Why is exception safety considered a contract in C++ API design?', N'Senior', N'Exception safety defines the guarantees a function provides when an exception is thrown, such as the basic, strong, or no-throw guarantee. Providing clear exception safety contracts is essential for writing reliable code that maintains system state consistency and prevents resource leaks during error handling.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1da384d6-c9dc-464e-b03b-f3d77406af16', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'How do I convert a number to a string?', N'Fresher', N'To convert, e.g., the number 144 to the string ''144'', use the built-in function str(). If you want a hexadecimal or octal representation, use the built-in functions hex() or oct(). For fancy formatting, use the % operator on strings, e.g. "%04d" % 144 yields ''0144'' and "%.3f" % (1/3.0) yields ''0.333''. See the library reference manual for details.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
