INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b7442ec6-4882-4983-860a-f3e125eb4dc4', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'Why is it often preferred to use ''Extensions'' for cross-cutting concerns in Axum?', N'Senior', N'Extensions provide a type-map that allows middleware to inject data into the request lifecycle without altering the handler signatures. This facilitates a decoupled architecture where handlers only declare what they need, keeping the business logic clean and agnostic of the underlying infrastructure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd427eacc-7021-4895-a1ad-f3e17f600908', N'954a0331-deff-4399-b588-96f39fec001d', N'What is the difference between a Component and a Module?', N'Junior', N'A component defines the view and logic for a specific part of the user interface. A module acts as a container that groups related components, directives, pipes, and services to define the application''s functional boundaries.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'95956c12-3d57-4bd7-a886-f3e4c0c0dd65', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'What is the role of the ''RequestParts'' trait in Axum?', N'Middle', N'RequestParts provides a way for extractors to inspect the request without consuming it. It is useful for middleware that needs to check headers or cookies before deciding whether to pass the request to a handler or block it.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'389f2363-40d5-4798-8ff5-f3e519e1374f', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'How does SolidJS maintain performance when dealing with large lists?', N'Senior', N'SolidJS uses a specialized ''For'' component that performs keyed list reconciliation, ensuring that only the changed items are updated in the DOM. By tracking the signal associated with each list item, it avoids re-rendering the entire list when a single item is added, removed, or updated.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c7a216e1-06cf-44d6-9c8f-f3e8327f6001', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'How do NoSQL databases manage relationships?', N'Junior', N'NoSQL databases typically avoid complex joins and instead handle relationships through embedding, where related data is stored within the same document, or through referencing, where a document contains an ID pointing to another document. This approach favors read performance over normalized storage.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fee7aba3-9e7b-4cbf-b5f5-f3efb1d3233d', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'How does Litestar facilitate testing through its ''TestClient''?', N'Senior', N'The TestClient allows for full-stack integration testing by simulating ASGI-compliant requests without the need for an external network. It supports dependency overriding, enabling developers to replace production-grade dependencies with mocked versions during test execution, ensuring high code coverage and reliability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e8e26003-2850-400f-9834-f3efeb2084e5', N'210c7148-726e-4e8b-bf12-40be36e55130', N'What are the trade-offs of using ''Arc'' versus ''Rc'' for reference counting?', N'Senior', N'Rc is a single-threaded reference counter that is faster because it does not require atomic operations for incrementing or decrementing counts. Arc is thread-safe and uses atomic operations, which incurs a performance cost but allows objects to be shared across thread boundaries safely.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
