INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'53ebf617-affd-483a-8d7a-f3fe2b2369c7', N'075b8862-431c-4678-9767-f55359758a4a', N'What are the problems solved by Single File Components?', N'Intern', N'The Single File Components solve the common problems occurred in a javascript driven application with a .vue extension. The list of issues are, 1. Global definitions force unique names for every component 2. String templates lack syntax highlighting and require ugly slashes for multiline HTML 3. No CSS support means that while HTML and JavaScript are modularized into components, CSS is conspicuously left out 4. No build step restricts us to HTML and ES5 JavaScript, rather than preprocessors like Pug (formerly Jade) and Babel.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
