INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ae08e445-0a36-41f9-9888-f40b0043e2be', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'What is the purpose of the ''index.html'' file being in the project root in Vite?', N'Junior', N'In Vite, the index.html file is treated as the entry point of the application rather than just a template. This allows Vite to treat the HTML file like any other module, where scripts are referenced using standard module script tags.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e3a1d118-a5b1-4890-9ca7-f40f1c827337', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'Why is the lack of a built-in ORM or Database layer in Hono considered an architectural advantage?', N'Senior', N'By remaining unopinionated about the data layer, Hono allows developers to choose the best database drivers or ORMs for their specific use case, whether it be a relational database, a NoSQL store, or a KV-based edge store. This decoupling prevents vendor lock-in and allows the infrastructure to scale independently of the application framework.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'14b083e1-aa9c-4ec9-92cd-f4113a943a8a', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'Explain the concept of ''Covered Queries'' and their impact on index performance.', N'Senior', N'A covered query occurs when all fields requested by a query are present in the index itself, allowing MongoDB to return results without accessing the actual document. This avoids the expensive ''fetch'' stage, significantly reducing disk I/O and latency for read-heavy operations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3ee15cf2-2288-46b1-b552-f4136c91efda', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'Why might a database index improve read performance but degrade write performance?', N'Middle', N'An index is a separate data structure that must be updated every time a record is inserted, updated, or deleted in the main table. While the index allows the engine to quickly locate specific rows during a read operation, the overhead of maintaining the index structure during write operations increases the overall latency of those transactions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b56749bb-2059-48ab-a44f-f413970d08b3', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'Compare the performance overhead of layout-triggering properties versus composite-only properties.', N'Senior', N'Properties like top, left, and width trigger reflows, forcing the browser to recalculate geometry for the entire document tree. Conversely, using transform and opacity triggers only the compositor layer, offloading work to the GPU and ensuring smooth 60fps animations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'70e4d69d-611a-4c68-ad80-f414381ebd2d', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'How does DynamoDB manage concurrency for updates?', N'Middle', N'DynamoDB supports optimistic locking using Conditional Expressions. By checking that an item version or attribute remains unchanged before applying an update, the system prevents lost updates in a multi-user environment.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'38c8c8d0-b23e-4e10-8e3c-f414fae30a08', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'How does R handle missing values (NA) differently than other primitives?', N'Middle', N'R treats ''NA'' as a special logical constant that propagates through most arithmetic and logical operations, ensuring that missing data is not accidentally ignored. Users must explicitly handle these values using specialized functions to prevent them from corrupting downstream analysis.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2b5ba6a7-22f0-4223-9479-f4157d050f96', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'What is the role of the ''Self'' keyword in Swift protocols?', N'Middle', N'The ''Self'' keyword refers to the type that will eventually conform to the protocol. It is used to enforce that methods return the same type as the conforming instance, which is crucial for maintaining type integrity in chained operations or factory patterns.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'05f8443f-e51e-49e5-97d6-f41625497996', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'What are the limitations of performing queries on DynamoDB?', N'Middle', N'DynamoDB queries are restricted to searching based on the primary key or secondary index keys. You cannot perform complex joins between tables, and filtering non-key attributes must be done after the query operation, which still consumes the read capacity of the full result set.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cc9976eb-de6f-42ae-9539-f41858e3b245', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'What is a Memtable?', N'Intern', N'A memtable is a memory-resident data structure where Cassandra stores incoming writes before they are flushed to disk. Once the memtable reaches a certain size, it is converted into an SSTable.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0506bde3-0496-4ca6-931b-f4185dbedc4a', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'What is the purpose of the ''var/'' directory in a Symfony project?', N'Junior', N'The var directory is used by Symfony to store volatile, generated files that the application needs to run. This includes the application cache, logs, and compiled container files, which should generally not be committed to version control.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
