INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c78dbecf-7e69-42af-936e-f41d78ab6824', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'What trade-offs are involved when choosing between middleware and guards?', N'Middle', N'Middleware is better for global request processing and environmental modification, whereas guards are specialized for security and authorization logic. Using guards is preferred for access control because they are more declarative and easier to attach to specific route subsets.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8b7f0b53-ad88-4009-ba24-f4210f013bd2', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'What is the difference between replication and sharding?', N'Junior', N'Replication involves copying data to multiple servers to ensure high availability and fault tolerance. Sharding involves partitioning data across multiple servers to increase storage capacity and throughput by distributing the load.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'46db65ef-9a50-4d33-9bc3-f4238208330b', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'What is the benefit of Axum''s ''Service'' composition over standard function calls?', N'Middle', N'Service composition allows you to stack cross-cutting concerns like logging and security in a reusable way. It treats these concerns as modular components that can be reused across different parts of the application without modifying the core business logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b2bf34a4-967b-4ba3-9ddf-f42495e75d06', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'What is the architectural role of Flask-SQLAlchemy''s scoped_session, and why is it necessary in a web context?', N'Senior', N'A scoped_session provides a thread-local registry for database sessions, ensuring that each web request uses a consistent, isolated transaction context. This prevents cross-thread interference and ensures that database connections are properly managed and closed at the end of each request lifecycle.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'914f969d-ff7a-4523-9c94-f4263e1b4c66', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'What is the ''next/head'' component used for?', N'Fresher', N'The Head component allows you to modify the HTML head section of a page, such as the document title or meta tags. This is crucial for Search Engine Optimization and ensuring that social media previews display correctly.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8a3d5d4c-6347-4f24-96f0-f427442e25af', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'How can you implement rate limiting in a Flask application?', N'Middle', N'Rate limiting is typically implemented using an extension like Flask-Limiter, which tracks the number of requests per user or IP address. It uses a storage backend like Redis or memory to store request counts and blocks excess requests. This protects your application from abuse, scraping, or brute-force attacks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5d6a1cee-4a1e-4a24-b1ea-f4281f3810ac', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'What is the purpose of the ''Options'' pattern?', N'Junior', N'The Options pattern is a way to group related configuration settings into strongly-typed classes. It makes it easier to access application settings throughout the code using Dependency Injection rather than manually reading from a configuration object.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ee9f2b02-7070-4e89-b204-f42875dad86f', N'fcd5873e-c89a-47d6-bb4c-c60b57c2ede1', N'Explain the concept of eventual consistency and why a system might choose it over strong consistency.', N'Middle', N'Eventual consistency allows for temporary data discrepancies across replicas in exchange for higher availability and lower latency. Systems choose this model under the CAP theorem to ensure the service remains responsive even during network partitions, accepting that updates will propagate and synchronize across all nodes over time.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e0480ba9-cbfd-4eaa-ad0f-f42940cefc95', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'What is the ''arbitrary values'' feature in Tailwind?', N'Fresher', N'Arbitrary values allow you to use specific, one-off values that aren''t in your theme by using square bracket notation. This is useful when you need a very specific pixel value or color that isn''t part of the standard design system.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2134f3d1-b112-415b-a9fa-f42b695c82d4', N'8d34dfc0-4a64-4128-b41a-cafa62ddad41', N'What are the architectural risks of using JWTs for session management compared to opaque tokens?', N'Senior', N'JWTs are stateless and self-contained, which improves performance and scalability, but they are difficult to revoke before expiration without a blacklist mechanism. Opaque tokens require a database lookup for each request, which is slower, but they allow for instant revocation and easier management of session metadata at the server side.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'200a9d92-58c7-41e3-8909-f42c11944d5a', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'What is the purpose of staging environments in the debugging process?', N'Junior', N'Staging environments provide a safe place to test a fix in a production-like setting without affecting real users. This allows me to verify that the bug is resolved and that the application remains stable under realistic load conditions before deploying to production.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
