INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'89b6464e-d4af-4e46-8d25-f42e67603ba3', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'How does Flask handle signal dispatching, and what are the risks of using them in complex architectures?', N'Senior', N'Signals allow decoupled parts of an application to be notified when certain events occur, such as a request starting or finishing. However, relying too heavily on them can lead to hidden side effects and difficulty in tracing the flow of execution, making the system harder to debug and reason about.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
