INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'11125cf1-68e6-44fa-89df-f43064da3058', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'How do you ensure that your technical solutions are scalable?', N'Intern', N'I consider how the solution will perform if the workload or data volume increases significantly. This involves identifying potential bottlenecks early and choosing efficient algorithms or data structures. Designing with scalability in mind avoids the need for a major architectural overhaul later.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
