INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd4565fc7-4e61-4388-b70e-f438ef0d6ca8', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'Why is ''shallow comparison'' used in the Redux ecosystem?', N'Middle', N'Shallow comparison is used for performance reasons, as deep comparison of large state trees would be computationally expensive. It assumes that if an object reference has changed, the underlying data has been updated, which is consistent with immutable update patterns.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd7a7946e-8aa4-4774-ba2c-f4395a2acb12', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'What is the difference between a declaration and a definition in C++?', N'Intern', N'A declaration introduces an identifier to the compiler, such as a function or variable name, without allocating memory for it. A definition provides the actual implementation or reserves the memory required for that identifier.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'54a5b678-2173-4e8b-a135-f43ba984ebdd', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'What is the purpose of the ''friend'' keyword?', N'Fresher', N'The ''friend'' keyword allows a specific function or class to access the private and protected members of another class. It is used when a non-member function needs privileged access to a class''s internal details.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7d49a0c6-bb17-40fc-b779-f43c2ef63377', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is BOM', N'Intern', N'The Browser Object Model (BOM) allows JavaScript to "talk to" the browser. It consists of the objects navigator, history, screen, location and document which are children of the window. The Browser Object Model is not standardized and can change based on different browsers. !Screenshot', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4ee5bc47-582b-4d97-80e9-f43caf514cc7', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'How can memory fragmentation occur in long-running C programs?', N'Middle', N'Fragmentation happens when memory is repeatedly allocated and freed in non-contiguous blocks, creating small gaps that are too tiny for new, larger allocations. Over time, this makes it difficult to find a large enough contiguous block of memory, even if the total free memory appears sufficient.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'47147093-60ba-4922-ad1d-f43fa9733be4', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'How do Gin''s Recovery and Logger middleware impact request latency and system reliability?', N'Senior', N'The Recovery middleware uses ''defer'' and ''recover'' to catch panics, preventing the process from crashing and ensuring the server remains available. While essential for stability, these middlewares add minor overhead, and developers must balance logging verbosity to avoid I/O bottlenecks under extreme traffic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5fa961ef-29e3-4bc3-826c-f441fd666fa5', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'How do you evaluate the trade-offs between optimistic and pessimistic locking in a high-concurrency environment?', N'Senior', N'Optimistic locking is ideal for systems with low contention, as it avoids the overhead of managing locks and prevents deadlocks. Pessimistic locking is necessary when contention is high and the cost of retries outweighs the overhead of holding locks, ensuring that transactions complete without the risk of conflict.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'003bd9b1-a4da-4a0b-bc66-f4427f5476de', N'a2838158-7305-480a-b22b-4dc35776b400', N'How does base64 encoding affect the size of a payload?', N'Middle', N'Base64 encoding increases the size of the original data by approximately 33%. This is a trade-off often made when binary data must be transmitted over systems designed primarily for text-based protocols like JSON or HTTP headers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
