INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bf78f635-151b-4993-847d-f45883bfff34', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'What is the purpose of the ''AnyVal'' class, and how does it relate to performance?', N'Middle', N'AnyVal is the base class for value classes, which allow the compiler to avoid runtime object allocation by treating the instance as the underlying primitive at runtime. This provides a way to add type safety through wrapper types without incurring the memory overhead associated with heap-allocated objects.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
