INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ac93e4dc-8e66-4286-a5ec-f46e6e185f98', N'210c7148-726e-4e8b-bf12-40be36e55130', N'What is the significance of ''Send + Sync'' constraints on thread-safe objects?', N'Senior', N'These constraints ensure that data can be safely moved to a different thread and accessed concurrently by multiple threads. Requiring both guarantees that the object is not only free of internal race conditions but also safe to transport through message-passing or shared-memory concurrency primitives.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2c2ec011-baa1-437b-9094-f472c1b70c58', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'Why is the volatile keyword used in C and how does it affect compiler optimization?', N'Middle', N'The volatile keyword tells the compiler that a variable''s value can change at any time due to external factors outside the program''s control, such as hardware or interrupt service routines. This prevents the compiler from performing optimizations like caching the variable in a register, forcing it to read the value from memory every time it is accessed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dc4dffe9-6891-414d-aa03-f473633d001f', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'How does Tailwind''s approach to responsive design via mobile-first prefixes impact the browser''s rendering performance?', N'Senior', N'Tailwind''s mobile-first media queries ensure that base styles are applied by default, reducing the complexity of CSS specificity cascades. This approach minimizes browser recalculations because the browser interprets styles linearly without needing to override desktop styles for mobile viewports.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a7761a73-7d34-48a7-8117-f47375581fd3', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'Does MongoDB support ACID transactions?', N'Intern', N'Yes, MongoDB supports multi-document ACID transactions. While it was originally known for atomicity at the document level, modern versions allow for transactions across multiple documents and collections to ensure data integrity.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dfc5b32e-0440-4d9e-819d-f47961d83eab', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'What are capped collections in MongoDB?', N'Junior', N'Capped collections are fixed-size collections that support high-throughput operations. When the collection reaches its maximum size, it automatically removes the oldest documents to make room for new ones, making them ideal for logging.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7b9e8006-63e0-4db1-915e-f479e916adb4', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'Explain the significance of the ''prototype chain'' in the context of memory efficiency.', N'Senior', N'The prototype chain allows methods to be shared across all instances of an object, saving memory by storing the method logic only once. This is significantly more efficient than attaching methods to every individual object instance during creation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'168096fc-ad9f-42a6-ba9b-f47aed929789', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'What is the purpose of the ''EXPLAIN'' statement in MySQL query tuning?', N'Middle', N'EXPLAIN provides the execution plan that the MySQL optimizer intends to use for a specific query. It reveals information such as which indexes are used, the join order, and the number of rows examined, allowing developers to identify inefficient full table scans or missing indexes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
