INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b2ddfb5b-cb2d-4a4c-86e9-f47ec6f74769', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'What is the difference between high cohesion and low coupling, and why are they desirable?', N'Intern', N'High cohesion means that elements within a module are closely related, while low coupling means modules have minimal dependencies on each other. These properties are desirable because they make the system easier to debug, refactor, and extend without causing ripple effects throughout the codebase.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
