INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a7809925-add8-4730-a870-f49b8323a1c8', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'What is a ''derived signal'' in SolidJS?', N'Intern', N'A derived signal is a value that is calculated based on one or more existing signals. You create them by wrapping an expression in a function; they automatically update whenever their source signals change.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'833cff7b-08d0-4a35-b2b0-f49d78e96208', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'How do jQuery''s utility functions (e.g., each, map) compare to modern ES6+ array methods?', N'Senior', N'jQuery utility functions were necessary when cross-browser support for native array methods was inconsistent. Today, native ES6+ methods offer better performance, are type-safe, and are widely supported, making jQuery''s utility functions redundant and unnecessary in the global scope.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'830c02c6-d336-4a27-84d5-f49f3c9f4e67', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'When estimating, how do you handle the trade-off between speed and code quality?', N'Junior', N'I prioritize maintainability and testing because rushed code often creates bugs that take longer to fix later. I would communicate to the team that a slightly longer initial timeline saves time in the long run by avoiding the ''fix-it-later'' loop.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f566752f-95a3-47bc-b309-f4a101783de0', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'How does the ''Undo Log'' contribute to MVCC (Multi-Version Concurrency Control) in InnoDB?', N'Senior', N'The undo log stores older versions of data rows, allowing transactions to read a consistent snapshot of the database as it existed at a specific point in time. This enables non-blocking consistent reads where writers do not block readers, which is the cornerstone of MySQL''s transaction isolation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b602590d-1b75-44f3-b162-f4a11ac36f61', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'How do you handle background task orchestration in Django, and what are the trade-offs of Celery?', N'Senior', N'Background tasks are typically managed using Celery with a message broker like Redis or RabbitMQ. While Celery is feature-rich, it introduces significant operational complexity, including the need to monitor worker health, manage task queues, and handle potential data consistency issues between the task state and the database.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ed8556b1-41e7-49b7-8abe-f4a2ddc98f23', N'210c7148-726e-4e8b-bf12-40be36e55130', N'What is the role of ''PhantomData'' in generic structures, and when is it required?', N'Senior', N'PhantomData is a zero-sized marker used to inform the compiler about type relationships that are not explicitly captured by the struct''s fields. It is essential when dealing with unsafe code or raw pointers to indicate that a type conceptually ''owns'' or ''borrows'' another type, which influences the compiler''s drop checking and variance analysis.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'91b7b2fe-5524-41bb-8d01-f4a4bcd5a19e', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is the difference between internal and external javascript', N'Fresher', N'Internal JavaScript: It is the source code within the script tag. External JavaScript: The source code is stored in an external file(stored with .js extension) and referred with in the tag.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'16d4d49b-e62d-42f9-9ab0-f4a695485646', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'What is the difference between @Async and standard method calls?', N'Middle', N'@Async allows a method to run in a separate thread, freeing up the calling thread immediately. This is useful for non-blocking operations, but it requires careful management of thread pools to avoid resource exhaustion.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'23a4ebd2-a05e-4605-96d2-f4a7fdeda4da', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'What is the ''N+1'' query problem in the context of database interaction?', N'Middle', N'The N+1 problem occurs when an application executes one query to fetch a list of parent records and then executes an additional query for every single parent to fetch its related child records. This results in excessive round-trips to the database, which can be solved using joins or eager loading.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'675987b7-57f0-4ec5-92b4-f4a9512911a1', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'Explain the difference between @staticmethod and @classmethod.', N'Middle', N'A @classmethod receives the class itself as the first argument, allowing it to access or modify class-level state. A @staticmethod does not receive an implicit first argument and behaves like a regular function that is simply bundled within the class namespace for logical organization.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'42d8cd79-2b43-4297-94e4-f4b153ed344b', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'Does Astro support using other frontend frameworks?', N'Intern', N'Yes, Astro supports ''UI Frameworks'' like React, Vue, Svelte, and Solid. You can use these frameworks to build interactive components, which Astro then integrates into your project.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'37dd5e04-184f-46a2-aa54-f4b2d9f10c0c', N'91fb4eff-ac6a-48b9-8ba4-2bbdf6237429', N'Why should you avoid storing sensitive information in logs?', N'Middle', N'Storing sensitive data in logs poses significant security and compliance risks, such as GDPR or PCI-DSS violations. Logs are often accessible to many developers and stored in third-party observability platforms, making them a high-value target for data breaches.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f7c40494-c283-414d-b769-f4b3b6adc1ab', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is the role of the ''Job Queue'' in the ECMAScript specification regarding promise resolution?', N'Senior', N'The Job Queue, or microtask queue, is a formal mechanism to handle the completion of asynchronous operations sequentially after the current execution context ends. It ensures that promise reactions are not executed synchronously, maintaining consistent asynchronous behavior across all environments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3bd2f3ab-fb2b-4834-b7e9-f4b4536d37a3', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'What is the default mode Gin runs in, and how do you change it?', N'Junior', N'Gin runs in Debug mode by default, which provides verbose logging. You can change this to Release or Test mode by setting the GIN_MODE environment variable or calling gin.SetMode.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'78f445f3-25e3-4c2d-b12e-f4b969c54e25', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'How do you decide between using a relational database versus a NoSQL database for a new feature?', N'Middle', N'I evaluate the data structure''s consistency requirements and the expected query patterns. If the data has strict schema requirements and requires complex ACID transactions, I choose a relational database; if the data is highly unstructured or requires rapid horizontal scaling with high write throughput, I opt for NoSQL.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4736e178-4dd2-4dcd-9f77-f4ba75fd54a2', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'What are Custom Decorators?', N'Intern', N'Custom decorators are user-defined annotations that can be used to add metadata to classes or methods. In NestJS, they are often used to extract specific data from a request object, such as user information or custom headers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'16282d4d-2c0d-4490-960b-f4ba90e51a88', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'Describe the implementation of ''transitions'' in Svelte and why they are performant.', N'Senior', N'Transitions are implemented using native CSS animations and the Web Animations API, triggered by the framework''s lifecycle hooks. By offloading the animation processing to the browser''s compositor thread and avoiding continuous JavaScript re-renders during the transition, Svelte achieves high-frame-rate animations with minimal CPU usage.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1885a62d-20bd-489b-9260-f4bbdec097ae', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'What is the concept of a one-to-many relationship?', N'Intern', N'A one-to-many relationship occurs when a single record in one table is associated with multiple records in another table. A common example is a customer who can place multiple orders, but each order belongs to only one customer.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd9d6e962-cb6d-4c45-ae36-f4bda06eec02', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'How does ASP.NET Core handle cross-origin resource sharing (CORS)?', N'Fresher', N'CORS is a security feature that allows a server to specify which origins are permitted to access resources. ASP.NET Core provides built-in middleware to configure these policies, ensuring that only trusted domains can interact with the API.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1650a667-dd54-4abe-9915-f4bef597864d', N'075b8862-431c-4678-9767-f55359758a4a', N'Explain the architectural benefit of using ''Suspense'' in Vue 3.', N'Senior', N'Suspense provides a declarative way to handle asynchronous dependencies in nested component trees. It allows developers to define fallback UI while nested async components or setup functions are resolving, improving the user experience during data loading.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
