INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f6a0afe9-fb80-44aa-8ce2-f4c0591e406d', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'What is the role of ASGI in Litestar?', N'Intern', N'ASGI, or Asynchronous Server Gateway Interface, is the specification that allows Litestar to communicate with web servers. It enables the framework to handle asynchronous requests and responses effectively.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f0f6af12-8a80-424b-8bc1-f4c07c9c5f3e', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'How can Remix be deployed in edge-computing environments?', N'Senior', N'Remix is designed to be platform-agnostic by using the Web Fetch API (Request/Response) as its base abstraction. This allows it to run on environments like Cloudflare Workers, Vercel Edge, or standard Node.js servers with minimal configuration, enabling low-latency execution near the user.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'12518169-2fc6-46f6-a449-f4c1334070ae', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is difference between [] and new Array()?', N'Fresher', N'[] and new Array() are two different ways of creating an array, but they are functionally equivalent. The primary difference between them is in how they are created and in their behavior when used with certain methods. [] is a shorthand for creating a new array. It is the preferred way to create an array in most cases, because it''s more concise and easier to read. For example: On the other hand, new Array() is a constructor function that creates a new array object. It can be used to create an array of a specific length or with specific elements. For example: One potential pitfall of using new Array() is that it can be ambiguous when you pass a single argument to the constructor.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8c00b42a-bcd5-4d33-99c5-f4c7e95195e2', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'When should you consider moving from a relational database like MySQL to a NoSQL solution?', N'Middle', N'You should consider NoSQL when you have extremely large volumes of unstructured data, require massive horizontal write throughput, or need a flexible schema that changes frequently. Relational databases are generally preferred when complex relationships, ACID compliance, and strong consistency are critical.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5dabcc1b-dcf6-4d54-8ca8-f4c994c22c92', N'075b8862-431c-4678-9767-f55359758a4a', N'How do ''Patch Flags'' enhance Vue 3''s rendering performance?', N'Senior', N'Patch flags are static analysis markers added by the compiler to virtual nodes that indicate which parts of the node are dynamic, such as text, props, or class lists. During reconciliation, the diffing algorithm skips static nodes and only checks the elements marked by these flags, drastically reducing the complexity of updates.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
GO
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'36ada5fe-cfa3-4407-a4ce-f4cfc14e9ebf', N'f2e963ff-7635-4429-a389-4d92535fb972', N'What is the purpose of the alt attribute in an img tag?', N'Junior', N'The alt attribute provides alternative text for an image if it fails to load or if the user is using a screen reader. It is essential for web accessibility, allowing visually impaired users to understand the context and purpose of the image.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b2e95fd0-5de8-4cb9-b2d4-f4d010d83816', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'What is the purpose of the ''q:base'' or ''q:instance'' attributes seen in Qwik-generated HTML?', N'Junior', N'These attributes are part of how Qwik tracks the state and location of components within the DOM. They allow the framework to lazy-load the necessary code for a component only when a user interacts with it, ensuring that no unnecessary JavaScript is executed during the initial page load.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b0c108eb-24af-4d59-a7e3-f4d17bcecb1a', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'Why would you use a Global Secondary Index (GSI) in DynamoDB?', N'Junior', N'A GSI allows you to query data using an attribute other than the primary key defined in the base table. This provides flexibility in data access patterns without requiring you to restructure the original table schema.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'34bb962c-acae-47cb-bb8f-f4d34e8bdd6e', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'What is a supervision tree in the context of a Phoenix application?', N'Junior', N'A supervision tree is a hierarchy of processes where supervisor processes monitor and restart child processes if they fail. This makes Phoenix applications highly fault-tolerant, as a crash in one part of the system does not bring down the entire application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1dc2a3c7-6d8b-4ebd-9f71-f4d549880275', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'How does SolidJS handle DOM updates without a Virtual DOM?', N'Junior', N'SolidJS compiles components into real DOM nodes and attaches fine-grained observers to them. When a signal updates, the framework directly modifies the specific DOM node bound to that signal, bypassing the need for a diffing process.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'242e3191-2ec9-4985-8760-f4d978924da6', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'What is the ''property'' decorator in Lit?', N'Intern', N'The property decorator is used to declare a reactive property. It tells Lit that changes to this field should trigger an update cycle for the component.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e5adb066-52d5-44ad-9965-f4daaea537ab', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'What is the purpose of the ''fastify-static'' plugin?', N'Intern', N'The fastify-static plugin is used to serve static files such as images, CSS, and client-side JavaScript files. It simplifies the process of configuring a web server to deliver public assets to the browser.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'060e9e2c-e192-429c-ac68-f4db7fec516d', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'Why is Hono considered a ''zero-dependency'' framework, and why does this matter for backend security?', N'Middle', N'By minimizing external dependencies, Hono reduces the attack surface of an application, making it less vulnerable to supply chain attacks. It also significantly decreases the bundle size, leading to faster cold-start times in serverless environments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'598b9b98-daa2-439e-a7b9-f4dbb1ab5b02', N'8d34dfc0-4a64-4128-b41a-cafa62ddad41', N'What is the primary architectural trade-off when implementing a Hardware Security Module (HSM) vs. a software-based Key Management Service (KMS)?', N'Senior', N'HSMs offer superior physical security and tamper-resistance by isolating keys in specialized hardware, which satisfies strict compliance requirements. KMS solutions offer better scalability, easier integration with cloud-native workflows, and lower operational overhead, though they rely on the underlying cloud provider''s isolation guarantees.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c9709a05-ba9f-485b-8b43-f4dded7032a9', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'What are the benefits of using ''ActiveJob'' over a direct library like Sidekiq or DelayedJob?', N'Middle', N'ActiveJob provides a unified interface for various background job backends, allowing developers to switch providers without changing their application code. It standardizes common tasks like retries, queue naming, and logging while maintaining the ability to use library-specific features through the underlying adapter.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f2980cd9-03fd-4622-bff8-f4de78b63b26', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'What is the purpose of the ''inline'' keyword for functions?', N'Middle', N'The ''inline'' keyword instructs the compiler to copy the function''s bytecode directly into the call site rather than performing a method call. This is particularly useful for higher-order functions that take lambdas as parameters, as it eliminates the overhead of creating function objects for each lambda.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'368099f2-9213-484f-b23e-f4e0680f56fe', N'f2e963ff-7635-4429-a389-4d92535fb972', N'Discuss the accessibility trade-offs of using ARIA labels versus semantic HTML elements.', N'Senior', N'Semantic HTML should always be the priority because it provides native keyboard navigation, role-based interaction, and inherent state management. ARIA should only be used as a fallback for complex components where native elements lack the necessary functionality, as over-reliance on ARIA can lead to maintenance issues and synchronization errors with screen readers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a777c353-1eac-4fb5-b725-f4e09c64511a', N'18ebabb7-555b-4ba1-beb6-844b8ee55dbd', N'How does a ''Distributed Lock'' interact with caching during a write operation?', N'Senior', N'A distributed lock ensures that only one process can update the backing database and the cache simultaneously, preventing ''race conditions'' that could lead to stale data in the cache. While it ensures consistency, it introduces significant latency and limits throughput compared to lock-free approaches.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd015d468-890e-448f-9439-f4e0d2903788', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'Does Fiber support query parameters?', N'Fresher', N'Yes, Fiber provides methods within the request context to retrieve query parameters from the URL. These are accessible via key-value pairs, making it easy to filter or sort data based on user input.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dc3faa69-b817-4d39-aa7e-f4e37a2b12f3', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'What is the purpose of the ''deferred loading'' feature in Dart?', N'Middle', N'Deferred loading allows a library to be loaded on-demand rather than at application startup. This significantly reduces the initial application size and startup time, which is particularly beneficial for web applications or modular mobile apps that have large, infrequently used components.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd765d782-54c3-4c9c-8bf6-f4e652e8f188', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'What does ''tree-shaking'' mean in the context of Vite''s production build?', N'Fresher', N'Tree-shaking is a process where the bundler removes dead or unused code from the final production bundle. Since Vite uses Rollup for production, it performs efficient tree-shaking to keep the final bundle size small.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6a5d03fb-0c53-48c8-8fda-f4ea0407b4ac', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'Does Quarkus support hot reloading?', N'Intern', N'Yes, hot reloading is a core feature of Quarkus dev mode. It automatically recompiles and reloads changes as soon as you save a file, allowing for a fast feedback loop without manual intervention.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'713a26d3-f53d-47d1-b8df-f4ea7471c123', N'18ebabb7-555b-4ba1-beb6-844b8ee55dbd', N'How does data serialization format choice impact distributed cache performance?', N'Senior', N'Serialization impacts both the memory footprint within the cache and the latency of network transfers. Choosing efficient binary formats like Protobuf or Avro reduces payload size and CPU usage for marshaling, which is critical when dealing with high-frequency cache operations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9dc8cc3f-53b5-4070-a75d-f4eb230dbe4f', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'How do you approach a problem that has no clear solution?', N'Intern', N'I would research how similar problems have been solved in the past and look for fundamental principles that might apply. I would then brainstorm several potential approaches, test the simplest one first, and iterate based on the findings.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'db45bc78-cff2-48c6-b9b4-f4ed6f164e32', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'How does Micronaut''s dependency injection mechanism differ from Spring''s?', N'Middle', N'Micronaut performs dependency injection at compile-time using annotation processors, whereas Spring typically relies on runtime reflection. This design choice results in lower memory consumption and faster application startup times since the dependency graph is pre-computed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'46e0f673-024f-4d61-8419-f4f06ea3a199', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'In a high-throughput scenario, why might Hono be preferred over a traditional framework for a microservice?', N'Senior', N'Hono''s minimal overhead and efficient routing allow it to handle a significantly higher number of requests per second with lower CPU and memory usage. Its design is optimized for the ''single-purpose'' nature of microservices, focusing on rapid execution and minimal latency rather than providing an all-encompassing suite of legacy features.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5f866ff8-f2f7-407d-a841-f4f24ab7ca49', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What is an optional property in an interface?', N'Intern', N'An optional property is a member of an object that may or may not be present. It is denoted by adding a question mark after the property name, informing the compiler that the property might be undefined.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3ab02a35-7bcb-4eae-9011-f4f828f5da3a', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'How does MongoDB differ from a relational database?', N'Intern', N'Relational databases use tables, rows, and columns with a rigid schema, while MongoDB uses collections and documents with a dynamic schema. This allows MongoDB to handle diverse data structures without requiring frequent database migrations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'96f66b93-f269-409b-a664-f4f997f6f7b5', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'What is the role of the ''main'' function in Dart?', N'Fresher', N'The main function is the mandatory entry point of any Dart application. When a Dart program is executed, the runtime looks for this specific function to begin executing the code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1c2daa28-8df2-49f4-8821-f4fb15ea1194', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'How does Redis handle memory fragmentation, and what trade-offs exist with active defragmentation?', N'Senior', N'Redis uses a jemalloc allocator which can suffer from fragmentation over time as keys are modified or deleted. Active defragmentation periodically moves data to more contiguous memory blocks, but this is a CPU-intensive process that can introduce latency spikes during high-load periods.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'675bbebf-ee99-41ac-9611-f4fb21fb791c', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'Why would you choose Nuxt over a standard Vite-based Vue app?', N'Junior', N'You would choose Nuxt if you need built-in server-side rendering, better SEO, or a more structured file-based development approach. Nuxt handles the complex configuration and boilerplate that you would otherwise have to set up manually.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'984cc801-4296-4641-8223-f4fd2ca1ba4a', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'What is the primary benefit of the peer-to-peer architecture?', N'Fresher', N'The primary benefit is the elimination of a single point of failure. Because every node can perform read and write operations, the system remains functional even if multiple nodes go offline.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3a96cc4c-c110-4fb4-aa85-f4ff9b3bd97d', N'18ebabb7-555b-4ba1-beb6-844b8ee55dbd', N'What are the risks of using ''Expiration'' (TTL) as the primary cache invalidation strategy?', N'Senior', N'Relying solely on TTL can lead to stale data being served if the source of truth is updated before the cache expires. This creates a window of inconsistency, which may be unacceptable for financial or state-critical applications, requiring explicit invalidation instead.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ec78f588-6916-4b33-ad3c-f5001ab05461', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'How does Remix handle concurrent mutations, and what is the ''Optimistic UI'' pattern in this context?', N'Senior', N'Remix manages concurrent mutations by automatically revalidating all active loaders after an action completes, ensuring data consistency. Optimistic UI is implemented by leveraging the state exposed by the fetcher or useNavigation hook to update the UI immediately, providing the user with instant feedback while the server processes the request in the background.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'154a801c-22f0-4741-838d-f5050a7441ed', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'Why is the use of `serialize()` and `unserialize()` considered a potential security risk in complex architectures?', N'Senior', N'Unserializing untrusted data can lead to PHP Object Injection, where an attacker manipulates the serialized string to trigger magic methods like __destruct or __wakeup on existing classes. This can lead to arbitrary code execution or privilege escalation if the application logic contains gadgets that perform dangerous actions when instantiated or destroyed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'30f0095e-4ec5-446b-9933-f5095f00ac9a', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'How does the JavaScript engine handle the memory management of closures, and what are the potential pitfalls?', N'Senior', N'Closures retain references to their lexical environment, preventing the garbage collector from reclaiming those variables as long as the closure exists. In long-running applications, this can lead to memory leaks if large objects are inadvertently held in scope. Developers should nullify references or limit scope depth to mitigate these risks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4f8795fb-cde5-4b6d-a596-f50b234534f8', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'How does Rocket manage concurrency?', N'Fresher', N'Rocket leverages Rust''s asynchronous runtime to handle multiple concurrent requests efficiently. It uses non-blocking I/O to ensure the server remains responsive under load.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
