INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'00791444-8054-4e11-b763-f51126a87231', N'074508f7-35bd-405f-8cc6-b41377b2d92c', N'What trade-offs are involved when choosing between a pull-based and a push-based message delivery model?', N'Middle', N'Push-based models provide lower latency as the broker delivers messages immediately, but they risk overwhelming consumers if not managed with backpressure. Pull-based models allow consumers to control their own processing pace based on their current resource availability, improving system stability at the cost of slight delay.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c9e135a6-ed8e-4dad-95f3-f512612c638a', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'How does Echo''s middleware chain architecture impact performance compared to a standard net/http stack?', N'Senior', N'Echo uses a ''chain of responsibility'' pattern where middleware is executed sequentially before reaching the handler. While this adds a negligible overhead per request, it provides significant architectural benefits by decoupling cross-cutting concerns like logging, recovery, and authentication from business logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
