INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'99934a98-432d-467e-a7d4-f53b4780aafd', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'What is the difference between dynamic and static typing?', N'Intern', N'Ruby is dynamically typed, meaning variable types are checked at runtime rather than compile time. This provides flexibility as a variable can hold different types of objects at different times during execution.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7bf4311d-42df-49a1-94ef-f53ca1d1bd35', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'Explain the difference between ''x-init'' and the component''s internal initialization process.', N'Middle', N'x-init is a specific directive used to run code immediately after a component is initialized, often for fetching data or setting up event listeners. The internal initialization process involves Alpine scanning the DOM to register the component''s state and directives before x-init is ever triggered.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'657b88ca-8792-40d9-8c33-f53d18305397', N'074508f7-35bd-405f-8cc6-b41377b2d92c', N'What is the ''competing consumers'' pattern?', N'Middle', N'The competing consumers pattern allows multiple instances of a consumer service to pull messages from the same queue. This enables the system to scale processing power horizontally and balance the load across available workers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8143754d-60e8-418e-a034-f53ed1a09f6d', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'Explain the architectural difference between Qwik''s resumability and traditional hydration.', N'Senior', N'Traditional hydration requires downloading, parsing, and executing the entire component tree to attach event listeners, which is computationally expensive. Resumability eliminates this by serializing the application state and framework metadata into the HTML, allowing the browser to execute only the specific code needed for an interaction without re-running initialization logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'48a16977-c15f-4718-9073-f53f4acae763', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What are the differences between WeakSet and Set', N'Intern', N'The main difference is that references to objects in Set are strong while references to objects in WeakSet are weak. i.e, An object in WeakSet can be garbage collected if there is no other reference to it. Other differences are: 1. Set can store any value whereas WeakSet can store only collections of objects 2. WeakSet does not have size property unlike Set 3. WeakSet does not have methods such as clear, keys, values, entries, forEach. 4. WeakSet is not iterable.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'eb019c2d-76a3-44e0-8368-f53f71a7af9f', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'What is the purpose of the nuxt.config file?', N'Intern', N'The nuxt.config file is the central place to customize and configure your Nuxt application. It allows you to define global settings, environment variables, head meta tags, and module configurations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b813b14a-c8e1-4867-ae2c-f5407907b893', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'Can you change the primary key of a DynamoDB table after it is created?', N'Intern', N'No, the primary key of a DynamoDB table is defined at the time of creation and cannot be changed later. To change the primary key, you would need to create a new table and migrate the data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'651b184f-81d9-4716-8a75-f543c90b98de', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'What is the purpose of the ''tokio'' runtime with Actix-web?', N'Intern', N'Actix-web is built on top of the Tokio runtime, which provides the underlying asynchronous infrastructure. Tokio manages task scheduling, timers, and I/O polling for the web server.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b53e5c0c-2dbb-49a4-a8e4-f5440b30d531', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'What is the primary difference between jQuery''s ''html()'' and ''text()'' methods regarding security?', N'Middle', N'The html method parses the input as HTML, which creates a risk of Cross-Site Scripting (XSS) if user input is not sanitized. The text method treats the input as literal text, automatically escaping characters and rendering it safe, making it the preferred choice for displaying user-generated content.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'54a320df-26c7-49b9-a781-f54cc43c838b', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'When should you use a database index in a Rails application?', N'Middle', N'Indexes should be added to columns that are frequently used in query filters, joins, or sorting. While they significantly speed up read performance, they do impose a slight penalty on write operations, so they should be added judiciously.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ab72fa90-360a-4910-a28d-f54d4fd0448d', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'What is chrome v8 engine?', N'Intern', N'V8 is an open-source, high-performance JavaScript and WebAssembly engine written in C++, developed by Google. It was originally designed for Google Chrome and Chromium-based browsers ( such as Brave ) in 2008, but it was later utilized to create Node.js for server-side coding. V8 is the JavaScript engine i.e. it parses and executes JavaScript code. The DOM, and the other Web Platform APIs ( they all makeup runtime environment ) are provided by the browser. V8 is known to be a JavaScript engine because it takes JavaScript code and executes it while browsing in Chrome. It provides a runtime environment for the execution of JavaScript code. The best part is that the JavaScript engine is completely independent of the browser in which it runs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd428e46c-2682-4a45-9559-f54dbe3133ec', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'Explain how Python decorators function internally.', N'Middle', N'Decorators are higher-order functions that take a function as an argument and return a wrapper function that extends or modifies the original''s behavior. They are essentially syntactic sugar that replaces the original function with the result of the wrapper, allowing for modular cross-cutting concerns.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a58a47a1-b09e-4183-b8d4-f54f98fec380', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'Why is it often recommended to favor composition over inheritance in Ruby?', N'Middle', N'Inheritance creates rigid hierarchies that are difficult to modify as requirements evolve. Composition, often implemented via modules or design patterns like Strategy, allows for greater flexibility by combining independent behaviors. This approach results in a more modular codebase that is easier to test and maintain.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'230d2a10-1a85-4a17-9de9-f5547b188118', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'What is the actor model used in the Actix ecosystem?', N'Intern', N'The actor model is a conceptual model for concurrent computation where ''actors'' are the primitive units. Each actor encapsulates state and behavior, communicating with other actors exclusively through asynchronous message passing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2d230c8e-2a74-400d-9c48-f5550373de1a', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'What are the trade-offs of choosing an event-driven architecture?', N'Junior', N'Event-driven systems are highly scalable and decoupled, allowing services to react to changes independently. However, they are harder to test, debug, and monitor because the flow of logic is not linear, and they require careful management of eventual consistency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f7fd2595-7095-4c47-bb8a-f55b4489f313', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'How does Vite handle environment variables, and what are the security considerations for client-side exposure?', N'Senior', N'Vite exposes environment variables through import.meta.env, but only those prefixed with VITE_ are included in the client bundle. This design prevents sensitive server-side secrets from being accidentally leaked to the browser.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'93fbda5d-6891-4904-a32f-f55c2e7115fb', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'What is the difference between constant and read-only fields?', N'Intern', N'A constant field must be assigned a value at compile-time and cannot be changed, while a read-only field can be assigned a value at runtime, typically within a constructor. Constants are implicitly static, whereas read-only fields can be instance-specific.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
