INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6f103f9c-7cda-44a6-92ec-f5688eab72b3', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'How does Flask handle URL routing and what happens if no route matches?', N'Middle', N'Flask uses a Werkzeug-based routing system to map URLs to specific view functions using a dispatcher. If no route matches the request, Flask automatically triggers a 404 Not Found error, which can be intercepted by custom error handlers to return a user-friendly response.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
