INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'026787eb-ae90-4aa2-ab9c-f57022c37611', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'How can you optimize Gin for high-load environments where JSON serialization is a bottleneck?', N'Senior', N'For extremely high-throughput systems, replacing the standard encoding/json library with a faster alternative like jsoniter can significantly reduce CPU usage. Additionally, implementing response caching for frequently accessed, static-result endpoints can further alleviate serialization overhead.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'eb63dc17-b899-47a3-b5fa-f574f6062252', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'What is the primary architectural model that Actix uses for handling concurrency?', N'Junior', N'Actix is built on the Actor model. In this model, independent units called actors encapsulate state and communicate exclusively by exchanging asynchronous messages, which helps avoid shared mutable state issues.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e54f5130-c429-4b33-88cd-f576c42599f5', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'What are the potential risks of using the C preprocessor?', N'Middle', N'The preprocessor operates before compilation and lacks knowledge of C syntax, which can lead to subtle bugs such as unexpected operator precedence or multiple evaluations of side effects. Overuse of macros can also make code difficult to debug, as the preprocessor masks the original source code during compilation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f4c8bb4f-6be5-4723-a907-f5770a110aa5', N'55404b9c-91b6-4b62-9dc7-63248e8ea1df', N'How does service discovery assist in horizontal scaling?', N'Middle', N'Service discovery enables dynamic management of service instances as they are added or removed from the cluster. It allows the load balancer or other services to automatically detect new nodes, ensuring that traffic is efficiently distributed without manual configuration updates.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'13c8e97a-1c06-4dc2-a20b-f57891fc446c', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'When faced with an incident where database connections are exhausted, what is your diagnostic process?', N'Senior', N'I examine the connection pool metrics to see if the growth is due to traffic spikes or connection leaks where sessions are not being closed. I then analyze active database queries for long-running transactions or deadlocks that hold connections open, and evaluate if the pool sizing is appropriately configured for the current concurrency load.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ac7787b0-9e2e-40f2-96cf-f579b1a32f3d', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'What is an enum in Swift and how is it powerful?', N'Junior', N'An enum defines a common type for a group of related values, making code more type-safe and readable. Swift enums are powerful because they can have methods, properties, and associated values for each case.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'53cc5c32-2f22-453b-a7a3-f579b6d17b4c', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'Describe the impact of ''strictFunctionTypes'' on variance in TypeScript.', N'Senior', N'With strictFunctionTypes enabled, TypeScript enforces contravariant checking for function parameters instead of the more permissive bivariant approach. This ensures that function arguments are type-safe, preventing runtime errors where a function expects a more specific type than provided.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'560e7c27-9ae1-4c7c-af59-f57ac70fe455', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'What is the purpose of the cluster state in Elasticsearch?', N'Junior', N'The cluster state contains information about the entire cluster, including node membership, index settings, and shard allocation. It is managed by the master-eligible nodes to ensure consistency across the cluster.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c6e21f94-09c3-4546-83d7-f57acfa25fd9', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'Discuss the trade-offs of using Hono''s JSX support for server-side rendering.', N'Middle', N'Hono includes a lightweight JSX engine that allows for generating HTML strings directly on the server. While this is efficient and avoids heavy frameworks, it lacks the complex state management features of libraries like React, making it best suited for static or simple dynamic content.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7c12440a-ab83-4ac2-9931-f57bf768b532', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'How does the Ember ''Adapter'' handle request batching or caching?', N'Senior', N'The adapter layer can be configured to implement caching strategies or coordinate with JSON:API specifications for request batching. By centralizing these concerns, the application avoids redundant network requests and ensures consistent data handling across the entire data layer.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9242c5d9-172e-45bf-9122-f57c9d006b0f', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'What is the purpose of the MongoDB Oplog, and how is it used in replication?', N'Middle', N'The Oplog is a capped collection that stores a rolling record of all operations that modify data in the database. Secondary nodes read the Oplog from the primary and apply these operations to their own data sets to maintain eventual consistency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2c77ce84-5c93-4f8b-815a-f57cd07dc269', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'How does Echo handle HTTP methods?', N'Intern', N'Echo provides specific methods on its instance to register handlers for standard HTTP verbs like GET, POST, PUT, DELETE, PATCH, OPTIONS, and HEAD. This allows developers to map specific URLs to specific actions based on the verb used.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'052a54e5-8d93-42c3-99dd-f57f39dcd419', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'What is the significance of the ''slots'' API in Lit for component composition?', N'Senior', N'Slots are the native Web Components mechanism for content projection, allowing users of a component to inject custom DOM into specific areas. This makes Lit components highly flexible and reusable, as they can accept arbitrary child content without needing complex prop configurations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b3249ae3-2f5a-4520-9685-f5833f9990fe', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What are the trade-offs of using ''any'' versus ''unknown'' in TypeScript?', N'Middle', N'The ''any'' type disables all type checking, effectively opting out of TypeScript''s safety features, which can lead to runtime issues. Conversely, ''unknown'' is the type-safe counterpart; it forces you to perform type checking or narrowing before you can perform operations on the variable, ensuring robustness.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ad981d29-e52c-4a4b-b2ed-f583744a9336', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'What is the purpose of the ''Hashable'' protocol?', N'Middle', N'The Hashable protocol allows a type to be stored in a Set or used as a key in a Dictionary. It requires the implementation of a hash value, which must be consistent and stable to allow for efficient lookups.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
