INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'23422da6-5085-46eb-baa4-f588225ab4aa', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'Explain the architectural trade-offs between using NestJS Interceptors versus Middleware for cross-cutting concerns.', N'Senior', N'Middleware executes before the route handler, providing access to the raw request and response objects, making them ideal for logging or authentication headers. Interceptors provide access to the execution context and the stream of data returned by the handler, allowing for sophisticated transformations, response mapping, or request caching that middleware cannot easily perform.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9276aa9a-1539-4479-871c-f58da4b682dc', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'What is a Micronaut Filter?', N'Intern', N'A filter is a component that allows developers to intercept and manipulate HTTP requests and responses. They are commonly used for tasks like authentication, request logging, or adding security headers to all outgoing or incoming traffic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
