INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1592eaf2-614a-430c-ad9b-f597739ffe07', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'What are the basic types in Kotlin?', N'Intern', N'Kotlin has a rich set of built-in data types tailored for various uses. They are mostly categorized into Primitive and Object data types. Basic Types Categories Primitive Types Kotlin introduces the following Primitive types: - Double: Double precision 64-bit floating point number. - Float: Single precision 32-bit floating point number. - Long: 64-bit integer. - Int: 32-bit integer. - Short: 16-bit integer. - Byte: 8-bit integer. - Char: A single 16-bit Unicode character. - Boolean: Represents truth values: true or false. Object Types These are Object types: - String: A sequence of characters. - Any: The root of the Kotlin class hierarchy. This is the equivalent of Object in Java. Other Types - Array: A class for array types.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0d9d6f6b-29ba-49ff-a4bd-f597aa4aad0e', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'What is the benefit of ''KeyPaths'' in Swift?', N'Middle', N'KeyPaths provide a type-safe way to access properties of an object dynamically without needing to know the specific instance. They are widely used in data-binding, reflection, and functional programming patterns, allowing for more concise code when accessing nested properties.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b824bb92-4968-4ada-821b-f5995152e337', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'What happens if a guard fails in a Rocket route?', N'Middle', N'If a guard fails, the request is aborted, and the framework typically returns a 401 Unauthorized or 422 Unprocessable Entity error depending on the guard''s configuration. This prevents the execution of the handler and ensures that the application state remains consistent.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f5526ca5-a6a1-4bca-a990-f599551035c3', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'Explain the architectural trade-offs between static and dynamic dispatch in Swift.', N'Senior', N'Static dispatch is resolved at compile time, allowing the compiler to perform aggressive optimizations like inlining, which significantly improves execution speed. Dynamic dispatch, typically facilitated by vtables or message passing, enables polymorphism but introduces runtime overhead for lookups. Swift prioritizes static dispatch by default for performance but uses dynamic dispatch when required for class-based inheritance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2ef5b742-f5ee-428d-a619-f59a4d239745', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'How does ''Read Repair'' work in a distributed database?', N'Middle', N'Read repair is a mechanism where the database identifies inconsistent data during a read operation by comparing responses from multiple nodes. If it detects a discrepancy, it writes the most recent version of the data back to the out-of-date nodes to bring them into sync.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'12cc4cd5-88d1-4632-a101-f5a03b74fe95', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'What is the purpose of normalization?', N'Intern', N'Normalization is the process of organizing data in a database to reduce redundancy and improve data integrity. It involves dividing large tables into smaller, related tables and defining relationships between them.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'282ecb85-7a35-4f8e-a83a-f5a221cc4245', N'8d34dfc0-4a64-4128-b41a-cafa62ddad41', N'How does implementing ''Least Privilege'' at the infrastructure level impact system observability?', N'Senior', N'Restricting permissions to the bare minimum required for a service to operate can complicate debugging, as it may limit the ability of monitoring tools to collect logs or metrics from sensitive components. Architects must balance this by using granular IAM policies that explicitly grant ''read'' access to observability agents while keeping ''write'' or ''delete'' actions highly restricted.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8e6c31d6-9f1f-4cd3-8d16-f5a22dad3624', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'What is the primary benefit of using CSS custom properties over preprocessor variables?', N'Middle', N'CSS custom properties are dynamic and live in the DOM, meaning they can be updated or changed at runtime via JavaScript or media queries. Preprocessor variables are static and compiled into fixed values, preventing them from being modified after the CSS has been generated.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7b934d49-298b-4bd6-9492-f5a22fc8da04', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'Can MongoDB perform joins like SQL databases?', N'Intern', N'While MongoDB is not a relational database, it does support a feature called $lookup that performs a left outer join between two collections. However, it is generally recommended to model data to avoid the need for frequent joins.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'82d63b6c-d9f7-43ba-91fb-f5a2e77c7f1c', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'Explain the mechanism behind Astro''s ''Content Collections'' and why it is beneficial for large-scale projects.', N'Senior', N'Content Collections provide type-safe access to local markdown or MDX files by enforcing schemas. This prevents runtime errors during content rendering and improves developer experience by enabling autocomplete and validation within the IDE for frontmatter data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'20467fe6-881c-485b-9ca6-f5a5f97e648a', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'What is the role of the ''getState'' method?', N'Fresher', N'The getState method is a function provided by the Redux store that allows you to retrieve the current state object of the application. It is primarily used when you need to access the store''s data outside of the React-Redux connector.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3e8db8c0-0486-4801-b5e8-f5a943cbb922', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'What is the role of an Index in a NoSQL database?', N'Fresher', N'An index is a data structure that improves the speed of data retrieval operations on a database table or collection. It allows the database to find records without scanning every single document or row.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7fc30b5b-2ba1-4197-8c37-f5a97e4ebc1c', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'How does the .NET ''Pinned Object'' mechanism affect Garbage Collector efficiency?', N'Senior', N'Pinning prevents the GC from moving an object during compaction, which can create ''holes'' in the managed heap that the GC cannot close. Widespread pinning increases memory fragmentation and forces the GC to work harder, potentially stalling the application during collection cycles.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5627119a-c7d9-46bb-acfe-f5a9f63d4202', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'What is the purpose of the ''useFetch'' or ''useAsyncData'' composables in Nuxt?', N'Junior', N'These composables are designed to handle data fetching during the server-side rendering process and prevent data fetching from being duplicated when the application hydrates on the client. They ensure that the data required for the page is fetched once and then passed from the server to the client seamlessly.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'05715cbe-634c-4256-b4eb-f5aa46539961', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'What is the purpose of an ''EventListener'' in Micronaut?', N'Middle', N'Event listeners facilitate decoupled communication within an application by allowing components to react to specific system events. This pattern improves maintainability by separating the logic of state changes from the side effects triggered by those changes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'53507e22-3414-4642-a41a-f5ae566acea2', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'How do you justify the trade-off of adding a message broker between two services instead of using direct synchronous communication?', N'Senior', N'I evaluate the need for temporal decoupling and load leveling during traffic spikes. While a message broker introduces operational overhead and asynchronous complexity, it prevents cascading failures and allows services to process tasks at their own pace.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8654bfcf-dc9a-460d-a315-f5ae6d52d95e', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'How do you handle exceptions in Python?', N'Fresher', N'Exception handling in Python is a structured mechanism used to manage runtime errors gracefully, ensuring program stability. It relies on a block-based syntax to catch, process, and recover from exceptions without terminating the execution flow unexpectedly. Core Components The standard syntax involves four primary blocks: - try: Contains code that might raise an exception. - except: Executes if an exception occurs. It is best practice to catch specific exceptions (e.g., ValueError) rather than using a bare except:. - else: Executes only if the try block completes without any exceptions. - finally: Executes regardless of the outcome. This is used for resource cleanup, such as closing file descriptors or database connections.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4cc11179-cd46-4918-b2bf-f5ae9db77c09', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'What is an alias in Vite configuration?', N'Intern', N'An alias is a configuration setting that allows you to create shortcuts for file paths. This helps avoid long, complex relative file paths like ''../../components'' by mapping them to simpler names.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'32f41d84-d28d-4808-aa34-f5afb0e9682d', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'Can you define properties in an interface in Kotlin?', N'Intern', N'Yes, interfaces in Kotlin can contain declarations of abstract properties. These properties must be implemented by the classes that implement the interface.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c2435c12-8fba-4cf0-812c-f5aff7f19554', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'What is boxing and unboxing?', N'Intern', N'Boxing is the process of converting a value type to a reference type by wrapping it in an object, while unboxing is the explicit conversion of that object back to a value type. This process has a performance cost and should be used sparingly.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
