INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'071ef513-0164-42de-a9ee-f5b135ff66b6', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'When should you prefer a ''Lazy Val'' over a standard ''Val''?', N'Middle', N'Lazy vals are initialized only upon the first access, which is beneficial for expensive computations that might not be needed in every execution path. However, they introduce a slight overhead due to internal synchronization and should be used cautiously to avoid initialization order deadlocks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'df1a5672-5409-4346-a21c-f5b1917d8b81', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'How does the ''reindex'' process handle data consistency and potential downtime?', N'Senior', N'The reindex API creates a new index and copies data from an existing one using an internal scroll query. Since it creates a new target, the original index remains available for reads and writes, ensuring zero downtime, though you must handle updates that occur during the process via versioning.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
