INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0bc500d8-8c42-4b2d-88e8-f5ba47fdfe6f', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'Explain the role of the WiredTiger cache and its eviction policy.', N'Senior', N'The WiredTiger cache stores raw data pages and handles data transformation before persisting to disk. When the cache reaches its capacity, the eviction thread proactively removes pages to free up memory, prioritizing pages that haven''t been accessed recently or those that are clean to minimize I/O.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
