INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a82746ef-cf73-4d53-85a8-f5bc19f2bd42', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'How do you balance consistency and availability during a network partition in a distributed system?', N'Senior', N'Following the CAP theorem, I would favor consistency if the business logic requires accurate financial data, or favor availability if the service is a content-delivery system where slight staleness is acceptable. I would explicitly define the failure mode, such as returning stale data or a temporary error, based on the specific service SLA.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'761a52ea-aa6e-456e-b7d9-f5bfc03eec75', N'f2e963ff-7635-4429-a389-4d92535fb972', N'Discuss the security implications of allowing arbitrary HTML via ''dangerouslySetInnerHTML'' or similar mechanisms.', N'Senior', N'Directly injecting HTML bypasses framework-level sanitization, making the application highly vulnerable to Cross-Site Scripting (XSS) attacks. If user-generated content must be rendered, it must be passed through a robust sanitization library to strip malicious scripts and event handlers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
