INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f0263354-6fcd-4e74-a286-f5c1cd479ff0', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'What is the purpose of a ''minimal reproducible example''?', N'Fresher', N'A minimal reproducible example strips away all unnecessary complexity to demonstrate the bug using the smallest possible set of inputs or states. This makes it easier to analyze the logic and ensures that the fix is focused only on the problematic segment.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
