INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7010a696-cebc-4500-b23f-f5c2a1898a21', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'What is the significance of the ''Node Role'' architecture in Elasticsearch?', N'Senior', N'Assigning specific roles like master, data, or ingest to nodes allows for better resource isolation. This prevents resource-heavy tasks like data ingestion from interfering with critical cluster management or data search operations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd75467e6-ec1b-4a7f-b1cb-f5c64da61014', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'What is meant by ''Atomicity'' in ACID?', N'Fresher', N'Atomicity ensures that all operations within a transaction are treated as a single unit. If any part of the transaction fails, the entire transaction is aborted, and the database remains unchanged.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'70fb6597-0ddb-403a-9970-f5c7f9a86c1f', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'What are Django Static files?', N'Intern', N'Static files are assets such as CSS, JavaScript, and images that are not dynamically generated by the application. Django provides a management system to collect these files from different locations and serve them efficiently to the browser.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ce07f765-e96b-4303-9fc2-f5c9de1e0b5e', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What are TypeScript Generics and why are they used?', N'Junior', N'Generics allow you to create reusable components that work with a variety of types rather than a single one. They enable you to maintain type safety while writing flexible functions or classes that can handle different data structures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c377f66d-15ac-481c-ac9a-f5cfe3c942eb', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'Explain the concept of Containment in CSS and its role in performance optimization.', N'Senior', N'The contain property allows developers to isolate a subtree of the DOM from the rest of the page''s layout and style calculations. By declaring a boundary, the browser can skip re-calculating the styles and geometry of the entire document when changes occur only within that subtree, significantly reducing layout thrashing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0afee3e5-e001-4aeb-bd42-f5d3feade35a', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'How does the Symfony Request/Response cycle handle exceptions?', N'Middle', N'When an exception occurs during the request cycle, Symfony dispatches a kernel.exception event. This allows specialized listeners or subscribers to catch the error, log it, and transform it into a proper Response object, such as a formatted JSON error or a custom HTML error page.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'948132e0-3b5b-4f29-a15b-f5d63b14e6db', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'What is the difference between an ''Optimistic'' and ''Pessimistic'' locking strategy in application-level MySQL usage?', N'Senior', N'Pessimistic locking uses ''SELECT ... FOR UPDATE'' to lock rows until the transaction ends, preventing concurrent modifications but reducing throughput. Optimistic locking uses version numbers or timestamps to verify that data hasn''t changed before updating, allowing for higher concurrency without holding locks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'028c0ca8-6fb2-4b40-a04c-f5d6927b898d', N'9a0e3785-3b73-4abc-ab01-df75bf097dff', N'Explain the role of the ''Strangler Fig'' pattern in migrating a monolith to microservices.', N'Senior', N'The Strangler Fig pattern involves incrementally replacing specific functionalities of the monolith with new microservices by placing an interception layer in front. Over time, the new services ''strangle'' the monolith until it is eventually decommissioned, allowing for risk-mitigated migration.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3a7daf73-befb-4419-ac07-f5d730017d51', N'91fb4eff-ac6a-48b9-8ba4-2bbdf6237429', N'Why is ''Idempotency'' critical for reliable distributed systems?', N'Senior', N'Idempotency ensures that performing the same operation multiple times has the same result as performing it once. In a distributed system where network retries are common, idempotency prevents duplicate state changes or inconsistent data resulting from partial network failures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f8740f75-7e22-41a3-8fc0-f5d74a0ba109', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'What are sub-routers in Chi and why are they useful?', N'Middle', N'Sub-routers allow developers to group routes under a common path prefix and apply specific middleware to that group. This promotes code modularity and keeps the route definitions organized as the application grows in complexity.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4542bfc2-cb46-4e3e-9aad-f5db259b41b5', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'How does error handling using ''do-try-catch'' differ from returning optional values?', N'Middle', N'Throwing errors provides a structured way to propagate specific error types up the call stack, allowing for detailed error handling. Returning optionals is simpler but loses context about why an operation failed, forcing the caller to handle all failure cases as a generic nil.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
