INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'eaac802a-81cd-453b-9756-f5ec1b956074', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'If a user reports that a website is loading very slowly, how would you begin to investigate the cause?', N'Intern', N'I would start by checking if the issue is local to my environment or affecting others by testing on different networks and devices. Then, I would use browser developer tools to inspect network activity and identify which resources, such as large images or slow server responses, are taking the most time to load.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'28b9a405-ef4b-43c9-87f1-f5ec6eaf85c0', N'a2838158-7305-480a-b22b-4dc35776b400', N'How does a bloom filter help optimize distributed system performance?', N'Senior', N'A bloom filter is a space-efficient probabilistic data structure that can tell if an element is definitely not in a set or possibly in a set. It is used to avoid expensive disk lookups or network calls by checking the filter first to see if the requested data exists on a specific node.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0a8816e6-d090-44a8-ad37-f5ed0f8dad9e', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'How does Preact handle event delegation differently than React?', N'Middle', N'Unlike React, which uses a synthetic event system that pools and delegates all events to the root document, Preact uses native DOM event listeners. This approach simplifies the architecture, improves performance by reducing event overhead, and ensures behavior is consistent with standard browser event propagation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
