INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'783e7531-b648-419f-8af2-f5fade9b20ed', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'How does Return Value Optimization (RVO) impact the semantics of move semantics?', N'Senior', N'RVO is a compiler optimization that eliminates unnecessary copying or moving of objects by constructing them directly in the target memory location. While move semantics provide a standard way to transfer resources, RVO is superior because it avoids the function call overhead associated with move constructors, effectively bypassing the need to even invoke move logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
