INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'833818bf-245b-41dc-97ec-f6006f37ec81', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'What are the risks of using ''Runtime Reflection'' in a Quarkus native application?', N'Senior', N'If reflection is not explicitly registered at build time, the native image compiler will assume the reflected code is unused and strip it away. This results in runtime errors, typically ClassNotFound or NoSuchMethod exceptions, when the application attempts to access the missing code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c5d2dd92-7fb5-41b3-ba2f-f60a7a7e703b', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'What is data redundancy?', N'Intern', N'Data redundancy occurs when the same piece of data is stored in multiple places within a database. It is generally avoided because it wastes storage space and increases the risk of data inconsistency during updates.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bf6cf8e1-ed3d-4695-87ea-f61392fcbc14', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'What is the difference between an API route (+server.js) and a page endpoint (+page.server.js)?', N'Middle', N'API routes are dedicated to creating REST or GraphQL endpoints that return JSON or other data formats for programmatic access. Page server files are specifically tied to the rendering lifecycle of a page, intended for fetching data to display directly in the UI.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9cb9f638-f619-4d2a-879d-f613adca5cb1', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'What is a RESTful Web Service?', N'Intern', N'A RESTful web service is an architectural style for providing interoperability between computer systems on the internet. It uses standard HTTP methods like GET, POST, PUT, and DELETE to perform operations on resources represented by URLs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f885c733-6413-4b7b-b653-f6141db14283', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'What is the ''Ref'' pattern, and why should it be used sparingly for data flow?', N'Senior', N'Refs allow direct access to DOM nodes or persistent mutable values that don''t trigger re-renders. Using them for data flow violates the declarative nature of React, as changes to ref values bypass the render cycle and make the UI state difficult to track and synchronize.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'060217ed-d138-4b0f-a3b2-f61b217662e0', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'What is the batch function used for?', N'Intern', N'The batch function groups multiple signal updates into a single update cycle. This prevents unnecessary intermediate re-renders and ensures that effects only trigger once after all changes are applied.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'34dee97c-f671-4fa0-802f-f6226af508ca', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'How does jQuery handle context in selector queries, and why should it be used cautiously?', N'Middle', N'Context allows you to restrict the scope of a search to a specific subtree. While it can optimize performance by limiting the search area, overusing complex contexts can lead to verbose and harder-to-maintain code compared to standard scoping.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd563cb07-11f4-4151-9a3b-f62285dc19e2', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'Why would you choose to use ''Buffer'' in Node.js?', N'Middle', N'Buffers are used to handle binary data streams, which is necessary when working with file systems, network sockets, or cryptographic tasks. Since JavaScript strings are typically UTF-8, Buffers provide a dedicated way to manipulate raw memory outside of the V8 heap.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd86169a0-564b-4222-964b-f6230a673d01', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'What is type inference?', N'Fresher', N'Type inference is the ability of the Kotlin compiler to automatically determine the data type of a variable based on the assigned value. This reduces the need for explicit type declarations, making code more concise.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7f597296-1c6a-46c5-a32d-f6244114d80c', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'What does ''asynchronous'' mean in the context of FastAPI?', N'Intern', N'Asynchronous programming allows the server to handle multiple requests concurrently without waiting for slow operations, like database queries or network calls, to finish. This improves the overall throughput and responsiveness of the application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'009a9df7-f4b8-4a92-949f-f6247d888dbc', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'What does it mean for a build tool to be ''opinionated''?', N'Intern', N'Being opinionated means the tool provides a set of sensible default configurations and workflows out of the box. Vite is opinionated because it encourages specific folder structures and build patterns to ensure a consistent developer experience.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'442844c1-28aa-4c2c-a568-f6268dd566e0', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'Why is the ''Data Down, Actions Up'' (DDAU) pattern strictly enforced in Ember, and what are the architectural consequences?', N'Senior', N'DDAU ensures a unidirectional data flow, which makes the state of the application predictable and easier to debug. By forcing components to communicate changes via events, it prevents hidden side effects, promotes component reusability, and makes it easier to implement time-travel debugging or state snapshots.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4e79cace-0c3b-4a90-8d36-f626fc26fd52', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'What is a relational database?', N'Fresher', N'A relational database stores data in structured tables consisting of rows and columns. It uses a predefined schema to define the relationship between data elements using keys.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
