INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'79cc7366-b7ee-41e2-9c2b-f62d3b88aa59', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'How would you design a caching strategy to prevent cache stampedes in a high-traffic system?', N'Senior', N'I implement request collapsing or locking mechanisms to ensure only one process fetches the data when the cache expires. Additionally, I use probabilistic early expiration or background cache refreshing to ensure the cache remains populated before the TTL actually expires.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f11d0189-4dec-4f55-a609-f633992f9e00', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'How does Kotlin''s inline value class mechanism differ from standard type aliasing at the bytecode level?', N'Senior', N'While type aliases are strictly a compile-time construct that do not change the resulting bytecode, inline value classes create a wrapper that the compiler attempts to unwrap during compilation. This avoids heap allocations by replacing the wrapper with the underlying primitive or object type in the generated bytecode, providing type safety without runtime overhead.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'994e813e-8a42-498d-9dc7-f636e803d30c', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'What is the purpose of the ''apply'' directive in Tailwind?', N'Fresher', N'The @apply directive allows you to extract common utility patterns into custom CSS classes. It is useful for reducing code repetition in your HTML while still utilizing Tailwind''s design system and design tokens.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'606dd49e-8294-4eef-bcb7-f63898e14f24', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'How do you estimate the risk of a legacy system migration?', N'Middle', N'I assess the complexity of the existing data, the degree of coupling between modules, and the availability of automated tests. A high-risk project would require a phased approach with feature flags and parallel run periods to ensure we can roll back immediately if issues arise.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'39ad6581-4a72-448e-9c2b-f63b0d482ef5', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'Explain the difference between Strongly Consistent and Eventually Consistent reads in DynamoDB.', N'Middle', N'Strongly Consistent reads return the most up-to-date data, reflecting all prior successful write operations. Eventually Consistent reads may return stale data if the write has not propagated to all storage nodes, but they provide lower latency and consume half the read capacity units.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'93e7a92e-ff80-469d-8a68-f64505380e56', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'How does Astro ensure that external assets like fonts and scripts are optimized?', N'Senior', N'Astro provides tools for font optimization and script loading strategies that minimize layout shifts and blocking. By leveraging Vite''s asset processing, Astro can inline critical CSS and manage the loading order of external resources to prioritize the critical rendering path.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd4756cd3-7c7a-48e2-9841-f6479e12adaf', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'Can you describe the directory structure of a Laravel Framework?', N'Junior', N'Laravel, a powerful PHP MVC framework, adopts a clear and intuitive file organization, aligning with modern development strategies. Core Directories 1. app: Centralizes application-specific code. 2. bootstrap: Contains auto-loading code and defines the starting point for the application. 3. config: Stores configuration files. 4. database: Houses database-related code, such as migrations and seeders. 5. public: The server''s publicly accessible web root. It contains the front controller and assets like images, CSS, and JS files. 6. resources: Affirming a cleaner division between client-side and server-side components. E.g., CSS and JS in resources/assets, and views in resources/views. Extended Directories 7. routes: Segregates application routes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a9435397-cd4e-4e7e-b924-f64889ea67f6', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What are compose and pipe functions?', N'Intern', N'The "compose" and "pipe" are two techniques commonly used in functional programming to simplify complex operations and make code more readable. They are not native to JavaScript and higher-order functions. the compose() applies right to left any number of functions to the output of the previous function.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'66091c1e-7fd5-496b-91cb-f648976285f5', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'Discuss the impact of ''Small Object Optimization'' (SOO) in standard containers.', N'Senior', N'SOO reduces heap fragmentation and improves cache locality by storing small objects or short sequences directly within the container''s internal buffer rather than allocating dynamic memory. This significantly boosts performance for common cases where data sizes are small, at the cost of a slightly larger memory footprint for the container object itself.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'034680de-be96-4ee9-a944-f64a08941a31', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'How does the scope chain work during variable lookup, and what is the performance implication?', N'Fresher', N'When a variable is referenced, the JavaScript engine performs a scope chain lookup: it starts at the current scope''s environment record and walks up through enclosing records until the variable is found or the global scope is exhausted. V8 optimises this through: 1. Hidden classes / shapes — objects have stable layouts; property access is compiled to a direct memory offset. 2. Inline caching (IC) — after the first lookup, V8 caches the resolved location. Repeated access to the same variable from the same call site is O(1). 3. Closure context allocation — V8''s Turbofan compiler performs context allocation analysis. Variables that are only used locally stay on the stack (fast).', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5f1a0557-f09f-48a1-aaf5-f64c23e38ca2', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'What is the role of the ''handle'' hook in SvelteKit, and why is it critical for multi-tenant applications?', N'Senior', N'The ''handle'' hook provides a global interceptor for every request, enabling the dynamic modification of the request object or the response. For multi-tenant apps, it is essential for identifying the current tenant from headers or cookies and injecting site-specific configuration or state before the page load begins.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'76019f44-1a44-4879-8e02-f64f437f04dc', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'Explain the role of the ''Rack'' interface in a Rails application.', N'Middle', N'Rack provides a minimal, modular interface between web servers and Ruby frameworks. Rails uses Rack to process incoming HTTP requests through a middleware stack, allowing developers to inject custom logic like logging, caching, or security headers before the request reaches the router.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'adee38be-bbce-4837-8c4f-f65003990341', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'Explain the role of the ''compiler hooks'' in Webpack''s plugin architecture.', N'Senior', N'Compiler hooks act as the lifecycle event system for Webpack, allowing plugins to tap into specific phases like compilation, emit, or done. By registering callbacks to these hooks, plugins can manipulate the dependency graph, inject assets, or perform custom side effects at precise moments during the build process.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9ccc3416-4360-492e-8ec3-f6507610504b', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'What is the role of the ''config/environments'' folder?', N'Intern', N'This folder contains separate configuration files for different environments like development, test, and production. These files allow you to define settings specific to each environment, such as logging levels, caching behavior, and error reporting.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'91b155af-2e9b-4d84-9058-f65278075507', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'How does Python handle memory management beyond reference counting?', N'Middle', N'Python primarily uses reference counting for immediate memory reclamation, but it also employs a cyclic garbage collector to detect and clean up reference cycles. This secondary mechanism identifies objects that refer to each other, preventing memory leaks that reference counting alone cannot resolve.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'44d31a1d-df08-4311-b631-f6529c20eed2', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'What is the purpose of the ''register'' method?', N'Junior', N'The register method is used to include plugins into your Fastify application. It establishes the plugin hierarchy and ensures that plugins are loaded in the correct order while respecting encapsulation boundaries.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e4bf87bf-67d8-4de5-8d29-f654c20a038f', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'How do you handle a scenario where data does not fit in memory?', N'Junior', N'If the working set of data exceeds the available RAM, performance will degrade due to disk I/O. To fix this, you should optimize your indexes, add more RAM, or use sharding to distribute the data load across multiple servers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6a866b69-38b0-41cf-ab19-f6581bb18bb2', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'What are ''derived signals'' (or Memos) in SolidJS?', N'Fresher', N'Derived signals are values computed from other signals that automatically update when their source signals change. Memos are a specific type of derived signal that caches the computed result, ensuring the calculation only runs again if the underlying dependencies have actually changed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6d363672-bfb1-483c-a93b-f65950cd2b99', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'What are the trade-offs between using a monolithic application structure versus microservices in PHP?', N'Middle', N'Monoliths are generally easier to develop, test, and deploy initially due to a unified codebase. Microservices provide better scalability, fault isolation, and the ability to use different tech stacks for specific services, but they introduce significant complexity in networking, data consistency, and service orchestration.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e6926817-5aee-40ee-b2bf-f659f2705784', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'How does Fastify''s schema-based serialization provide a performance advantage over standard JSON.stringify?', N'Senior', N'Fastify uses a JIT compiler to generate optimized serialization functions based on the provided JSON schema. By avoiding runtime type checking and object inspection, it significantly reduces CPU overhead when serializing large objects into strings.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'831f83a8-be0b-447e-8883-f65a58a7578c', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'What is the impact of using ''web::block'' for legacy code integration?', N'Senior', N'web::block allows wrapping blocking legacy code into a Future that can be executed on a thread pool. While it enables integration, over-reliance on it defeats the purpose of an asynchronous framework and should be treated as a temporary bridging strategy.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'354b860e-6c56-4a85-8a02-f65bc6ba5c3d', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'What is the impact of using Global Secondary Indexes (GSI) on write latency and cost?', N'Senior', N'GSIs are asynchronously updated via a background process that replicates data from the base table. This introduces a slight delay in data visibility and consumes additional write capacity units on the index. The primary trade-off is the cost of storage and write throughput versus the ability to perform highly efficient queries on non-key attributes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
