INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'da42aa72-976a-4a79-9976-f66642331e6f', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'What is the benefit of using Nuxt over a standard Vue CLI setup?', N'Intern', N'Nuxt provides a standardized project structure, built-in routing, automated configuration, and server-side rendering capabilities out of the box. This allows developers to focus on building features rather than setting up complex build tooling.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fb178e4c-24c5-4287-bb17-f66f0971c981', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'Discuss the impact of String Interning on memory efficiency versus the overhead of maintaining the String pool.', N'Senior', N'String interning reduces memory consumption by ensuring that duplicate string literals share the same physical memory location in the pool. However, it increases the overhead on the PermGen or Metaspace and can lead to performance degradation if the pool grows too large, requiring careful management and awareness of the application''s unique string distribution.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'425d5a5a-1217-4cd0-9863-f67250a9c0b5', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'What is the primary difference between a SynchronizationContext and a TaskScheduler?', N'Senior', N'SynchronizationContext provides an abstraction for the environment''s threading model, such as the UI thread in WPF or WinForms, ensuring code executes in the correct context. TaskScheduler is a lower-level construct that dictates which threads are used to execute queued tasks, prioritizing throughput over specific environmental context.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
