INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a8576bb6-53a6-42ae-97cf-f67442871c60', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'How does Alpine.js''s reactivity system compare to Vue''s Reactivity Transform or Proxy-based system?', N'Senior', N'Alpine.js utilizes a proxy-based reactivity system similar to Vue 3, but it is scoped specifically to the DOM element hierarchy rather than a standalone state management engine. It leverages the browser''s native capabilities to track dependency updates, making it lightweight by avoiding a virtual DOM overhead.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9239c7ca-9ab7-4fd9-b5e9-f676e462bc6a', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'What is the impact of GSI replication lag?', N'Middle', N'Updates to a GSI are asynchronous, meaning there is a brief period where the index may not reflect the latest changes from the base table. Developers must design their applications to handle this eventual consistency, often by relying on the base table for the most recent state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
