INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'61090c3d-f01a-4b44-a3d7-f67d0fdf3c51', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'How can Preact''s Signals be used to avoid common ''prop drilling'' issues?', N'Senior', N'Signals act as observable values that can be imported and consumed directly by any component, bypassing the need to pass state through intermediary layers. This creates a decentralized state architecture where components subscribe only to the specific data they need, improving performance and maintainability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
