INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e99991e2-c6e1-4c0a-b029-f69049186f5c', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'What is the primary purpose of a web framework like Flask?', N'Intern', N'A web framework provides a standardized way to build web applications. It handles low-level details like HTTP requests and responses, allowing developers to focus on building the business logic of their application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6d968076-31ad-4387-aa0e-f6936c52c518', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'How do SolidJS ''Stores'' differ from standard signals, and when should they be preferred?', N'Senior', N'Stores are specialized reactive objects designed for nested data structures, allowing for fine-grained reactivity even when deep properties change. They should be preferred over multiple individual signals when managing complex state trees to maintain a unified interface and efficient update tracking.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'57068ee9-3506-410b-aaac-f6937aab989b', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'How do you balance writing code quickly with writing high-quality code?', N'Junior', N'I focus on writing clean, simple, and well-tested code from the start, as this prevents time-consuming bugs later on. While speed is important, taking the time to implement it correctly the first time is usually more efficient than rushing and having to fix it later.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd192493b-fea7-4b8c-a68b-f6947c83480e', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'How do you handle authentication in a way that remains secure across both SSR and client-side transitions?', N'Senior', N'Authentication should be handled using secure, HttpOnly cookies to store session tokens. This ensures that the server can verify the user identity during SSR, and the client can maintain the session without exposing tokens to JavaScript-based attacks like XSS.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3f544a5f-a307-4ba1-b6a5-f69777c0bf03', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'What is the difference between @Controller and @Singleton in Micronaut?', N'Fresher', N'@Controller is a specialized annotation that marks a class as a web request handler, while @Singleton indicates that a class should have only one instance. All controllers in Micronaut are implicitly singletons.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2953e914-ceec-4278-ac93-f697ad830421', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'Why is JavaScript considered ''single-threaded'' and how does it handle I/O operations?', N'Middle', N'JavaScript runs on a single main thread to simplify memory management and avoid concurrency issues associated with multi-threading. It handles I/O operations asynchronously by offloading them to the browser or Node.js runtime APIs, which perform the work in the background and notify the main thread via callbacks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'26b7e0d4-51e6-4b76-a961-f698e6c0f7c6', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What are ''keyof'' and ''typeof'' operators used for?', N'Middle', N'The ''keyof'' operator extracts the union of all property names of a type. The ''typeof'' operator retrieves the type of a value at compile time, which is very useful for deriving types from existing objects or constants.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'95d224c3-5932-4c43-b544-f699ea5f38d8', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'What considerations go into choosing a primary key for a distributed database?', N'Middle', N'I look for a key that is unique, immutable, and preferably monotonically increasing or time-ordered to ensure even data distribution. I avoid keys that could lead to hotspots, such as sequential IDs in high-write systems, opting instead for UUIDs or K-ordered identifiers to maintain performance across partitions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e6674d3f-69c4-44b4-8987-f69c7c0c3296', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'Explain the concept of Type Erasure in TypeScript and its implications for runtime behavior.', N'Senior', N'Type erasure means that all interface, type, and generic annotations are removed during compilation, leaving only plain JavaScript. Consequently, these types do not exist at runtime, which prevents the use of ''instanceof'' on interfaces and necessitates runtime checks for data validation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a901adf5-ec37-4ee3-a7e1-f69cd6bce45a', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'If a server is failing to respond, how would you start troubleshooting the issue?', N'Fresher', N'I would first check the network connectivity to ensure the server is reachable via ping. Then, I would investigate the server logs to identify any application-level errors or resource exhaustion, such as high CPU or memory usage.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
