INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4c166753-b1a2-400f-8ac7-f6a0419834d2', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'How does Ruby''s visibility (public, protected, private) affect method access?', N'Middle', N'Public methods are accessible from anywhere. Private methods can only be called within the instance itself without an explicit receiver, while protected methods can be called by any instance of the same class or its subclasses, allowing for cross-instance access between related objects.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0da0efb2-a12d-4034-bd03-f6a2198ba0e6', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'What is the trade-off of using Django''s built-in User model versus a custom user model from the start of a project?', N'Senior', N'The built-in model is convenient but rigid, making it extremely difficult to swap out once a project is in production. Defining a custom user model at the project''s inception provides long-term flexibility, allowing for custom authentication requirements and specialized user profile data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
