INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cb4d9fb6-3bbc-4fd3-aa17-f6a73c879e1c', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'How does Alpine.js maintain state persistence if a component is hidden via CSS ''display: none'' versus being removed from the DOM?', N'Senior', N'When an element is hidden via CSS, the component remains in the DOM tree, and Alpine continues to track its state and reactivity. This allows the state to persist perfectly, but it consumes memory and potentially CPU cycles if reactive expressions are still evaluating. If the component is removed via ''x-if'', Alpine cleans up the state, effectively destroying the component''s memory footprint.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
