INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fc6df808-0697-4a33-998c-f6b77a95a8df', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'What is the main advantage of using profiles in Spring Boot?', N'Intern', N'Profiles allow you to define different configurations for different environments, such as development, testing, and production. You can activate specific profiles to load only the relevant settings for the current environment.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6be3c1db-6d5c-4669-94b5-f6b99e0be0f3', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'How can Django applications effectively handle database read replicas for read-heavy workloads?', N'Senior', N'Django supports multi-database configurations where you can implement a custom database router to route read operations to replicas and write operations to the primary instance. This offloads the primary database, but requires careful handling of replication lag to ensure users do not see stale data immediately after writing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'09593648-6be8-4e09-a041-f6ba65c9fbce', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'What are the limitations of using Chi for very large APIs?', N'Middle', N'The primary limitation is that Chi does not enforce a project structure or provide a built-in dependency injection container. As an API scales, the developer must establish their own conventions for managing service layers and configuration to avoid a flat, unmanageable routing file.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c9bf3aa8-29fd-417f-a43b-f6ba822744d9', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'Why is it often recommended to avoid ''SELECT *'' in production environments?', N'Middle', N'Using ''SELECT *'' retrieves all columns, which increases network overhead and consumes unnecessary memory on the database server. It also prevents the use of covering indexes, which allow queries to be satisfied entirely by the index without performing a costly lookup to the data pages.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1b1e918d-7298-41f6-bf3e-f6bccea60731', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'What is the benefit of using ''FromData'' for request bodies?', N'Middle', N'The FromData trait allows Rocket to automatically parse and validate the body of a request based on its Content-Type. This promotes a declarative style where you define the expected structure, and the framework handles the deserialization and potential error reporting before the handler is invoked.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
