INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3a0cacd5-ddd4-4fa5-9578-f6c25ef765a1', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'How does Symfony handle session management?', N'Middle', N'Symfony abstracts session management through the Session component, allowing the developer to store user data across multiple requests. It supports various storage drivers, including files, databases, or Redis, making it flexible for different hosting environments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'837861c4-497b-4b47-8a10-f6c299ead3a5', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'How does garbage collection work in Java?', N'Fresher', N'In Java, the Virtual Machine (JVM) manages memory through automatic garbage collection (GC). This process identifies and reclaims objects that are no longer in use. Key Concepts - Reachability: Objects are considered "alive" if they are reachable from the root object, which can be a Thread, Stack, or Static reference. Unreachable objects are eligible for garbage collection. - Reference Types: There are different reference types that play a role in determining an object''s reachability and GC eligibility. Reference Types - Strong References: The most common type, created with Object obj = new Object(). Objects with strong references are not eligible for GC. - Soft References: Denoted by SoftReference softRef = new SoftReference<>(obj).', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'77b4447b-ef1f-47e7-96e1-f6c471f53f5f', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'What is the significance of the ''application.properties'' file?', N'Junior', N'The application.properties file is the central location for configuring the Quarkus application environment. It allows developers to define database connections, server ports, and custom configuration keys without needing to recompile the source code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'acbceaaa-5a67-48c7-95b2-f6c60fb23340', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'Why does Cassandra prefer writes over reads?', N'Junior', N'Cassandra is designed for high-volume write workloads because it uses an append-only architecture. Writes do not require immediate disk updates or row locks, making them extremely fast compared to complex relational database transactions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
