INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'199cfa90-78fe-4d1a-9bb0-f6d695a1e9fc', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'What are the trade-offs of using Django''s ORM versus raw SQL queries for complex analytical reports?', N'Middle', N'Django''s ORM provides high productivity and security against SQL injection, but it can struggle with complex joins, window functions, or performance optimization for massive datasets. Raw SQL allows for fine-tuned query execution and database-specific features, though it increases maintenance overhead and makes the application less database-agnostic. The decision should be based on whether the query complexity justifies sacrificing the abstraction and safety provided by the ORM.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
