INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'74f1a8af-a0a7-4b05-b74e-f6dd6435d9a0', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'Describe the implications of the C++ object lifetime and the ''Rule of Five''.', N'Senior', N'The rule of five dictates that if a class manages a resource, it should define or delete the destructor, copy constructor, copy assignment operator, move constructor, and move assignment operator. This ensures proper resource ownership semantics, prevents double-free errors, and enables efficient transfer of ownership through move semantics, which is critical for resource-heavy objects.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'acc4f391-b13e-4cbd-85f1-f6de043d1dd1', N'f2e963ff-7635-4429-a389-4d92535fb972', N'How do ''aria-live'' regions affect the accessibility tree and user experience?', N'Senior', N'The ''aria-live'' attribute informs screen readers that the content within an element is dynamic and should be announced to the user when it changes. This is vital for real-time updates like notifications or status messages, but if used excessively, it can cause overwhelming audio feedback for screen reader users.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4ea913a3-a5af-4834-80c4-f6de8c5a7c09', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'Explain NEGATIVEINFINITY in JavaScript?', N'Fresher', N'The Number.NEGATIVE_INFINITY property represents the negative Infinity value. Syntax: * Negative infinity is a number in javascript, which is derived by ''dividing negative number by zero''. * A number object needs not to be created to access this static property. * The value of negative infinity is the same as the negative value of the infinity property of the global object. &#9885; Try this example on CodeSandbox', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
