INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2cb01af3-e4f6-44bd-b5ea-f6e1d0bf808d', N'91fb4eff-ac6a-48b9-8ba4-2bbdf6237429', N'What is the difference between mean time to detect (MTTD) and mean time to recovery (MTTR)?', N'Middle', N'MTTD measures the average time it takes to become aware of an incident, while MTTR measures the average time taken to resolve the incident once it is detected. Both are key KPIs for measuring the effectiveness of an organization''s observability and incident response processes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd6baa655-f4b6-466b-b62c-f6e248d30a45', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'What is the ''Try'' type and how does it differ from ''Option''?', N'Junior', N'Try is used for operations that might throw an exception, containing either Success or Failure. While Option represents presence or absence, Try represents success or a specific error state, making it better for error handling.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'08c09bae-f3a5-4ba7-ad19-f6e393bd7612', N'954a0331-deff-4399-b588-96f39fec001d', N'What is the difference between an ''embedded view'' and a ''host view''?', N'Middle', N'A host view is created by a component and is linked to the component class instance. An embedded view is created from a TemplateRef and is not directly tied to a specific component class, often used for structural directives like ngIf or ngFor.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'96b0a1e4-30e8-41a1-9cf9-f6e79fd72650', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'What are the trade-offs of Svelte''s approach to state management compared to traditional Redux or MobX architectures?', N'Senior', N'Svelte provides built-in stores that offer a lightweight, observable pattern without the boilerplate associated with Redux. While it simplifies state management, it lacks the ecosystem of middleware and dev-tooling that large-scale Redux architectures provide, which can be a limiting factor in massive, complex enterprise applications.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a632a2bd-44bd-44f8-b864-f6e9505c6fbe', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'Why is testing a first-class citizen in the Go ecosystem?', N'Middle', N'The Go toolchain includes a built-in testing framework that requires no external dependencies. By placing tests in the same package and using standard naming conventions, the language encourages developers to write tests alongside their code, fostering a culture of high test coverage.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8458066a-a8e0-4f39-8574-f6eab960bb8b', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'What role does the ''Fairing'' trait play in Rocket''s request lifecycle?', N'Senior', N'Fairings are lifecycle hooks that allow developers to intercept and modify requests or responses at specific stages, such as initialization, request processing, or response completion. They are instrumental for cross-cutting concerns like logging, distributed tracing, and security header injection.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b2c2578b-12bb-4455-a2c8-f6ec19f972ca', N'18ebabb7-555b-4ba1-beb6-844b8ee55dbd', N'Explain the trade-offs of using consistent hashing for a distributed cache.', N'Senior', N'Consistent hashing minimizes cache misses during node additions or removals because only a fraction of keys need to be remapped. However, it can lead to uneven data distribution if the hash distribution is not uniform, requiring the use of virtual nodes to balance the load.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'67482604-5c8e-41a2-9d46-f6ec60b8bba3', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'Why is it dangerous to over-engineer a simple problem?', N'Intern', N'Over-engineering introduces unnecessary complexity that makes the system harder to maintain, test, and debug. It consumes resources that could be better spent on other tasks and may lead to performance overhead. Simple solutions are often more reliable and easier for the team to manage over time.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'69d154bd-3e5e-4250-b2de-f702bf7ed8a2', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'What is an EventEmitter?', N'Intern', N'The EventEmitter class is a core module that facilitates communication between objects in Node.js. It allows objects to emit named events that cause previously registered listeners to be called.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ce5f5825-3418-43b6-8826-f707075547a0', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'Describe the trade-offs of using R''s ''formula'' objects in statistical modeling.', N'Senior', N'Formula objects provide a compact, symbolic representation of relationships between variables, which abstracts away the complexity of matrix construction. However, they rely heavily on non-standard evaluation, which can make debugging model specifications difficult and lead to unexpected behavior if the environment in which the formula is evaluated changes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'49b48422-bdcc-41cc-b1e9-f70b6f3352c1', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'What is the purpose of Express Router?', N'Junior', N'The Express Router is a mini-application used for modularizing routes. It allows you to group related routes into separate files, making the code cleaner, more maintainable, and easier to scale as the application grows.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3da1732c-256c-4739-82da-f70c3e68460e', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'How does the ''super()'' function resolve inheritance in a complex diamond hierarchy?', N'Senior', N'The ''super()'' function delegates calls to the next class in the Method Resolution Order rather than the immediate parent class. This dynamic dispatch ensures that every class in the hierarchy has a single chance to participate in the method call, preventing multiple execution of base class logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f97bcaa3-5de0-4eae-83f0-f70ca2e3ab73', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'Explain the concept of ''tree-shaking'' and its dependency on module systems.', N'Senior', N'Tree-shaking is a form of dead-code elimination that relies on the static nature of ES modules to determine which exports are actually used. It fails with CommonJS because dynamic require calls make it impossible for build tools to safely prune unused code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3c806030-eba1-4057-aba7-f70f51fa093f', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'How do you ensure that your debugging process is efficient and doesn''t waste time?', N'Middle', N'I follow a scientific method: form a hypothesis based on the symptoms, gather data to prove or disprove it, and then implement a fix if confirmed. I avoid ''trial and error'' changes without evidence, as this often leads to regressions. Keeping a record of what has been tested helps stay focused and avoids repeating the same failed steps.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9c6fbe32-b756-4831-aac1-f7104072daff', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'Why would you choose to store large binary files outside of a database?', N'Middle', N'Storing large blobs directly in a database can lead to bloated backups, increased I/O latency, and reduced cache efficiency. Storing them in object storage while keeping only the reference path in the database is generally more scalable and cost-effective.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
