INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fe91c5de-12d4-4673-a48d-f717af5298b2', N'fcd5873e-c89a-47d6-bb4c-c60b57c2ede1', N'What are the trade-offs of using an API Gateway versus a direct client-to-service communication model?', N'Senior', N'An API Gateway centralizes cross-cutting concerns like authentication, rate limiting, and request routing, simplifying client interactions. However, it introduces a single point of failure and a potential performance bottleneck if not scaled appropriately compared to direct communication.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f04b81af-f0f7-4ed2-929f-f7184b26270a', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'What are the Pointer Events supported in React?', N'Intern', N'_Pointer Events_ provide a unified way of handling all input events. In the old days we had a mouse and respective event listeners to handle them but nowadays we have many devices which don''t correlate to having a mouse, like phones with touch surface or pens. We need to remember that these events will only work in browsers that support the _Pointer Events_ specification. The following event types are now available in _React DOM_: 1. onPointerDown 2. onPointerMove 3. onPointerUp 4. onPointerCancel 5. onGotPointerCapture 6. onLostPointerCapture 7. onPointerEnter 8. onPointerLeave 9. onPointerOver 10. onPointerOut', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'92f1d5e4-bb2c-460a-943e-f71ae5be55a4', N'f2e963ff-7635-4429-a389-4d92535fb972', N'What is the <noscript> element?', N'Intern', N'The element defines fallback content to display when JavaScript is disabled in the browser or when the browser does not support scripting. In — used to inject alternative or tags: In — used to show fallback UI: Common use cases: - Displaying a meaningful message for users with JS disabled - Providing a server-rendered fallback for JS-driven SPAs - Inserting no-JS tracking pixels ( inside ) for analytics', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'723a206a-aac5-4f0b-a663-f71afd2c00a6', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'How do you decide between synchronous REST and asynchronous event-driven communication?', N'Senior', N'Synchronous communication is best for simple request-response flows where immediate feedback is necessary for the user experience. Event-driven communication is superior for decoupling services, improving system scalability, and building resilient workflows that can handle bursts in load by buffering events in a queue.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a3fefe36-206d-476a-96a6-f71c345eb58d', N'4c000000-0000-0000-0000-000000000005', N'What is a distributed transaction?', N'Middle', N'A distributed transaction involves multiple independent systems or databases that must all commit or abort together to maintain consistency. Implementing this is difficult and often involves protocols like Two-Phase Commit or the Saga pattern.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a6f4b38c-809a-4b4f-b9b0-f71cb7c01f33', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is the Temporal Dead Zone', N'Intern', N'The Temporal Dead Zone (TDZ) refers to the period between the start of a block and the point where a variable declared with let or const is initialized. During this time, the variable exists in scope but cannot be accessed, and attempting to do so results in a ReferenceError. This behavior is part of JavaScript''s ES6 (ECMAScript 2015) specification and applies only to variables declared with let and const, not var. Variables declared with var are hoisted and initialized with undefined, so accessing them before the declaration does not throw an error, though it can lead to unexpected results. Example', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'459a4dc5-ae1d-4e97-8a2e-f71dac1ad1e7', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'How does Swift''s ''Copy-on-Write'' mechanism work and why is it important for performance?', N'Senior', N'Copy-on-Write is an optimization technique where a value type, such as an array, is only copied when it is modified, rather than when it is assigned. By sharing the underlying storage through reference counting until a mutation occurs, Swift reduces unnecessary memory allocations and copying overhead. This makes passing large collections as value types highly efficient without sacrificing safety.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'129461d7-5ddc-4604-a0b2-f71e70ff7315', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'What is the purpose of unmountComponentAtNode method?', N'Intern', N'This method is available from react-dom package and it removes a mounted React component from the DOM and clean up its event handlers and state. If no component was mounted in the container, calling this function does nothing. Returns true if a component was unmounted and false if there was no component to unmount. The method signature would be as follows,', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'46b10358-7d5b-4ba0-9638-f71fde006d20', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'Explain the difference between PHP''s shared-nothing architecture and stateful application servers.', N'Middle', N'In a shared-nothing architecture, each request starts with a clean slate, destroying all variables and state once the execution finishes. This design simplifies scalability by preventing side effects between requests, whereas stateful servers maintain memory across multiple requests, which can lead to complex synchronization issues.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'330cb8c2-35ab-4970-98e1-f72758b78a82', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'How does boxing and unboxing affect the performance of a C# application?', N'Middle', N'Boxing involves wrapping a value type in an object on the heap, which incurs an allocation cost and increases garbage collection pressure. Unboxing requires a type check and a copy operation, both of which introduce performance penalties that can significantly degrade execution speed in tight loops or high-frequency operations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8d1e5195-2268-431a-8f22-f72a272cd1e2', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'Explain the difference between app.use() and app.get() in terms of route matching.', N'Middle', N'app.use() is used for middleware that matches any path starting with the specified prefix, making it ideal for global logic or mounting routers. app.get() specifically registers a handler for HTTP GET requests matching the exact path provided, allowing for more specific endpoint control.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5a99b0aa-95a6-41bc-89b4-f72b2e405279', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'How does Remix handle document meta tags?', N'Fresher', N'Remix provides a meta function that allows you to define dynamic document titles and meta tags for each route. Since this function runs on the server, the tags are included in the initial HTML response, which is crucial for SEO.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1f0edf0c-04cb-4139-8899-f72e6e3170c0', N'24c74bdc-c63e-4370-b1ac-bd560cb834d6', N'What is a circuit breaker pattern and how does it improve API resilience?', N'Middle', N'A circuit breaker prevents an application from repeatedly trying to execute an operation that is likely to fail, such as calling a down service. It ''trips'' the circuit to fail fast for a period of time, allowing the failing service to recover and preventing cascading failures across the system.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'96be8e3f-f31b-4a76-9def-f732068f61b9', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'How would you implement request tracing in Hono for observability in a distributed system?', N'Senior', N'Request tracing can be implemented by creating a custom middleware that generates a unique correlation ID at the start of the request lifecycle and injects it into the context. This ID can then be propagated to all downstream services and logged, providing a unified trace across the entire distributed system, independent of the internal framework implementation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a0be4ed0-d767-49cd-8df7-f732d9c4af3c', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'How does Fastify maintain thread safety in a single-threaded environment?', N'Middle', N'While Node.js is single-threaded, Fastify ensures state integrity through the encapsulation of the plugin context. By avoiding shared global state and strictly scoping variables to the request-reply lifecycle, it prevents race conditions that could occur in asynchronous operations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'01711f07-5f2a-4609-bdb7-f73342534814', N'9a0e3785-3b73-4abc-ab01-df75bf097dff', N'How does the Database-per-Service pattern impact data consistency across microservices?', N'Middle', N'Each service owns its own schema, which prevents tight coupling and allows independent scaling. However, it makes maintaining ACID transactions across services difficult, requiring the implementation of eventual consistency models like event-driven architectures or the Saga pattern.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'33e48bce-c339-4e5f-a5f8-f733c71013ac', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'How does Echo support path parameters in URLs?', N'Junior', N'Echo uses a colon syntax in the route definition to define named parameters within the path. These parameters can then be easily retrieved within the handler function using the Context object.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'63d67d45-b274-4477-9de9-f7367abe923b', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'Why is the order of middleware registration important in Actix?', N'Fresher', N'Middleware is executed in the order it is registered. When a request arrives, it travels through the middleware stack, and when a response leaves, it travels back through the stack in reverse order.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'eb58e4fa-26fe-4cae-909d-f7373e6fb545', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'Explain the trade-offs of using Incremental Static Regeneration (ISR) versus traditional cache-control headers.', N'Senior', N'ISR allows you to update static pages in the background after deployment without rebuilding the entire site, providing a balance between performance and content freshness. Cache-control headers rely on the browser or CDN to respect expiration policies, which can lead to stale content if not carefully invalidated, whereas ISR manages invalidation at the framework level.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'eb833b99-e996-4b51-b527-f737617dc1fc', N'954a0331-deff-4399-b588-96f39fec001d', N'What is AOT?', N'Intern', N'Ahead-of-Time (AOT) is a type of compilation that compiles your app at build time. This is the default starting in Angular 9. When you run the ng build (build only) or ng serve (build and serve locally) CLI commands, the type of compilation (JIT or AOT) depends on the value of the aot property in your build configuration specified in angular.json. By default, aot is set to true.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
