INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'730a0673-1ee7-490a-88f0-f737b8218cce', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'What is the function of the Flask ''request'' object?', N'Intern', N'The request object contains all the data sent by the client to the server during an HTTP request. This includes information such as form data, query parameters, headers, and cookies.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd1fe5fdf-f998-4ba7-a166-f737f7853780', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'What is a request context in Flask?', N'Intern', N'A request context stores information about the current HTTP request, such as the URL, headers, and form data. It allows the application to access request-specific data globally within the thread handling that request.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c25a4f25-8827-4430-b48b-f738b37a55b7', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'Why is deep copying a primary concern when interfacing R with C++ via Rcpp?', N'Senior', N'When passing data between R and C++, Rcpp aims to provide zero-copy access where possible, but changing data types or modifying objects often triggers a copy to maintain R''s immutability requirements. If not carefully managed using external pointers or specific wrapper classes, these implicit copies can lead to excessive memory consumption in high-performance pipelines.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ac36ff2b-592f-4a0b-ba99-f7397fc19ec9', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'How does Fiber handle errors in route handlers?', N'Intern', N'Fiber allows developers to return an error object from a handler, which is then caught by a global error handler. This provides a centralized way to log errors and send appropriate HTTP status codes back to the client.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
