INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e5355687-eb91-46db-8705-f73d0555f1ad', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'What is load balancer and how it works?', N'Intern', N'A load balancer is a process that takes in HTTP requests and forwards these HTTP requests to one of a collection of servers. Load balancers are usually used for performance purposes: if a server needs to do a lot of work for each request, one server might not be enough, but 2 servers alternating handling incoming requests might. 1. Using cluster module: NodeJS has a built-in module called Cluster Module to take the advantage of a multi-core system. Using this module you can launch NodeJS instances to each core of your system. Master process listening on a port to accept client requests and distribute across the worker using some intelligent fashion. So, using this module you can utilize the working ability of your system. 2.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c4a87963-c2a3-4b4e-9e97-f73eba2953ef', N'074508f7-35bd-405f-8cc6-b41377b2d92c', N'How does message ordering work in a distributed queue, and what are its trade-offs?', N'Middle', N'Maintaining strict ordering requires routing messages with the same key to the same partition or consumer instance. This limits parallelism and throughput because the system cannot distribute the processing load across multiple consumers efficiently.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f4898921-0b69-4e4d-8ec5-f74275a801b4', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'What are the security implications of using Django''s built-in session management in a distributed system?', N'Senior', N'Default session backends store data in the database or files, which can create a bottleneck and session synchronization issues across nodes. Using a centralized cache backend like Redis is necessary to keep sessions performant and accessible by all application servers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
