INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'324d1eb1-be4b-4dbc-90ab-f7444719c00d', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'How do Promises and the underlying job queue differ from the standard task-based event loop?', N'Senior', N'Promises are handled via the microtask queue, which has higher priority than the task queue used for setTimeout or I/O. This ensures that asynchronous resolutions are processed as soon as possible after the current execution context concludes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
