INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1204f0a4-8be4-4c84-bc58-f749fc45a6c8', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What does the ''void'' type represent?', N'Intern', N'The ''void'' type is typically used as the return type for functions that do not return a value. It indicates that the function performs an action but does not provide a result back to the caller.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4e387110-3d6d-4635-b0fd-f74b9991c80e', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'What is the significance of the main function in a C program?', N'Fresher', N'The main function serves as the entry point of any C program. When a program is executed, the operating system calls this function first, and the execution of the entire application begins and ends within its scope.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ca879103-0b80-426c-b7b6-f74ea1ea074b', N'24c74bdc-c63e-4370-b1ac-bd560cb834d6', N'How do you ensure data integrity when using APIs for state changes?', N'Middle', N'Data integrity can be ensured through the use of optimistic locking or ETags, which detect if a resource has changed since it was last retrieved. By requiring these tokens in update requests, you prevent accidental overwrites in concurrent environments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7aead03b-8c48-402f-b97e-f74f16b15f54', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'When designing a user interface, what is the trade-off between simplicity and functionality?', N'Junior', N'A simple interface is easier for new users to learn and navigate, reducing friction. However, extreme simplicity can hide advanced features or limit the power-user experience, whereas a feature-rich interface may overwhelm users with a steep learning curve.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7a86963e-4879-46c3-8fad-f74f341885e0', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'What does ''lazy evaluation'' mean in Django ORM?', N'Intern', N'Lazy evaluation means that creating a QuerySet does not actually hit the database. The database is only queried when the data is explicitly accessed, such as when iterating over the result or calling a specific method.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a37c61a2-a49d-4db8-b44b-f75338c8747f', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'What is the main advantage of using Spring Boot devtools?', N'Junior', N'Spring Boot devtools provides features like automatic application restarts whenever files are changed in the classpath. This significantly improves developer productivity by reducing the time spent manually rebuilding and restarting the application during development.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'59fe75da-eb73-49fb-bfa5-f758a2036a89', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'How do custom decorators in NestJS facilitate cross-cutting concerns, and how do they differ from standard middleware?', N'Senior', N'Custom decorators utilize the underlying metadata reflection system to attach behavioral instructions to classes or methods. Unlike middleware, which executes sequentially in the request-response cycle, decorators provide a declarative way to extract request data or apply interceptors at the handler level without polluting business logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd3cfbc6c-de25-466b-be0e-f758beb31fc7', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'Explain the difference between a cache-aside pattern and write-through caching in Redis.', N'Middle', N'In cache-aside, the application is responsible for reading from and writing to both the database and the cache, typically fetching from the database on a cache miss. In write-through, the application writes directly to the cache, which then synchronously updates the underlying database, ensuring consistency at the cost of higher write latency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c76bdf89-1f70-4c2c-96d7-f75a98813d64', N'24c74bdc-c63e-4370-b1ac-bd560cb834d6', N'What are the security considerations when choosing between API Keys, OAuth2, and JWT for microservice authentication?', N'Senior', N'API keys are simple but lack fine-grained authorization and revocation capabilities. OAuth2 provides a robust framework for delegated access, while JWTs allow for stateless authentication across services, provided the trade-off of token revocation difficulty is managed through short lifetimes or blacklisting.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8857c71b-e848-4335-865c-f75b67aecd5b', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'Why is Flask considered ''extensible''?', N'Fresher', N'Flask is considered extensible because its core is intentionally kept small and simple. It allows developers to choose and integrate only the specific libraries or tools they need for their project rather than forcing a specific architecture.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'60936bc2-1ad3-4f02-8962-f75e2912f90a', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'What are the common strategies for handling database migrations?', N'Middle', N'Migrations should be handled using version-controlled scripts that are applied incrementally to the database schema. It is best practice to keep migrations reversible and to test them thoroughly in a staging environment to prevent data loss or downtime during deployment.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'75a27169-5f47-46b3-a107-f76035923b24', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What are the pros and cons of promises over callbacks?', N'Intern', N'Below are the list of pros and cons of promises over callbacks, Pros: * It avoids callback hell which is unreadable * Easy to write sequential asynchronous code with .then() * Easy to write parallel asynchronous code with Promise.all() * Solves some of the common problems of callbacks(call the callback too late, too early, many times and swallow errors/exceptions) * Integrated error handling. * Additional static methods: Promise.allSettled(), Promise.any(), Promise.race() Cons: * It makes little complex code * It cannot return multiple arguments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b3a5e47e-df8b-489f-9568-f762943708a3', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'How do you handle data loading in Ember routes?', N'Middle', N'Data loading is typically handled within the model hook of a route. Ember waits for the promise returned by this hook to resolve before transitioning to the route, ensuring that the necessary data is available before the template is rendered.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2c8b8cd9-14c1-4619-a315-f76385e42545', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'What is a document database?', N'Intern', N'A document database is a type of NoSQL database that stores data in document-oriented formats like JSON or XML. Each document contains pairs of fields and values, which can be nested for complex data structures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cf1c52a5-d725-47e1-bfb4-f763a25c9b0a', N'd5b12859-0c9f-4e2f-9b3a-1ccb6c5080e5', N'What is the trade-off of implementing a distributed consensus algorithm like Paxos or Raft?', N'Senior', N'These algorithms allow a distributed cluster to agree on state changes reliably, ensuring strong consistency even if nodes fail. The trade-off is increased latency for write operations because the system must wait for a quorum of nodes to acknowledge the change, which can be significant in geo-distributed setups.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'28ad2fc1-42c4-4697-912f-f763e801245a', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'Discuss the performance implications of JSON serialization in ASP.NET Core and strategies for optimization.', N'Senior', N'Default JSON serialization can be CPU-intensive and generate significant memory pressure due to allocations. Optimizations include using System.Text.Json with source generators to minimize reflection usage or adopting binary formats like Protobuf or MessagePack for high-performance service-to-service communication.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'243abc00-9f65-446a-bb11-f768845537ba', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'Why is the selection of a shard key irreversible in a live cluster?', N'Senior', N'The shard key determines the physical distribution and routing of data across the cluster; changing it would require a complete redistribution of all existing data. Because the data is partitioned based on the original key, the cluster cannot dynamically re-shard based on a new key without significant downtime or complex background migrations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7b71c729-e153-4f14-abf4-f7688640d2f3', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'Explain the architectural implications of R''s copy-on-modify semantics and how it impacts memory management for large-scale data processing.', N'Senior', N'R utilizes copy-on-modify semantics to ensure functional purity and data integrity, meaning that modifying an object creates a new memory allocation. In large-scale systems, this leads to significant memory overhead and potential performance bottlenecks due to frequent garbage collection cycles. Senior architects must mitigate this by employing reference semantics via packages like data.table or using memory-mapped files to avoid redundant data duplication.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c363ed4d-02aa-469c-a310-f7689458bbcb', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'What are the trade-offs of using ''Immer'' for state updates in Redux?', N'Senior', N'Immer simplifies immutable updates by allowing developers to write ''mutative'' code that is safely converted into immutable updates, reducing boilerplate significantly. The trade-off is a slight overhead in performance due to the proxy-based tracking and the potential loss of explicit understanding of immutability concepts by newer developers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'23ec967c-2305-4c8c-92e7-f7696dcc783f', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'What is the purpose of the ''const'' keyword?', N'Intern', N'The ''const'' keyword is used to define constants, meaning the value of the variable cannot be changed after initialization. It can also be applied to functions and pointers to ensure they do not modify the data they access.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'99d77ce9-786b-4447-99de-f76cb0c90a76', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'How do you define an index signature in an interface?', N'Junior', N'An index signature allows you to define objects where the property names are not known ahead of time. You use square brackets to define the type of the key and the type of the corresponding value.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ec07f7f6-4333-44c5-860d-f76d558d98af', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'What are the different ways to visually hide content (and make it available only for screen readers)?', N'Intern', N'These techniques are related to accessibility (a11y). * visibility: hidden: However, the element is still in the flow of the page, and still takes up space. * width: 0; height: 0: Make the element not take up any space on the screen at all, resulting in not showing it. * position: absolute; left: -99999px: Position it outside of the screen. * text-indent: -9999px: This only works on text within the block elements. * Metadata: For example by using Schema.org, RDF, and JSON-LD. * WAI-ARIA: A W3C technical specification that specifies how to increase the accessibility of web pages.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'79026d65-ce44-42b3-9fa6-f76e0c2827d5', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'Why is it important to use ''fastify-plugin'' when creating reusable modules?', N'Middle', N'Using fastify-plugin prevents the plugin from creating a new encapsulation context. This allows the module to share its decorators and settings with the parent application, which is necessary when you want to extend the base server functionality globally.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bede9e06-85a7-476b-be00-f7749fcf36ed', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'Can Elasticsearch handle schema-less data?', N'Fresher', N'Yes, Elasticsearch is schema-less by default. It can infer the data type of a field automatically when a document is indexed, which is known as dynamic mapping.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'40e39f0f-a9c2-4b64-b684-f7755c9c9bc9', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'What is the role of the ''static'' keyword for class members?', N'Junior', N'A static member variable is shared among all instances of a class rather than being unique to each object. Static member functions can only access static data members and can be called without creating an instance of the class.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'34a4269c-e8b4-4a01-94df-f7755e47e809', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'What is the primary role of the Data Down, Actions Up pattern in Ember?', N'Middle', N'This pattern ensures that data flows unidirectionally from parent components to children via properties, while children communicate changes back to parents through action callbacks. It promotes predictable state management and makes components easier to debug and test in isolation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'525ed7eb-468c-4e9f-8e58-f7764c10dd2a', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'What is the difference between a query parameter and a path parameter in Fiber?', N'Intern', N'A path parameter is part of the URL structure itself, while a query parameter is appended to the URL after a question mark. Fiber provides distinct methods to access these two types of data from the request context.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6d778a0c-10ad-44ef-a31e-f777d67c2389', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'When should you implement a custom ''Dynamic Module'' instead of a static one?', N'Senior', N'Implement a dynamic module when the configuration of the module needs to be determined at runtime or passed from the parent module. This is common for SDK wrappers or database modules where connection strings and credentials must be injected dynamically during the application startup sequence.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ff3accb4-81ea-4425-9c74-f7791a2536a0', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'What is horizontal scaling, and why is it common in NoSQL?', N'Fresher', N'Horizontal scaling involves adding more servers or nodes to a system to distribute the workload. NoSQL databases are designed to scale this way naturally, allowing them to handle increasing amounts of traffic by spreading data across multiple commodity machines.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0ecd23f5-b636-451c-8cf9-f779623b2619', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'Why does Python have a ''with'' statement for exception handling?', N'Middle', N'The ''with'' statement simplifies resource management by guaranteeing cleanup actions regardless of whether the code block completes successfully or raises an exception. It replaces boilerplate try-finally blocks, making the code more readable and less error-prone.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd28febc7-1688-4fc2-952c-f77b2a01c03e', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What is the ''unknown'' type?', N'Intern', N'The ''unknown'' type is a safer alternative to ''any'' because it forces the developer to perform type checking before using the value. It prevents accidental operations on variables whose types are not yet determined.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9bb927fd-cbab-4f76-adfb-f77b3179750f', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'How do mapped types help in enforcing consistency across an application''s data models?', N'Middle', N'Mapped types allow you to create new types by transforming every property of an existing type, such as making all fields read-only or nullable. This ensures that if the source model changes, all derived types update automatically, maintaining synchronization and reducing bugs caused by manual updates.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0f2d12c7-aee8-4c23-9ee8-f77b3d2e49e9', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'What are the limitations of Sass when working with modern CSS custom properties?', N'Senior', N'Sass processes code at build-time, while CSS custom properties are evaluated by the browser at runtime. Sass cannot ''read'' the value of a CSS variable, which limits its ability to perform logic on dynamic theme values, often leading to a bifurcation where Sass handles static logic and CSS variables handle dynamic state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bc074883-7ed9-4d91-862f-f77c3cb83886', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'What is the function of the Spring WebClient?', N'Middle', N'WebClient is a non-blocking, reactive HTTP client used for making requests to external services. It is the recommended replacement for the older RestTemplate, especially in high-throughput applications that require better scalability and asynchronous behavior.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e64f2a93-f3c7-491c-b7ff-f77cc587adaa', N'4c000000-0000-0000-0000-000000000005', N'How do you handle the ''thundering herd'' problem when a popular cache key expires?', N'Senior', N'Implement cache locking or probabilistic early recomputation. By using a mutex or a distributed lock, only one request is allowed to recompute the data while others serve stale content or wait, preventing a spike in database load.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cca398bb-b6fa-4b85-9ad4-f77cf04911f3', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'How does Vite''s ''glob import'' feature improve developer productivity?', N'Senior', N'Glob imports allow developers to import multiple modules at once using patterns, which is ideal for dynamic routing or automated component registration. It eliminates the need for manual import statements and scales well as the project structure grows.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a8ee141d-69dc-4447-803b-f77f5ebca278', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'In the context of Fastify''s request lifecycle, what is the primary architectural trade-off when choosing between a synchronous hook and an asynchronous one for high-throughput services?', N'Senior', N'Synchronous hooks execute immediately on the main event loop, offering lower latency for simple tasks, but they risk blocking the loop if the logic is CPU-intensive. Asynchronous hooks allow for non-blocking I/O operations, which is critical for scalability, but they introduce overhead due to promise resolution and microtask queue management, potentially impacting the maximum request-per-second capacity under extreme load.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'59fa9db1-568b-46cd-82c4-f77f8e2db2db', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'How do you detect if your estimation logic has a hidden bias?', N'Intern', N'I would challenge my own assumptions by considering extreme scenarios and asking ''what if'' questions to see if the outcome changes drastically. Discussing the logic with a peer can also reveal blind spots or unconscious biases that I might have overlooked during the initial reasoning process.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'99e6e080-9bf6-4705-ae92-f780818f2b12', N'a2838158-7305-480a-b22b-4dc35776b400', N'Explain the ''Database Sharding'' strategy and its associated architectural challenges.', N'Senior', N'Sharding distributes data across multiple database instances based on a partition key to scale write throughput and storage capacity. The main challenge is performing cross-shard queries and maintaining ACID guarantees, as atomic operations are difficult across physical boundaries. Poor shard key selection can also lead to ''hot shards,'' where a single node receives disproportionate traffic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
