INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'47ab34cb-6631-462e-8c4f-f78b04567eaa', N'210c7148-726e-4e8b-bf12-40be36e55130', N'What is a lifetime in Rust and why are they necessary?', N'Middle', N'Lifetimes are a construct that the compiler uses to ensure that all borrows are valid and that data is not accessed after it has been dropped. They are necessary to prevent dangling pointers by documenting the relationship between the scope of different references.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
