INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd781469c-a525-49b9-8795-f78d94a16822', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'Explain the architectural trade-offs of using ValueTask versus Task in asynchronous C# methods.', N'Senior', N'ValueTask is a struct designed to reduce heap allocations when an asynchronous operation completes synchronously. It should be used only for high-frequency paths where the overhead of a Task object allocation is measurable, as it carries risks of misuse such as awaiting it multiple times.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
