INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0121c16b-6a6a-441f-b323-f792a6d125f8', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'How to get responses of multiple api calls, when some API fails?', N'Fresher', N'Promise.allSettled(): To handle failures in multiple API calls, Promise.allSettled() method can be used. The method returns a Promise that resolves after all of the given promises have either resolved or rejected. It returns an array of objects with two properties: status and value. The status property is either "fulfilled" or "rejected", depending on whether the promise was resolved or rejected. The value property is the value of the promise if it was resolved or the reason for rejection if it was rejected. Example:', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a9d2b9d0-e535-4707-b96b-f79866354fb1', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'Why is it important to use ''Self'' in protocol extensions?', N'Middle', N'Using ''Self'' refers to the concrete type that is adopting the protocol rather than the protocol itself. This allows methods in extensions to return or interact with the specific type, maintaining type safety instead of returning the generic protocol type.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'20707b24-bfe8-4c7a-8648-f79fe7acc754', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'How do you pass data from a parent component to a child component in Lit?', N'Junior', N'Data is passed to child components via HTML attributes or properties. In Lit, the parent sets the property value on the child element, and the child''s reactive property receives that value to update its internal state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'11487fe0-1cad-40df-bf5a-f7a29c82aa97', N'55404b9c-91b6-4b62-9dc7-63248e8ea1df', N'Explain the ''CQRS'' pattern and why it is used for scaling.', N'Senior', N'CQRS (Command Query Responsibility Segregation) separates the models for reading and writing data, allowing each to be scaled independently. This allows for optimized read-side schemas or projections, such as using an Elasticsearch index for searching while keeping a relational store for transactional integrity.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4d243072-1229-455a-9e61-f7a33afe84c6', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'How are sessions handled in Flask?', N'Intern', N'Flask uses sessions to store information specific to a user across multiple requests. These are stored on the client side in a signed cookie, which ensures the data cannot be modified by the user without invalidating the signature.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1c8cef71-a36f-4546-9c9f-f7a375ea6d23', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'Explain the security implications of using Django''s auto-escaping and when it might be bypassed.', N'Senior', N'Django''s template engine auto-escapes output to prevent XSS, but this can be bypassed using the ''safe'' filter or ''mark_safe'' function. These should be used with extreme caution, only when the input is known to be trusted and sanitized, as improper usage opens the application to arbitrary code execution.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c8d22399-63af-4f26-85c0-f7a4f9f0c42e', N'210c7148-726e-4e8b-bf12-40be36e55130', N'What is a ''borrow'' in the context of Rust programming?', N'Intern', N'Borrowing is the act of creating a reference to a resource without taking ownership of it. Rust allows either one mutable reference or any number of immutable references to a piece of data at any given time. This mechanism prevents data races at compile time.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'91e64927-c725-4124-a3b3-f7a6cba9e32c', N'210c7148-726e-4e8b-bf12-40be36e55130', N'How does Rust''s variance system affect subtyping in generic types?', N'Senior', N'Variance defines how the subtyping relationship of complex types relates to their components, such as whether a reference to a long-lived type can be used where a short-lived one is expected. Rust uses this to ensure that lifetimes are sound when passing generic types, preventing the creation of dangling references through covariant or contravariant conversions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5bb47fb4-76ce-4479-a49c-f7a8a7103d79', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'What is an API?', N'Intern', N'An API, or Application Programming Interface, is a set of rules and protocols that allow different software applications to communicate with each other. In backend development, it typically refers to an interface that allows a client to request data or perform actions on a server.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'542d1dd7-0978-43e8-829b-f7a8e0905bfd', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'What is the benefit of breaking a large problem into smaller sub-problems?', N'Intern', N'Breaking down a large problem makes it easier to understand, manage, and solve because each sub-problem is less complex. It allows for easier delegation of tasks within a team and provides clearer milestones to track progress. It also makes it simpler to test and debug specific components of the overall solution.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'781f74cb-52a1-45a6-acda-f7a90641d221', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'Describe the browser''s paint process and how CSS properties like ''background-attachment: fixed'' affect it.', N'Senior', N'The paint phase involves converting computed styles into pixels. Properties like background-attachment: fixed force the browser to repaint the background whenever the scroll position changes, which can cause significant performance bottlenecks on low-powered devices compared to static backgrounds.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c04b17aa-b983-40e6-9511-f7a999cbdf4a', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'Why is the garbage collection process in JavaScript considered non-deterministic?', N'Middle', N'Garbage collection is managed by the engine''s internal implementation and runs automatically when memory pressure is high or during idle time. Developers cannot manually trigger or predict exactly when memory will be reclaimed, making it non-deterministic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
