INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c8c4e669-2368-4559-8256-f7c98def6754', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'What architectural risks are associated with injecting the ''ModuleRef'' directly into services?', N'Senior', N'The ''ModuleRef'' provides a way to resolve providers dynamically, which bypasses the standard static dependency injection graph. Overusing it can lead to hidden dependencies and decreased type safety, making it difficult to analyze the application''s structure and potentially hiding circular dependencies or misconfigured providers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
