INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f4a54202-e58c-4454-8bc2-f7cea00c5157', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'What is the Redis ''List'' data structure used for?', N'Intern', N'A Redis list is a sequence of string elements sorted by insertion order. It is commonly used to implement queues, where you can push elements to one end and pop them from the other.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'59590590-bc04-4a83-a036-f7d10d348e76', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'How does Axum''s approach to ''Query'' parameters differ from traditional frameworks?', N'Senior', N'Axum uses Serde for deserializing query parameters into custom structs, enabling strict schema enforcement. This design forces the developer to define the expected input format explicitly, which acts as living documentation and prevents bugs caused by unexpected or missing query string parameters.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a65d741a-afc4-401b-a4ef-f7d4e01e110d', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'How are variables declared in PHP?', N'Fresher', N'In PHP, variables are declared by placing a dollar sign ($) before the variable name. They do not require explicit type declaration because PHP is a loosely typed language.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5541c09d-c15b-4cb0-8eba-f7d5297e297d', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'What is the difference between include and require?', N'Intern', N'The main difference is how they handle errors. If the file is not found, include will generate a warning and continue the script, while require will generate a fatal error and stop the script execution.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'081f8499-1201-4569-bd3d-f7d71903c8e7', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'Why is Cassandra considered a ''Masterless'' architecture?', N'Intern', N'Cassandra uses a peer-to-peer architecture where all nodes are equal and perform the same tasks. This prevents a single point of failure and allows for easier scaling compared to master-slave systems.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
