INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'80ea064a-c327-41e0-8023-f7d95b2a7290', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'How do you debug an issue where data in a database is corrupted or inconsistent?', N'Middle', N'I would first identify the scope of the corruption by querying the affected tables and comparing the data against audit logs or application logs to trace back when the change happened. I would then analyze the code responsible for those data modifications to identify missing transaction boundaries or race conditions. Once the logic error is fixed, I would run scripts to sanitize and repair the inconsistent data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0ee8d470-3241-4843-8f66-f7da218acc22', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'What is Eventual Consistency?', N'Intern', N'Eventual consistency is a model where the system guarantees that, if no new updates are made to an item, all access to that item will eventually return the last updated value. It allows for higher availability by not requiring immediate synchronization across all nodes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f51a782d-0d2b-44c4-acef-f7de87454e74', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'How does Go handle error handling?', N'Intern', N'Go treats errors as values rather than using exceptions. Functions typically return an error as a second return value, which the caller is expected to check.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7d60709d-ea58-49e4-8b80-f7df1f7cd378', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'Why use TypeScript with NestJS?', N'Intern', N'TypeScript provides static typing, which helps catch errors during development and improves code readability. NestJS is built with TypeScript to take advantage of these features, ensuring better maintainability and developer experience.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0f94eaf3-e061-4486-87da-f7e0849166c3', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'How do you handle feedback on your work that you strongly disagree with?', N'Fresher', N'I listen carefully to understand the reasoning behind the feedback, as there might be project-specific context I am missing. I ask clarifying questions to ensure I fully grasp their perspective and then explain my reasoning calmly and professionally. If we still disagree, I am willing to defer to the team’s standards or seek a third opinion to find the best path forward.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b56a0deb-9178-46d7-ba11-f7e1fcb49b6d', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'How do you balance speed with quality in your work?', N'Fresher', N'I aim for high quality by following best practices from the start, which prevents costly rework later. While speed is important, I prioritize accuracy to ensure the final result does not require constant patching.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a5f33d2a-bdc3-4961-9f36-f7e547da4a4d', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'How does CSS Grid layout differ from Flexbox regarding internal browser calculation?', N'Senior', N'Flexbox is content-out, meaning it calculates sizing based on the items within the container, which can lead to complex reflows if content changes. CSS Grid is container-in, allowing for explicit layout definitions that are generally more performant and predictable for complex, two-dimensional page structures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
