INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'74e73ae2-b007-4516-90f4-f7ef2a445278', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'Why is ''serialization'' critical in Qwik?', N'Middle', N'Serialization is essential because it allows the application state to be transferred from the server to the client via the HTML itself. Without it, the browser would have to re-run all initialization logic to recreate the state, which would defeat the purpose of resumability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'abc96177-f76e-488c-9ab2-f7efa45da0e5', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'How does Next.js determine whether a route should be statically or dynamically rendered?', N'Middle', N'Next.js automatically chooses static rendering by default if data fetching is constant or can be cached at build time. It switches to dynamic rendering if the page uses functions like cookies, headers, or fetch calls with no-store caching, ensuring the response is generated per request.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'10e48b45-dc8e-4442-a035-f7f0a4551b6e', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'What does ''high availability'' mean in the context of NoSQL?', N'Intern', N'High availability means that the database remains operational and accessible even if a server or node fails. This is typically achieved through replication and automated failover mechanisms.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
