INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c9a12fb5-39a4-497a-9d4b-f7fb4428bac7', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'When designing for high availability, how do you handle the trade-off between consistency and availability during a network partition?', N'Senior', N'Apply the CAP theorem to prioritize one based on the specific business requirement. If data integrity is paramount, prioritize consistency even if it leads to downtime; if the user experience depends on continuous access, prioritize availability and implement conflict resolution strategies like eventual consistency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
