INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd24e8cef-ae6d-4a0a-bf2b-f7fe7089e754', N'954a0331-deff-4399-b588-96f39fec001d', N'How can Angular''s ''ChangeDetectorRef'' be used to manually manage performance in scenarios where standard strategies are insufficient?', N'Senior', N'ChangeDetectorRef allows manual interaction with the change detection cycle via methods like detectChanges() or markForCheck(). This is useful when data updates occur outside of Angular''s zone, such as during complex third-party library integrations or WebSocket messages, to ensure the UI remains in sync with the underlying state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'35539518-8a69-4cae-b90b-f80353ce7ad9', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'Do NoSQL databases typically support ACID transactions?', N'Fresher', N'Many traditional NoSQL databases prioritize performance and availability over strict ACID compliance, often following the BASE model instead. However, some modern NoSQL systems have introduced support for multi-document ACID transactions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd3c1dce5-ee00-486d-8a59-f8040027b474', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'How do you approach the debugging of a race condition in a distributed locking mechanism?', N'Senior', N'I review the implementation of the lock acquisition logic to ensure that fence tokens or timestamps are correctly used to guard against stale writes. I analyze distributed logs to detect instances where multiple clients successfully acquired the same lock or where lock expiry occurred during an active operation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1c0d7fd6-ca19-4506-a286-f8044428ffd3', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'What is the ''ducks'' pattern in Redux?', N'Middle', N'The ducks pattern is a way to organize code by grouping the action types, action creators, and the reducer for a specific feature into a single file. This improves maintainability by keeping related logic physically close in the project structure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ba4b7496-3948-4567-814b-f8047b99d518', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'What is the function of the ''useAsyncData'' composable?', N'Junior', N'useAsyncData is used to fetch data from an API during the server-side rendering phase. It ensures that the data is fetched and available before the page is sent to the client, preventing content flickering.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'561d0801-34d4-4477-9f35-f804d90a9e23', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'How does the ''Plugin'' system in Litestar affect application startup time and memory footprint?', N'Senior', N'Plugins allow for modular extension of the framework, but loading too many plugins can increase the initial startup time and memory usage. It is essential to only include necessary plugins and ensure they are optimized, as they often hook into the application lifecycle and dependency resolution processes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e4ed6a08-9e8d-4ca4-b0cb-f8051dd85717', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'What is eventual consistency and when is it acceptable?', N'Middle', N'Eventual consistency is a model where data updates are propagated to all nodes over time, ensuring that all accesses will eventually return the last updated value. It is acceptable in systems where high availability and low latency are prioritized over immediate, absolute data accuracy.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a0f798dc-5728-4aea-a6e7-f806f6764ae7', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'Why is it often recommended to use a separate validation library with Gin?', N'Middle', N'While Gin has basic binding capabilities, external validation libraries provide more powerful, declarative constraints like email format, range checks, and cross-field validation. This keeps the handler logic clean and adheres to the separation of concerns principle.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b528b062-dd7e-484b-89a4-f80977928869', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'How can Sass help in implementing a themeable application architecture?', N'Senior', N'Sass can manage theme tokens through maps, which are then passed to mixins to generate CSS variables or static utility classes for different theme modes. This allows for a clean separation between the design configuration and the CSS implementation, facilitating easier theme switching or customization.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'31d1bde4-1df4-4991-81b4-f80aea2c8d2a', N'954a0331-deff-4399-b588-96f39fec001d', N'What are the advantages with AOT?', N'Intern', N'Below are the list of AOT benefits, 1. Faster rendering: The browser downloads a pre-compiled version of the application. So it can render the application immediately without compiling the app. 2. Fewer asynchronous requests: It inlines external HTML templates and CSS style sheets within the application javascript which eliminates separate ajax requests. 3. Smaller Angular framework download size: Doesn''t require downloading the Angular compiler. Hence it dramatically reduces the application payload. 4. Detect template errors earlier: Detects and reports template binding errors during the build step itself 5. Better security: It compiles HTML templates and components into JavaScript. So there won''t be any injection attacks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'60381fba-06d0-4968-9a9b-f80d28e57866', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'What is the purpose of the ''src/pages'' directory?', N'Junior', N'The ''src/pages'' directory is the central hub for routing in an Astro project. Every file inside this folder automatically becomes a webpage reachable by a URL corresponding to the file''s path.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e3bd27f0-c5ce-49cc-8bf4-f815ac0220ac', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'What is the purpose of ''Middleware'' in Actix?', N'Intern', N'Middleware in Actix are components that wrap the request-response cycle. They allow you to perform actions before a handler is called or after a response is generated, such as logging, authentication, or modifying headers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3d02ea0d-13b3-4c50-a287-f81a7b28321a', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'What is the primary difference between a collection in NoSQL and a table in SQL?', N'Fresher', N'A table in SQL requires a rigid schema where all rows must have the same columns. A collection in NoSQL acts as a container for documents, where each document can have a unique set of fields, offering more flexibility.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'80d7513d-ea03-445a-a492-f81ae4100395', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'What architectural role does the ''Type Provider'' play in Fastify?', N'Senior', N'Type providers bridge the gap between runtime schema validation and static analysis. By using TypeScript''s type system to generate schemas automatically, they ensure that the API contract is always in sync with the codebase, reducing runtime bugs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'97c98325-0f82-4804-8ac8-f81b8f0f8012', N'fcd5873e-c89a-47d6-bb4c-c60b57c2ede1', N'What is ''Distributed Tracing'' and why is it necessary for microservices?', N'Senior', N'Distributed tracing tracks a request''s path through multiple services by propagating a unique correlation ID. It is essential for debugging performance bottlenecks and failures in complex architectures where a single user action may trigger a chain of asynchronous service calls.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7eb1a539-1e8b-4c5f-a855-f81c25c61c13', N'24c74bdc-c63e-4370-b1ac-bd560cb834d6', N'How do you handle long-running processes via a REST API?', N'Senior', N'Return a 202 Accepted status code immediately with a Location header pointing to a status endpoint. The client can then poll this status resource to check for completion, or receive a webhook callback if the process is asynchronous and long-lived.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b9ed8d86-3e85-4111-8da1-f81ef5828371', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'How can you prevent SQL injections?', N'Fresher', N'Modernized SQL Injection (SQLi) Defense Strategies (2026) SQL Injection (SQLi) occurs when an application improperly neutralizes user-supplied input, allowing an attacker to interfere with query logic. Defense relies on the principle of separation of data from code. --- 1. Parameterized Queries (Prepared Statements) Description: The industry-standard primary defense. The SQL query structure is sent to the database engine first, and user inputs are sent later as bound parameters. The database driver ensures inputs are treated strictly as data, never as executable code, reducing the risk to $O(1)$ complexity regarding query logic manipulation. - Python (SQLAlchemy 2.0 / psycopg3) Example: - Benefits: - Eliminates the category of "In-band" SQLi.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b8da96f7-d55f-42d5-af20-f81f67b0d2a5', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'What are the trade-offs of using Remix on the edge versus a traditional Node.js server?', N'Senior', N'Edge deployment reduces latency by running code geographically closer to the user but imposes limitations on runtime size and persistent connections. Traditional servers offer more flexibility and access to long-running background processes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ac0a7f1d-8d26-4f87-a9c8-f81fedd08bfd', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'When investigating a memory leak in a production environment, what metrics and tools do you prioritize?', N'Senior', N'I prioritize heap utilization metrics, garbage collection pause times, and object allocation rates. I would use memory profiling tools to capture heap dumps and analyze them for long-lived objects or growing collections that suggest a failure to release resources.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'561ab272-37ea-489d-84ba-f820e7c189ef', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'What is meant by the term ''Immutability'' in Scala?', N'Fresher', N'Immutability refers to the practice of creating data structures that cannot be changed after they are created. This helps prevent side effects and simplifies reasoning about code, especially in concurrent programming environments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3d7eb006-73ca-44c3-a7a7-f822c369e8c4', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'What does it mean for a property to be reflected to an attribute?', N'Fresher', N'Reflecting a property to an attribute means that when the JavaScript property value changes, Lit automatically updates the corresponding HTML attribute on the element. This is useful for allowing CSS to select the element based on its property state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'99486d59-06c5-4995-af53-f82347815f7b', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'How do browser engines optimize CSS style sharing?', N'Senior', N'Browsers optimize performance by sharing computed style objects between elements that have identical property values. Over-using unique inline styles or highly dynamic class toggling prevents this optimization, forcing the browser to compute styles individually for every element.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3352f96a-6243-4d04-8aaf-f823b7e9ea2c', N'24c74bdc-c63e-4370-b1ac-bd560cb834d6', N'What is the role of an API contract, and how does it benefit development?', N'Middle', N'An API contract serves as a formal agreement between the client and the server regarding the request/response structure and behavior. It enables parallel development, as teams can build against the contract without waiting for the actual implementation, and serves as a foundation for automated testing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f9e27b37-b53c-47a8-8dad-f8293228c40c', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'How does Preact''s approach to error boundaries compare to the standard React pattern?', N'Senior', N'Preact provides error boundaries via the ''componentDidCatch'' lifecycle method, allowing components to catch errors in their child component tree. This pattern is functionally identical to React''s, providing a mechanism to gracefully handle UI failures without crashing the entire application, though it relies on Preact''s specific reconciliation path.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f5596235-6825-454b-86fd-f82d7d4594c3', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'How can you optimize Spring Boot startup time for serverless environments?', N'Senior', N'You can use Ahead-of-Time (AOT) compilation with GraalVM to generate native executables, which significantly reduces startup latency and memory footprint. Additionally, disabling unnecessary auto-configurations and using lazy bean initialization can further speed up the process.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e9eec8bd-40b9-4a4d-bb8e-f82e508b5513', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'What are the architectural implications of using React Context for global state management?', N'Senior', N'Context is designed for dependency injection of low-frequency data rather than high-frequency state updates. Because any component consuming a context value will re-render whenever the value changes, frequent updates can lead to performance bottlenecks, making it less efficient than dedicated state management libraries for complex, granular state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2f635065-907d-4922-89f2-f82f424d3d5d', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'Why would you choose to use ''web::block'' in an Actix-web application?', N'Middle', N'web::block is used to offload blocking functions to a separate thread pool managed by the runtime. This is essential when interacting with synchronous libraries, such as legacy database drivers, ensuring that the main event loop remains responsive.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fe87b2d6-ce31-4503-9503-f83037d782ab', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'What is the difference between a Module and a Controller in NestJS?', N'Junior', N'A Controller is responsible for handling incoming HTTP requests and returning responses to the client. A Module acts as an organizational unit that groups together related controllers, providers, and other modules to define the application structure and boundaries.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2dfc0aa0-a8f9-4f4a-b0b2-f83045526ee4', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'Explain how this works in JavaScript?', N'Fresher', N'The this keyword refers to an object. Which object depends on how this is being invoked (used or called). The this keyword refers to different objects depending on how it is used. * In an object method, this refers to the object. * Alone, this refers to the global object. * In a function, this refers to the global object. * In a function, in strict mode, this is undefined. * In an event, this refers to the element that received the event. * Methods like call(), apply(), and bind() can refer this to any object. Example:', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b856732d-bdb9-4dab-85e8-f8308a628d11', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'Explain the architectural trade-offs of using the 7-1 pattern in a large-scale Sass project.', N'Senior', N'The 7-1 pattern enforces modularity and maintainability by organizing files into specific folders like base, components, and layout. While it significantly improves scalability and developer experience in large teams, it can lead to a deeply nested file structure that requires careful management of import paths and compilation overhead.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e0ec5cea-942d-4c03-86e6-f830f60918b9', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'Explain the ''Guard'' vs ''Authenticator'' concepts in Symfony Security.', N'Senior', N'The Guard component was an older, event-driven approach to handling authentication, which has been superseded by the Authenticator system in modern Symfony versions. The current Authenticator architecture is more streamlined, reducing complexity by consolidating authentication logic into a single class responsible for handling requests, credentials, and identity loading.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8c9a3748-eada-4d1c-9562-f8320c65e524', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'What is an ''async'' function in FastAPI?', N'Intern', N'An async function allows the server to handle other requests while waiting for an I/O-bound operation, such as a database query or an external API call, to finish. This improves the overall concurrency and scalability of the application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cc955ed2-a437-42c5-84fc-f83633bfb896', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'How do you access the event object in an Alpine.js handler?', N'Fresher', N'You can access the native browser event object in any Alpine.js expression by using the special $event variable. This allows you to inspect event targets, input values, or keystrokes directly.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
