INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2256fe4c-a8ac-4c40-ad93-f83a22617f50', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'Why should you avoid using console.log for production logging?', N'Junior', N'Console.log is synchronous and can block the event loop, which degrades performance under heavy load. Production environments typically use dedicated logging libraries that handle logs asynchronously and offer features like log levels, file rotation, and structured output.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd6ee89ef-fec9-43f6-bd8b-f83ced929fc3', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'What is the difference between a variable declaration and a definition?', N'Fresher', N'A declaration informs the compiler about the existence, name, and type of a variable without allocating memory for it. A definition informs the compiler to allocate memory for the variable based on its type.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
