INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'034f0291-ac55-4e7b-b183-f843b5bceb66', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'When considering documentation, what is the trade-off between writing extensive docs versus writing self-documenting code?', N'Junior', N'Self-documenting code is always up to date and close to the logic, which is highly efficient. External documentation is necessary for explaining the ''why'' behind architectural decisions and onboarding new members, but it is often neglected and can quickly become outdated.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e186115c-841f-499e-989d-f844ef60ebdb', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'What is the difference between a full backup and an incremental backup?', N'Junior', N'A full backup creates a complete copy of the entire database. An incremental backup only saves the data that has changed since the last backup, which saves storage space and reduces the time required for the backup process.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'176ad631-4d09-4299-a12a-f8454689a8c5', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'In what scenario would Preact''s synthetic event system be considered a performance advantage over native DOM events?', N'Senior', N'Preact''s event delegation attaches a single event listener to the document root, which improves performance in large, dynamic lists. By bubbling events up to the root, it avoids the memory overhead of attaching individual listeners to thousands of child elements.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
