INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'73d49363-cc74-4f8d-8a7b-f84bf061f367', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What is TypeScript and how does it relate to JavaScript?', N'Intern', N'TypeScript is a strongly typed programming language that builds on JavaScript by adding static type definitions. It is a superset of JavaScript, meaning any valid JavaScript code is also valid TypeScript code, which is then compiled into plain JavaScript for browsers to execute.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a7a10925-72f3-4dba-bf91-f84c4d2d4b5b', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'How does the WeakMap data structure differ from Map, and what are its primary use cases in large-scale applications?', N'Senior', N'WeakMap holds weak references to its keys, allowing garbage collection to reclaim keys if no other references exist, which prevents memory leaks. It is ideal for storing private data associated with DOM elements or objects without interfering with the object''s lifecycle.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1ff92f6a-648f-4aa1-b0ca-f84c75eb4b80', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'How does DynamoDB reconcile updates in Global Tables?', N'Senior', N'DynamoDB Global Tables use a ''last writer wins'' conflict resolution strategy based on timestamps. In the event of concurrent writes to the same item in different regions, the system keeps the version of the item with the most recent timestamp.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
