INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'90e59f36-323f-4c9b-bac9-f8509a935816', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'How do you handle logging in a Flask application to facilitate effective debugging?', N'Middle', N'You should use Python''s built-in logging module, configuring different handlers for different severity levels and output destinations. It is best practice to log structured data to a file or a centralized logging service rather than relying on standard output, ensuring that logs are persistent and searchable during production issues.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e28e6c3f-928b-403b-9b00-f85251e004e9', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'How do you evaluate the ''cost of delay'' when deciding between fixing technical debt and shipping a new feature?', N'Senior', N'I quantify the cost of delay by assessing the potential impact on customer churn, development velocity, and system stability if the debt is not addressed. I prioritize based on which option maximizes long-term ROI, often favoring the fix if the debt is currently acting as a bottleneck to future feature delivery.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
