INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6092c903-e9ce-4146-9221-f85bc49225dd', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'How is the concept of inheritance applied in CSS?', N'Fresher', N'Inheritance is a concept in which the child class will inherit the properties of its parent class. It is used in CSS to define the hierarchy from the top level to the bottom level. Inherited properties can be overridden by the children class if the child uses the same name. Example:', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd7578749-6bd5-4acd-9ace-f85bde265c90', N'4c000000-0000-0000-0000-000000000005', N'What are the common strategies for handling cache invalidation?', N'Middle', N'Strategies include Time-To-Live expiration, write-through caching, or explicit cache eviction when data is updated. Choosing the right strategy depends on the balance between data freshness requirements and performance goals.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'227821d0-85f5-45ed-a18b-f85fe5354459', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'What is a subquery?', N'Intern', N'A subquery is a query nested inside another SQL query. It is used to return data that will be used in the main query as a condition to further restrict the data to be retrieved.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'61aebe73-76a2-4ce9-86fd-f8607a847b41', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'What is the Intermediate Language (IL) in the context of C#?', N'Intern', N'When C# source code is compiled, it is converted into Intermediate Language, which is a CPU-independent instruction set. This IL code is then executed by the Common Language Runtime, which uses Just-In-Time compilation to translate the IL into native machine code for the specific processor.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dda77fe0-ce5f-4709-abf8-f8609b0d162e', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'What is the Scala Collection hierarchy?', N'Intern', N'The Scala collection hierarchy is a set of classes and traits organized into mutable and immutable versions. It provides a rich set of methods for transforming, filtering, and traversing data, providing a consistent API across different types of collections.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f6208dd6-4ee5-4f9c-b0bc-f863dd8f95ee', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'When should you choose a Global Secondary Index (GSI) over a Local Secondary Index (LSI)?', N'Middle', N'GSIs should be used when you need to query by a different partition key or require more flexibility in terms of index creation and scaling. Unlike LSIs, GSIs can be created at any time and consume their own independent provisioned throughput.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a792e992-7e4b-42c7-bbb2-f8645e9d06d1', N'18ebabb7-555b-4ba1-beb6-844b8ee55dbd', N'What is Cache Eviction, and what are common strategies?', N'Middle', N'Cache eviction is the process of removing entries from the cache when it reaches its capacity. Common strategies include Least Recently Used (LRU), which removes the oldest items accessed, and Least Frequently Used (LFU), which removes items with the lowest access count.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'373ac6d0-5327-44be-b8ca-f866347ebe7a', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'How does Echo handle URL parameter extraction, and is it safe from common vulnerabilities?', N'Senior', N'Echo uses structured path parsing to extract parameters, which is inherently safer than manual string splitting. Since parameters are treated as distinct variables, it mitigates common injection risks, though developers must still validate the content of these parameters before passing them to database queries.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4f4a0523-001c-484b-8eb1-f866a6d09f39', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'Explain the impact of the ''split-brain'' scenario in a master-slave replication setup.', N'Senior', N'Split-brain occurs when the network connection between nodes fails, causing multiple nodes to believe they are the primary and accept writes simultaneously. This leads to data divergence and integrity issues that are difficult to reconcile, requiring robust fencing mechanisms or consensus algorithms like Raft or Paxos to prevent.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
