INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bbc88c86-28f5-424b-a905-f8761c0a5a6f', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'Does Astro require a backend server to run?', N'Intern', N'Not necessarily. If you use static site generation, Astro outputs simple HTML, CSS, and JavaScript files that can be hosted on any static file server or CDN. If you use SSR, you will need a server environment to handle requests.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
