INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b46219c1-1cc2-4fbc-86d9-f87edf047545', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'How do you distinguish between a ''nice-to-have'' feature and a ''must-have'' requirement when estimating?', N'Junior', N'I evaluate each requirement against the core project goals and the definition of a minimum viable product. Must-have items are essential for the primary functionality, while nice-to-have items are deferred to later phases to ensure the project remains on schedule.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
