INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8cc1bafa-9619-475e-a175-f8864b40f25a', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'Why might ''ObjectSpace'' be useful for debugging and profiling, and what are the performance concerns?', N'Senior', N'ObjectSpace allows for the traversal of all live objects currently tracked by the Ruby runtime, which is invaluable for identifying memory leaks and counting allocations. However, enabling or extensively traversing ObjectSpace can significantly degrade performance and increase memory usage, as it keeps references to objects that might otherwise be garbage collected.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
