INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e295d784-9b26-406b-b3bc-f8a839de5a6b', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'How does the Kotlin compiler implement reified type parameters, and what are their limitations?', N'Senior', N'Reified type parameters work by inlining the function at the call site, allowing the compiler to substitute the actual type argument into the bytecode. This mechanism only functions within inline functions and cannot be used with non-inlined code because the type information is erased at runtime otherwise.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
