INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f2c785e4-15fa-43dc-9c39-f8d43cff287b', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'What is the benefit of using NestJS''s built-in ValidationPipe?', N'Middle', N'It automates the validation of incoming request payloads using class-validator decorators. This ensures that invalid data is rejected before it reaches the business logic, reducing repetitive manual checks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'76486bb2-42ad-4c51-9481-f8da642f94af', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'How can ''sideEffects'' in package.json improve bundle optimization?', N'Senior', N'The ''sideEffects'' flag informs Webpack that a package does not modify global state or have imports that execute code solely for side effects. This allows Webpack to safely skip entire modules during tree shaking, significantly reducing the size of the final bundle.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0371c693-0654-4ed8-a60b-f8e07f93f844', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'Why is Hono considered suitable for Serverless environments?', N'Intern', N'Hono is well-suited for serverless because of its small footprint and reliance on standard Web APIs. These characteristics lead to faster startup times and lower memory usage, which are essential for minimizing costs and latency in serverless platforms.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e2093b26-18c4-445f-a7f1-f8e13785b877', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'How does Flask handle signal-based communication, and what are the risks of using it in a distributed system?', N'Senior', N'Flask signals allow decoupled components to react to events via a sender-receiver pattern. In a distributed system, these signals are strictly local to the application instance, making them ineffective for inter-service communication; relying on them for cross-service events would require an external message broker like RabbitMQ or Kafka.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'094b4e3c-5576-479f-8c87-f8e192cdfcb8', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'How does the gossip protocol work in a Cassandra cluster?', N'Middle', N'The gossip protocol is a peer-to-peer communication mechanism where nodes periodically exchange state information with a few randomly selected neighbors. This allows the cluster to maintain an updated view of node health and topology without a central master node.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c65e4fc7-7122-40de-81f5-f8e481162a11', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'Explain the concept of Dependency Injection in Symfony.', N'Fresher', N'Dependency Injection is a design pattern where an object''s dependencies are provided to it from the outside rather than being hardcoded inside the class. Symfony handles this automatically via the Service Container, making code easier to manage and swap during testing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b993515f-d93b-4c14-92ec-f8e490b7839f', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'Describe how Node.js manages the ''call stack'' during asynchronous operations.', N'Senior', N'Asynchronous operations in Node.js do not keep the function on the call stack; instead, they register a callback in the event loop and return immediately. When the operation completes, the callback is pushed onto the call stack as a new execution context, meaning stack traces for errors often lose context of the original caller without async stack traces.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'63bac29b-6a0e-4f18-b43a-f8e4b63b08e0', N'4c000000-0000-0000-0000-000000000005', N'Describe the difference between optimistic and pessimistic locking in database transactions.', N'Senior', N'Pessimistic locking prevents conflicts by locking resources upon access, ensuring consistency but reducing concurrency. Optimistic locking assumes conflicts are rare and validates state changes at commit time, which improves throughput in read-heavy systems but requires logic to handle retries upon collision.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd5dbbfb4-e854-4afa-8f24-f8e88fecda03', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'Describe the trade-offs of using MongoDB''s ''w: 1'' versus ''w: majority'' write concern.', N'Middle', N'The ''w: 1'' write concern acknowledges the write once it is applied to the primary node, offering lower latency but risking data loss if the primary fails before replication. ''w: majority'' ensures the write is acknowledged by a majority of voting nodes, providing higher durability and consistency at the cost of increased latency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ba58d18d-cc84-42e0-85bc-f8ea3f0ffb17', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is recursion in JavaScript?', N'Intern', N'Recursion is a technique in which a function calls itself until it reaches a base case (a condition that stops further calls). Every recursive function must have a base case to avoid infinite loops and stack overflow errors. Example 01: Factorial Example 02: Fibonacci Example 03: Flatten a nested array Recursion vs Iteration: * Recursion is more readable for tree/graph traversal, nested structures, and divide-and-conquer problems * Iteration is more performant for simple loops — use it when recursion depth could be large *Note: For deeply nested structures, iterative solutions with an explicit stack are preferred over recursion to avoid stack-overflow errors.*', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e903587d-fc6a-4100-a315-f8f0495552ff', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'Describe the trade-offs of using Redis Cluster versus a standalone instance with replication.', N'Senior', N'Redis Cluster provides horizontal scalability and automatic partitioning (sharding) across multiple nodes, which is essential for massive datasets. A standalone instance with replication is simpler to manage but is limited by the memory capacity of a single machine and provides only read-scaling.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'375fbaf6-d045-48d4-8b40-f8f254e38634', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'Why is ''resumability'' considered a paradigm shift in frontend development?', N'Fresher', N'Resumability is a shift because it challenges the assumption that hydration is a necessary step for client-side interactivity. By proving that applications can resume from server-side state, it enables a new level of web performance that traditional frameworks struggle to match.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8eb5908b-5605-47cc-968d-f8f2dd480f7d', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'In a distributed Phoenix deployment, how do ''Nodes'' discover each other, and what are the limitations?', N'Senior', N'Nodes typically discover each other via mDNS, DNS, or static configuration within a cluster. The main limitation is the ''fully connected'' requirement for the Erlang distribution protocol, which can become a bottleneck as the number of nodes increases, often requiring a hub-and-spoke topology or partitioned clusters.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'175eb222-aa89-44aa-a9be-f8f5349cb1b3', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'Why might you choose a relational database over a NoSQL database?', N'Intern', N'Relational databases provide strict schema enforcement and complex query capabilities that are ideal for structured data and transactional integrity. NoSQL databases are chosen when you need to handle massive volumes of unstructured data or require extreme write speeds.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cb414042-d2b0-4be9-a23d-f8f5452fc034', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'How does the ''shared_buffers'' parameter influence database performance, and is ''bigger always better''?', N'Senior', N'Shared buffers store frequently accessed data pages in memory to reduce disk I/O. While more memory generally helps, setting it too high can lead to OS-level page cache contention and increased checkpoint overhead, causing diminishing returns or performance instability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'43e7a8c5-32cb-4a42-94b3-f8f5d9368727', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'What is the difference between a synchronous and asynchronous function?', N'Fresher', N'A synchronous function executes tasks sequentially and blocks the execution until the current task completes. An asynchronous function allows the program to continue executing other tasks while waiting for a long-running operation to finish.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0dd3fff2-fd81-4834-8b43-f8f5edd5e82d', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'Explain the concept of Micronaut Data.', N'Fresher', N'Micronaut Data is a database access toolkit that generates repository implementation code at compile-time. It provides a simple way to perform database operations without the overhead of runtime reflection found in traditional ORMs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4cc64544-7b26-45d1-abcc-f8f670996e6e', N'f2e963ff-7635-4429-a389-4d92535fb972', N'How do you create an accessible HTML table?', N'Fresher', N'An accessible table ensures screen reader users can understand the relationship between headers and data cells. Key techniques: 1. Use with scope for all header cells: 2. Use id + headers for complex tables with merged cells: 3. Always include for a meaningful title. 4. Avoid using tables for layout — use CSS Grid or Flexbox instead. Layout tables confuse screen readers that expect tabular data. 5. Don''t use empty header cells — if a corner cell has no content, use instead of , or add visually hidden text: Accessibility checklist: - [ ] present - [ ] All column headers use - [ ] Row headers use where applicable - [ ] Complex tables use id/headers association - [ ] No empty cells - [ ] Table used for data, not layout', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2ef320e4-c294-4f00-a707-f8f7ad49dad9', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'How does the Symfony Request-Response kernel handle sub-requests, and what are the performance implications?', N'Senior', N'Sub-requests allow for the nesting of controller logic, which is useful for modular components like ESI or fragments. While powerful for code reuse, heavy reliance on sub-requests can increase memory consumption and latency, as each sub-request triggers its own kernel boot and event propagation cycle.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'01e23da7-8b6f-4e1c-9cbb-f8fa8bc81b5d', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'What are the advantages of using ''View Components'' compared to standard partials?', N'Middle', N'View Components allow you to encapsulate view logic into Ruby classes, making them easier to test and reuse across the application. Unlike partials, which rely on instance variables in controllers, components provide a clean interface for passing data and promote better separation of concerns.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd45f2b7a-9b91-4c14-9935-f8fb974d971f', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'How does Axum achieve type-safety when extracting data from HTTP requests?', N'Middle', N'Axum uses the ''FromRequest'' trait, which allows the framework to automatically deserialize request parts like headers, query parameters, or JSON bodies into Rust structs. This process enforces type-checking at compile time, ensuring the handler only receives valid, well-structured data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'63a6489e-9360-48f1-8fe0-f8fdc33fc058', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'Describe the security implications of using Astro''s dynamic routing compared to static routing.', N'Senior', N'Static routing pre-generates paths at build-time, virtually eliminating common injection vulnerabilities associated with dynamic URL parameter processing. Dynamic routing in SSR mode requires rigorous server-side validation to prevent cross-site scripting or unauthorized data exposure, as the server is processing user-controlled inputs to generate the page content.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'13d87956-86dc-41dd-b479-f902b8aa884e', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'What does ''Dependency Injection'' look like in Quarkus?', N'Junior', N'Quarkus uses ArC, a dependency injection framework based on CDI, which is optimized for build-time resolution. It allows developers to inject beans into classes using the Inject annotation, ensuring loose coupling and easier testing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8d362bfd-0bbe-46b9-8e4e-f9066f31fb76', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'Why is DynamoDB considered ''schemaless''?', N'Intern', N'DynamoDB is considered schemaless because it does not enforce a strict structure on the data stored in a table. You can add or remove attributes for individual items without having to modify the entire table structure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ba898575-fe44-4a5f-8ddd-f9069c1aab1f', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'How does the ''shouldComponentUpdate'' method influence Preact''s performance?', N'Senior', N'By implementing ''shouldComponentUpdate'', developers can prevent unnecessary re-renders by performing shallow equality checks on props and state. This is a manual optimization technique that stops the reconciliation process early, saving CPU cycles in complex component trees where deep re-renders are costly.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8080cd7b-74a5-41ba-b473-f906ee6371a4', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'How do you troubleshoot a circular dependency issue between two microservices?', N'Middle', N'I would analyze the request flow and service dependencies to identify the cycle, then redesign the communication pattern to use an asynchronous event-driven architecture or an intermediary service. By decoupling the services, I eliminate the direct dependency, making the system easier to debug and more resilient to failures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'20f9998c-b031-445f-8207-f907ce0a6018', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'What is the advantage of using Quarkus for serverless applications?', N'Fresher', N'Serverless environments require fast cold-start times to be effective. Quarkus''s native compilation provides near-instant startup, which prevents the latency issues common in traditional Java applications when they are triggered by serverless events.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'128d7a93-7909-4089-a32c-f90bfa089c66', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'Why is it beneficial to separate the concerns in a software design?', N'Intern', N'Separation of concerns makes the system easier to understand, maintain, and test because each module focuses on a single responsibility. If one part of the system needs to change, it is less likely to break unrelated components.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8013cc6d-c60c-4e93-8f4f-f90d37125f43', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'How do you approach the decision to build a custom solution versus using an existing third-party library?', N'Intern', N'Building a custom solution provides full control and avoids external dependencies, but it requires significant maintenance and development time. Using a library saves time and leverages community expertise, but it introduces a dependency on external code that may not perfectly match your requirements.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3f214d4e-10e4-40b1-a8d6-f90dc91da994', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'What is the role of the Service Container in Symfony?', N'Intern', N'The Service Container is a tool used to manage the instantiation and injection of services throughout an application. It centralizes the creation of objects, ensuring that dependencies are automatically provided to classes, which promotes loose coupling and easier testing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'999bd1dd-100c-4750-bfcf-f90de546e4cf', N'074508f7-35bd-405f-8cc6-b41377b2d92c', N'What is backpressure and how is it handled in messaging systems?', N'Middle', N'Backpressure occurs when a system receives data faster than it can process it, potentially causing buffer overflows or crashes. It is handled by slowing down the producers, increasing consumer concurrency, or using persistent storage to buffer the overflow until the consumer catches up.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'de852efd-2a73-4823-a6e5-f90e8ed121c7', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'How do Ember''s ''Service'' objects differ from simple singletons, and what is their impact on application state management?', N'Senior', N'Services provide a formalized, dependency-injected way to share state and logic across the application. Unlike simple singletons, services are managed by the Ember container, making them easier to test, mock, and inject into components without creating tight coupling.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5005e70c-83e7-4747-849f-f90ea8a2fdf5', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'Why is it important to use parameters in queries instead of concatenating strings?', N'Junior', N'Using parameterized queries prevents SQL injection attacks, where malicious users might attempt to manipulate queries to gain unauthorized access. It also allows the database to reuse query execution plans, improving overall performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9fadaae0-fcaf-4e81-9df7-f90fb97ae9de', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'What is meant by the term ''strongly typed'' in the context of Dart?', N'Intern', N'Being strongly typed means that the type of a value is known at compile time or runtime, and the language enforces strict rules about how those types interact. Dart uses a mix of static type checking and runtime checks to ensure type safety.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9e470eb1-1e6b-4e5b-a599-f91106629a78', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'Why is it generally recommended to avoid using @extend across different media queries?', N'Middle', N'Sass cannot extend a selector from inside a media query to outside of it, or vice versa, because of how CSS rules are structured. Attempting to do so often results in compilation errors or unexpected CSS output, making it safer to use mixins for responsive style variations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f402621e-cab8-4fd0-addb-f91349fad601', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'What is an ''endpoint'' in SvelteKit?', N'Fresher', N'An endpoint is a server-side route defined in a +server.js file that handles HTTP requests like GET, POST, PUT, or DELETE. It allows you to create server-side logic that does not render any Svelte components.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5abfe684-5398-4501-aa94-f91718182db1', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'Can you use dynamic routes in Astro?', N'Junior', N'Yes, Astro supports dynamic routes using bracket notation in file names, such as ''src/pages/posts/[id].astro''. This allows you to generate multiple pages from a single template using data sets or APIs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e3d732a2-4910-425e-8ccf-f91b6ec9420c', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'How does Flask''s ''request'' object handle multiple concurrent uploads or large request bodies?', N'Senior', N'Flask streams request bodies to temporary files or memory buffers depending on configuration settings, preventing the entire request from loading into RAM. For large uploads, it is critical to configure maximum content length limits to prevent resource exhaustion attacks and ensure the underlying WSGI server is configured to handle streaming correctly.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd2a2d57c-b670-42bc-9d12-f91fd0f67b78', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'How do you manage configuration in a scalable Express application across different environments?', N'Senior', N'Environment-specific configurations should be managed using environment variables rather than hardcoded files. Tools like dotenv are common, but for production, injecting variables directly from orchestration platforms like Kubernetes or secret managers ensures security and consistency across deployment stages.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7edd8407-49c8-4254-9446-f92107041e21', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'What are the primary performance concerns when using Java Reflection in high-throughput systems?', N'Senior', N'Reflection bypasses compile-time type checking and incurs overhead due to constant access checks and method resolution. While modern JVMs optimize reflection via internal caching, it still prevents many JIT optimizations like inlining, and excessive use can lead to significant bottlenecks in performance-critical code paths.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b9f190cb-0c51-4c9a-a78d-f921139547dd', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'Why is ''VACUUM FULL'' generally discouraged in favor of the ''pg_repack'' or ''pg_squeeze'' extensions?', N'Senior', N'VACUUM FULL requires an exclusive lock on the table, blocking all reads and writes until the operation completes, and it rewrites the entire table to disk. Extensions like pg_repack perform the same task by creating a new table in the background and syncing changes, allowing for online operation without downtime.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2907bb95-feb4-4ee4-bb51-f922d768e5d7', N'f2e963ff-7635-4429-a389-4d92535fb972', N'Why is semantic HTML important for accessibility and SEO?', N'Middle', N'Semantic HTML uses tags that describe the meaning of content, such as nav, article, or section, rather than just style. Assistive technologies like screen readers rely on these elements to provide a meaningful structure to users. Search engines also use these tags to better understand the hierarchy and relevance of content, which can improve indexing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a6cdfb37-4c20-4a4c-91bd-f923a139244e', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'What is the x-show directive used for?', N'Intern', N'The x-show directive is used to toggle the visibility of an HTML element. It works by toggling the CSS display property of the element based on the truthiness of the provided JavaScript expression.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b4521739-3984-404d-903a-f923c6cde407', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'Explain the significance of the __slots__ attribute in a Python class.', N'Middle', N'By default, Python objects use a dictionary to store instance attributes, which consumes significant memory. Using __slots__ restricts the creation of instance attributes to a predefined set, preventing the creation of the instance dictionary and significantly reducing the memory footprint of objects.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6989ad8a-5f48-45f0-9aee-f924d3cb7e2b', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'Does Tailwind CSS support dark mode?', N'Intern', N'Yes, Tailwind has built-in support for dark mode. You can use the ''dark:'' modifier to apply different styles when the user''s system preference is set to dark mode or when a dark class is applied to a parent element.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dd7de712-895b-4f81-ad3e-f92694293d3f', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'How do you loop through or enumerate javascript object?', N'Fresher', N'You can use the for-in loop to loop through javascript object. You can also make sure that the key you get is an actual property of an object, and doesn''t come from the prototype using Object.hasOwn() (ES2022) or the older hasOwnProperty() method.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'28739050-4e1e-43fb-a9ef-f92818c15dc0', N'fcd5873e-c89a-47d6-bb4c-c60b57c2ede1', N'How does ''Hexagonal Architecture'' (Ports and Adapters) simplify testing?', N'Senior', N'By decoupling the core business logic from infrastructure concerns like databases and external APIs, you can test the domain logic in isolation using mock adapters. This makes the architecture technology-agnostic and allows for faster, more reliable unit testing of business workflows.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1152709c-185d-483f-8451-f92ab2e1387a', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'Why is it often recommended to cache jQuery selectors?', N'Junior', N'Querying the DOM can be an expensive operation for the browser. By storing a selector in a variable, you avoid re-scanning the entire document every time you need to interact with that element, which significantly improves performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9714cc98-3a66-472e-8cae-f92dd60f71c8', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'What is the purpose of using version control for your project?', N'Fresher', N'Version control tracks every change made to the project, allowing you to revert to previous versions if a bug is introduced. It also enables multiple people to work on the same project simultaneously without overwriting each other''s changes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ffe508da-e66c-4fcf-8a06-f92fdf7d9539', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'What is the difference between Symfony''s ''Stateful'' and ''Stateless'' authentication mechanisms?', N'Senior', N'Stateful authentication typically relies on session cookies to maintain user identity across requests, which is standard for web applications. Stateless authentication, such as JWT, does not persist state on the server, making it superior for REST APIs where the client sends credentials or tokens with every request.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd0f0be33-1366-4de1-9af4-f93402c7d3aa', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'Explain the purpose of Flask Blueprints and when they should be used.', N'Middle', N'Blueprints are a way to organize an application into distinct components or modules. They are used to group related routes, templates, and static files, which makes the codebase modular, easier to maintain, and allows different developers to work on separate parts of the system independently.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
