INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ffea2091-a2ab-4d48-862b-f937b8e001f4', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'What is the purpose of the ''use client'' directive?', N'Fresher', N'The ''use client'' directive is a string at the top of a file that tells Next.js to treat the component as a Client Component. This is necessary when you need to use interactive features like React state, effects, or event listeners.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5732ba19-3892-48dd-a825-f937ed16e434', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'Discuss the performance characteristics of Hono''s middleware chain compared to the traditional ''next()'' function approach.', N'Senior', N'Hono''s middleware follows a promise-based chain that is optimized for speed by avoiding unnecessary object creation and deep call stacks. By leveraging modern JavaScript asynchronous patterns, it ensures that middleware execution is non-blocking and highly efficient, which is essential for maintaining strict latency budgets in serverless environments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a912bc98-7f9a-4915-a753-f9381328ab41', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'What are the architectural risks of using too many actors in an Actix system?', N'Senior', N'Excessive actors increase context switching overhead and memory footprint due to the allocation of individual mailboxes and stacks for each actor. In high-scale systems, this can lead to diminished returns where the overhead of managing the actor system outweighs the benefits of isolation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'deedecc5-e687-4eb0-a92e-f93cc0e90eb3', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'How does Remix''s data loading architecture differ from traditional SPA patterns, and what are the implications for application state management?', N'Senior', N'Remix replaces client-side state management libraries with a model that treats the browser URL as the primary source of truth, utilizing server-side loaders to fetch data concurrently before navigation occurs. This architecture significantly reduces the need for complex global state stores like Redux by ensuring data is always fresh and synchronized with the server. Consequently, the reliance on client-side caching and revalidation logic is minimized, shifting the burden of state consistency from the client to the server-side route definitions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0f745144-012f-476a-94e9-f93d0bb3b8b2', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'What are Sass variables and what problem do they solve?', N'Intern', N'Sass variables allow you to store information, such as colors, font stacks, or any CSS value, and reuse it throughout your entire stylesheet. They solve the problem of repetition by allowing you to change a value in one central place instead of manually updating every occurrence in your code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'26fbff8c-39df-48d9-a742-f93e7138ea1c', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'Explain the concept of ''Lazy Loading'' in the context of services.', N'Middle', N'Lazy loading allows a service to be instantiated only when it is actually needed, rather than at the beginning of every request. This improves performance by reducing the total number of objects created if a specific request does not require the functionality of that service.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0b5b8d4a-17e5-4b73-a4a3-f93f4448c19b', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'What is the difference between a Function-Based View and a Class-Based View?', N'Junior', N'Function-Based Views are simple, easy-to-read Python functions that handle a request and return a response. Class-Based Views provide a structured, object-oriented approach that allows for code reuse through inheritance and mixins, making them better for handling complex logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd80ec0c3-960e-4b03-abab-f9400cf872b2', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'Why is it often preferred to use ''Doctrine Embeddables'' over simple One-to-One relationships in certain domain models?', N'Senior', N'Embeddables map an object''s properties directly into the parent entity''s table, avoiding unnecessary join operations required by One-to-One relationships. This approach improves query performance and simplifies the database schema for Value Objects, though it limits the ability to query the embedded data independently.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5de534e8-a9f6-458b-8745-f940bfb9112c', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'What is the purpose of the ''late'' keyword?', N'Intern', N'The late keyword is used to declare variables that will be initialized at a later time rather than at the moment of declaration. This is useful for variables that cannot be initialized in the constructor but are guaranteed to be set before use.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6647ec55-b12d-448c-9ae1-f940c3438b67', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'What is the purpose of the ''export'' keyword in Svelte?', N'Fresher', N'In Svelte, the export keyword is used to declare variables as props. When a variable is exported in a component, it becomes accessible from the outside, allowing parent components to pass data into it.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f264b980-d525-40a3-8f16-f9436ce19ca5', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is a higher order function', N'Intern', N'A higher-order function is a function that either accepts another function as an argument, returns a function as its result, or both. This concept is a core part of JavaScript''s functional programming capabilities and is widely used for creating modular, reusable, and expressive code. The syntactic structure of higher order function will be explained with an example as follows, In this example: 1. firstOrderFunc is a regular (first-order) function. 2. higherOrder is a higher-order function because it takes another function as an argument. 3. firstOrderFunc is also called a callback function because it is passed to and executed by another function.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dc676e01-9739-40bd-bea8-f947de844366', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'What is Dependency Injection in ASP.NET Core and why is it used?', N'Fresher', N'Dependency Injection is a built-in design pattern that allows for the loose coupling of classes and their dependencies. It promotes maintainability and testability by injecting required services into constructors rather than having classes create their own dependencies manually.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6c254c57-2eac-46b1-993e-f948f670d4c6', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'What is Django middleware and when should you use it?', N'Junior', N'Middleware is a series of hooks that process requests and responses globally before they reach the view or after they leave it. It is used for tasks that affect every request, such as authentication, session management, or security checks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b95b4aee-4625-4be0-a61b-f94c20949888', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'How do you prevent ''noisy neighbor'' issues in a shared multi-tenant environment?', N'Senior', N'I would implement strict resource quotas and limits at the container orchestration level, supplemented by per-tenant request rate limiting at the API gateway. This ensures that no single tenant can consume disproportionate CPU, memory, or network bandwidth at the expense of others.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'398b7c91-8242-4ab8-bff8-f94e7a591a5b', N'18ebabb7-555b-4ba1-beb6-844b8ee55dbd', N'How do you handle large objects that exceed cache entry size limits?', N'Middle', N'For large objects, one can either split the data into smaller chunks, use a blob storage service and cache only the metadata/pointers, or choose not to cache the object at all. Forcing large objects into memory caches can lead to rapid memory exhaustion and aggressive eviction of other important keys.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'462d0b6e-d06d-4bd6-a278-f94f78042fe5', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'Discuss the performance implications of Server Actions in a large-scale Next.js application.', N'Senior', N'Server Actions simplify form handling and mutations by executing code directly on the server, eliminating the need for custom API routes. While they improve developer experience, they require careful handling of state synchronization to ensure the client-side UI remains consistent with the server''s state after a mutation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'aaa02248-7160-4a35-8e75-f9516c82f37c', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'What is the Vite dev server?', N'Intern', N'The dev server is a local web server provided by Vite that runs during development. It compiles and serves code on the fly, monitors file changes for HMR, and resolves module imports dynamically.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'af3653d6-105a-40ff-9281-f951d6ef8ab1', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'How do you handle a scenario where a stakeholder asks for a feature that conflicts with the system''s architecture?', N'Intern', N'I would explain the trade-offs of implementing the feature, specifically highlighting the impact on stability or performance. I would then propose alternative ways to achieve the stakeholder''s goal without compromising the integrity of the core system.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
