INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'68a655b3-1e18-4e97-90c2-f95996b5ae49', N'd5b12859-0c9f-4e2f-9b3a-1ccb6c5080e5', N'How do you decide between vertical and horizontal scaling for a relational database?', N'Senior', N'Vertical scaling is preferred when the bottleneck is CPU or RAM and the workload is read-heavy or requires strict consistency without complex partitioning. Horizontal scaling, or sharding, is necessary when the dataset size exceeds the capacity of a single node''s storage or when the write throughput requires parallel processing across multiple independent instances.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f332401e-cc07-4d6e-9bb5-f95b9d651943', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'What is the function of the ''layout.js'' file?', N'Fresher', N'A layout.js file is used to define a UI structure that is shared across multiple pages. It allows you to maintain persistent UI elements like navigation bars or footers while the main page content changes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
