INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ba175b37-7c07-42df-967a-f95ca4644a0f', N'a2838158-7305-480a-b22b-4dc35776b400', N'Explain the role of a message queue in a microservices architecture.', N'Middle', N'Message queues enable asynchronous communication between services by decoupling the sender and receiver. This improves system resilience, as the producer does not need to wait for the consumer to process the message, and it helps manage traffic spikes through buffering.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ff4de2a5-e7d6-4196-bdf9-f962350fa010', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'What is the role of the ''next'' function in the Express middleware lifecycle, and what happens if it is not called?', N'Senior', N'The next function passes control to the subsequent middleware or route handler in the stack. If it is omitted without terminating the request with a response, the request hangs indefinitely, eventually causing the socket to time out and wasting server resources.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e2cf7aa5-10e5-4d47-89c2-f96465e87e16', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'Describe the function of the translation unit in the C compilation process.', N'Middle', N'A translation unit is the result of the preprocessor running on a single source file, including all included header files. It is the fundamental unit that the compiler processes to generate an object file, which is later combined by the linker to form an executable.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5aa4d576-efaf-4ff4-b50e-f964c37cedab', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'What is the primary benefit of using nesting in Sass?', N'Fresher', N'Nesting allows you to write CSS selectors in a way that follows the visual hierarchy of your HTML. This makes the stylesheet easier to read, understand, and maintain by grouping related styles together under parent elements.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'afcc50c7-b148-4044-994a-f96545361e1e', N'f2e963ff-7635-4429-a389-4d92535fb972', N'What is the difference between ordered and unordered lists?', N'Intern', N'An ordered list uses numbers or letters to show a specific sequence, while an unordered list uses bullet points to group items without implying a specific order. Both are used to organize related information clearly on a page.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2a27cbef-d619-4883-8d97-f9661ba71f05', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'Compare the performance implications of using arrow functions versus traditional functions.', N'Middle', N'Arrow functions are generally more concise but do not have their own ''this'' context, which can simplify scoping but complicates testing if the function depends on dynamic binding. Traditional functions are often better for object methods where dynamic ''this'' binding is required, and they may be slightly more performant in specific hot-path scenarios due to how engines optimize function objects.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ffbf7cde-75b5-4b6e-9f61-f968eff0d569', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'What is the purpose of the ''lock'' statement in C#?', N'Middle', N'The lock statement ensures that only one thread can enter a critical section of code at a time by acquiring a mutual exclusion lock on a specific object. It prevents race conditions when accessing shared resources, though it should be used carefully to avoid deadlocks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5b28a9c0-f5af-498b-8ac3-f96d5d3b7fd4', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'What are the trade-offs of using ''ValueTask'' instead of ''Task''?', N'Middle', N'ValueTask is a struct that can reduce heap allocations when a method completes synchronously. However, it should only be used in performance-critical paths because it has more restrictions than Task, such as not being allowed to be awaited multiple times.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e16c5bde-0095-48ce-9707-f96f18c735cc', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'What should you do if you encounter a bug that appears intermittently and is difficult to pin down?', N'Intern', N'Focus on gathering data over time, such as timestamps, user actions, and system states during each occurrence. Look for patterns in these occurrences to see if the issue correlates with specific times, user load, or resource spikes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5b5361fa-5fe7-474d-bb8e-f971127ecc31', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'Explain the trade-offs between static and dynamic polymorphism in C++.', N'Senior', N'Static polymorphism via templates provides compile-time type safety and allows for aggressive compiler optimizations like inlining, but increases binary size and compilation times. Dynamic polymorphism using virtual functions enables runtime flexibility and interface-based design at the cost of a vtable lookup overhead and the potential for cache misses due to indirect function calls.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'902606bf-3eb0-41a7-b287-f97412631236', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What is the purpose of the ''void'' type in TypeScript?', N'Intern', N'The ''void'' type is typically used as the return type for functions that do not return any value. It signifies that the function performs an action but does not produce an output that needs to be captured or used.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b31c55fd-d6dd-4b52-8a50-f97506f864bf', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'What is the significance of the root layout in the App Router?', N'Junior', N'The root layout is a required file that defines the top-level structure of your application, including the HTML and body tags. It wraps all pages and remains active for the entire duration of the application lifecycle.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'787439fb-4f0f-479b-8d4a-f975541b0793', N'4c000000-0000-0000-0000-000000000005', N'What are the trade-offs between using Saga patterns versus Two-Phase Commit (2PC) in distributed transactions?', N'Senior', N'2PC provides strong consistency but suffers from blocking issues and reduced availability in distributed environments. The Saga pattern favors availability and scalability by using compensating transactions to reach eventual consistency, though it increases complexity in handling partial failures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'45f306dc-6441-48a0-9869-f9778b13f03d', N'8d34dfc0-4a64-4128-b41a-cafa62ddad41', N'What is the role of a Hardware Security Module (HSM) in enterprise key management?', N'Senior', N'An HSM provides a tamper-resistant environment for the generation, storage, and management of cryptographic keys. It ensures that sensitive keys never leave the hardware boundary in plaintext, protecting against physical theft and unauthorized software-level extraction.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1e427cbf-aba1-4de8-b967-f97ae0e40987', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'What is a constructor in C#?', N'Intern', N'A constructor is a special method inside a class that is automatically called when an instance of that class is created. Its primary purpose is to initialize the object''s data members and ensure the object starts in a valid, ready-to-use state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9fc64a16-c109-4c9c-94ee-f97b886d22df', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'What is Lit and what is its primary purpose?', N'Intern', N'Lit is a lightweight library for building fast, efficient, and reusable web components. Its primary purpose is to simplify the process of creating custom HTML elements that work natively in any browser and with any modern framework.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ef46bbe8-b3e0-4c4d-8128-f981fd903e6f', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'What is the purpose of the ''Connect'' pattern versus the ''useSelector/useDispatch'' hooks in modern Redux, and are there performance differences?', N'Senior', N'The connect pattern is a Higher-Order Component approach that passes state via props, while hooks allow functional components to subscribe directly to the store. Hooks are generally preferred for better ergonomics and TypeScript support, though both share the same underlying subscription mechanism for updates.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'57c52280-92b2-486a-b852-f98284e226d7', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'What is your strategy for handling database migrations in a high-availability environment?', N'Senior', N'I advocate for a multi-step, additive migration approach where the database schema is updated to support both old and new code simultaneously. By decoupling the deployment of schema changes from the deployment of application code, I ensure that the system can always roll back to a previous state without data corruption.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9ca398ee-87c7-4fb8-9c4a-f983407b833d', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'Discuss the strategy for handling database transactions within Litestar''s dependency injection system.', N'Senior', N'Transactions are best managed via dependencies that yield a session or connection, ensuring that the lifecycle of the transaction is tied to the request scope. By injecting the session, you can use a ''try-except-finally'' pattern to commit or rollback based on the outcome of the handler, keeping transaction management clean and reusable.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a14fbf7c-d59a-410c-b5f4-f987c484ba27', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'What is the Symfony Form component?', N'Intern', N'The Form component handles the creation, rendering, and validation of HTML forms. It maps input data from an HTTP request directly to objects, simplifying the process of updating application state from user input.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8ab4f0fd-2a2c-456a-a44d-f98cff715e02', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'Explain how Express handles asynchronous operations and error catching within route handlers.', N'Middle', N'In modern Express, you must wrap asynchronous route handlers in a try-catch block or use an async utility wrapper to pass errors to the next function. Without explicit error propagation, an unhandled promise rejection in a route handler will not be caught by Express''s internal error-handling mechanism.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9576b50e-5fa4-4ae9-95ca-f98ef66acb70', N'4c000000-0000-0000-0000-000000000005', N'What are the trade-offs of using a leader-follower replication model?', N'Senior', N'This model simplifies read scaling and provides a clear path for data durability, but it introduces potential staleness for reads and a recovery window during leader election. It is generally unsuitable for write-heavy workloads unless combined with sharding or multi-leader strategies.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
