INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'74cc2152-bcba-4d43-8db0-f990ef9391c1', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'What is the purpose of a primary key in a relational database?', N'Intern', N'A primary key is a column or set of columns that uniquely identifies each record in a table. It ensures that no two rows have the same value in that column, which helps maintain data integrity and allows for efficient searching and referencing of specific records.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
