INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8e69bfe9-d4ba-408c-82f4-f993f4b9f4de', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'What is the benefit of using Redux?', N'Fresher', N'Redux provides a predictable way to manage state, which makes it easier to understand how data flows through an application. It also facilitates easier debugging, testing, and the ability to implement features like undo/redo.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a578acf4-7154-432b-86d7-f998a021b47b', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'What is the best way to handle a situation where you accidentally break something in a shared environment?', N'Junior', N'I immediately report the incident to the team to prevent further impact and initiate the rollback or fix procedure. After the issue is resolved, I perform a post-mortem to understand why it happened and what steps I can take to prevent a recurrence. Transparency and quick action are more important than hiding the mistake.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ea5d81f3-30bc-4e81-88b7-f99996906201', N'954a0331-deff-4399-b588-96f39fec001d', N'Discuss the performance implications of using Zone.js and the benefits of transitioning to Zoneless Angular.', N'Senior', N'Zone.js patches browser asynchronous APIs to notify Angular when to run change detection, which creates a global performance overhead and makes debugging stack traces difficult. A Zoneless architecture relies on explicit signals or RxJS streams to trigger change detection, resulting in smaller bundles, better predictability, and improved performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
