INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'44a6208a-4b4c-4a02-a0a3-f99d260a9066', N'18ebabb7-555b-4ba1-beb6-844b8ee55dbd', N'What is the purpose of a ''Write-Around'' caching strategy?', N'Middle', N'Write-Around writes data directly to the database while bypassing the cache, which is useful for data that is written once and rarely read again. This prevents the cache from being polluted with data that is unlikely to be requested in the near future.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c335a3fe-b724-4741-9b31-f9a6ce4aab9a', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'Explain the concept of Routing in Laravel.', N'Fresher', N'Routing is the process of mapping a URL to a specific controller action or a closure. In Laravel, routes are defined in route files, which act as the entry point for all incoming HTTP requests to the application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1495ff65-cb19-4bd5-8825-f9a841993c89', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'Are Svelte applications generally smaller in size than those built with other frameworks?', N'Intern', N'Yes, because Svelte does not ship a large framework runtime to the browser. Only the code necessary for your specific application is included in the final bundle, leading to smaller download sizes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2a9676ef-d45d-4528-97fd-f9a9394e660b', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'Why does Phoenix use ''Postgrex'' specifically, and what benefits does it offer over generic DB drivers?', N'Senior', N'Postgrex is designed specifically for PostgreSQL and takes full advantage of advanced features like LISTEN/NOTIFY and custom types. This allows Phoenix to implement efficient real-time notifications directly from the database and handle complex data structures with high performance and type safety.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'97b9b21e-8055-40df-b836-f9a94c848535', N'954a0331-deff-4399-b588-96f39fec001d', N'What is Angular Framework?', N'Intern', N'Angular is a TypeScript-based open-source front-end platform that makes it easy to build web, mobile and desktop applications. The major features of this framework include declarative templates, dependency injection, end to end tooling which ease application development.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ea6f25c2-d77e-4343-b361-f9a94d24d401', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'How do you approach learning a new technology or tool you have never used before?', N'Intern', N'I start by reading the official documentation to understand the core concepts and intended use cases. Then, I look for a small, practical tutorial to build a simple project that applies these concepts. Finally, I experiment with the tool''s features to understand its limitations and best practices.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c13c1369-a48a-4791-9515-f9ab17afdc17', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'What is use of capped collection in MongoDB?', N'Intern', N'Capped collections are fixed-size collections that support high-throughput operations that insert and retrieve documents based on insertion order. Capped collections work in a way similar to circular buffers: once a collection fills its allocated space, it makes room for new documents by overwriting the oldest documents in the collection. Capped collections restrict updates to the documents if the update results in increased document size. Since capped collections store documents in the order of the disk storage, it ensures that the document size does not increase the size allocated on the disk. Capped collections are best for storing log information, cache data, or any other high volume data. Example:', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'09a8234e-abac-40f5-8fe5-f9ab66571f81', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'How does R''s functional approach to error handling (tryCatch) differ from traditional exception handling?', N'Senior', N'R''s ''tryCatch'' is designed to handle errors within the context of its functional call stack, allowing for the recovery of intermediate states or the return of default values. It is tightly integrated with the condition system, which distinguishes between errors, warnings, and messages, enabling fine-grained control over how control flow is diverted during failures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'044518b1-acb3-481a-8028-f9ae2e9b0438', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'What is a template in C++?', N'Intern', N'A template is a feature that allows functions and classes to operate with generic types. By using templates, a developer can write a single piece of code that works for any data type, such as integers or strings. This promotes code reuse and type safety without the need to write separate versions for each data type.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3a3edc38-48e1-4f49-9bde-f9aec7e1cca0', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'Why might a DBA choose an ''Index-Organized Table'' (IOT)?', N'Senior', N'An IOT stores the data rows directly within the B-Tree index structure, eliminating the need for separate lookups to retrieve the full record after finding the index key. This is highly efficient for primary key lookups but can be inefficient for tables with frequent updates or large rows.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'02fbcf7b-d0e9-4b3d-950b-f9b0d9fdcf6e', N'd5b12859-0c9f-4e2f-9b3a-1ccb6c5080e5', N'How do indexes affect write performance in high-throughput databases?', N'Senior', N'Every index on a table requires an additional write operation whenever data is inserted, updated, or deleted, leading to increased latency and I/O pressure. In high-throughput systems, it is often necessary to balance the benefit of fast read queries against the overhead of maintaining multiple indexes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dc27bf9a-7228-497c-aea6-f9b44f5649cc', N'210c7148-726e-4e8b-bf12-40be36e55130', N'What is the difference between a panic and a result-based error?', N'Junior', N'A panic is used for unrecoverable errors that should stop the program execution immediately. Result-based errors are for recoverable situations where the program can handle the problem and continue running.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'713e64d1-aaa9-4c65-a6d8-f9b49f8305e1', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'How does Actix-web handle backpressure compared to traditional thread-per-request models?', N'Senior', N'Actix-web utilizes non-blocking I/O and asynchronous streams to handle backpressure effectively. By using futures and polling, it ensures that the system does not accept more work than it can process, preventing memory exhaustion under high load.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
