INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6cd29ea4-0f94-4296-b2c0-f9bbadd844f3', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'What is the difference between local and global scope?', N'Intern', N'Local scope refers to variables defined within a function or block, which are only accessible inside that block. Global scope refers to variables defined outside of all functions, making them accessible from anywhere in the program.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'53c57289-0c04-44d7-b0b8-f9bc01ea8cb3', N'24c74bdc-c63e-4370-b1ac-bd560cb834d6', N'What is the benefit of filtering and sorting parameters in API endpoints?', N'Middle', N'Filtering and sorting allow the client to retrieve a subset of data rather than the entire collection. This reduces data transfer volume, improves client-side processing speed, and offloads heavy computation to the database where it can be indexed and optimized.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ccc6d3dc-87c8-4ca0-9965-f9bd14b87564', N'075b8862-431c-4678-9767-f55359758a4a', N'How does Vue''s ''keep-alive'' component manage memory, and what are the risks of over-utilizing it?', N'Senior', N'Keep-alive caches component instances in memory to preserve state during navigation. Over-utilization can lead to significant memory bloat, as cached instances remain active in the heap, potentially causing performance degradation or data staleness if not managed with proper lifecycle hooks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fee90b2c-e61a-43f5-9b68-f9c0a1367e51', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'How do you account for ''context switching'' when estimating your daily capacity?', N'Junior', N'I assume that I will not be productive for 100% of my eight-hour day, accounting for meetings, emails, and code reviews. I typically plan for about six hours of focused work, leaving the remaining time as a buffer for the inevitable overhead of daily team operations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'731abd37-dfda-4f6a-ba41-f9c0c4dfc791', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'What is the function of a Safepoint and how does it impact JVM performance during GC cycles?', N'Senior', N'A safepoint is a specific point in execution where the JVM state is consistent, allowing the GC to safely scan thread stacks and manipulate objects. Frequent safepoints ensure timely GC pauses, but excessive safepoint checks can introduce minor overhead, requiring a careful balance to ensure the JVM remains responsive without sacrificing execution speed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
