INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5a269b93-8549-4455-92fc-f9c9ade4d5ce', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'What is the trade-off between memory usage and processing speed in software design?', N'Intern', N'Often, an application can run faster by caching data in memory, but this consumes more RAM, which could limit the number of concurrent users. Conversely, reducing memory usage often requires re-calculating data or fetching it from disk, which decreases overall processing speed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
