INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'96403bd5-afde-4efc-b214-f9ce1f8671fc', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'What is the ''normalized state'' pattern and why is it preferred for large datasets?', N'Senior', N'Normalization involves storing data in a flat structure where entities are keyed by their unique IDs, similar to a database table. This eliminates data duplication, prevents inconsistent state updates across different parts of the tree, and allows for O(1) lookups instead of traversing nested arrays.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
