INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e88202e1-e604-4b0d-a52a-f9d218261a5f', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'What is the main advantage of using CSS logical properties over physical properties?', N'Middle', N'Logical properties, such as ''inline-start'' or ''block-size'', adapt based on the writing mode and direction of the document, such as left-to-right versus right-to-left. Physical properties like ''left'' or ''width'' are static and do not change regardless of the document''s orientation. Using logical properties makes the interface inherently internationalization-friendly and easier to adapt for global users.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'557f9763-6a2d-42cf-ad3b-f9d2fb30bdbc', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'How does Ember ensure data consistency between the store and the server?', N'Middle', N'Ember Data acts as a client-side database, tracking changes to records and managing the persistence lifecycle. It uses identity mapping to ensure that if a record is requested multiple times, the application always refers to the same object instance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3fe4f64f-58f5-4c76-9246-f9d334331e4b', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'Explain the trade-offs of using Symfony''s ''Service Decoration'' versus ''Compiler Passes''.', N'Senior', N'Service decoration is ideal for wrapping existing services to add behavior while maintaining the original interface, whereas compiler passes provide deep, global access to the container. Compiler passes are more powerful for bulk modifications or dynamic service registration based on tags, but they significantly increase the complexity of the container build process.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'50d1e0e3-6682-4416-a803-f9d548d4831b', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'How does the Phoenix Presence module differ from simple PubSub?', N'Middle', N'Phoenix Presence tracks real-time user state across a distributed cluster, providing a way to list and synchronize information about users or devices. While PubSub is designed for broadcasting messages, Presence maintains a replicated state that is eventually consistent across all nodes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2774edfe-2b2c-4d36-82e2-f9d654962bcd', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'What is the purpose of the ''meta'' function in Remix route modules?', N'Middle', N'The meta function allows developers to define dynamic SEO tags, such as page titles and descriptions, on a per-route basis. These tags are injected into the head of the document during the server-side rendering process, ensuring proper meta-data for search engines and social media sharing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'96b71281-a971-4a67-b417-f9d79274f91b', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'If users report that a website is loading very slowly, what factors would you consider?', N'Fresher', N'I would look at the size of the assets being loaded, such as large images or unoptimized scripts. I would also consider the server response time and whether there are too many external dependencies or blocked network requests occurring.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8b3b4419-2c8c-47d1-bb4f-f9d9c339c5bf', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'How does Preact compare to React in terms of bundle size?', N'Intern', N'Preact is significantly smaller than React, often weighing in at around 3kb compared to React''s much larger library size. This makes it an excellent choice for performance-sensitive applications or mobile-first environments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e117ff5e-244f-4649-acb9-f9de11d4e352', N'f2e963ff-7635-4429-a389-4d92535fb972', N'What is the significance of the ''fetchpriority'' attribute in modern HTML?', N'Senior', N'Fetchpriority allows developers to explicitly signal the relative importance of resources to the browser, helping to override the browser''s default prioritization heuristics. This is particularly useful for optimizing the Largest Contentful Paint by ensuring that hero images or critical fonts are fetched before lower-priority assets like tracking scripts.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'edbf1c28-6684-4d99-a76c-f9e08301c358', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'How does Next.js handle caching at the framework level, and what is the difference between the Data Cache and the Full Route Cache?', N'Senior', N'The Data Cache stores the results of data fetches across requests, while the Full Route Cache stores the rendered HTML and RSC payload of a route at build time. Understanding these layers is critical for managing cache invalidation strategies and ensuring users see up-to-date information.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'225d832d-d2fc-4866-959f-f9e23f920f55', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'What is the primary benefit of using macros in Rocket?', N'Intern', N'Macros reduce boilerplate code by allowing developers to define complex routing and metadata with simple attributes. This makes the code cleaner, more readable, and easier to maintain.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'aeeb9fa6-e460-46ca-aaac-f9e4c0518415', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'How do you handle distributed transactions in a system that cannot rely on traditional two-phase commit?', N'Senior', N'I adopt the Saga pattern, breaking transactions into a sequence of local transactions with compensating actions for failures. This approach maintains data integrity across services without the performance degradation and blocking nature of distributed locking.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'35ac6787-ddc2-4fac-911f-f9e5b1c861b8', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'What is the ''page'' store in SvelteKit?', N'Junior', N'The page store is a built-in Svelte store that provides reactive access to information about the current page. It includes data such as the current URL, route parameters, and status codes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a4265762-880b-41ff-b4ae-f9e6b28cfdc3', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'What is the function of the refresh interval?', N'Fresher', N'The refresh interval determines how often Elasticsearch makes changes to an index visible to search. By default, it happens every second, which makes data searchable shortly after it is indexed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a8cfb620-2672-432a-8957-f9e72ce77a80', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'What does it mean that Remix is a full-stack framework?', N'Intern', N'Being full-stack means Remix manages both the server logic and the browser interface. It allows developers to write code that talks directly to databases or APIs on the server while simultaneously updating the user interface.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5352fb3c-9762-4a50-b2d1-f9e91af77ac4', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'How does Python implement closures?', N'Middle', N'A closure is a function object that remembers values in enclosing scopes even if they are not present in memory. Python implements this by creating a function that carries its local variable scope with it, allowing data to be encapsulated within a function without relying on global variables.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'baac1d56-8fd8-4859-83b9-f9eb11dcf093', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'How can you share functionality across different parts of a Fastify app?', N'Junior', N'You can use the ''decorate'' method to add methods or properties to the Fastify instance, request, or reply objects. Once decorated, these features become accessible throughout your application or within specific plugin scopes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5b07bf19-678a-431f-a4f9-f9ee6733c607', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'Explain the concept of ''hoisting'' and how it differs between var, let, and const.', N'Middle', N'Hoisting is the mechanism where variable and function declarations are moved to the top of their scope during compilation. While ''var'' declarations are initialized with ''undefined'', ''let'' and ''const'' declarations remain uninitialized in the temporal dead zone, preventing access until the code execution reaches the declaration.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ec5256a7-e60a-473c-9eae-f9f03b6b8bc1', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'How do you approach testing a new feature you have developed?', N'Junior', N'I follow a multi-layered approach starting with unit tests for individual functions, followed by integration tests to ensure different parts of the system interact correctly. I also perform manual exploratory testing to simulate how a real user would interact with the feature and catch edge cases.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7f86592c-c705-40b8-958f-f9f58832b3c7', N'a2838158-7305-480a-b22b-4dc35776b400', N'What are the benefits and drawbacks of using a service mesh?', N'Middle', N'A service mesh provides out-of-the-box observability, security, and traffic management by offloading these concerns to a sidecar proxy. However, it introduces significant operational overhead and potential performance latency due to the additional network hops required for each request.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'517e4a18-9e97-454b-ace5-f9f5cf96d581', N'18ebabb7-555b-4ba1-beb6-844b8ee55dbd', N'Explain how ''Cache Invalidation'' via Pub/Sub differs from ''Time-To-Live'' (TTL) based invalidation.', N'Senior', N'TTL provides eventual consistency by automatically expiring data after a duration, which is simple but can serve stale data. Pub/Sub invalidation allows the system to proactively purge specific keys when the underlying data changes, ensuring much stronger consistency at the cost of increased architectural complexity.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6e62fcd2-e7b9-49db-bfd6-f9fafd99da5e', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What are the trade-offs of using server-side rendering versus client-side rendering?', N'Middle', N'Server-side rendering improves initial page load speed and SEO by sending fully formed HTML to the client. Client-side rendering offers a smoother, app-like experience after the initial load but requires the browser to download and execute JavaScript before the content becomes interactive.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0eb7cb47-841e-48f0-ae38-f9fc991191a8', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'What are the trade-offs in choosing a serialization format like JSON versus Protobuf?', N'Middle', N'JSON is human-readable and universally supported, making it excellent for public APIs and debugging, but it is verbose and slower to parse. Protobuf is binary, highly efficient in terms of size and speed, and enforces strict schemas, but it requires more effort to implement and is harder to debug without specialized tools.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c3818559-c8c2-42e0-971f-fa01cbb6fe2a', N'f2e963ff-7635-4429-a389-4d92535fb972', N'Why should you use the button element instead of a div for click events?', N'Junior', N'Using a button element provides built-in accessibility features like keyboard focus, enter-key activation, and proper screen reader announcements. A div does not have these behaviors by default, making it inaccessible to users who rely on keyboards or assistive technology.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cec1ab3d-9aa9-4986-ae61-fa0242b4c1df', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'What is the jQuery .hide() method used for?', N'Intern', N'The .hide() method is used to remove an element from view by setting its CSS display property to none. It is a simple way to toggle the visibility of an element without removing it from the document.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'98f901fa-e395-4fd4-b887-fa048e04df63', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'What are the trade-offs of using Preact''s signal-based state management?', N'Senior', N'Signals allow for fine-grained reactivity, where components only re-render when the specific value they consume changes, bypassing the need for manual memoization. The trade-off is the introduction of a more complex reactivity graph that can be harder to debug if circular dependencies or stale closures occur.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'eb1e5e04-e505-49cb-bf5b-fa06f835157f', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'What is a Component in Ember.js?', N'Fresher', N'A component is a reusable UI element that encapsulates both its own template and its specific behavior. It allows developers to break down complex interfaces into smaller, manageable, and modular pieces.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2347c823-8806-4b8f-85c8-fa0ec4a5ac27', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'Why is SolidJS considered ''compiler-heavy''?', N'Middle', N'SolidJS relies on a specialized Babel or SWC plugin to transform JSX into optimized DOM creation code. This compilation step is what enables the framework to perform fine-grained updates without the overhead of a runtime reconciliation engine.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'acac4050-7fea-49cc-a085-fa0ef0b4f40f', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'How does x-show work in Alpine.js?', N'Intern', N'The x-show directive toggles the visibility of an element based on the truthiness of a given expression. It functions by adding or removing the display: none style property to the element.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f9815f85-20eb-4dea-8a19-fa0f85b08cbe', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'How do CSS transitions differ from CSS animations?', N'Middle', N'CSS transitions allow for smooth changes between two states when a property changes, usually triggered by user interaction like hover or focus. CSS animations allow for more complex, multi-step sequences using keyframes that can run automatically without user interaction. Transitions are for simple state changes, whereas animations provide fine-grained control over temporal sequences.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'73e50ce7-0e4c-4278-b80b-fa10b39856fa', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'How does partitioning (partitioning by range vs. hash) affect query performance?', N'Senior', N'Range partitioning is efficient for queries covering contiguous data segments, but it often leads to hotspots where the latest data is concentrated. Hash partitioning spreads data evenly across nodes to prevent hotspots, which maximizes throughput but makes range-based queries expensive as they must be broadcast to all nodes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'df87484c-2120-4de6-b62a-fa127173bdeb', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'What is the purpose of ''Parallel Routes'' in the Next.js architecture?', N'Senior', N'Parallel Routes allow multiple independent segments of a page to be rendered simultaneously and managed by the same layout. This is particularly useful for complex UIs like split-panes or dashboards where different sections have independent loading states and error boundaries.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e4830374-45ac-41e3-b7eb-fa14c94ad4ac', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'How do you handle a situation where a dependency you rely on is failing?', N'Fresher', N'I verify if the issue is with the dependency itself or how I am interacting with it by reviewing the API documentation or logs. If the dependency is definitely down or broken, I communicate the delay to my team and look for a temporary workaround or alternative approach. Maintaining open communication ensures the team is aware of external blockers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fbec5b54-3799-4819-bd82-fa157630a19f', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'What is the purpose of the ''Option'' type in Scala and how does it compare to null?', N'Middle', N'Option is a container that represents the presence or absence of a value, effectively replacing null. It forces developers to handle the ''empty'' case explicitly, thereby preventing NullPointerExceptions and making the API contract clearer.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'09fad9cd-e99c-4964-87af-fa16c66b97cb', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'If a user reports a feature is broken, what information do you ask for to help troubleshoot?', N'Junior', N'I would ask for a clear description of the steps taken, any error messages seen, and the specific browser or device used. Getting a screenshot or screen recording is also very helpful to see exactly what the user is experiencing versus what the system is doing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'37f0fe53-db07-4828-a5ed-fa17d5c0cfc6', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'How does the ''MVCC'' (Multi-Version Concurrency Control) mechanism work in InnoDB?', N'Middle', N'MVCC allows multiple transactions to read data simultaneously without blocking, by maintaining different versions of rows. Each transaction sees a consistent snapshot of the data based on the transaction ID, ensuring high concurrency without sacrificing isolation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9c91da06-b428-48a0-ba71-fa19037c99eb', N'91fb4eff-ac6a-48b9-8ba4-2bbdf6237429', N'How does ''Rate Limiting'' protect a service?', N'Middle', N'Rate limiting restricts the number of requests a user or service can make within a specific time frame. It protects the system from being overwhelmed by abusive traffic, accidental loops, or distributed denial-of-service (DDoS) attacks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5c87073e-4652-417e-91d1-fa1b02ee7a2a', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'Can you describe the lifecycle of a PHP request?', N'Junior', N'Understanding the detailed lifecycle of a PHP request will help you optimize your web applications for better performance. Stages of a PHP Request 1. Bootstrap - Code in your index.php file initializes the PHP environment.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1fff82d8-ae2a-43e6-919f-fa217f0015f0', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'Discuss the scalability of Tailwind when implementing a design system versus a one-off project.', N'Senior', N'For design systems, Tailwind acts as a scalable constraint-based engine where the config serves as the single source of truth for tokens. For one-off projects, it provides rapid prototyping speed, though the lack of semantic class names can sometimes hinder long-term maintainability if not governed correctly.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e5b50e05-509c-4e55-a971-fa24a4855594', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'What does ''Atomicity'' mean in the context of ACID properties?', N'Intern', N'Atomicity ensures that a series of database operations are treated as a single ''unit'' of work. Either all operations within the transaction succeed, or none of them do, preventing partial updates that could corrupt data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a472464f-230f-412a-b954-fa2543161eec', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'What is the impact of transaction log growth on database performance?', N'Middle', N'If transaction logs are not truncated regularly through backups or checkpoints, they can consume excessive disk space. Furthermore, a massive log file increases the time required for the database to perform crash recovery, as the system must scan and process a larger volume of data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'03a683b0-f4b3-47f8-8069-fa25de56e97f', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'Explain the architectural difference between a static route and a parameterized route in Echo''s router.', N'Senior', N'Static routes are stored as direct pointers in the radix tree, leading to faster lookups, while parameterized routes require the router to perform pattern matching at each node. While the difference is micro-scale, static routes are technically more performant for high-traffic endpoints.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c1c777ad-49cc-4eba-ab16-fa2781d9aa89', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'What is the benefit of using an external library like Babel with Webpack?', N'Junior', N'Babel is used to transpile modern JavaScript into older versions that are compatible with a wider range of browsers. By using it with Webpack, you can write modern code while ensuring it works on legacy platforms.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd899461e-adb8-4f8d-ae58-fa29044f5b78', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'Why does Remix recommend against using global state management libraries like Redux?', N'Middle', N'Since Remix keeps state on the server and synchronizes it via loaders, most client-side global state becomes redundant. Managing state locally via loaders and actions significantly reduces complexity and prevents synchronization bugs between the client and server.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e012f887-de82-4479-9831-fa2c0aa7f523', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'Why does Remix prioritize web standards?', N'Junior', N'By relying on standard browser APIs like Request, Response, and URL, Remix ensures that your skills remain transferable. It also makes the application more resilient and compatible with different deployment environments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
