INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'95c9320f-f191-44a3-8c3f-fa2fd2ba1adc', N'8d34dfc0-4a64-4128-b41a-cafa62ddad41', N'How do you handle ''Data Sovereignty'' requirements at the architectural level?', N'Senior', N'Data sovereignty is managed by implementing geo-fencing at the database and application levels, ensuring that user data is physically stored and processed within specific jurisdictions. This involves deploying regionalized clusters and using orchestration logic to route user requests to the appropriate region based on their residency or legal requirements.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6ae085d5-f768-4ee5-8044-fa3477ef7055', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'How does Spring Support IoC?', N'Fresher', N'1. Bean Management: Spring manages Java objects, known as beans, by detailing their creation, configuration and deletion through Bean Factories. 2. Configurations: Spring employs both XML and annotations for defining bean configurations. 3. Dependency Resolution and Injection: Spring ensures that inter-bean dependencies are resolved and injected, thereby reducing tight coupling and enhancing testability and flexibility. 4. Lifecycle Management: Using Spring''s Bean Lifecycle, you can manage the instantiation, modification and disposal of beans in a systematic manner. 5. AOP and Declarative Services: Spring aids IoC by offering an Aspect Oriented Programming (AOP) system and allowing declarative services via Java annotations, enabling you to externalize cross-cutting concerns. 6.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'eebc4b25-2eed-4d19-b25f-fa35b8693e8a', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'How does Litestar handle HTTP methods?', N'Fresher', N'Litestar uses decorators to map specific HTTP methods like GET, POST, PUT, or DELETE to handler functions. This explicit mapping ensures that a route only responds to the intended type of request.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'249be78d-f0ee-43d7-a915-fa35f1c6a603', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'Why is it beneficial to move data fetching from the client to Server Components?', N'Senior', N'Moving data fetching to the server allows direct database or API access, avoiding the need for a secondary public API layer and preventing waterfall requests. It also reduces the amount of data transferred and eliminates the need for complex loading state management typically required in client-side orchestration.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4d6df186-4af6-49e0-8166-fa373bde340f', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'What is Vite?', N'Intern', N'Vite is a modern build tool and development server designed to provide a faster and leaner development experience for web projects. It leverages native browser ES modules to serve code without needing to bundle the entire application during development.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3f7a19fc-192c-4997-b39f-fa3787fe4876', N'075b8862-431c-4678-9767-f55359758a4a', N'What is the trade-off between using ''ref'' and ''reactive'' in the Composition API?', N'Senior', N'Ref is designed for primitives and objects, providing a consistent interface via the .value property, which prevents data loss when passing values across scopes. Reactive only works with objects and relies on proxy-based reactivity, which can be lost if a property is destructured, making ref generally safer for state management in complex applications.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'282e4ef9-03fd-4d8f-8361-fa3c2f19f9bd', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'How do you estimate the impact of a migration to a serverless architecture on total cost of ownership?', N'Senior', N'I analyze the cost per request versus fixed infrastructure costs, accounting for cold starts and execution duration. I evaluate the operational savings from reduced infrastructure management against the potential for vendor lock-in and the need for new observability tooling.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1bb3f7f7-2b0b-46f9-a83b-fa416ea11b3c', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'How do you debug an issue that cannot be reproduced in the local development environment?', N'Middle', N'I would compare the configurations, environment variables, and dependency versions between the local and production environments to spot discrepancies. If the environment is identical, I would leverage production-level observability tools to capture the state of the system during the failure. Often, the issue is caused by external factors like network latency, firewall rules, or data volume differences that are missing locally.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'387c5700-e2cb-475f-b04a-fa42da1d0b14', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'What is the ''invalidation'' mechanism in SvelteKit?', N'Middle', N'Invalidation tells SvelteKit that the data fetched by a load function is potentially stale and needs to be re-fetched. This is triggered automatically after form submissions or manually via the invalidate function to ensure the UI stays synchronized with the server state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'968dec2a-8c9e-43e3-8502-fa4b8a5037b9', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'How do you evaluate the trade-off between using an ORM versus raw SQL or a thin abstraction layer?', N'Senior', N'ORMs increase developer productivity and provide a consistent data access pattern but can mask underlying performance issues and generate inefficient queries. I choose ORMs for CRUD-heavy applications and raw SQL for performance-critical paths where precise control over execution plans is necessary.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6c658407-6a35-4cd6-a4a1-fa4c1d1dc5c0', N'24c74bdc-c63e-4370-b1ac-bd560cb834d6', N'How do you maintain API performance under heavy load?', N'Middle', N'Performance is maintained through strategies like caching frequent responses, implementing rate limiting, using efficient serialization formats, and distributing load across multiple service instances. Caching at the edge, such as with a CDN, is particularly effective for read-heavy APIs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7a7c8112-cbac-4966-9093-fa4dddc1e4f2', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What are Type Predicates and when should they be used?', N'Middle', N'Type predicates are functions that return a boolean value while informing the TypeScript compiler about the type of the variable within a specific scope. They are used to create custom type guards when the built-in guards are insufficient for verifying complex object structures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1a175bd0-0993-4c7f-940b-fa4f27df3e6e', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'Discuss the trade-offs of using a document-oriented database versus a relational database for hierarchical data.', N'Senior', N'Document databases store hierarchical data as nested structures, eliminating the need for complex joins and mapping logic, which is ideal for evolving schemas. Relational databases require normalization and joins to represent hierarchies, which can lead to performance degradation on deep structures but provide stronger schema enforcement and transactional integrity.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6bf7fe92-ba24-472d-9751-fa500c1a0ffa', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'How does Rocket handle testing?', N'Fresher', N'Rocket includes a ''local'' module that allows developers to simulate HTTP requests against the application without actually starting a network server. This makes writing unit and integration tests for handlers simple and fast.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5a654693-d752-4d47-9969-fa521a168f26', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'How do you decide whether to use a push or pull model for a monitoring system?', N'Middle', N'A pull model is generally better for service discovery and controlling the load on the monitoring system, as it allows the server to manage the collection frequency. A push model is more appropriate for short-lived jobs like batch processes that are not always available to be polled.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1b68e2c3-a383-4e6f-be13-fa5363e1a48c', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'How do you implement dynamic routes in Nuxt?', N'Junior', N'Dynamic routes are created by using square brackets in a file name within the pages directory, such as users/[id].vue. Nuxt will treat the content inside the brackets as a parameter that can be accessed in your component.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9ac7dc51-c9b5-46cc-84ac-fa542d78c202', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'What is the difference between In-Memory caching and Distributed caching?', N'Middle', N'In-Memory caching stores data in the local server''s RAM, offering very low latency but limited scalability across multiple instances. Distributed caching, such as Redis, stores data in a shared location accessible by all app instances, which is essential for maintaining consistency in load-balanced environments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd00dc408-0251-4d4e-b79b-fa55afbfea4c', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'How can Fastify be configured to support different protocols like HTTP/2 or HTTP/3?', N'Senior', N'Fastify abstracts the underlying Node.js HTTP server, allowing you to easily swap the server instance for HTTP/2 or HTTP/3 compatible implementations. This requires minimal configuration changes, as the framework''s internal request-response handling is protocol-agnostic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'55096082-8dd3-4563-b80d-fa562b340caf', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'What is the benefit of Actix''s ''Scope'' feature in large-scale applications?', N'Senior', N'Scopes allow for grouping related routes under a common path prefix and sharing specific middleware or application data. This modularizes the codebase, making it easier to maintain and test large-scale systems with multiple service domains.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0fc7509b-9403-461d-8508-fa57c1499ec1', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'What are source maps and why are they useful in Webpack?', N'Junior', N'Source maps provide a way to map the transformed code back to the original source code. This is crucial for debugging in the browser, as it allows you to see your original files and line numbers instead of the minified or transpiled bundle code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2b35c67c-1068-443c-b399-fa58f855d1e0', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'How does the Global Interpreter Lock (GIL) impact the scalability of CPU-bound tasks in CPython?', N'Senior', N'The GIL prevents multiple native threads from executing Python bytecodes at once, effectively serializing execution within a single process. This limits CPU-bound applications from leveraging multi-core architectures through threading, necessitating the use of the multiprocessing module or alternative implementations to achieve true parallelism.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4a80b049-271c-464f-bdde-fa5c79e9e59e', N'24c74bdc-c63e-4370-b1ac-bd560cb834d6', N'How does API documentation affect adoption and maintenance?', N'Middle', N'Clear, interactive documentation like Swagger or OpenAPI reduces the learning curve for developers, leading to faster integration. It also serves as a single source of truth, reducing the need for support requests and helping to ensure that changes to the API are communicated effectively.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1d650f0f-f3d8-46b8-9760-fa5df2506572', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'Describe the concept of Hinted Handoff.', N'Middle', N'Hinted Handoff is a mechanism where a healthy node stores a write request on behalf of a temporarily unavailable node. Once the failed node returns, the healthy node delivers the ''hinted'' data to ensure the cluster reaches eventual consistency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3ddbcffc-5c4d-4495-9201-fa60d00f7210', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'Explain the concept of ''Eventual Consistency'' in the context of distributed database design.', N'Senior', N'Eventual consistency allows for temporary divergence in data across nodes to favor high availability and low latency. The system guarantees that, absent new updates, all replicas will eventually converge to the same value, requiring careful application-level conflict resolution strategies.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2fb383fc-dd4b-495d-94d1-fa6180efb014', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'What role does logging play in incident response?', N'Fresher', N'Logs provide a historical trail of system activity, allowing developers to see the sequence of events leading up to a failure. Without logs, troubleshooting is essentially guesswork because there is no visibility into internal state changes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8a9f14be-6080-4f7d-862d-fa6504ed791f', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'What is the role of the Service Container in facilitating dependency inversion in Laravel?', N'Senior', N'The Service Container acts as a central registry for managing class dependencies and performing dependency injection. By binding interfaces to implementations within the container, you decouple your business logic from concrete classes, making the system significantly easier to unit test and maintain.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'87c0794e-1016-4fe1-8999-fa66438f9892', N'18ebabb7-555b-4ba1-beb6-844b8ee55dbd', N'What is the impact of cache fragmentation?', N'Middle', N'Cache fragmentation occurs when memory is allocated and deallocated in non-contiguous blocks, leading to inefficient memory usage. This can cause the cache to hit its memory limit prematurely, forcing the eviction of useful data and degrading performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1999888d-160d-4b74-aabe-fa68be9e4fda', N'9a0e3785-3b73-4abc-ab01-df75bf097dff', N'What is the purpose of ''Bulkheading'' in service architecture?', N'Senior', N'Bulkheading isolates pools of resources to prevent a failure in one area from exhausting resources for the entire system. By partitioning threads, connection pools, or memory, you ensure that a surge in traffic to one feature doesn''t starve critical system components.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'30db4831-2383-4c28-855e-fa68ff517dae', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'How do C++ move semantics improve performance for resource-heavy objects?', N'Senior', N'Move semantics allow the transfer of ownership of resources, such as buffers or file handles, from a source object to a target without deep-copying the underlying data. By stealing the internal pointers and nullifying the source, it eliminates expensive heap allocations and memory copies, significantly improving performance for containers and large objects.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9443bef5-7c37-4afa-bd29-fa6d63885ecb', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'What is the main goal of the Remix framework regarding web standards?', N'Intern', N'The main goal is to rely heavily on standard web APIs, such as the Request and Response objects. By using these standard interfaces, Remix makes it easier for developers to understand how data moves between the server and the browser.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bb586b96-5d03-431b-b993-fa6dc069ec45', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'Explain the concept of ''Tree Shaking'' in the context of Dart''s build process.', N'Middle', N'Tree shaking is an optimization technique used during AOT compilation that removes unused code from the final application bundle. By analyzing the dependency graph, the compiler identifies and strips out classes, functions, or libraries that are never referenced, resulting in smaller binary sizes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd97aabb7-fca4-4659-9769-fa7075a8ecd4', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'What are the limitations of Fiber''s zero-allocation design?', N'Middle', N'The zero-allocation goal is achieved through object pooling, which introduces complexity for the developer. If a developer needs to pass data asynchronously to a background goroutine, they must manually copy the data, as the original pointers will become invalid once the main handler returns.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'138a1f85-be4d-445a-a602-fa70d540029f', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'Compare the performance of Lit''s template literal parsing against React''s Virtual DOM.', N'Senior', N'Lit uses static template parsing to identify dynamic parts of the DOM, meaning it only updates the specific nodes that change rather than diffing a massive virtual tree. This approach is generally faster and more memory-efficient because it avoids the overhead of creating and comparing large object representations of the UI.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'106de4a3-1318-4611-9063-fa710cabe191', N'9a0e3785-3b73-4abc-ab01-df75bf097dff', N'How does the ''Sidecar'' pattern improve the maintainability of microservices?', N'Senior', N'The sidecar pattern offloads cross-cutting concerns like logging, security, or proxying to a separate container colocated with the service. This allows developers to focus on business logic while keeping the infrastructure logic decoupled and language-agnostic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'07c41d3e-2227-4c18-8411-fa714e5d8d35', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'What are status codes and why are they important?', N'Intern', N'Status codes are standard HTTP codes that indicate the result of a client request, such as success, client error, or server error. They are important because they provide a clear, standardized way for the client to understand what happened during the request.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1b3f1e6e-9744-490e-83b4-fa72037f5830', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'Can you use standard thread-safe types inside an actor?', N'Junior', N'Yes, but it is often unnecessary because actors are designed to own their state. Since only one message is processed at a time, you rarely need to use Mutex or other synchronization primitives for internal actor state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9fbf6c42-1dc5-4209-ab53-fa733850f43e', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'What is the difference between an Access Exclusive lock and a Row Share lock?', N'Middle', N'Access Exclusive is the most restrictive lock and is held by commands like DROP TABLE or ALTER TABLE, blocking all other access. A Row Share lock is acquired by SELECT FOR UPDATE and allows other transactions to read the table while preventing them from modifying or deleting the specific rows being locked.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'22bc9cc9-e8a6-4981-9dd2-fa78375fc2bd', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'When should you choose a Route Handler over a Server Action?', N'Middle', N'Route Handlers are better suited for creating public-facing APIs, webhooks, or endpoints that need to be consumed by external services. Server Actions are designed specifically for handling form submissions and internal data mutations within the React component lifecycle.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1cdd7b3c-6d6e-4e33-928f-fa794ce3905f', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'What is the ''defer'' statement in Swift?', N'Intern', N'The defer statement is used to execute a set of statements just before code execution leaves the current scope. It is commonly used to ensure that cleanup tasks, such as closing file handles or releasing resources, are performed regardless of how the scope is exited.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3652d3a0-b204-435d-8493-fa795992f1a4', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'How does Next.js determine which pages are static and which are dynamic at build time?', N'Middle', N'Next.js automatically detects if a page uses dynamic functions like cookies, headers, or search params, or if it performs a non-cached data fetch. If these are detected, the page is marked as dynamic; otherwise, it is pre-rendered as a static page.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3f4d66d7-6f7c-470e-a0cc-fa79cd48376f', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'Explain the concept of ''configuration over customization'' in the context of the Tailwind config file.', N'Middle', N'Tailwind encourages extending the default theme through a centralized configuration file rather than overriding styles via external CSS files. This ensures design consistency across the project by restricting developers to a defined set of spacing, colors, and typography tokens.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'03da4b7c-da60-4a2d-933d-fa7d38e0660a', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'If a system is performing slowly, how would you start investigating the cause?', N'Fresher', N'I would start by identifying which specific part of the system is slow and look for bottlenecks like high resource usage or inefficient data processing. I would monitor logs and system metrics to narrow down whether the issue is related to the software, infrastructure, or external dependencies.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b8f14e93-0db2-428c-9197-fa7f60df79d1', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'What is the role of the health check extension in Quarkus?', N'Fresher', N'The health check extension provides endpoints that allow orchestration tools like Kubernetes to verify if the application is alive and ready to handle traffic. It helps in managing the lifecycle of containerized pods by automatically restarting unhealthy instances.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e354e999-58d1-44c2-aafb-fa7fc52ae52a', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'Why is it important to keep a record of your troubleshooting steps?', N'Intern', N'Keeping a record prevents you from repeating failed attempts and helps you track your thought process. It also serves as valuable documentation for team members who might encounter similar issues in the future.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a1ae281c-de48-405d-85e2-fa81b65af00e', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'What does the CHECK constraint do?', N'Fresher', N'A CHECK constraint ensures that all values in a column satisfy a specific boolean expression or condition. If a row is inserted or updated with a value that fails the condition, the operation is rejected.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c3eb88fa-66d5-4588-8e6f-fa83e23505de', N'f2e963ff-7635-4429-a389-4d92535fb972', N'Describe the browser''s process for handling invalid HTML and its impact on performance.', N'Senior', N'Browsers use complex error-recovery algorithms to ''fix'' invalid HTML, which can lead to unpredictable DOM tree structures and forced reflows. These deviations from the spec increase parsing overhead and can cause visual inconsistencies across different rendering engines, making strict validation essential for stability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'325ad4be-d565-4e69-be46-fa84c190be71', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'Why is Cassandra considered an AP database in the CAP theorem?', N'Junior', N'Cassandra is categorized as AP because it prioritizes Availability and Partition tolerance. It ensures that the system remains operational and accepts writes even if some nodes are unreachable.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd76aa8ab-fdbe-4160-8d0e-fa89b5535cdc', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'What is your approach to deciding between shared-database and database-per-service patterns?', N'Middle', N'I default to database-per-service to ensure loose coupling and allow teams to choose the best storage technology for their specific data needs. I only consider a shared database if the services are tightly coupled and the complexity of managing distributed transactions outweighs the benefit of autonomy.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9fc200e6-a99d-4f3a-990b-fa8aa2875e87', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'What does the ''static'' keyword do when used inside a function?', N'Junior', N'When applied to a local variable inside a function, the static keyword ensures the variable maintains its value between successive function calls. The variable is initialized only once when the program starts, rather than every time the function is called.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'313baa8e-e042-4449-80c1-fa8e242c679c', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'What is ''Just-in-Time'' (JIT) mode in Tailwind CSS?', N'Intern', N'JIT mode generates CSS on-demand as you write your HTML, rather than generating all possible utility classes upfront. This makes the build process faster and allows for arbitrary values that are not in the default design system.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e68b4c2a-49d5-45b1-8cd3-fa91395f93ea', N'fcd5873e-c89a-47d6-bb4c-c60b57c2ede1', N'Describe the architectural implications of adopting a ''Database per Service'' pattern.', N'Senior', N'This pattern enforces strict service boundaries and prevents hidden coupling via shared databases, but it complicates cross-service transactions and reporting. Architects must implement mechanisms like the Saga pattern to ensure data integrity across services without relying on distributed transactions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'23f13279-9be8-4fce-84b4-fa92036c8b99', N'8d34dfc0-4a64-4128-b41a-cafa62ddad41', N'Explain the architectural trade-offs between using OIDC/OAuth2 and SAML for authentication.', N'Senior', N'OIDC is designed for modern web and mobile applications using JSON/REST, offering better performance and developer experience through its lightweight token structure. SAML is an XML-based standard more commonly used in enterprise environments for legacy SSO integrations, but it introduces significant overhead due to complex message structures and potential vulnerabilities like XML injection.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
