INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a3e78488-d616-4299-a4ca-faa00494b7b5', N'd5b12859-0c9f-4e2f-9b3a-1ccb6c5080e5', N'Compare Partitioning vs. Sharding in a database context.', N'Senior', N'Partitioning usually refers to breaking a large table into smaller, manageable chunks within a single database instance to improve performance and maintenance. Sharding is a form of horizontal partitioning where data is spread across multiple physical servers to scale beyond the limits of a single machine.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
