INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e39b9d8b-686e-498d-9954-faad18a8d0fc', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'What architectural trade-offs exist when moving from a synchronous framework like Flask to FastAPI?', N'Senior', N'The transition requires shifting to an asynchronous programming model, which demands a deep understanding of the event loop and non-blocking I/O. While the benefits include significantly higher concurrency, the trade-off is increased code complexity and the need for all database drivers and third-party libraries to support ''async/await''.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'77880a25-636c-48fe-954f-faafee27df7c', N'a000805c-e41f-42a9-af12-66b45348f77b', N'How does Lucid ORM handle database transactions across multiple service calls?', N'Middle', N'Lucid provides a transaction object that can be passed through different service methods to ensure operations share the same database connection. If any operation within the transaction block fails, the entire set of changes can be rolled back to maintain data integrity.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'53206191-83c8-4ec6-a2f9-fab64ccc4593', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'What are the performance implications of using empty interfaces in Go?', N'Middle', N'Using empty interfaces involves type assertion and dynamic dispatch, which incurs a runtime overhead compared to static typing. It also bypasses compile-time type safety, potentially leading to runtime panics if the underlying type is not what the developer expected.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'72500cd6-fe2c-4aaa-b5c1-fabb35d08b91', N'18ebabb7-555b-4ba1-beb6-844b8ee55dbd', N'How do you decide between Write-Through and Write-Back caching strategies in a high-throughput distributed system?', N'Senior', N'Write-Through ensures strong consistency by updating the cache and database synchronously, which increases latency but minimizes data loss risks. Write-Back improves performance by updating the cache immediately and syncing to the database asynchronously, but it introduces a risk of data loss if the cache node fails before the write-back occurs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3454277f-85d7-426f-bffa-fabefa3bde7f', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'How does Micronaut handle cloud-native configuration management?', N'Middle', N'Micronaut supports distributed configuration through integration with services like HashiCorp Consul or AWS Parameter Store. It allows applications to dynamically fetch properties at startup or refresh them at runtime, facilitating seamless horizontal scaling in cloud environments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3135d8eb-a4ce-4d07-a187-fabfad6a8719', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'What is SEO in the context of Nuxt?', N'Intern', N'SEO, or Search Engine Optimization, is the practice of making your web pages easier for search engines to find and rank. Nuxt helps with SEO by providing server-side rendered content, which search engine crawlers can read much more easily than client-only content.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fe4c8d40-5637-48ba-8110-fac024ae1fdc', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'How does a database engine detect a deadlock?', N'Junior', N'Most database engines maintain a wait-for graph that tracks which transactions are waiting for which locks. If the system detects a cycle in this graph, it identifies a deadlock and typically kills one of the involved transactions to break the cycle.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6ad6dc41-0f73-4c09-b1a3-fac2f4368ac7', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is modules in ES6?', N'Intern', N'Making objects, functions, classes or variables available to the outside world is as simple as exporting them, and then importing them where needed in other files. Benefits * Code can be split into smaller files of self-contained functionality. * The same modules can be shared across any number of applications. * Ideally, modules need never be examined by another developer, because they’ve has been proven to work. * Code referencing a module understands it''s a dependency. If the module file is changed or moved, the problem is immediately obvious. * Module code (usually) helps eradicate naming conflicts. Function x() in module1 cannot clash with function x() in module2. Options such as namespacing are employed so calls become module1.x() and module2.x().', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dd383664-cd54-4204-a4d3-fac421702b42', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'How do you access headers in an incoming request?', N'Junior', N'You can access HTTP request headers using the req.get() method or the req.headers object. These objects contain information about the client, such as the User-Agent, Content-Type, or custom authorization tokens.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5ee0638a-ab37-4705-af29-fac673866e87', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'What is a delegate and how does it differ from an interface?', N'Middle', N'A delegate is a type-safe function pointer that allows methods to be passed as arguments to other methods. While an interface defines a set of methods that a class must implement, a delegate defines a specific signature for a method, making it more focused on functional abstraction than object behavior.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f7a5e7f3-71a8-489b-8c3c-fac8bcb6a78b', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is the prototype chain and how does it work?', N'Intern', N'The prototype chain is a mechanism in JavaScript that allows objects to inherit properties and methods from other objects. When you try to access a property on an object, JavaScript will first look for the property on the object itself. If it doesn''t find it, it will look at the object''s prototype, and then the prototype''s prototype, and so on, until it either finds the property or reaches the end of the chain, which is null. In this example, alice inherits the greet method from Person.prototype. ↑ &nbsp;&nbsp;/&nbsp;&nbsp; ✏️ Edit answer Explain the difference between classical inheritance and prototypal inheritance Classical inheritance is a model where classes inherit from other classes, typically seen in languages like Java and C++.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5c9a8743-0947-4329-a532-fac8f8d16c96', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'When faced with two different ways to solve a problem, how do you decide which one to pursue?', N'Junior', N'I evaluate them based on criteria like maintainability, time-to-delivery, and long-term scalability. I prefer the solution that is simplest to understand and test, unless the requirements explicitly demand high performance or complex features.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'301840d4-1be6-451b-9456-facac42779a8', N'954a0331-deff-4399-b588-96f39fec001d', N'What is the purpose of Wildcard route?', N'Intern', N'If the URL doesn''t match any predefined routes then it causes the router to throw an error and crash the app. In this case, you can use wildcard route. A wildcard route has a path consisting of two asterisks to match every URL. For example, you can define PageNotFoundComponent for wildcard route as below', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ccb8f8c3-1825-4b75-a65c-faced028233d', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'Why might you use a ''virtual module'' in a Vite plugin?', N'Middle', N'Virtual modules do not exist as physical files on the disk. They are generated dynamically by a plugin, which is useful for injecting configuration data, environment-specific constants, or computed metadata into the application bundle.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0b60f2be-368e-498c-b42d-facfa079e65f', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'How does PostgreSQL handle temporary tables compared to regular tables?', N'Middle', N'Temporary tables are private to the current session or transaction and are automatically dropped when the session ends or the transaction closes. They are stored in a special temporary schema and do not participate in the standard WAL logging process, which makes them faster but prevents them from being replicated to standby servers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd4971907-9c59-4b60-865b-fad2c6209129', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'What role does technical debt play in your daily work?', N'Junior', N'Technical debt is a reality of development, so I try to manage it by balancing the need for quick delivery with the need for long-term code quality. I communicate the existence of technical debt to my team and advocate for setting aside time in the sprint to address it periodically.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'81a59811-b442-44fd-87af-fad5e3e7381e', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'Describe the relationship between C and the underlying hardware regarding integer overflow.', N'Senior', N'In C, signed integer overflow is undefined behavior, which allows the compiler to assume it never happens and optimize accordingly, such as eliminating checks that would otherwise be necessary. Unsigned overflow is defined as modular arithmetic, which is a key design choice for representing binary counters and bitwise operations. Understanding this distinction is vital for writing secure code that interacts correctly with architecture-specific integer representations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2b8fe8c4-7c9f-4de6-980a-fad68ce4aad4', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'What is pessimistic locking?', N'Junior', N'Pessimistic locking assumes that conflicts will happen and locks the data as soon as a transaction starts. This prevents other transactions from modifying the record until the first one is finished.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1216d67c-6319-4bc5-a17e-fad7a55e5ad1', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'What is the difference between state and props?', N'Intern', N'Props are passed into a component from the outside and are immutable for the receiving component. State is managed internally by the component itself and can be updated to trigger re-renders.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'250ddfb4-f065-4581-b8fd-fadf38f96a96', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'How does Symfony''s Dependency Injection Container (DIC) utilize compilation to optimize performance?', N'Senior', N'During the container compilation phase, Symfony resolves all service definitions, parses tags, and flattens the dependency graph into a highly optimized, generated PHP class. This eliminates the overhead of dynamic dependency resolution at runtime by caching the container structure as static PHP code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'37bd22fa-f46f-4318-afbc-fae131e4e653', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'What is the role of Rollup in Vite?', N'Intern', N'Rollup is the production bundler used by Vite to build the application for deployment. It excels at tree-shaking, which removes unused code to produce smaller, more efficient final bundles.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7ead9394-e15b-4d6e-a5a9-fae27ea2a634', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'How does Phoenix handle security regarding CSRF tokens?', N'Middle', N'Phoenix automatically includes a CSRF plug in the browser pipeline that validates a unique token for every state-changing request like POST or PUT. This ensures that the request originated from your application and prevents malicious sites from performing unauthorized actions on behalf of a logged-in user.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'14a69424-6b23-4492-8fdd-fae3f3559f4b', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'What are the performance implications of using barrel files in a Vite project?', N'Middle', N'Barrel files can negatively impact Vite''s dev server performance because they force the bundler to analyze and load all modules referenced in the barrel. It is often better to import specific files directly to keep the dependency graph smaller.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'403dac62-8f12-42af-8116-fae4d260e4cf', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'Why is it important to avoid storing calculated data in a database?', N'Intern', N'Storing calculated data can lead to data inconsistency if the source values change without updating the calculated field. It is generally better to calculate these values on the fly when retrieving data to ensure accuracy.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5003f053-b3d1-4c42-a5c7-fae4d98d8276', N'a000805c-e41f-42a9-af12-66b45348f77b', N'Explain how AdonisJS handles authentication.', N'Fresher', N'AdonisJS has a robust built-in authentication system that supports multiple guards like session-based auth, API tokens, or basic auth. It provides a simple API to log users in, check their current status, and protect routes based on user permissions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bf749d3a-30ce-46e4-b65f-fae8016ea804', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'What is a ''hot key'' problem and how can it be mitigated?', N'Middle', N'A hot key occurs when a specific partition key receives a disproportionately high volume of requests, causing performance degradation on that node. It can be mitigated by choosing a more granular partition key or by using caching layers to distribute the load.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c5494051-1d50-4a87-86dd-faea2795673c', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'Is Webpack the only available bundler for frontend projects?', N'Fresher', N'No, there are several other popular bundlers available, such as Vite, Rollup, and Parcel. While Webpack is the most mature and feature-rich, these alternatives often prioritize faster build times or simpler configuration for modern projects.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bb7e9f8b-2d06-4625-aba6-faeebfaf4dad', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'How does Swift''s module system prevent namespace collisions?', N'Middle', N'Swift organizes code into modules, where each module defines its own namespace. Even if two modules have classes with the same name, they are kept separate, and the developer can disambiguate them by prefixing the class name with the module name.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cdd5bb1a-53f2-434f-bea5-faef6471f9a7', N'210c7148-726e-4e8b-bf12-40be36e55130', N'Explain the concept of interior mutability in Rust.', N'Middle', N'Interior mutability is a design pattern that allows you to mutate data even when there are immutable references to that data. It is typically implemented using types like ''RefCell'' or ''Mutex'', which move the borrow checking from compile time to runtime.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'17407190-509f-4e3b-b5f1-faf08137a3f4', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'How does Express handle backpressure when streaming large responses, and what is the risk of bypassing it?', N'Senior', N'Express relies on the underlying Node.js streams API to manage backpressure by pausing the readable stream when the writable buffer is full. Bypassing this by forcing data into the stream can lead to unbounded memory growth and potential process termination due to heap exhaustion.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7c648fe4-dc58-439e-98a1-faf94b713841', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'Describe the concept of ''Read Repair'' in Dynamo-style distributed databases.', N'Senior', N'Read repair is a mechanism where the coordinator node compares the versions of data returned by multiple replicas during a read request. If inconsistencies are detected, the coordinator pushes the latest version back to the lagging replicas to ensure eventual consistency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'58435390-3041-4e57-bbd1-fafa2b664dd1', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'What is the risk of ''hotfixing'' a bug without thorough testing?', N'Junior', N'While hotfixing addresses the immediate issue, bypassing the standard testing process increases the risk of introducing critical new bugs. It is better to use automated testing to ensure the fix is robust and safe for production.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f8ffa40a-a6b5-4cdf-a939-fafb322f734b', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'How does Axum achieve type safety?', N'Fresher', N'Axum leverages Rust''s strict type system to ensure that extractors and responses match the expected types at compile time. This prevents many common runtime errors related to data structure mismatches.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'56824d0b-75aa-4d56-b600-fafbebcffbee', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'Why is it important to document engineering processes?', N'Intern', N'Documentation ensures that knowledge is shared across the team rather than being held by a single individual. It helps new team members onboard faster and provides a reference for troubleshooting recurring issues. Proper records also maintain consistency and improve the quality of future development cycles.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f1b66132-803e-4d57-8521-fafd14f076bb', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'What is the role of Micronaut''s ''Bean Definition'' classes?', N'Senior', N'Bean definition classes are generated at compile time to store metadata and instantiation logic for every bean. These classes effectively replace the need for runtime reflection-based scanning, as the container simply loads these pre-compiled definitions to wire the application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'86e4a0aa-34a7-4190-adf3-fafda53f9ff9', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'Is Redux tied exclusively to React?', N'Intern', N'No, Redux is a standalone library that can be used with any JavaScript framework or even plain JavaScript. It is frequently used with React, but it does not depend on it.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
