INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a72797a3-34cc-4eef-8ded-fb034f353fd5', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'Explain how this works in JavaScript?', N'Fresher', N'The this keyword refers to an object. Which object depends on how this is being invoked (used or called). The this keyword refers to different objects depending on how it is used. * In an object method, this refers to the object. * Alone, this refers to the global object. * In a function, this refers to the global object. * In a function, in strict mode, this is undefined. * In an event, this refers to the element that received the event. * Methods like call(), apply(), and bind() can refer this to any object. Example:', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c6bba951-84f2-4712-abb0-fb058ae0e01d', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'How do you optimize Symfony''s performance in a production environment?', N'Senior', N'Optimization involves enabling opcode caching, using a high-performance HTTP cache like Varnish, and ensuring the service container is compiled and cached. Additionally, minimizing the number of loaded bundles and tuning the database connection pool are essential for reducing overhead.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0bdd5777-6965-476a-9659-fb080f29114f', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'What are the performance implications of using complex Pydantic models in Litestar request validation?', N'Senior', N'Deeply nested Pydantic models with complex validators can become a bottleneck due to the CPU-intensive nature of recursive validation. For high-performance endpoints, simplifying the validation schema or using DTOs to limit the scope of validation can significantly improve response times.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
