INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2a32eaf3-8e77-4ad0-8109-fb0c0e06aa53', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'How do Kotlin coroutines improve performance compared to traditional thread-based concurrency?', N'Middle', N'Coroutines are lightweight abstractions that allow suspending execution without blocking the underlying thread. By using a small pool of threads to execute many coroutines, they significantly reduce the memory and overhead costs associated with creating and context-switching between heavy operating system threads.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
