INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a7767896-bb9e-4d8a-a109-fb14243e8955', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'How does Rocket approach performance instrumentation?', N'Senior', N'Performance instrumentation is achieved primarily through Fairings that capture the time elapsed between the start of a request and its final response. Because this is decoupled from the business logic, it provides accurate, non-intrusive metrics that can be exported to monitoring systems like Prometheus.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3a63ae1c-2a41-4cbd-9ade-fb16fd2f223b', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'How do you handle a situation where you realize a task will take significantly longer than your original estimate?', N'Junior', N'I would communicate the delay to my manager or lead as soon as I identify the risk, rather than waiting until the deadline. I would explain the specific blockers or technical complexities discovered and suggest either adjusting the scope or extending the timeline.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8e379825-2c2c-4191-84e0-fb187a93e468', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'What is your process for choosing between a relational database and a NoSQL store?', N'Senior', N'I choose based on the data model''s complexity and the required consistency guarantees. If the application requires complex transactional integrity and structured queries, a relational database is superior, whereas NoSQL is selected for unstructured data, high write throughput, or massive horizontal scale where schema flexibility is critical.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'46b0d235-4098-4f18-906f-fb1b2ef155f5', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'What are Svelte stores?', N'Intern', N'Svelte stores are objects used for managing global or shared state that needs to be accessed by multiple components. They provide a simple way to subscribe to data changes without needing to pass props down through multiple levels of the component tree.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd452762f-1975-498b-9bf5-fb1b78d223a2', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'What is a NoSQL database, and how does it differ from SQL?', N'Fresher', N'NoSQL databases, like DynamoDB, are non-relational and do not require a fixed table schema, making them flexible for unstructured data. In contrast, SQL databases are relational, use tables with predefined schemas, and rely on structured query language for data manipulation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f3c340d1-2e00-4646-8a1e-fb1f1e470fa0', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'What is the purpose of x-show in Alpine.js?', N'Fresher', N'The x-show directive is used to toggle the visibility of an element by adding or removing the CSS display property. It is the standard way to show or hide UI elements based on a boolean state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e62385c4-75ac-4a22-a76e-fb23f81f6c86', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'How does data flow work in Svelte?', N'Fresher', N'Data in Svelte flows unidirectionally from parent to child components via properties. If a child component needs to communicate back to the parent, it typically uses dispatchers or event forwarding.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1e9d948c-ba14-45a5-ad66-fb26602fe519', N'954a0331-deff-4399-b588-96f39fec001d', N'How does Angular''s ''Signals'' architecture fundamentally change the way state management is handled compared to RxJS-based streams?', N'Senior', N'Signals provide a fine-grained reactivity model that tracks dependencies automatically at the template level, avoiding the need for manual subscription management or complex async pipes. This simplifies state flow and enables the framework to update only the specific DOM nodes dependent on a changed value, rather than re-checking entire component subtrees.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
