INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c891d770-803f-43e8-8b7d-fb4d0f5e5b67', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'Explain the concept of ''covariance'' and ''contravariance'' in TypeScript''s function parameter checking.', N'Senior', N'TypeScript treats function return types as covariant, meaning they can be more specific than the base type, but function parameters as bivariant for practical flexibility. This design choice prioritizes developer ergonomics over strict mathematical type soundness in function assignment.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'41f1a7cc-fbd2-49e1-9e30-fb4de2969e13', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'How does the SAGA pattern address distributed transaction management in microservices?', N'Senior', N'The SAGA pattern breaks a distributed transaction into a sequence of local transactions, where each step triggers the next. If a step fails, the SAGA executes compensating transactions to undo the changes made by previous steps, providing eventual consistency instead of immediate atomic consistency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'18bc481e-05d2-4cc9-9b5f-fb500279f44c', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'How does Remix handle navigation compared to traditional web pages?', N'Fresher', N'Remix uses a feature called ''nested routing'' to load only the specific parts of a page that need to change during navigation. Instead of reloading the entire document like a classic multi-page application, it fetches only the necessary data and UI updates, providing a smooth, fast user experience.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9e217748-ef1f-4826-9c09-fb50f1f34a50', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'What is the role of the ''virtual'' keyword in C++?', N'Fresher', N'The virtual keyword is used in base classes to enable polymorphism. It tells the compiler to use dynamic binding, ensuring that the appropriate derived class function is called at runtime when accessed via a base class pointer or reference.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3edca6bf-0952-4719-aac9-fb518d650e75', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'How does Qwik manage user events?', N'Intern', N'Qwik uses global event delegation, meaning it listens for events at the document level. When a user interacts with an element, Qwik identifies the required code chunk for that event and downloads it on demand.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7c41b0ca-a809-4242-b843-fb529c37bb7a', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'What are case classes in Scala?', N'Fresher', N'Case classes are regular classes that are specialized for use in pattern matching and immutable data modeling. They automatically provide useful methods like equals, hashCode, and toString, and they include a built-in factory method for creation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'aebeb92c-390b-415b-ab90-fb52d2cf2182', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'How does Axum handle shared state across different handlers in a thread-safe manner?', N'Senior', N'Axum uses the State extractor to inject shared data into handlers, which must implement Clone to be shared across threads. For mutable access to state, developers typically wrap the data in synchronization primitives like Arc > or Arc > to ensure thread-safe concurrent access.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fa129726-bd67-4450-882a-fb551ba7429b', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'Why is using Fastify''s ''reply.hijack()'' method considered a high-risk architectural decision?', N'Senior', N'Hijacking the reply object bypasses Fastify''s standard response lifecycle, including serialization, hook execution, and error handling. It is typically used for low-level stream handling, but misuse can lead to memory leaks or broken connection states if the underlying socket is not closed properly.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'18a43ea1-16df-4473-8709-fb552b1c6876', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'How does Flask handle incoming JSON data in a request?', N'Middle', N'Flask provides a request.get_json() method that parses the incoming request body as JSON and converts it into a Python dictionary. It automatically checks the content type header and raises an error if the data is not valid JSON. This simplifies the process of building RESTful APIs where data exchange is primarily in JSON format.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e00151cb-7512-4a7b-aee6-fb553dc9a719', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'What is the difference between a primary and a secondary node in terms of operations?', N'Middle', N'The primary node is the only member that can accept write operations and perform strong consistency reads. Secondary nodes replicate data from the primary and can handle read operations, but they cannot perform writes, making them suitable for scaling read throughput.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0dc154b4-da95-4e8a-9377-fb57ce5e83e2', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'What is the primary architectural philosophy of Alpine.js compared to heavy frameworks like React?', N'Middle', N'Alpine.js follows a declarative, minimalist approach that brings behavior directly into the HTML markup. Unlike React, which uses a virtual DOM and separate component files, Alpine leverages the browser''s native DOM, making it ideal for progressively enhancing static sites.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0e12006c-878f-4311-bbca-fb606be2334d', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'How do you handle a production incident where the root cause is unclear and the system is unstable?', N'Middle', N'My priority is to restore service stability first, often by rolling back the last deployment or scaling up resources. Once the system is stable, I perform a post-mortem analysis by gathering telemetry data, logs, and metrics from the time of the incident. This approach prevents further downtime while allowing a calm, data-driven investigation into the root cause.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'89fa701d-3a73-4d15-b269-fb60cc434409', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'How does Chi handle request body parsing?', N'Junior', N'Chi does not provide specific body parsing helpers, as it stays focused on routing. You should use the standard library''s json.NewDecoder on the request body to decode incoming data in your handler.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'02ef9c6b-0b3b-4292-8db9-fb6615114f2d', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'What is the purpose of the Scala REPL?', N'Intern', N'The REPL, which stands for Read-Eval-Print Loop, is an interactive shell used for testing and experimenting with Scala code. It allows developers to execute code snippets immediately and see the results without needing to compile a full project.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e62b5a06-320c-47dc-b339-fb663009669a', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'What approach do you take when logs are insufficient to diagnose a critical production failure?', N'Senior', N'I would pivot to observability tools like distributed tracing and metrics to visualize the system state at the time of the incident. If observability data is also sparse, I would use traffic mirroring or network packet captures to inspect the raw data flow, while simultaneously deploying temporary, non-intrusive sidecar instrumentation to gather high-fidelity runtime telemetry.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5299e843-8b3f-4a11-9692-fb67341e2d87', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'What is the item limit in a single DynamoDB table?', N'Intern', N'There is no practical limit to the number of items you can store in a single DynamoDB table. The storage capacity is limited only by your AWS account limits, which can be increased upon request.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bf4f4453-e174-4956-ac4e-fb678f9da22c', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'How does Svelte''s reactivity model differ from the Virtual DOM approach used by React?', N'Middle', N'Svelte is a compiler that converts declarative components into highly efficient, imperative code that surgically updates the DOM. Unlike React, which uses a Virtual DOM to diff changes, Svelte tracks state dependencies at compile time, eliminating the runtime overhead of reconciliation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd8f9ba86-f59d-4b15-86bf-fb6b3c9f0381', N'a000805c-e41f-42a9-af12-66b45348f77b', N'What is the ''config'' directory used for?', N'Intern', N'The config directory holds configuration files for various parts of the framework, such as database connections, session settings, and mail drivers. Keeping these separate from the code allows for easy adjustments without modifying the application logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2fe5e693-8b48-4406-9d13-fb6b5008ae4f', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'What process do you follow when estimating the time required to complete a complex engineering task?', N'Middle', N'I break the task down into smaller, manageable sub-tasks and estimate each individually based on historical data or team consensus. I also explicitly factor in time for research, testing, and potential risks to provide a realistic range rather than a single optimistic deadline.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b101fde1-007b-4a0f-8b2d-fb6b5acc986d', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'What is your strategy for managing secrets and sensitive configuration in a cloud-native environment?', N'Senior', N'I utilize dedicated secret management services that provide dynamic secret generation and automated rotation. I ensure that secrets are never committed to version control and are injected into the application environment at runtime using secure sidecar patterns or volume mounts.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'22f527dc-a797-457d-8914-fb6cc971ab0a', N'fcd5873e-c89a-47d6-bb4c-c60b57c2ede1', N'What is the ''CAP Theorem'' and how does it influence database selection?', N'Senior', N'CAP theorem states that a distributed system can only provide two out of three guarantees: Consistency, Availability, and Partition Tolerance. Since network partitions are inevitable in distributed systems, architects must choose between prioritizing consistency (CP) or availability (AP) when a partition occurs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'03b54f38-34e4-48f4-b181-fb6ea3a1853a', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'Describe the ''keyof'' operator.', N'Middle', N'The ''keyof'' operator takes an object type and produces a union of its literal keys. It is highly useful for creating generic functions that accept object keys as parameters, ensuring that the passed key actually exists on the object. This improves type safety when working with dynamic property access.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'553ea267-f57d-4913-9376-fb701eb826a3', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'What is the @apply directive in Tailwind CSS?', N'Fresher', N'The @apply directive allows you to take existing utility classes and apply them to a custom CSS class. This is useful when you want to avoid repeating the same long string of classes across multiple elements.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ac963a49-c320-456b-9dd8-fb75116af527', N'd5b12859-0c9f-4e2f-9b3a-1ccb6c5080e5', N'Explain the concept of write-ahead logging (WAL) and its importance.', N'Middle', N'WAL is a technique where changes are logged to a persistent file before being applied to the actual data files. This ensures data integrity during system crashes, as the database can recover by replaying the logs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6f9cb1d1-ccf9-44db-a787-fb764ac474bb', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'How Encapsulation concept implemented in JAVA?', N'Fresher', N'Encapsulation in Java is a mechanism of wrapping the data (variables) and code acting on the data (methods) together as a single unit. In encapsulation, the variables of a class will be hidden from other classes, and can be accessed only through the methods of their current class. Therefore, it is also known as data hiding. To achieve encapsulation in Java − * Declare the variables of a class as private. * Provide public setter and getter methods to modify and view the variables values. Example:', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7d8d7775-c964-4cd1-9db6-fb7aee2f6e3b', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'Describe the trade-offs of using jQuery''s event delegation versus modern declarative event handling in frameworks.', N'Senior', N'jQuery delegation attaches a single listener to a parent to capture events from children, which is memory-efficient for dynamic lists. However, modern frameworks use a synthetic event system or direct binding that is better integrated with component lifecycles, reducing the risk of memory leaks and stale event handlers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cd2bc668-3812-439d-ab78-fb7b38fbb0fa', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'How does Symfony handle user authentication?', N'Fresher', N'Symfony uses a dedicated Security component to handle authentication and authorization. It manages login forms, user identity verification, and role-based access control to ensure that users can only access parts of the application they are permitted to see.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b234fa7d-7c78-4103-b72d-fb7ecfb997d1', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'How does Hono manage environment variables across different deployment platforms?', N'Senior', N'Hono abstracts environment variables through the Context object, which is populated by the specific runtime''s binding interface. This allows the same application code to access secrets and configurations seamlessly whether running on Cloudflare, Bun, or Node.js.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f7b80362-4d7f-404b-92ef-fb7f724bba5a', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'How do you weigh the benefits of automated testing against the time required to maintain the test suite?', N'Middle', N'Automated tests provide rapid feedback and safety for refactoring, reducing long-term maintenance costs and regression risk. However, poorly maintained tests become brittle, increasing the time needed for every code change, so the trade-off is managed by focusing on testing critical business logic and high-risk paths rather than every trivial component.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'06e48d5b-5a0b-454c-8633-fb7f97b08db3', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'When estimation for a high-priority project is significantly off, how do you communicate this to non-technical leadership?', N'Senior', N'I use a data-driven approach that isolates the specific technical challenges encountered versus the original assumptions, explaining the impact on the critical path. I present a range of scenarios—such as descoping non-essential functionality or adding resources with a clear understanding of the ramp-up cost—to allow leadership to make informed trade-offs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f38a32d1-efed-4f76-94ee-fb84698d239c', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'What is the purpose of the SELECT statement?', N'Fresher', N'The SELECT statement is used to retrieve data from a database. The result is stored in a result table, sometimes called the result set.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'feb7b9c9-8973-408d-9dd7-fb84ff6957e3', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'What is the benefit of SvelteKit''s built-in routing?', N'Intern', N'Built-in routing eliminates the need for external client-side router libraries. It is deeply integrated with the framework, allowing for automatic code splitting and efficient page transitions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'daf39a80-d846-4707-8189-fb85be30f5a5', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'How would you implement state persistence in Redux, and what are the security considerations?', N'Senior', N'State persistence is usually implemented by subscribing to the store and saving the state to local storage or IndexedDB. Security risks include leaking sensitive user information or PII into persistent storage, which should be mitigated by filtering out sensitive slices before saving and encrypting the persisted data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1d74149a-d335-4e03-91af-fb85f723b5d0', N'a000805c-e41f-42a9-af12-66b45348f77b', N'How does AdonisJS handle environment variables for different deployment stages?', N'Middle', N'AdonisJS uses a strict environment variable validation system that fails fast if required variables are missing or incorrectly formatted. This prevents runtime errors in production by ensuring the application configuration is fully verified at startup.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a28384e2-c52c-42b5-b715-fb89c0de945f', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'Explain fetch() properties in JavaScript?', N'Fresher', N'A fetch() function is available in the global window object. The fetch() function takes one mandatory argument, the path to the resource you want to fetch. It returns a Promise, whether it is successful or not. If request is successful .then() function will receive Response object, if request fails then .catch() function will receive an error object Example: &#9885; Try this example on CodeSandbox Headers Object The Headers interface allows to create own headers object via the Headers() constructor. A headers object is a collection of name-value pairs. Example: &#9885; Try this example on CodeSandbox Request Object The Request Object represents a resource request.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bc5d5130-0e92-4eb5-919b-fb8a73cd335e', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'How does Axum handle shared state between different request handlers?', N'Fresher', N'Axum uses the State extractor to inject shared application data into handlers. This allows multiple routes to access common resources, such as database connection pools or configuration settings, in a thread-safe manner.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd930d3c2-8478-4404-97a5-fb8c05bf2dfe', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'What is the role of the View in the MVC pattern?', N'Intern', N'The View is responsible for the presentation layer of the application. It takes the data provided by the controller and renders it into a format that the user can see, typically HTML, to be displayed in a web browser.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8cc0e63d-1913-4a17-a0cc-fb8dcbb8f26b', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'Why is Gin considered faster than the standard library''s net/http?', N'Fresher', N'Gin is faster because it uses a more efficient routing algorithm and minimizes memory allocations during request handling. By using a specialized tree structure for routes, it reduces the complexity of finding the correct handler for an incoming request.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'84195465-d1b4-412d-a705-fb8e1b2c659b', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'Does Chi support wildcard or catch-all routes?', N'Fresher', N'Yes, Chi supports wildcard patterns like * for matching segments of a URL. This is useful for handling complex routing scenarios or serving single-page applications where all traffic is directed to one file.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd8a0177c-cd52-423e-b0d4-fb91c1899919', N'f2e963ff-7635-4429-a389-4d92535fb972', N'Why should you use the button element instead of a div for click interactions?', N'Junior', N'Using a button element provides built-in accessibility features like keyboard focus, tab navigation, and screen reader announcements. A div does not have these behaviors by default, making it less accessible for users who rely on keyboards or assistive technology.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'31ed2670-6d03-4f4e-afe8-fb98999a0948', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'What is the purpose of the ''headers'' export in a route?', N'Middle', N'The headers export allows developers to define custom HTTP response headers for a specific route, such as Cache-Control or Content-Security-Policy. This gives granular control over how the browser or CDN caches the document for that specific page.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1df7fdc4-019a-4974-87d4-fb98ff451362', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'What is the ''continue'' statement?', N'Fresher', N'The continue statement is used inside loops to skip the remainder of the current iteration and jump directly to the beginning of the next iteration. It does not terminate the loop but rather bypasses the current code block.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c792e421-2bd7-4e20-ae44-fb9a2a804395', N'a000805c-e41f-42a9-af12-66b45348f77b', N'What is the architectural impact of using Lucid ORM''s eager loading on memory usage?', N'Senior', N'Eager loading solves the N+1 query problem by fetching related models in minimal database trips. While this significantly improves database performance, loading large relations into memory simultaneously can lead to heap exhaustion; developers must use pagination or partial selects to mitigate this.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'09f3223a-ad44-477a-8019-fb9a93d798b9', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'What is the purpose of load balancing in a system architecture?', N'Intern', N'A load balancer distributes incoming network traffic across multiple servers to ensure no single server becomes a bottleneck. This improves application availability, fault tolerance, and performance by preventing server overload.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f4859ed5-98f0-4351-b9a7-fb9fcc04df65', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'What are the risks of using thread pools improperly?', N'Middle', N'Improperly sized thread pools can lead to resource exhaustion, where too many threads consume excessive memory and CPU context-switching. Conversely, a thread pool that is too small can lead to task starvation and significant latency in request processing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd0985f77-6e46-47a1-b0ca-fba0ca620890', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'What is the distinction between a metaclass and a class decorator, and when is one preferred over the other?', N'Senior', N'Metaclasses control the creation of classes themselves, allowing for deep interception of class definition, while decorators merely modify or wrap a class after it has been created. Metaclasses are preferred for structural changes that must be inherited, whereas decorators are better for simple modifications or adding metadata.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'63c6461b-c32b-4a27-9317-fba239711684', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'Is DynamoDB suitable for analytical (OLAP) workloads?', N'Fresher', N'No, DynamoDB is optimized for operational (OLTP) workloads, which involve high-frequency, simple reads and writes. For complex analytical queries, data is typically exported to a data warehouse like Amazon Redshift.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7d88911f-d18a-4e69-842e-fba2638589ed', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'What are decorators in Python?', N'Intern', N'In Python, a decorator is a design pattern and a language feature that allows you to dynamically modify or extend the behavior of functions or classes without permanently changing their source code. They are a form of metaprogramming where one function (the wrapper) modifies the behavior of another. How Decorators Work - Higher-Order Functions: Decorators are functions that take another function as an argument and return a new function. - Closures: They leverage Python’s support for closures to "wrap" the original function, allowing code execution both before and after the target function runs. - First-Class Objects: Since functions in Python are first-class objects, they can be passed as arguments, assigned to variables, and returned from other functions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'de90f848-7061-4e4d-987f-fba27bd683f1', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'What is the ''Snapshot Isolation'' level?', N'Middle', N'Snapshot isolation provides each transaction with a consistent view of the database as it existed at the start of the transaction. It prevents non-repeatable and phantom reads, but it can lead to write skew anomalies if not carefully managed by the application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'331b276a-4ba7-432c-91c1-fba6863852c0', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'What is the Encapsulation?', N'Intern', N'The concept of binding or grouping related data members along with its related functionalities is known as a Encapsulation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'41d5912c-7d3f-4e58-b57d-fba800b1d63c', N'a000805c-e41f-42a9-af12-66b45348f77b', N'How do you handle secrets and sensitive configuration in AdonisJS?', N'Senior', N'Sensitive configuration should be handled using environment variables and a validation schema that ensures required secrets are present at startup. This prevents the application from booting if critical security parameters are missing, and ensures that sensitive data is never hard-coded or committed to version control systems.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7cd38b0c-1afa-4087-bc01-fba851a04b7d', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'What is a major advantage of using JSON in NoSQL?', N'Intern', N'JSON is a lightweight, text-based format that is easy for humans to read and for machines to parse. Its hierarchical nature allows for complex data structures to be represented naturally within a single database record.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e0104210-3cd9-4b65-b7de-fbabd6f57b0a', N'8d34dfc0-4a64-4128-b41a-cafa62ddad41', N'Explain the concept of defense in depth in system architecture.', N'Middle', N'Defense in depth is a security strategy that uses multiple layers of security controls throughout an IT system. If one layer fails to stop an attacker, subsequent layers are in place to mitigate the risk and provide additional protection.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'da406e90-dcd8-4646-a012-fbaf4322b222', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'What is PostgreSQL and what type of database model does it follow?', N'Fresher', N'PostgreSQL is an open-source object-relational database management system. It follows the relational model, organizing data into tables with rows and columns while supporting advanced object-oriented features.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a7a44f1b-8c63-482a-be0b-fbb052346b53', N'954a0331-deff-4399-b588-96f39fec001d', N'What is a singleton service and how can it be achieved?', N'Intern', N'A singleton service in Angular means that only a single instance of that service exists throughout the entire application. This is useful for managing global state, sharing data or logic across different components and services, or optimizing resource usage. The most common and recommended way to achieve a singleton service is by providing it at the root level using the providedIn: ''root'' property in the @Injectable() decorator: When providedIn: ''root'' is used, Angular registers the service with the application''s root injector. Any component or service that injects DataService anywhere in the application will receive the _same_ instance. > Try out Angular coding questions on GreatFrontEnd. ↑', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'318da1b5-84fe-4770-9c96-fbb252403899', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'What is your methodology for debugging race conditions that only appear in production-scale traffic?', N'Senior', N'I would implement distributed logging with high-resolution timestamps and request correlation IDs to reconstruct the sequence of events across nodes. If the issue is persistent, I would use observability tools to look for anomalies in state mutation patterns or evaluate the locking granularity to see if synchronized blocks are being bypassed or improperly scoped.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
GO
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'54f1a0a8-72b3-4e66-9867-fbb256b5c1bb', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'What is a memory leak?', N'Junior', N'A memory leak occurs when a program allocates memory on the heap but fails to release it back to the system when it is no longer needed. This causes the program to consume increasing amounts of memory over time, potentially leading to a crash.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
