INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'70d7df60-5ae7-4386-81fb-fbb317ff21ef', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'Why is it important to keep the main thread free in Swift applications?', N'Middle', N'The main thread is responsible for handling UI updates and user interactions. If it is blocked by heavy computation or synchronous I/O, the interface becomes unresponsive, leading to a poor user experience and potential watchdog termination.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b0a61b96-fe00-430c-bbaf-fbb330d7c9c2', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'Why is the Read Uncommitted isolation level rarely used in production systems?', N'Senior', N'Read Uncommitted allows dirty reads, where a transaction can see uncommitted data from another concurrent transaction. This leads to data integrity issues if the uncommitted transaction later rolls back, making the system state unpredictable and unreliable for most business applications.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1c783054-935c-4119-a463-fbb9d27cf2f4', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'What are the scalability benefits of Axum''s asynchronous request handling?', N'Senior', N'Axum leverages Rust''s non-blocking async/await model, allowing the runtime to multiplex thousands of concurrent requests across a small, fixed-size thread pool. This model prevents thread starvation during heavy IO operations, ensuring that the application remains responsive under high load without the overhead of thread-per-request models.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
