INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f168e418-01aa-4db9-ad9a-fbce66c94d5c', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'How do Ruby''s ''Constant Lookup'' rules differ from standard lexical scoping, and why is this a frequent source of bugs?', N'Senior', N'Constants in Ruby are resolved based on the nesting of modules and classes, not just the lexical scope of the calling code. This often leads to surprising behavior when constants are accessed across different namespace boundaries, as the search path includes the constant''s lexical scope and the ancestors of the current class.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
