INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'66c213b0-980b-42ab-ab1c-fbcf56e521c0', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'How does Chi support streaming responses effectively?', N'Senior', N'Chi manages streaming by providing access to the underlying http.ResponseWriter, allowing handlers to flush data incrementally. Because it remains compatible with the standard library, it handles long-lived connections, such as those required for Server-Sent Events or WebSockets, without interfering with the streaming process.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'60e05579-ad1b-4bf3-84ee-fbcf785b3b77', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'How does Next.js handle fonts?', N'Intern', N'Next.js includes a built-in font optimization feature that automatically downloads and hosts Google Fonts at build time. This prevents layout shifts and improves performance by avoiding external network requests for fonts.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'caf3da3f-e93b-4ea4-851d-fbd0a8dc5f9a', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What are the available constraint validation DOM properties', N'Intern', N'Below are the list of some of the constraint validation DOM properties available, 1. validity: It provides a list of boolean properties related to the validity of an input element. 2. validationMessage: It displays the message when the validity is false. 3. willValidate: It indicates if an input element will be validated or not.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bc0df291-5914-44f9-8808-fbd63505ca76', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'How does denormalization affect storage usage in Cassandra?', N'Middle', N'Denormalization involves duplicating data across multiple tables to support different query patterns, which increases the total storage footprint. This is a deliberate trade-off where storage space is sacrificed to achieve high performance and low-latency reads.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'eb5a42a3-b7f6-40a3-8d77-fbdb3e2bef05', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'What does it mean for an Axum handler to be ''async''?', N'Intern', N'An async handler means the function can pause its execution while waiting for I/O operations, such as database queries or file access, without blocking the entire thread. This is crucial for handling high-concurrency web services.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fcadf256-5af7-4415-ab31-fbdbcb542812', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'Why is it generally discouraged to store large amounts of data in Actor mailboxes?', N'Middle', N'Storing large amounts of data in mailboxes can lead to significant memory pressure and potential out-of-memory errors. It also increases the latency of message processing, as the actor must traverse a large queue to process messages.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c0c1e215-e434-40d0-b786-fbde3b28ae75', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'What is the benefit of using ''directives'' in Lit-html?', N'Middle', N'Directives are functions that can hook into the rendering process to perform complex DOM manipulations. They allow for optimized, reusable logic like conditional rendering, list rendering, and async data handling.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'60c49695-5680-4bfd-bcf9-fbdffac0e3bf', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'What is the function of the shared_buffers setting?', N'Middle', N'Shared_buffers determines how much memory PostgreSQL uses for caching data blocks in RAM. A well-tuned buffer size reduces the need for slow disk I/O by keeping frequently accessed data in memory.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a9b13ad9-c9f5-45b6-bc0d-fbe1b3b36914', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'What is ''DTO'' in the context of Litestar?', N'Intern', N'DTO stands for Data Transfer Object. In Litestar, DTOs are used to define the structure of data being sent to or received from the API, allowing for a clear separation between internal data models and the external API schema.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3944a246-3844-42be-be4e-fbe20e7316a9', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'How do you differentiate between a transient network glitch and a genuine application error?', N'Middle', N'I look for patterns in the logs; if errors occur across multiple, unrelated services simultaneously, it points to an infrastructure or network issue. If errors are specific to one service or code path and persist regardless of network stability, it is likely an application-level bug.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0964d95c-1eeb-47fb-a0df-fbe344bd46b8', N'9a0e3785-3b73-4abc-ab01-df75bf097dff', N'What is the ''Anti-Corruption Layer'' pattern and when should it be used?', N'Senior', N'This pattern involves creating a translation layer between two systems with different models to prevent the legacy system''s model from leaking into the new system. It is particularly useful when integrating a new microservice with a legacy monolith, ensuring the new service remains clean and domain-focused.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c473a319-aece-4cfb-b4a1-fbe364ab8fca', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'How does Python''s Method Resolution Order (MRO) work in multiple inheritance?', N'Middle', N'Python uses the C3 Linearization algorithm to determine the order in which base classes are searched for methods. This algorithm ensures that the search order is consistent, respects the order of inheritance, and correctly handles complex inheritance hierarchies.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'133e3dda-9a25-4f70-adbb-fbe64c7876bc', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'What is the difference between a Primary Key and a Foreign Key?', N'Fresher', N'A primary key uniquely identifies a record within its own table. A foreign key is a field that links to the primary key of another table, establishing a relationship between the two tables and maintaining referential integrity.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'123bb386-258c-4732-8dd8-fbe73bf5f7c4', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'Explain the purpose of the ''virtual'' keyword in C++ inheritance.', N'Middle', N'The virtual keyword enables dynamic dispatch, allowing a program to call the correct function implementation based on the actual type of the object at runtime. Without it, the compiler uses static binding, which calls the function based on the pointer or reference type rather than the object instance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd67d3374-2f6e-46e9-9807-fbec403d8417', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'What is the benefit of Axum being built on the Tokio runtime?', N'Intern', N'Being built on Tokio allows Axum to leverage highly efficient, non-blocking asynchronous I/O. This enables the server to scale to thousands of concurrent connections with minimal memory overhead.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'83b72250-6f23-470a-8414-fbee760fedb3', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'What are the risks and benefits of using function pointers for polymorphism in C?', N'Senior', N'Function pointers enable a form of dynamic dispatch that allows for decoupled, plugin-based architectures, which is essential for modular C systems. However, they can inhibit compiler optimizations like inlining, as the target of the call may not be known until runtime. Additionally, they introduce indirect branch overhead, which can impact performance in critical loops by increasing branch misprediction penalties.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5e7d04bb-345e-43d9-8596-fbef28fd4232', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'What happens if a route is not found in Fiber?', N'Fresher', N'If no route matches the incoming request, Fiber automatically returns a 404 Not Found status code. You can also define a custom 404 handler to return a specific response format.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'62c26e4b-79c5-4cc6-9c33-fbef3e20b0c0', N'954a0331-deff-4399-b588-96f39fec001d', N'What are the different ways to group form controls?', N'Intern', N'In Angular reactive forms, you group form controls primarily using two classes: FormGroup and FormArray. - FormGroup: Used to group a collection of FormControl, FormGroup, or FormArray instances into a single object, where each child control is identified by a unique key (like properties in an object). It''s suitable for fixed structures like a user''s name and email. - FormArray: Used to group a collection of FormControl, FormGroup, or FormArray instances into an array. It''s suitable for dynamic lists of controls, like a list of phone numbers or addresses, where the number of items can change. You typically create these using the FormBuilder service for convenience: In the template, you bind to these groups using [formGroup] and [formArrayName] directives.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd11ede7a-6080-4796-a9fa-fbefb950cd24', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'How does ''noexcept'' improve performance?', N'Middle', N'The noexcept specifier informs the compiler that a function will not throw exceptions, allowing it to perform aggressive optimizations that would otherwise be unsafe. It also simplifies the logic for move constructors and containers, which can utilize the noexcept guarantee to make operations like reallocation more efficient.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a0ef228a-cdcd-4e91-8999-fbf05ab7333c', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'What is the advantage of Quarkus being ''Kubernetes Native''?', N'Middle', N'Quarkus is designed to generate Kubernetes resources like Deployment files and Knative services automatically during the build. This tight integration ensures that the application is optimized for container orchestration, including support for health checks and resource limits.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'65af0b56-c698-41de-a949-fbf16a6dd838', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'How do you respond to negative feedback during a code review?', N'Junior', N'I view feedback as an opportunity to learn and improve my skills rather than a personal criticism. I thank the reviewer for their input, ask questions to clarify any points I don''t understand, and implement the requested changes efficiently.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6969e594-1673-4962-9f9e-fbf1e58005ee', N'954a0331-deff-4399-b588-96f39fec001d', N'What is NoopZone?', N'Intern', N'Zone is loaded/required by default in Angular applications and it helps Angular to know when to trigger the change detection. This way, it make sures developers focus on application development rather core part of Angular. You can also use Angular without Zone but the change detection need to be implemented on your own and noop zone need to be configured in bootstrap process. Let''s follow the below two steps to remove zone.js, 1. Remove the zone.js import from polyfills.ts. 2. Bootstrap Angular with noop zone in src/main.ts.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0cd83e82-dbe6-452b-a430-fbf36b9e2fc3', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'What is data modeling?', N'Intern', N'Data modeling is the process of creating a visual representation of an entire information system or parts of it to communicate connections between data points. It helps developers and stakeholders understand the requirements and structure of the database before implementation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e76d61b4-3092-4fa0-a128-fbf71194b274', N'a000805c-e41f-42a9-af12-66b45348f77b', N'How does AdonisJS manage global state in a multi-threaded or cluster environment?', N'Middle', N'AdonisJS encourages stateless architecture where global state is stored in external stores like Redis or databases rather than memory. By relying on external persistence, the application remains scalable across multiple processes and nodes without encountering synchronization issues.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'65313a63-0d89-4b12-9122-fbf78f42f76a', N'210c7148-726e-4e8b-bf12-40be36e55130', N'What is the purpose of the ''pin'' module in Rust, and when is it required?', N'Senior', N'Pin is used to guarantee that a value will not be moved in memory, which is critical for self-referential structures. It is most commonly required for asynchronous programming, where futures may contain internal references to their own state that would be invalidated if the structure were moved.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a012af19-c29f-4192-8a2f-fbf7bc47e5a8', N'91fb4eff-ac6a-48b9-8ba4-2bbdf6237429', N'What are the risks of ''Alert Fatigue'' and how can it be mitigated?', N'Senior', N'Alert fatigue occurs when operators are overwhelmed by non-actionable or redundant alerts, leading them to ignore critical notifications. Mitigation involves implementing intelligent alerting thresholds, suppressing noisy alerts, and ensuring every alert has a clear, documented runbook for resolution.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'087c58f7-4b25-41a3-b1f5-fbf8cb9ac647', N'55404b9c-91b6-4b62-9dc7-63248e8ea1df', N'Explain the role of ''Partitioning'' (Sharding) keys in a distributed database.', N'Senior', N'A partition key determines how data is distributed across different nodes. Choosing an effective key is critical to avoid ''hot shards,'' where a single node receives disproportionately high traffic, which would create a bottleneck and undermine the benefits of sharding.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bc1ed510-dbc1-4c15-9184-fbfc0304c482', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'What are the advantages of React over Vue.js?', N'Intern', N'React has the following advantages over Vue.js: 1. Gives more flexibility in large apps developing. 2. Easier to test. 3. Suitable for mobile apps creating. 4. More information and solutions available. Note: The above list of advantages are purely opinionated and it vary based on the professional experience. But they are helpful as base parameters.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b59a0198-a551-4721-83ef-fbfdfd802e2d', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'Why is it important to define styles as a static array in Lit?', N'Middle', N'Defining styles as a static array allows Lit to optimize the creation of ''CSSStyleSheet'' objects. By sharing these sheets across all instances of a component, Lit significantly reduces memory usage and improves style application performance compared to injecting individual style tags for every instance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c5c7b806-0a74-4af7-b820-fbfe701c695f', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'What are ''implicits'' in Scala?', N'Intern', N'Implicits are a language feature that allows the compiler to automatically provide certain arguments or conversions to a function. They help reduce boilerplate code and allow for the extension of existing types without modifying their original definition.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e537b551-3ce2-4d86-a240-fbfe9b72dc8c', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'What is the primary architectural drawback of using jQuery''s .each() method over native array prototypes?', N'Senior', N'The .each() method is an abstraction that adds unnecessary function call overhead compared to native array methods like forEach or map. Additionally, native methods provide better type safety and are better optimized by modern JavaScript engines for iteration performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'602d36a1-78e3-4671-8870-fc01d5e19ddb', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'What is a header file in C and why do we use them?', N'Intern', N'A header file is a file containing declarations of functions, macros, and data types that can be shared across multiple source files. They allow programmers to organize code logically and maintain consistency by providing a standard interface for accessing library features.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4196d2c7-fa73-4a6a-986e-fc02cae89fe5', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'Why is the call stack limited in size, and what happens when it exceeds that limit?', N'Middle', N'The call stack has a finite size because it must store all active function execution contexts. When a function calls itself indefinitely or recurses too deeply, it causes a stack overflow error, causing the execution to halt to prevent memory corruption.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c7b708a4-9d63-4b49-93da-fc042d40a97a', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'What are Symfony Constraints and how are they used?', N'Junior', N'Constraints are validation rules applied to object properties, such as ensuring a field is not empty or matches a specific format. They are defined in the entity or form class to ensure that data meets business requirements before being persisted to the database.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9c731528-ae6d-4b70-b359-fc06110aa7da', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'What is the purpose of the ''importlib'' module?', N'Middle', N'The ''importlib'' module provides a programmatic interface to the import machinery, allowing developers to import modules dynamically at runtime. It is essential for building plugin systems, testing frameworks, or tools that need to load code based on external configuration rather than static imports.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4b6756ef-7dd0-4f9d-8384-fc086d625c1b', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'Describe the Layering mechanism in CSS and how it relates to the browser''s graphics pipeline.', N'Senior', N'Browsers create layers for elements with specific properties like 3D transforms, opacity, or canvas elements, which are then composited on the GPU. Using the ''will-change'' property hints to the browser to promote an element to a new layer, though overusing this can lead to excessive memory consumption.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'27107603-225b-4342-a415-fc0c3a8b085a', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'How does Symfony handle different request formats (JSON, XML, HTML) transparently?', N'Senior', N'Symfony uses Request Matchers and Content-Type negotiation to identify the requested format and automatically route the response through appropriate encoders. This allows developers to write controller logic that remains format-agnostic, improving maintainability for APIs and traditional web pages alike.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4792768d-8b13-4bd3-b0fc-fc0ca35a2fc5', N'a000805c-e41f-42a9-af12-66b45348f77b', N'Explain the architectural trade-offs of the AdonisJS ''Service Provider'' pattern.', N'Senior', N'The Service Provider pattern decouples object creation from consumption, allowing for complex configuration before injection. The trade-off is an increased abstraction layer which can make the initial request flow harder to trace, but it significantly improves testability and the ability to swap implementations without modifying consuming services.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5bf029be-38fe-45ee-b67b-fc0d753de930', N'55404b9c-91b6-4b62-9dc7-63248e8ea1df', N'What is the trade-off between consistency and availability in the context of the CAP theorem?', N'Middle', N'In a distributed system, you cannot simultaneously guarantee perfect consistency and total availability during a network partition. You must choose whether to return the most up-to-date data, potentially failing if nodes are unreachable, or return potentially stale data to ensure the system remains responsive.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd66678ca-2bcc-4b84-ac31-fc117b30cab8', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'How does Astro handle page routing?', N'Intern', N'Astro uses file-based routing. This means that every file placed inside the project''s pages directory automatically becomes a route on your website based on its file path.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'35276f93-8d56-48bc-9ec9-fc12360e41f0', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'Explain the difference between CSS grid and Flexbox.', N'Junior', N'Flexbox is designed for one-dimensional layouts, focusing on distributing space along a single row or column. Grid is a two-dimensional system that manages both rows and columns simultaneously, making it better for complex page structures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
