INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6418fef8-2c37-4465-ad70-fc2171f5647b', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'Explain the internal mechanism of Spring Boot''s Starter POMs and their impact on dependency management.', N'Senior', N'Starters act as opinionated dependency descriptors that aggregate common libraries required for specific use cases. They simplify dependency management by enforcing version compatibility through the parent POM, effectively reducing ''dependency hell'' and ensuring that transitively included libraries are verified for stability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e31c8f13-afb3-496a-b4d1-fc217c6efaa0', N'074508f7-35bd-405f-8cc6-b41377b2d92c', N'How does a broker handle backpressure when producer rates exceed consumer processing capacity?', N'Senior', N'Brokers manage backpressure by either buffering messages in memory or on disk, applying rate limiting to producers, or triggering consumer auto-scaling. If buffers fill up, the system must decide between dropping older messages, rejecting new writes, or exerting pressure back to the upstream service.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
