INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c547f20f-11ec-42b1-9b65-fc2dfc6fd9a2', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'How does Alpine ensure security when evaluating expressions?', N'Middle', N'Alpine uses the Function constructor to evaluate expressions, which is a common pattern in template-based frameworks. However, developers should avoid using user-provided input in expressions to prevent potential cross-site scripting vulnerabilities, as Alpine evaluates these as live JavaScript.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c18286c4-775f-47c1-8c06-fc2f41ee1c87', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'What is the purpose of the @state decorator?', N'Intern', N'The @state decorator is used to define internal reactive properties that should not be exposed as public attributes to the outside world. Like @property, it triggers a re-render when the state changes, but it is intended for private component logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a485d339-59df-402d-9503-fc30efc45639', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'How does Ruby''s garbage collection work at a high level?', N'Junior', N'Ruby uses a mark-and-sweep garbage collection algorithm. It identifies objects that are no longer reachable by the program and reclaims their memory to keep the application efficient.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'aab68398-3dee-4b95-86f2-fc321a020264', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'What are the performance implications of having too many indexes on a table?', N'Middle', N'Every index must be updated whenever an INSERT, UPDATE, or DELETE is performed on the table. Excessive indexing increases write latency, consumes extra disk space, and adds significant overhead to the autovacuum process, which may degrade overall database performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ba54fa70-70c2-47af-8294-fc33204770dc', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'What is a View in the context of ASP.NET Core MVC?', N'Intern', N'A View is a file that contains the user interface logic of the application. It is responsible for rendering the data provided by the controller into an HTML format that can be displayed in the user''s browser.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'76847754-afc5-4d76-ad26-fc3450467fe9', N'210c7148-726e-4e8b-bf12-40be36e55130', N'What does the concept of ownership mean in Rust?', N'Intern', N'Ownership is a set of rules that governs how memory is managed in Rust. Every value in Rust has a variable that is called its owner, and there can only be one owner at a time. When the owner goes out of scope, the memory is automatically reclaimed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'06bb344c-3632-494b-96af-fc352b864ded', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'Why is the C ''const'' qualifier not necessarily a guarantee of immutability?', N'Senior', N'The ''const'' qualifier merely tells the compiler that the identifier should not be modified through that pointer or reference. It does not prevent the underlying memory from being changed via a non-const pointer or through external hardware, and it does not place the data in read-only memory by default.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'42c279e9-557c-4261-aeef-fc3743c8b867', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'What is the difference between ''List'' and ''Set'' interfaces?', N'Junior', N'The List interface maintains an ordered collection and allows duplicate elements. The Set interface does not allow duplicate elements and does not guarantee a specific order of elements.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd5683589-098c-472c-951f-fc37c8c93925', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'Why is proper error handling critical in Node.js compared to multi-threaded environments like Java?', N'Senior', N'In Node.js, an unhandled exception bubbles up to the process level and crashes the entire application. Unlike multi-threaded environments where a single thread might crash leaving others running, a Node.js process crash kills all active connections. Robust error handling and process supervisors like PM2 are essential for uptime.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8dfe5151-f13c-4051-80c3-fc3bbf339dc4', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'What are the basic data types in Ruby?', N'Intern', N'Ruby is claimed to treat "everything as an object". But like many languages, Ruby has both primitive and abstract data types. Primitive Types - Numbers: - Integers can be of any size (limited by system memory). - Floating-Point numbers follow the IEEE 754 standard. - Booleans: Represented by true and false. - Symbols: Unique, immutable identifiers represented with a : followed by a name. Abstract Types - Strings: Unicode with multiple encodings. - Arrays: Ordered, indexed collections. - Hashes: Key-value pairs, also known as dictionaries or maps in other languages. Others assimilated Primitive Types Ruby, despite its philosophy of being completely object-oriented, has some underlying primitive paradigms due to its performance concerns and efficiency considerations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'db797d40-ddae-479e-8458-fc3bc66ff435', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'What is a ''Connection'' (conn) object in Phoenix?', N'Junior', N'The conn struct represents the entire HTTP request and response cycle. As it passes through various plugs, information is added to or modified within this struct, providing a unified way to access request data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd7fcbf3d-9e3c-4132-868b-fc3d88fa1662', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'How does DynamoDB ensure high availability?', N'Fresher', N'DynamoDB automatically replicates data across multiple physical locations, known as Availability Zones, within an AWS region. This ensures that the database remains available even if one of the locations experiences a failure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
