INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd4e8942a-fc7c-49ea-abf6-fc46cf995004', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'What is the purpose of the Isolation property?', N'Intern', N'Isolation ensures that concurrent transactions do not interfere with each other. It allows multiple users to perform operations simultaneously without the intermediate results of one transaction being visible to others until it is finalized.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'67693631-1d82-4b43-b1a2-fc4998a117fb', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'How does Swift''s ''Result'' type improve error handling over traditional exception propagation?', N'Senior', N'The Result type treats errors as first-class values that can be passed around, returned, or stored, rather than relying on the side-effect-heavy mechanism of stack unwinding. It forces explicit handling of failure states at the type level, reducing the risk of unhandled errors and making asynchronous error propagation more robust. This paradigm aligns better with functional programming patterns and clarifies the flow of control.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5ca741c1-3800-4f23-a6d3-fc4ab33b9a60', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'What is a Kernel Event in Symfony?', N'Intern', N'A Kernel Event is a hook that triggers at specific points during the request-response cycle, such as when a request is received or an exception occurs. It allows developers to inject custom logic globally without modifying the core framework code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8aaebc11-ea1f-4b33-bc42-fc4b8a6984f6', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'What is the difference between Spring Data JPA''s save() and saveAndFlush() methods?', N'Middle', N'The save() method persists an entity but does not necessarily execute the SQL INSERT or UPDATE immediately, as it relies on the EntityManager''s synchronization. saveAndFlush() forces the synchronization of the persistence context with the database immediately, which is useful when you need to trigger database-level constraints or triggers before proceeding.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'910844e8-72b5-4191-91ec-fc4bff151c47', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'How does multi-version concurrency control (MVCC) work in NoSQL?', N'Middle', N'MVCC allows multiple versions of a document to exist simultaneously, enabling non-blocking reads even when a write is in progress. It is a common technique for maintaining consistency in distributed environments without forcing locks that degrade performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c6212bb2-8bf1-40d3-8996-fc4c0ac28221', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'Explain the significance of the Memory Barrier (Fence) in the context of Java concurrency.', N'Senior', N'Memory barriers are hardware-level instructions that enforce ordering constraints on memory operations, preventing the CPU or compiler from reordering reads and writes across the barrier. In Java, volatile variables and synchronization blocks implicitly issue these fences to ensure that memory updates are visible to other threads according to the happens-before guarantee.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd2255cea-2b10-423d-9aaf-fc4c8fbe8f2a', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'Explain the concept of Layering in CSS (at-layer) and its effect on conflict resolution.', N'Senior', N'The at-layer rule allows developers to explicitly define the order of cascading layers, providing a way to manage style conflicts without relying solely on selector specificity. This is particularly useful for overriding external library styles or implementing complex design systems where base styles need to be easily overridden by component-specific styles.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'991aaf6a-0f4b-4624-9406-fc4eaa348a54', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'How does Lit handle array updates in templates?', N'Fresher', N'Lit treats arrays as standard JavaScript objects. When rendering lists, you can use the map function within the template to generate elements, and Lit will efficiently update only the items that have changed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ae94459b-af79-4908-ab4a-fc54f2eaf9ad', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'What is ''lazy execution'' in Qwik?', N'Junior', N'Lazy execution is the practice of delaying the execution of JavaScript until it is absolutely necessary. Qwik accomplishes this by splitting code into small chunks that only run when the user interacts with an element.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'59ff75ed-e8d3-4116-8ecc-fc55b82e2d62', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'In what scenarios would you choose Preact over React for a large-scale enterprise application?', N'Senior', N'Preact is preferable when the primary constraints are bundle size, initial load time, and memory usage on low-end devices. If an application relies heavily on complex third-party React libraries that aren''t compatible with the compat layer, or requires advanced concurrent rendering features, React remains the superior choice.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
