INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd82300da-e707-4cd1-bc96-fc562f6fe191', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'How do you approach the decision to build versus buy a component for a system?', N'Middle', N'Build if the component provides a unique competitive advantage or core business value that is not available in the market. Buy or use open-source if the component is a commodity, such as authentication, logging, or database management, to save development time and maintenance effort.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'81e5e327-ec9d-4fb3-b07b-fc570e8fc29a', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'How does Ember''s ''Addon'' system facilitate ecosystem scalability?', N'Senior', N'Addons allow for reusable packages that can hook into the build pipeline, inject services, or provide components. By standardizing the integration of external dependencies, Ember ensures that third-party code adheres to the framework''s architecture, reducing the risk of conflicts and installation friction.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'eb44a071-5533-4c80-979b-fc5adf3bbc05', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'How do you approach testing in a microservices environment compared to a monolith?', N'Middle', N'In microservices, I emphasize contract testing to ensure services can communicate correctly without relying on full integration tests which are brittle and slow. I still maintain unit tests for business logic, but I use consumer-driven contracts to catch breaking changes early in the CI/CD pipeline.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6275df39-d845-4786-882e-fc5c0c8159b9', N'fcd5873e-c89a-47d6-bb4c-c60b57c2ede1', N'What is the purpose of the ''Outbox Pattern'' in microservices?', N'Senior', N'The outbox pattern solves the dual-write problem by saving an event to a local database table as part of the primary business transaction. A separate relay process then polls this table to publish the event to a message broker, ensuring atomicity between database updates and event emission.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3d2592ce-e8c3-4743-a844-fc5c10e846b3', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'How does Alpine.js handle nested components?', N'Fresher', N'Alpine.js components can be nested within each other. Child components can access the data of their parent components through the scope chain, allowing for a hierarchical organization of logic and state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
