INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5b37a46f-016b-4122-ab47-fc71103c7be6', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'Why is vectorization preferred over explicit loops in R, and what are its performance implications?', N'Middle', N'Vectorization leverages highly optimized C and Fortran code under the hood, pushing the iteration process into compiled routines rather than executing it within the R interpreter. This significantly reduces the overhead of the R interpreter''s dynamic dispatch and loop management. Consequently, vectorized operations are generally orders of magnitude faster and result in more concise, readable code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
