INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2423d8e9-45e0-4cd2-9d8e-fc8659afe3fd', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'What happens if a request guard fails?', N'Junior', N'If a request guard fails, the request is forwarded to the next matching route or rejected entirely. The handler associated with the failed guard will not be executed, ensuring that the logic inside the handler only runs under valid conditions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2608b2b5-91be-4fc7-973f-fc86c4b23c40', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'What are the primary differences between hardware-level atomics and software-level synchronization in the JVM?', N'Senior', N'Hardware-level atomics use processor-specific instructions like Compare-And-Swap (CAS) to perform lock-free operations, which are highly efficient for low-contention scenarios. Software-level synchronization uses intrinsic locks or ReentrantLocks, which provide stronger memory consistency guarantees but incur overhead due to context switching and thread blocking when contention is high.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cef05b69-814a-46bc-9a2b-fc892712dc5b', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'How does Ecto''s ''Multi'' pattern facilitate data integrity in complex transactional operations?', N'Senior', N'Multi allows developers to bundle multiple database operations into a single atomic transaction, ensuring that either all operations succeed or none are committed. This is critical for maintaining consistency in distributed systems where partial updates could lead to corrupted application state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0545187a-8bfd-4c5f-ba1f-fc89437f43fc', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'What are the advantages of using FastAPI''s ''Depends'' over global variables?', N'Middle', N'Dependency injection with ''Depends'' provides a clean, modular way to manage state and resources without polluting the global namespace. It improves testability because you can override any dependency at the application or request level during testing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3007d9dd-5703-4509-b089-fc895fd6db1d', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'Does SolidJS use classes for components?', N'Intern', N'No, SolidJS uses functional components exclusively. This approach is preferred for its simplicity and better compatibility with the reactive primitive system.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'996b201d-b0ce-49d6-b90d-fc8961d1e21f', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'What is the middleware feature in Nuxt?', N'Intern', N'Middleware allows you to run custom code before navigating to a specific route. It is commonly used for tasks like checking if a user is authenticated or redirecting users to a login page if they do not have the required permissions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e699832a-ae43-4fa9-a937-fc8a398a9755', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'How do Utility Types like ''Partial'' and ''Pick'' assist in development?', N'Middle', N'Utility types provide ready-made transformations to existing types without needing to define new ones manually. ''Partial'' makes all properties optional, while ''Pick'' creates a new type by selecting a subset of keys from an existing one, improving code reuse.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'302a8776-a525-4140-b406-fc8afe736746', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What is the primary benefit of using TypeScript over JavaScript in a frontend project?', N'Junior', N'TypeScript provides static type checking, which allows developers to catch errors during development rather than at runtime. It improves code maintainability and readability by explicitly defining the shapes of objects and the types of function parameters.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'24e84121-19d0-459a-883b-fc8bfa8c6e6b', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is isNaN?', N'Intern', N'The isNaN() function determines whether a value is NaN ( Not a Number ) or not. This function returns true if the value equates to NaN. The isNaN() method converts the value to a number before testing it. Example: &#9885; Try this example on CodeSandbox', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0d8672cc-624d-4116-9fb3-fc8cc25fbb4e', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'How do ''ParamConverters'' simplify controller logic?', N'Middle', N'ParamConverters automatically fetch database records based on request parameters and inject them directly into controller methods. This removes the need to manually perform database lookups inside the controller, keeping the controller focused on request handling rather than data retrieval.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'650cab0e-7341-4221-94a1-fc8d4ad96fed', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'What is the difference between a Route and a Component in Remix?', N'Fresher', N'A route is a specific URL path associated with a file, while a component is the UI element rendered by that route. In Remix, a single route file often exports the component, loader, and action.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fd924149-fd17-41dc-8455-fc8ec0acd4ab', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'What is the role of past project data in your current estimation process?', N'Junior', N'I look at historical velocity or similar past tasks to identify patterns in how long certain types of work typically take. This provides a data-driven baseline that helps me avoid repeating previous estimation mistakes and sets more realistic expectations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'14944f2e-9e62-4137-92f0-fc92396a5177', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'What are Middleware in NestJS and when should they be used?', N'Junior', N'Middleware are functions called before the route handler, providing access to the request and response objects. They are typically used for cross-cutting concerns like logging, authentication checks, or modifying request headers before they reach the main application logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b7cc5c59-6b8e-415f-9300-fc93535423a1', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'What data types does DynamoDB support?', N'Fresher', N'DynamoDB supports scalar types like strings, numbers, and booleans, as well as complex document types like lists and maps. It also supports set types for collections of unique values.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'29f36495-ec8f-4132-a487-fc961c4c517a', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'What is contextual selector?', N'Intern', N'A contextual selector targets an element only when it appears within a specific context (ancestor). It''s a string of selectors separated by whitespace, where only the last element is styled — but only if it matches the specified ancestral path. Example: This styles elements only when they are descendants of a — not all elements on the page.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'889b1b85-9e49-4ed4-85ac-fc9689a3ccfe', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'Explain the benefit of Tailwind''s ''group'' and ''peer'' modifiers.', N'Middle', N'These modifiers allow for styling elements based on the state of a parent or sibling. This enables complex interactive states, like changing the color of an icon when its parent container is hovered, without requiring custom JavaScript or complex CSS selectors.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9daee112-a675-4e4a-baf3-fc9d948de62b', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'Explain the performance implications of using CSS containment properties.', N'Senior', N'The contain property allows developers to isolate subtrees of the DOM, informing the browser that changes within a specific element do not affect the rest of the page. This significantly reduces the scope of recalculating styles and layout, thereby improving rendering performance for complex applications.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e079795c-d3de-4fa2-9028-fc9efc868d76', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'How does R''s ''promise'' object relate to lazy evaluation?', N'Middle', N'A promise is a data structure in R that contains the expression to be evaluated, the environment where it should be evaluated, and the resulting value once calculated. It acts as a placeholder that delays computation until the value is actually required by the code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6c7f68c6-7d68-4300-aaae-fca0041eccdb', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'How does the garbage collector in Go balance latency and throughput?', N'Middle', N'The Go garbage collector is designed as a concurrent mark-and-sweep collector that prioritizes low latency by performing most of its work simultaneously with the application. This approach minimizes ''stop-the-world'' pauses, though it requires slightly more CPU overhead compared to stop-the-world collectors.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'85bcc08e-7e12-4efe-a243-fca02fdf0349', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'What is the purpose of the ''sealed'' modifier on a class?', N'Middle', N'The ''sealed'' modifier prevents a class from being inherited by other classes. This is used to define a closed design or to improve performance slightly by allowing the compiler to perform devirtualization optimizations since it knows the object cannot be overridden.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'54d9ab23-2610-4e53-ba97-fca054da8706', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'How does the C# runtime handle interface dispatch compared to class inheritance?', N'Senior', N'Interface dispatch is generally slower than virtual class inheritance because it requires an interface lookup table search at runtime to find the method implementation. Modern JIT compilers attempt to inline these calls through devirtualization, but the lookup overhead remains a factor in extremely tight loops.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'44c3fa30-2a4b-47e2-80da-fca0943c7adc', N'a2838158-7305-480a-b22b-4dc35776b400', N'What is the ''split-brain'' scenario in a distributed cluster?', N'Middle', N'A split-brain occurs when a network partition causes a cluster to divide into two or more independent groups, each believing it is the sole authority. This leads to conflicting data writes and state inconsistencies that require consensus algorithms to resolve.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'84e6946d-3a9d-4d1f-865a-fca33b926b8e', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'How does Ember manage the browser''s history and URL state?', N'Middle', N'The Ember router synchronizes the internal state of the application with the browser''s URL using the Location API. It handles transitions, query parameters, and back-button navigation by mapping URL changes to specific route handlers, ensuring that the application state remains bookmarkable and shareable.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2e8d61c7-1dfb-4a16-adb0-fca3f806b11c', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'When designing a microservice, what factors influence your decision to use synchronous versus asynchronous communication?', N'Middle', N'I choose synchronous communication, such as REST or gRPC, when immediate feedback is required for a user action. I opt for asynchronous communication, like message queues or event buses, when the operation can be decoupled, requires high availability during downstream service outages, or involves long-running background tasks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c3dc4dd8-13dc-4ea0-9ad0-fca58a8bf560', N'f2e963ff-7635-4429-a389-4d92535fb972', N'What is the difference between block-level and inline elements?', N'Intern', N'Block-level elements always start on a new line and occupy the full width available to them, like a division or a paragraph. Inline elements do not start on a new line and only occupy as much width as their content requires, like a span or a link.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bd97fbdd-bd20-44ea-99bd-fca5a65b13b3', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'What architectural risks arise when building deep component hierarchies in Alpine.js?', N'Senior', N'Deeply nested components can lead to complex scoping chains and potential performance degradation during scope lookup, as Alpine must traverse the DOM tree to resolve variable references. Managing communication between distant nodes becomes difficult, often leading to over-reliance on global stores. This can degrade maintainability and make the data flow harder to trace compared to frameworks with explicit state-passing mechanisms.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'22700769-f7d7-442c-a578-fca5ae13ca1b', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'Discuss the implications of ''Transaction Isolation Levels'' on concurrency and data anomalies.', N'Senior', N'Higher isolation levels like Serializable prevent all anomalies but reduce concurrency by increasing lock contention. Lower levels like Read Committed improve throughput by allowing more simultaneous transactions, but they risk anomalies such as non-repeatable reads or phantoms.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a6360aed-ecf5-4734-9ba8-fca5e958f19c', N'55404b9c-91b6-4b62-9dc7-63248e8ea1df', N'What is the primary benefit of implementing a cache in a scalable system?', N'Middle', N'Caching stores frequently accessed data in memory, which significantly reduces latency and lowers the load on primary data stores. This allows the system to handle a higher volume of requests without needing to scale the backend database infrastructure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a27580c7-86a3-4836-bf02-fcaa9f2ecf76', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is a unary function', N'Intern', N'A unary function (also known as a monadic function) is a function that accepts exactly one argument. The term "unary" simply refers to the function''s arity—the number of arguments it takes. Let us take an example of unary function, In this example: - unaryFunction takes a single parameter a, making it a unary function. - It performs a simple operation: adding 10 to the input and printing the result.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dd68a92f-b326-4c6d-b83b-fcacdb5cd9e9', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'How does Ember''s ''Model'' hook support data pre-fetching and performance?', N'Senior', N'By fetching data before the component renders, the router ensures that the UI remains responsive and doesn''t flicker with loading states. This design promotes a pattern where the application is in a stable, ready state before the user sees the view, contributing to a perceived higher performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'90583c83-663d-4dd5-8d3b-fcae7b50ca08', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'What is the significance of the ASGI standard for FastAPI''s deployment strategy?', N'Senior', N'As an ASGI framework, FastAPI supports long-lived connections such as WebSockets and server-sent events, which are not supported by WSGI. This enables the development of real-time applications and allows deployment on highly concurrent servers like Uvicorn or Daphne.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'26fdfb0e-a0dc-405d-b0ad-fcaf514cbd5f', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'How does Micronaut handle security within its non-blocking architecture?', N'Senior', N'Micronaut Security is designed to work with reactive streams, allowing authentication and authorization checks to occur asynchronously. It provides built-in support for standard protocols like JWT and OAuth 2.0, ensuring that security headers can be validated without blocking the main request processing thread.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7da8df3d-24d1-499a-99de-fcb214e247f3', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'Why does Vite pre-bundle dependencies?', N'Junior', N'Vite pre-bundles dependencies to convert CommonJS or UMD modules into ESM and to reduce the number of HTTP requests for libraries with many internal files. This optimization ensures the browser does not get overwhelmed by hundreds of network requests during development.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5383fba7-031d-434c-ae62-fcb56432e044', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'What are the architectural considerations for implementing a micro-frontend strategy using Next.js?', N'Senior', N'Implementing micro-frontends in Next.js often involves using Module Federation or independent deployments linked via a common shell. The primary challenge is maintaining shared design systems and state while ensuring that bundle size remains optimized and dependencies do not conflict.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'650f7cf7-ba73-40a1-b921-fcbc7184683f', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'How does Chi accommodate complex path patterns like regex or wildcards?', N'Senior', N'Chi supports pattern matching within route definitions, allowing for flexible path segments that can be validated via regular expressions. This moves the validation logic closer to the routing layer, ensuring that handlers only receive requests that meet specific path criteria.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b03ca6d0-8509-4f90-89af-fcbdb3eacbc9', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'When an engineering team consistently underestimates tasks, how do you diagnose and address the root cause?', N'Senior', N'I analyze the delta between planned and actual velocity to identify if the issue stems from poor task decomposition, hidden technical debt, or external interruptions. I address this by implementing stricter definition-of-ready criteria and ensuring that non-functional requirements are explicitly included in estimation sessions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'413e741e-cc32-42d4-934e-fcc0e22feea3', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'What is the technical significance of Kotlin''s ''strict'' null-safety in interop scenarios?', N'Senior', N'Strict null safety prevents common crashes by treating Java types as potentially nullable unless explicitly annotated. This forces the developer to acknowledge the lack of guarantees from Java APIs, which shifts the burden of validation to the point of entry and improves overall system robustness.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd037a688-9c23-41d2-9f09-fcc14a2c0f33', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'You are tasked with choosing between a relational database and a NoSQL database for a new application. What factors would guide your decision-making process?', N'Junior', N'I would evaluate the structure of the data and the necessity of ACID compliance. If the data is highly structured with complex relationships and requires strict consistency, a relational database is the better choice. Conversely, if the application requires high scalability, rapid development with evolving schemas, or handles large volumes of unstructured data, a NoSQL solution would be more appropriate.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1dc56c92-bb9b-4d9d-b1ef-fcc1573de3f7', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'How does Preact''s lack of a synthetic event system impact cross-browser consistency?', N'Senior', N'Preact relies on native browser events rather than a synthetic wrapper, which reduces the library''s size and complexity. While this improves performance, developers must be more aware of browser-specific event quirks, as Preact does not normalize these differences as extensively as React''s synthetic event system.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'19800c5b-0cc7-4c67-87ab-fcc43741f8a7', N'a000805c-e41f-42a9-af12-66b45348f77b', N'What is the ''Seeders'' feature in AdonisJS?', N'Intern', N'Seeders allow you to populate your database with initial or dummy data. This is particularly useful for setting up a development environment or testing the application with a populated dataset.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e0511019-c9ce-4b76-a346-fccab95a1926', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'What architectural considerations are necessary when scaling Phoenix applications across different geographic regions?', N'Senior', N'Scaling globally requires careful management of data locality and cluster latency. Since BEAM nodes communicate frequently, high-latency links can degrade performance, so developers often use regional clusters and a global data replication layer (like global Postgres or CRDTs) to minimize cross-region chatter.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1ab5deef-5f72-411b-91af-fccbcf7e73d6', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'Why is SolidJS considered ''fine-grained''?', N'Intern', N'It is called fine-grained because the framework knows exactly which DOM node corresponds to which piece of data. Updates are applied directly to those specific nodes rather than comparing a whole virtual tree, making it highly efficient.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'80e70d50-9ea5-4e73-a2b2-fccd46142369', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What is a structural type system?', N'Intern', N'TypeScript uses a structural type system, which means that type compatibility is determined by the members of the type rather than its explicit name. If two objects have the same shape, they are considered to be of the same type.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dd0bbe22-8299-4298-877f-fcce42bccdfb', N'210c7148-726e-4e8b-bf12-40be36e55130', N'What is the role of ''Cargo'' in Rust development?', N'Fresher', N'Cargo is Rust''s build system and package manager. It handles tasks such as downloading dependencies, compiling packages, creating documentation, and running tests, streamlining the entire development lifecycle.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f34320ba-5de7-4f32-96b4-fcd5fc9d3785', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'Why is it generally discouraged to use synchronous methods in Node.js?', N'Middle', N'Synchronous methods block the entire event loop, preventing the server from handling any other incoming requests until the operation finishes. This leads to poor performance and high latency, as the application becomes unresponsive during the execution of synchronous calls.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b3a765da-7aa6-4d07-95a0-fcd6400afa2d', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'What are Phoenix Views and Templates?', N'Intern', N'Views are modules that prepare data for the UI, while templates are files containing the structure and markup of the response. Together, they allow the developer to separate the logic of data formatting from the actual presentation layer.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2dfc11d3-5396-42af-b273-fcd64a7a8c97', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is debouncing?', N'Intern', N'Debouncing is a programming technique used to limit how often a function is executed. Specifically, it ensures that a function is only triggered after a certain amount of time has passed since it was last invoked. This prevents unnecessary or excessive function calls, which can help optimize performance and reduce unnecessary CPU usage or API requests. For example, when a user types in a search box, you typically want to wait until they’ve finished typing before fetching suggestions. Without debouncing, an API call would be triggered on every keystroke, potentially causing performance issues. With debouncing, the function call is postponed until the user stops typing for a specified period (e.g., 300ms). If the user types again before this time elapses, the timer resets.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ee0008bb-b9a8-42cd-89ff-fcd9711f4e6e', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'Does Hono support TypeScript, and why is that beneficial?', N'Fresher', N'Yes, Hono is built with TypeScript and provides excellent type safety out of the box. This is beneficial because it allows developers to catch errors during development, provides better autocomplete in IDEs, and makes it easier to maintain and understand complex API structures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2e11bc19-0480-44a9-929e-fcda0929dbd3', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'What is the purpose of the ''through'' argument in a ManyToManyField?', N'Middle', N'The ''through'' argument allows you to specify a custom intermediary model to store additional data about the relationship, such as a timestamp, a role, or a status. This is necessary when the relationship itself needs to hold properties beyond just the two foreign keys.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'851eeead-8f78-43ae-b60a-fcddcfe43206', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'Why is it often better to use a dedicated Message Broker over NestJS''s built-in TCP transport?', N'Senior', N'The built-in TCP transport is suitable for simple, internal communication but lacks the robustness of enterprise brokers like RabbitMQ or Kafka. Brokers provide persistent messaging, load balancing, consumer groups, and replayability, which are essential for reliable, asynchronous communication in high-scale distributed systems.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'320df2a6-1a06-45ff-9d12-fcde1418e81f', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'Explain the trade-off between ''Fail Fast'' and ''Robust Error Handling'' in a system.', N'Junior', N'Failing fast allows you to identify issues immediately during development and testing, preventing the propagation of corrupted states. Robust error handling ensures the system remains available and provides a better user experience, though it can sometimes mask underlying issues by suppressing errors.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'12d27326-f2fa-4c31-a740-fcde95601cdd', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'How does Django''s transaction management work, and why is it important for data integrity?', N'Middle', N'Django''s transaction management ensures that a series of database operations either all succeed or all fail, preventing partial updates that could corrupt data. By using the transaction.atomic decorator or context manager, you maintain atomicity, which is crucial for operations involving multiple related database tables.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'17ed5874-8667-4ec0-b436-fcdf0e30c5d4', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What does the ''infer'' keyword do within Conditional Types?', N'Middle', N'The ''infer'' keyword allows you to extract or ''capture'' a type variable from a specific part of another type, such as the return type of a function. It is essential for creating advanced type utilities that deconstruct and analyze existing type signatures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
