INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5ddbe198-5003-4575-b088-fce6c7dd77d1', N'954a0331-deff-4399-b588-96f39fec001d', N'Explain the purpose of the Angular zone.js library.', N'Middle', N'Zone.js patches asynchronous browser APIs like setTimeout and XHR to notify Angular when an asynchronous operation completes. This allows the framework to automatically trigger change detection without the developer manually calling update methods.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a7312780-1f47-4f19-a733-fceb60a3536f', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'Discuss the performance impact of using Streams versus simple Future-based asynchronous programming.', N'Senior', N'Futures represent a single value returned in the future, while Streams represent a sequence of asynchronous events. Using Streams for continuous event data avoids the overhead of creating numerous Future objects, but they require careful management to prevent memory leaks through unclosed subscriptions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
