INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'89c7bd33-5849-4ad1-af4e-fcfa4558679a', N'24c74bdc-c63e-4370-b1ac-bd560cb834d6', N'How do webhooks differ from traditional API polling?', N'Middle', N'Webhooks push data to the client as soon as an event occurs, which is much more efficient than polling. Polling requires the client to repeatedly ask for updates, which wastes network bandwidth and processing power on both sides.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3bbc35ac-ecf3-4065-935c-fd0073ece5d8', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'Explain the concept of ''Hydration Mismatch'' and its impact on SEO.', N'Senior', N'Hydration mismatch occurs when the server-generated HTML differs from the client-side initial render, often due to non-deterministic data or browser-specific APIs being accessed during SSR. This forces the browser to discard the server-rendered DOM and rebuild it from scratch, causing layout shifts and potentially penalizing SEO rankings due to poor performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ed604142-6024-442a-b272-fd022956efbf', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'Explain how Micronaut''s HTTP server leverages Netty compared to traditional servlet-based containers.', N'Senior', N'Micronaut uses an event-loop-based non-blocking architecture powered by Netty, allowing it to handle many concurrent connections with a small number of threads. Traditional servlet containers often follow a thread-per-request model, which can lead to thread exhaustion and higher memory overhead under high concurrency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ea8b67d2-f8c0-457a-88dc-fd053343e134', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'How does Scala''s ''Object'' keyword implement the Singleton pattern, and what are the concurrency implications?', N'Senior', N'An ''object'' in Scala is a lazily-initialized singleton managed by the JVM''s class loader, which provides a thread-safe way to create global instances. The initialization is synchronized internally by the JVM, ensuring that multiple threads do not create duplicate instances. However, developers must be careful to avoid circular dependencies during object initialization, which can lead to deadlocks or partially initialized state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
