INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c2d93938-09ee-46cb-86d2-fd15cacfc667', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'How does Laravel''s polymorphic relationship work at the schema level, and what are the performance implications?', N'Senior', N'Polymorphic relationships use a type column and an ID column to reference multiple tables from a single relationship. The trade-off is the inability to enforce database-level foreign key constraints, which can lead to data integrity issues if not managed carefully at the application layer.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'df559014-20b4-4afd-9c8e-fd18e4afa3e4', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'Discuss the impact of ''static styles'' in Lit on memory usage and performance.', N'Senior', N'Lit utilizes Constructible Stylesheets to share a single instance of a CSS style object across all instances of a component. This significantly reduces memory consumption compared to traditional approaches where styles would be duplicated in every DOM tree.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd99ae672-9119-4e8c-91b7-fd1947765325', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'Describe the utility of Fastify''s ''onClose'' hook in the context of graceful shutdowns.', N'Senior', N'The onClose hook allows developers to perform cleanup tasks like closing database connections or finishing pending background jobs when the server receives a shutdown signal. This ensures that resources are released properly, preventing data corruption or connection leaks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'727e47f4-38a0-41ae-b63d-fd1c66bc4686', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'How do you handle a bug that is caused by a third-party library?', N'Fresher', N'I would check the library''s documentation and issue tracker to see if the bug is known or already fixed in a newer version. If not, I would create a minimal example demonstrating the issue to report it to the maintainers or look for a workaround.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd15d31b7-aeff-42ce-9ef0-fd1d007a09e1', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'How does Qwik ensure consistency between server and client?', N'Middle', N'Consistency is guaranteed by the serialization of both the application state and the framework''s internal metadata. The client starts exactly where the server left off, using the exact state and structure produced by the server.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'206aeaf2-6eca-4b5a-9909-fd1fa9bf42cb', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'What is the role of a ''load balancer'' in a server network?', N'Intern', N'A load balancer acts as a traffic director, distributing incoming requests across multiple servers to ensure no single server becomes overwhelmed. This improves the reliability and responsiveness of an application. If one server fails, the load balancer can redirect traffic to the healthy servers, preventing downtime.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4ab2a4d0-6f19-4087-886c-fd1fb435ddcf', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'When designing a large-scale system, how do you handle the trade-offs defined by the CAP theorem?', N'Senior', N'I analyze the business requirements to determine whether availability or consistency is the higher priority for specific use cases. For instance, I might choose eventual consistency for social media feeds to prioritize availability, but require strong consistency for financial transactions at the cost of potential latency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'302d7c2a-d62e-448c-a999-fd1fe0871d73', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'How does Svelte''s slot mechanism improve component composition?', N'Senior', N'Slots allow components to define placeholders for content injected by parent components. Svelte handles slot rendering efficiently by treating projected content as part of the parent''s reactive scope, ensuring that updates flow correctly even across component boundaries.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'916e9b9a-f125-4c2d-9b95-fd28e8640b14', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'Discuss the trade-offs of using Micronaut''s compile-time dependency injection in a CI/CD pipeline.', N'Senior', N'The primary trade-off is an increase in build time, as the framework must perform extensive analysis and bytecode generation during compilation. However, this is offset by significantly faster deployment times, lower infrastructure costs due to reduced memory footprints, and earlier detection of configuration errors.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0b999475-c854-4889-82a3-fd29f4a3256d', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'What is the difference between a Model and a Component?', N'Middle', N'A Model represents a data entity and its schema, focusing on the structure and validation of information. A Component represents the user interface logic and presentation, focusing on how that information is displayed and interacted with by the user.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bf827534-6bb8-4991-8122-fd2ad8002d6f', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'Explain the role of the Astro middleware.', N'Middle', N'Middleware allows developers to run code before every request to a page or API route. It is commonly used for authentication, setting headers, or modifying the response before it reaches the client.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7c22e6c5-41ac-4a3f-b89a-fd2bac2e146b', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'What is the primary difference between SQL and NoSQL databases like Cassandra?', N'Fresher', N'SQL databases are relational and use structured tables with fixed schemas and strong consistency. Cassandra is a NoSQL database that is schema-flexible, optimized for high-write throughput, and designed for horizontal scalability across distributed clusters.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3634ea59-c900-45d9-90d4-fd2c3c4a20e2', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What are rest parameters and how are they used?', N'Intern', N'Rest parameters in JavaScript allow a function to accept an indefinite number of arguments as an array. They are denoted by three dots (...) followed by the name of the array. This feature is useful for functions that need to handle multiple arguments without knowing the exact number in advance. ↑ &nbsp;&nbsp;/&nbsp;&nbsp; ✏️ Edit answer Explain the concept of the spread operator and its uses The spread operator (...) in JavaScript allows you to expand elements of an iterable (like an array or object) into individual elements. It is commonly used for copying arrays or objects, merging arrays or objects, and passing elements of an array as arguments to a function. ↑ &nbsp;&nbsp;/&nbsp;&nbsp; ✏️ Edit answer', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4ee9f741-4abf-4cff-abc1-fd2e272bbf35', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'What is the difference between the ''flex'' and ''grid'' layout models regarding their structural purpose and browser computation?', N'Senior', N'Flexbox is designed for one-dimensional layouts where content dictates size, whereas Grid is a two-dimensional system designed for complex, container-defined structures. Grid is generally more performant for complex layouts as it reduces the need for nested containers and relies on the browser''s internal grid-tracking algorithms.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2cb17def-2693-493f-9c31-fd2fa82e1552', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'How do you assess the root cause when a service is behaving correctly in staging but failing in production?', N'Senior', N'I would compare the environmental differences, such as traffic volume, database dataset size, and infrastructure configurations like instance types or network latency. I would also check for production-specific dependencies like external APIs or rate-limited services that might be behaving differently under the higher load and scale of the production environment.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3ce0e8e7-309b-48a5-9a4b-fd3128daf734', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'What are Redis HyperLogLogs and when should they be used?', N'Middle', N'HyperLogLogs are probabilistic data structures used for estimating the cardinality, or the number of unique elements, in a massive dataset. They provide a space-efficient way to count unique items with a very small error margin, making them perfect for high-traffic analytics where absolute precision is less important than memory usage.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd89c584d-fe16-4570-93f6-fd35ebdcd3a3', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is the role of ''WeakMap'' and ''WeakSet'' in managing memory-sensitive data structures?', N'Senior', N'These collections hold weak references to their keys, meaning that if no other references to the object exist, the entry can be garbage collected. This is critical for associating metadata with objects without preventing them from being reclaimed, effectively preventing memory leaks in long-lived state management.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cde0e9c8-7f8e-47b0-be9d-fd370d843b0c', N'8d34dfc0-4a64-4128-b41a-cafa62ddad41', N'What is a JSON Web Token (JWT) and what are the security risks associated with it?', N'Middle', N'A JWT is a compact, URL-safe means of representing claims to be transferred between two parties. The main risks include the inability to easily revoke tokens before they expire and the potential for sensitive information to be exposed if the token is not encrypted.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8e55a02b-9949-446b-a45d-fd378d8bd98a', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'What is the difference between a sparse index and a non-sparse index?', N'Middle', N'A sparse index only contains entries for documents that have the indexed field, omitting documents where the field is missing. This reduces index size and disk usage but may cause queries to omit documents from results if the index is used for the retrieval.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4e15335f-6a97-4da2-954d-fd3a10f9f22c', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'How can you analyze a Webpack bundle to identify performance bottlenecks?', N'Middle', N'You can use tools like ''webpack-bundle-analyzer'' to generate a visual representation of the bundle contents. This allows you to see which dependencies are taking up the most space, identify large modules that should be lazy-loaded, and detect duplicated code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'16985406-e542-495f-b7f0-fd4580f2543a', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'How does Swift''s protocol-oriented programming model differ from classical class-based inheritance?', N'Senior', N'Protocol-oriented programming favors composition over inheritance by defining shared behavior through requirements rather than shared state. This avoids the fragility of deep inheritance hierarchies and the ''diamond problem'' associated with multiple inheritance. It provides a more flexible design pattern where types can conform to multiple protocols, leading to better decoupling and testability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'709da282-4280-4d3b-980a-fd48e5fd6b92', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'Why is Astro considered a ''content-driven'' framework?', N'Junior', N'Astro is designed primarily for websites that feature heavy content, such as blogs, portfolios, and documentation sites. It prioritizes content loading speed by minimizing the JavaScript overhead that usually comes with heavy application frameworks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'19352a3b-6ed6-4954-b97e-fd4a10392c65', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'How does Micronaut handle configuration properties?', N'Intern', N'Micronaut uses a hierarchical configuration system that allows properties to be defined in various sources like property files, YAML files, or environment variables. The framework automatically binds these properties to configuration beans or allows them to be injected directly using value annotations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'784e92df-d27c-4677-b0bf-fd4f4f6c25b9', N'954a0331-deff-4399-b588-96f39fec001d', N'What is NgRx?', N'Intern', N'NgRx is a framework for building reactive applications in Angular. It is a state management library that provides a Redux-inspired architecture for managing and centralizing application state. NgRx is built on top of RxJS and follows the principles of reactive programming. The main components of NgRx include: 1. Store: A single, immutable data structure that holds the entire application state. 2. Actions: Plain objects that describe events or user interactions that can change the state. 3. Reducers: Pure functions that take the current state and an action, and return a new state. 4. Effects: Side effect handlers that listen to actions and can perform asynchronous operations like API calls. 5. Selectors: Functions used to query and derive data from the store.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b87c7703-bf08-4c28-b374-fd5046993118', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'What is the role of a surrogate key, and why is it often preferred over a natural key?', N'Middle', N'A surrogate key is an artificial, system-generated identifier that has no business meaning. It is preferred because it remains immutable even if business rules change, whereas natural keys might need to be updated, causing cascading foreign key issues.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'62d5ef45-2053-4d31-9362-fd5407c365b1', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is a proxy object', N'Intern', N'The Proxy object is used to define custom behavior for fundamental operations such as property lookup, assignment, enumeration, function invocation, etc. A proxy is created with two parameters: a target object which you want to proxy and a handler object which contains methods to intercept fundamental operations. The syntax would be as follows, Let''s take a look at below examples of proxy object and how the get method which customize the lookup behavior, In the above code, it uses get handler which define the behavior of the proxy when an operation is performed on it. These proxies are mainly used for some of the below cross-cutting concerns. 1. Logging 2. Authentication or Authorization 3. Data binding and observables 4.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'603aafe8-4904-440e-b074-fd540e9474d6', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'How does Remix’s approach to data loading differ from traditional Client-Side Rendering frameworks like React Query?', N'Senior', N'Remix utilizes route-based data loading via loaders that run exclusively on the server, eliminating the need for client-side orchestration. This architecture prevents request waterfalls by fetching all required data for a nested route structure in parallel during the initial document request.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e39fd43f-7b3d-4190-a81b-fd55a52a5a8b', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'How does hoisting affect the execution order of multiple var declarations and function declarations with the same name?', N'Fresher', N'When multiple var declarations or function declarations share the same identifier in the same scope, the engine applies specific precedence rules during the compilation phase: 1. var declarations are merged into one — only one undefined slot is allocated; whichever assignment executes last wins at runtime. 2. Function declarations override var declarations of the same name during hoisting — the function body wins over var''s undefined. 3. Multiple function declarations with the same name: the last one in source order wins (it overwrites the earlier one during hoisting). Example: Why this matters architecturally: In large legacy codebases (pre-modules), concatenating multiple script files together frequently caused silent name collisions of this kind.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'02a8ea49-0657-4b48-b217-fd55bdabe4dc', N'210c7148-726e-4e8b-bf12-40be36e55130', N'What does ''Result'' represent in Rust?', N'Fresher', N'The Result enum is used for error handling and represents the outcome of an operation that could either succeed or fail. It has two variants: Ok, which contains the successful value, and Err, which contains the error information.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dec71bdf-2d5b-43b4-9fe9-fd5968a72c79', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'What are Request mappings in Spring MVC?', N'Fresher', N'Request mappings are annotations like @RequestMapping, @GetMapping, and @PostMapping used to map web requests to specific controller methods. They define the URL path and HTTP method that a particular method should handle.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fadd0cdc-a320-4c46-bf59-fd5a4f846909', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'What is the trade-off between using an in-memory cache like Redis and querying a persistent database directly?', N'Junior', N'Using a cache drastically reduces latency and database load for frequently accessed data, improving user experience. The trade-off is the added complexity of managing cache invalidation and the risk of serving stale data if the cache is not updated correctly.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0664f2fa-5511-41fe-a3d9-fd5be9cd6921', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'How do you access URL parameters in SvelteKit?', N'Junior', N'URL parameters are available through the ''params'' object passed as an argument to load functions. These parameters correspond to the folders defined in square brackets in your routes directory.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3855f14d-5cd5-4042-b01b-fd5c33c9dcaf', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'What is the significance of the Tokio runtime for Axum?', N'Intern', N'The Tokio runtime provides the infrastructure for asynchronous execution in Rust. Axum relies on it to handle the non-blocking network operations required to manage multiple HTTP connections simultaneously.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ab991b3d-6c07-4ecb-9177-fd5cf70b0e06', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'How do props work in Svelte components?', N'Fresher', N'Props in Svelte are used to pass data from a parent component to a child component. You define a prop by using the export keyword on a variable, which allows the parent to set that variable''s value through attributes in the component tag.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5aee406b-826c-466a-b125-fd5d87ad73e4', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'What is the purpose of the @Service annotation?', N'Intern', N'@Service is a stereotype annotation used to indicate that a class is a service provider, typically containing business logic. It helps the framework identify these classes for component scanning and dependency injection.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ec08c086-4183-4365-a136-fd60463eeec0', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What are the various ways to create objects in JavaScript?', N'Intern', N'Creating objects in JavaScript offers several methods: - Object literals ({}): Simplest and most popular approach. Define key-value pairs within curly braces. - Object() constructor: Use new Object() with dot notation to add properties. - Object.create(): Create new objects using existing objects as prototypes, inheriting properties and methods. - Constructor functions: Define blueprints for objects using functions, creating instances with new. - ES2015 classes: Structured syntax similar to other languages, using class and constructor keywords. ↑ &nbsp;&nbsp;/&nbsp;&nbsp; ✏️ Edit answer', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'11f1696d-0541-4a77-bf3b-fd60cb4e5db5', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'How does Gin''s design influence the testability of your business logic?', N'Senior', N'If you strictly separate business logic from the Gin handler, your code remains testable with standard unit tests. If you embed business logic directly into the handler, you are forced to use httptest to simulate requests, which is significantly slower and more cumbersome for deep logic testing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4f392d69-bcd8-41fe-908d-fd6125d5eba6', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'What is the ''Any'' type in Scala?', N'Junior', N'Any is the root of the Scala class hierarchy, meaning every class in Scala inherits from it. It defines universal methods like equals, hashCode, and toString that are available to all objects.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7e37d424-2f89-42d0-82da-fd61d1b8d282', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'Why is selecting an appropriate Partition Key critical for performance?', N'Middle', N'An inappropriate partition key can lead to ''hot spots'' where one node receives significantly more traffic than others. Ideally, the key should have high cardinality to ensure data is distributed evenly across the entire cluster.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0f80d6bf-eceb-4e63-83c7-fd62562620da', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'What is the difference between single and double quotes in PHP strings?', N'Intern', N'Single quotes treat content as literal text, while double quotes attempt to parse variables and special characters within the string. Using double quotes allows for variable interpolation, whereas single quotes are generally faster for static strings.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c104f8c8-c7ea-4b4c-abc0-fd64e8bce1e1', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'What are the differences between ''public'', ''protected'', and ''private'' access modifiers in Ruby?', N'Junior', N'Public methods can be called by anyone. Private methods can only be called from within the same class and cannot be called with an explicit receiver, even for other instances of the same class. Protected methods can be called by any instance of the defining class or its subclasses, allowing objects of the same type to access each other''s protected methods.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c6d4d6d5-5b2a-48fc-988a-fd655de2663d', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'What is the primary difference between a partition key and a composite primary key in DynamoDB?', N'Middle', N'A partition key determines the logical partition where data is stored, while a composite primary key consists of a partition key and a sort key. The composite key allows for querying related items that share the same partition key but have different sort keys.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'eb545e54-14b1-43aa-a106-fd68976c1ce7', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'How does Flask manage session security, and what are the limitations of the default client-side session implementation?', N'Senior', N'Flask''s default sessions are stored in signed cookies, which are easy to implement but limited by the 4KB cookie size constraint and the risk of exposing sensitive data if the secret key is compromised. For high-security or large-data requirements, server-side session storage using Redis or a database is a more robust architectural choice.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2177798a-91ae-434f-b3be-fd6b169dabff', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'Does Preact support portals for rendering components outside the main DOM hierarchy?', N'Middle', N'Yes, Preact provides a createPortal API that allows rendering a component into a different DOM node, such as a modal or a tooltip container. This maintains the component''s logical placement in the tree while physically moving it elsewhere in the document structure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bd1f49ae-e032-4d97-bb14-fd6e91e318fe', N'9a0e3785-3b73-4abc-ab01-df75bf097dff', N'What is the primary architectural benefit of using microservices over a monolithic architecture?', N'Middle', N'Microservices enable independent scalability and deployment, allowing teams to develop, deploy, and scale specific components without affecting the entire system. This modularity improves fault isolation and allows the use of different technology stacks for different services.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c8d188e1-ad70-406a-9d59-fd6f6efd8c98', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'How does Quarkus perform hot-reloading?', N'Fresher', N'Quarkus monitors the file system for changes in source code. When a change is detected, it triggers a partial build and reloads the modified classes into the running application process, allowing developers to see changes instantly.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1082708f-4f3a-4c7f-adc1-fd705c543272', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What are some tools that can be used for JavaScript testing?', N'Fresher', N'For JavaScript testing, you can use tools like Jest, Mocha, Jasmine, and Cypress. Jest is popular for its ease of use and built-in features. Mocha is flexible and can be paired with other libraries. Jasmine is known for its simplicity and behavior-driven development (BDD) style. Cypress is great for end-to-end testing with a focus on real browser interactions. ↑ &nbsp;&nbsp;/&nbsp;&nbsp; ✏️ Edit answer', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ebbe254e-d8ae-4fe2-9fae-fd74aa10f9ec', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'What does the x-if directive do?', N'Intern', N'The x-if directive conditionally adds or removes an element from the DOM entirely based on an expression. Unlike x-show, which only hides the element, x-if physically removes it from the document structure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'247e3493-0237-4415-8f6c-fd74ac0447bc', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'What is the trade-off between using Actors and standard async functions in Actix?', N'Middle', N'Actors are ideal for managing complex stateful workflows and isolated concurrency, but they introduce overhead due to message passing. Standard async functions are more lightweight and performant for simple request-response cycles, making them the preferred choice for stateless REST endpoints.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3e9f3ea3-7689-4d79-8a35-fd7523c705da', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'What is a self-join?', N'Junior', N'A self-join is a regular join that is performed on a single table as if it were two separate tables. It is typically used to compare rows within the same table, such as finding employees who report to the same manager.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3c44c764-a253-427a-a37a-fd753c06bc11', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'What is the default behavior of Actix-web when a route is not found?', N'Intern', N'If a request does not match any defined route, Actix-web automatically returns a 404 Not Found HTTP error response. This behavior is built-in and requires no manual configuration.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'854e87b1-706a-4acc-9511-fd7a3e7c6d07', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'What is an instance variable and how is it denoted?', N'Junior', N'An instance variable belongs to a specific object instance and persists as long as the object exists. It is denoted by a single ''@'' prefix before the variable name.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'038f26f7-6bdc-4d0e-9546-fd7e88649476', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'Describe the trade-offs of using ''std::function'' versus function pointers or template-based callbacks.', N'Senior', N'std::function provides a type-erased polymorphic wrapper that can store any callable, offering flexibility but often incurring heap allocation and virtual function call overhead. Function pointers are lightweight but lack the ability to capture state, while template-based callbacks avoid runtime overhead by allowing the compiler to inline the calls, though they result in less flexible code structures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'67f11d96-b3d8-4845-bde7-fd8066e28709', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'How can you mitigate the impact of slow database queries in a Rails application without changing the business logic?', N'Senior', N'Optimization can be achieved through database indexing strategies, using read replicas for complex reporting queries, or materializing expensive calculations into pre-calculated tables. Additionally, caching query results in a fast key-value store can offload the database entirely for frequently accessed, read-heavy data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ef8fdc19-0eac-424f-92a8-fd82a58b957e', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'What happens to the client-side state when a user navigates between pages in SvelteKit?', N'Senior', N'When navigating, SvelteKit performs a ''soft navigation'' where only the necessary data is fetched and the components are updated in place. The client-side state is preserved unless the route change triggers a full page reload or the developer explicitly resets the state during the navigation lifecycle.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'66f9349e-9e72-4d0e-a1ce-fd850ab8e66a', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'Explain the architectural utility of ''Context Functions'' introduced in Scala 3.', N'Senior', N'Context functions provide a cleaner syntax for passing implicit arguments by making them first-class functions that accept parameters from the implicit scope. This reduces the boilerplate associated with deep implicit nesting and improves the ergonomics of libraries that rely on context-passing. It simplifies the implementation of dependency injection and configuration-heavy APIs while maintaining strong type safety.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'239c39b2-4de0-4611-a1c8-fd8ad7c8f1d8', N'954a0331-deff-4399-b588-96f39fec001d', N'How can you prevent a component''s lifecycle hooks from running unnecessarily?', N'Middle', N'You can use the OnPush change detection strategy to reduce the number of times lifecycle hooks and change detection cycles are triggered. Additionally, detaching the component from the change detector tree or using pure pipes can prevent unnecessary re-computations within the component template.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6822ee7b-cb2f-4d2d-ad44-fd8fe0036b5b', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'How do you decide between using a relational versus a non-relational database?', N'Intern', N'You choose a relational database when data is highly structured and requires complex relationships or strict ACID compliance. Non-relational databases are better for unstructured data, high-velocity requirements, or when the schema needs to be flexible and scale horizontally.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a549402e-5a1f-4a1c-b69a-fd9193acced8', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'How does Spring Boot resolve the correct bean when multiple exist for an interface?', N'Junior', N'Spring uses the @Primary annotation to indicate a default bean or the @Qualifier annotation to specify the exact bean name by ID. These mechanisms help the container resolve ambiguities when multiple classes implement the same interface.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'82af1a38-4ca1-4f21-bab0-fd9729f56b9f', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'Why is it important to validate and sanitize all user input in Express routes, even if the frontend performs validation?', N'Senior', N'Frontend validation is purely for user experience and can be easily bypassed by malicious actors using tools like Postman or cURL. Server-side validation is the only way to ensure data integrity and prevent security vulnerabilities like SQL injection or Cross-Site Scripting.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'704245ac-37e7-4e3c-9911-fd980869de10', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'What is the benefit of Vite''s ''On-demand'' compilation?', N'Intern', N'On-demand compilation means that Vite only processes the specific files requested by the browser. This drastically reduces the time it takes for the development server to start, as it does not waste resources bundling parts of the app that are not currently being viewed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
