INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cedba445-efff-4d5b-a5ca-fd9c9173138f', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'What is a ''Cache Miss''?', N'Intern', N'A cache miss occurs when an application requests data from the cache, but the data is not found. The system must then fetch the data from the primary database, which is slower, and then store it in the cache for future requests.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a5d3fa1c-8ff4-4ed3-8bae-fd9cc4a96561', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'What is a ''Commit'' in database transactions?', N'Intern', N'A commit is a command that saves all changes made during the current transaction to the database permanently. Once a transaction is committed, those changes become visible to other users and cannot be rolled back.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'638790bd-d7ff-4621-8905-fd9fcbf0171c', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'How does Gin handle concurrent writes to the response body from within different goroutines?', N'Senior', N'Gin’s Context is not thread-safe for concurrent writes to the response stream. If a handler spawns goroutines that attempt to write to the response, it will lead to race conditions; developers must ensure that all writes are synchronized or that the handler waits for concurrent tasks to complete before writing the final response.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'210d60c7-85ab-4732-b572-fda100e99c8c', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'What is normalization in a database?', N'Intern', N'Normalization is the process of organizing data in a database to reduce redundancy and improve data integrity. It involves dividing large tables into smaller, related tables and defining relationships between them.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
