INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2a6fd6c8-225b-48bf-b7e3-fda64238872f', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'How do you test a Flask application that relies on external services or databases?', N'Middle', N'You should use the Flask test client to simulate requests without running a real server and use mocking libraries to replace external API calls with fake responses. For databases, you should configure a separate test database and use setup and teardown methods to ensure the database is reset to a clean state before each test case.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7559d8d7-aceb-4f26-a327-fda791523639', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'How does Preact manage memory efficiently when handling large lists or frequent UI updates?', N'Senior', N'Preact optimizes memory by reusing component instances and minimizing the creation of wrapper objects during the diffing phase. By keeping the object graph shallow, it reduces the workload on the JavaScript garbage collector, which is critical for maintaining performance in dynamic, data-heavy interfaces.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8db415c9-0441-46f0-ba5f-fda891cf3bdb', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'How does the browser''s CSS Object Model (CSSOM) construction interact with the critical rendering path?', N'Senior', N'The CSSOM is a blocking resource; the browser must parse all CSS files before it can construct the render tree. This creates a render-blocking delay, which is why critical CSS should be inlined in the document head to allow the browser to paint the above-the-fold content without waiting for external stylesheets.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
