INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'131ddc39-d5fa-4d6a-a108-fdaa59eee6cd', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'How does Hono handle routing compared to traditional frameworks?', N'Junior', N'Hono uses a high-performance, trie-based router that matches request paths and methods very efficiently. Unlike some older frameworks that use regex-based matching, Hono''s router is optimized for speed, which is crucial for applications running in resource-constrained edge environments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9effc888-1e95-4979-8033-fdaa84b758b1', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'How do you implement custom error handling in Gin to avoid exposing internal details?', N'Middle', N'You should create a centralized error-handling middleware that catches errors passed via the context. This middleware can map internal errors to user-friendly messages and appropriate HTTP status codes, ensuring that stack traces or sensitive database errors remain hidden.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f50ed7d9-9b8a-4682-99bc-fdad150d89a1', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'What is the trade-off between running Quarkus in JVM mode versus Native mode for a production microservices environment?', N'Senior', N'JVM mode offers faster build times and full compatibility with dynamic language features or complex reflection, but requires a higher memory baseline and longer cold starts. Native mode provides near-instant startup and minimal memory footprint, making it ideal for serverless environments, though it requires longer build times and strict adherence to static analysis constraints.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd93a8d99-2a3d-448f-98f1-fdb1a1ebc3d3', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'What is a YAML file used for in Symfony?', N'Intern', N'YAML files are primarily used for configuration, such as defining routes, service definitions, or security settings. They provide a human-readable format that the Symfony container reads to configure the application''s components.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cd6ef466-09de-4089-9ed9-fdb7bc08b6d7', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'Why is it important to test edge cases rather than just the ''happy path''?', N'Junior', N'The happy path only confirms that the system works under ideal conditions, whereas edge cases reveal how the system handles unexpected or invalid inputs. Testing these ensures the application is robust and prevents crashes or data corruption when users do something unanticipated.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b9acefde-6b1f-4bfb-9b22-fdb8466a1b94', N'954a0331-deff-4399-b588-96f39fec001d', N'What are the trade-offs of using Angular Signals compared to RxJS for state management?', N'Middle', N'Signals provide a more synchronous, fine-grained reactivity model that is easier to debug and performant for simple state updates. RxJS is better suited for complex asynchronous streams and event orchestration, but it introduces a higher learning curve and more potential for memory leaks if not managed correctly.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ac178b2f-724b-42e7-b6ba-fdbb8d56496b', N'954a0331-deff-4399-b588-96f39fec001d', N'What are lifecycle hooks available?', N'Fresher', N'Angular application goes through an entire set of processes or has a lifecycle right from its initiation to the end of the application. The representation of lifecycle in pictorial representation as follows, !ScreenShot The description of each lifecycle method is as below, 1. ngOnChanges: When the value of a data bound property changes, then this method is called. 2. ngOnInit: This is called whenever the initialization of the directive/component after Angular first displays the data-bound properties happens. 3. ngDoCheck: This is for the detection and to act on changes that Angular can''t or won''t detect on its own. 4. ngAfterContentInit: This is called in response after Angular projects external content into the component''s view. 5.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'18132c17-9bf1-48d5-9a04-fdbbdddf1928', N'074508f7-35bd-405f-8cc6-b41377b2d92c', N'Compare the performance trade-offs of using a persistent disk-backed queue versus an in-memory queue.', N'Senior', N'Disk-backed queues offer durability and fault tolerance, allowing message recovery after a crash, but suffer from high I/O latency. In-memory queues provide extremely high throughput and sub-millisecond latency but risk complete message loss in the event of a broker process failure or power loss.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c6d88c40-786a-40b0-9120-fdbe1dc0bec8', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'What is the purpose of route parameters and how do they differ from query strings?', N'Middle', N'Route parameters are dynamic segments of the URL path used to identify specific resources, such as an ID in a RESTful structure. Query strings are appended to the end of the URL after a question mark and are generally used for filtering, sorting, or pagination rather than resource identification.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'40619f39-8b95-4f20-aa43-fdbf25226962', N'a000805c-e41f-42a9-af12-66b45348f77b', N'How does AdonisJS handle request lifecycle management compared to a framework like Express, and what are the benefits of its architectural approach?', N'Middle', N'AdonisJS uses a structured, service-oriented architecture with a centralized execution pipeline and dependency injection container. Unlike the middleware-heavy, loosely structured nature of Express, AdonisJS enforces strict patterns like Service Providers and Controllers, which improves maintainability, testability, and predictability in larger enterprise applications.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2eaec686-7e29-4da3-b86a-fdc46a4af157', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'How does ''Cardinality'' affect the choice of index strategy?', N'Senior', N'Cardinality refers to the number of unique values in a column; high cardinality columns are ideal for indexing because they allow the database to narrow down results quickly. Low cardinality columns, such as a boolean flag, are often inefficient to index because the tree traversal does not significantly reduce the search space.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6e36161b-d9d9-4d4e-9198-fdc8534fd9e7', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'How can you leverage Sass maps to manage design systems or theme configurations?', N'Senior', N'Sass maps allow you to store key-value pairs representing design tokens like colors, spacing scales, or typography. By iterating over these maps with @each loops, you can programmatically generate utility classes or theme variants, reducing code duplication and ensuring consistency across the design system.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f0f02ca4-0a5e-487a-abd4-fdc94976770d', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'What is meant by schema flexibility in DynamoDB?', N'Intern', N'Schema flexibility means that items in a table do not need to have the same attributes, except for the primary key. You can add or remove attributes from individual items at any time without having to restructure the entire database.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ab1d5d7d-4415-4bcd-9238-fdc9d2fc95d0', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'Why is Go often used for cloud and network services?', N'Intern', N'Go is popular for cloud infrastructure because it produces small, statically linked binaries that start quickly and consume minimal memory. Additionally, its built-in support for concurrency makes it ideal for handling high-volume network traffic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fb930d19-57b9-48b3-a479-fdce326e2186', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'What is the difference between a Local Secondary Index and a Global Secondary Index?', N'Fresher', N'A Local Secondary Index has the same partition key as the base table but a different sort key, while a Global Secondary Index can have a completely different partition key and sort key. Global indexes are more flexible but are eventually consistent, whereas local indexes maintain strong consistency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e28ce6a4-0028-4aa0-8a5b-fdcf4e14ffbe', N'a2838158-7305-480a-b22b-4dc35776b400', N'What is the difference between a hot standby and an active-active deployment?', N'Middle', N'An active-active deployment distributes traffic across multiple instances simultaneously, providing better load balancing and fault tolerance. A hot standby involves having a secondary instance ready to take over only when the primary fails, which provides redundancy but underutilizes the secondary resource.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e2f40711-a641-464b-88bc-fdd04f5c159b', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'What is the primary benefit of the Tower ecosystem integration in Axum?', N'Junior', N'The main benefit is the ability to use a wide variety of existing, well-tested middleware. Since many Rust web frameworks share the Tower interface, developers can easily swap or add functionality like rate limiting and retries.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
