INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'952fd672-ae8b-4ab8-a72b-fdd082709ce9', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'Why might you choose Lit over a framework like Vue or Angular for a micro-frontend architecture?', N'Senior', N'Lit produces native Web Components, which are framework-agnostic and interoperable across different technology stacks. This makes it an ideal choice for micro-frontends where different teams might use different frameworks, as the components can be consumed like standard HTML tags.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8853dd5b-952c-4c0d-8929-fdd334e88733', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'What are the trade-offs of using a schema-less design versus a strictly typed schema in a document store?', N'Senior', N'Schema-less designs offer maximum flexibility for evolving data requirements but shift the burden of validation to the application layer. Strictly typed schemas provide better data quality, easier indexing, and clearer API contracts, but require migration scripts that can complicate deployments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6e70a027-fee5-43cd-8d2b-fdd88f30caa3', N'f2e963ff-7635-4429-a389-4d92535fb972', N'What is the role of the head section in an HTML document?', N'Junior', N'The head section contains meta-information about the document that is not displayed directly on the page. This includes the page title, links to stylesheets, character encoding declarations, and scripts that need to be loaded.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a97f9f60-55f0-4e1b-9e60-fddbdc272815', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'How does Quarkus achieve fast startup times?', N'Intern', N'Quarkus achieves fast startup by shifting most of the initialization work, such as metadata processing and dependency resolution, to the build phase. This leaves very little work for the application to perform when it actually starts up.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3bb49262-c2dd-4808-b1c4-fddd1e4b3324', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'Why is NoSQL considered ''flexible''?', N'Fresher', N'NoSQL is considered flexible because it does not enforce a rigid schema, allowing developers to store data with different structures in the same database. This is particularly useful for evolving applications where data requirements change frequently.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8c327290-dd88-454d-8f6e-fdde60233029', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'How do you estimate the impact of adding a new developer to a project that is already behind schedule?', N'Middle', N'I apply Brooks''s Law reasoning, acknowledging that adding resources to a late project often makes it later due to the overhead of onboarding and communication. I would only recommend this if the task is easily parallelizable and we have a clear, documented plan that minimizes the ramp-up time for the new developer.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1c85862f-2675-4fec-8e88-fddff35e8d96', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'How does Fiber handle HTTP errors?', N'Intern', N'Fiber includes a built-in error handling mechanism that allows developers to return errors from handlers. The framework can intercept these errors and send appropriate HTTP status codes and messages back to the client based on the error type.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8297d1e7-cc01-4b2f-9914-fde02b028cc0', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'What approach do you take when choosing a technology stack for a new service?', N'Middle', N'I assess the team''s existing expertise, the community support and ecosystem around the technology, and whether it aligns with the service''s specific requirements like latency, throughput, or data processing. I prioritize technologies that minimize maintenance burden and align with the existing organizational standards to facilitate easier support and talent acquisition.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4754ca74-7222-429b-8d1e-fde1c347365a', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'How do you pass data from a parent to a child in SolidJS?', N'Junior', N'You pass data using props. Because props are reactive objects, the child component can access them as signals or use them directly in the template, and the child will update automatically when the parent changes the passed data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c40fb819-3312-4e91-ae19-fde1ca541d3f', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is callback() function in javascript?', N'Intern', N'A callback function is a function passed into another function as an argument, which is then invoked inside the outer function to complete some kind of routine or action. Example: Key points: * Callbacks can be named or anonymous functions * They enable asynchronous and non-blocking code * Overusing nested callbacks leads to "callback hell" — solved by Promises or async/await *Note: callbacks are often used to continue code execution after an asynchronous operation has completed — these are called asynchronous callbacks.*. &#9885; Try this example on CodeSandbox', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b74b1c99-4ac2-45d6-a623-fdec0474e7d2', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'How does Tailwind''s JIT compiler handle ''dead code elimination'' for CSS?', N'Senior', N'The JIT compiler performs dead code elimination by design; it never generates CSS for classes that are not explicitly present in the scanned source files. This ensures that the generated CSS bundle size is directly proportional to the functionality used in the project, rather than the size of the framework itself.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd62b5dc2-0118-42a7-8a78-fdefa84c1269', N'a000805c-e41f-42a9-af12-66b45348f77b', N'Why would you choose AdonisJS''s Validator over manual schema validation?', N'Middle', N'The AdonisJS Validator is tightly integrated with the request lifecycle, allowing for declarative validation schemas that automatically return structured error responses. This reduces boilerplate code and ensures consistent error handling across the entire API.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1674734f-9047-40a8-8bc3-fdf050a25d18', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'What is the purpose of the PostgreSQL Query Planner?', N'Middle', N'The Query Planner analyzes a SQL statement and evaluates multiple execution strategies, such as different join types or scan methods. It uses statistical information about the data distribution to choose the plan with the lowest estimated cost.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c3175cc9-2a83-4ec2-9875-fdf160f2f239', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'What is Middleware in Laravel and when should you use it?', N'Junior', N'Middleware provides a convenient mechanism for filtering and inspecting HTTP requests entering your application. It is commonly used for tasks like authentication, logging, or restricting access to specific routes based on user roles.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'902259f1-e6a9-4557-81f4-fdf2f5ce5ef4', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'How does PostgreSQL''s Multi-Version Concurrency Control (MVCC) handle vacuuming, and why is it necessary?', N'Senior', N'MVCC creates new row versions instead of overwriting old ones, leaving dead tuples behind. The VACUUM process reclaims the space occupied by these dead tuples for reuse, preventing table bloat and ensuring efficient storage utilization.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bdbfe914-fbbd-4cef-8cd3-fdf67537ef47', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'How does Hono handle streaming responses, and when should this be preferred over buffered responses?', N'Senior', N'Hono supports ''ReadableStream'' natively, allowing for the transmission of large payloads or real-time data chunks before the entire response is processed. This should be preferred for long-running LLM responses or large data exports to reduce time-to-first-byte and overall memory consumption on the server.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cd05f9ca-96d4-4723-ad7b-fdf716770738', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'How do you stay objective when you have become attached to a specific solution?', N'Intern', N'I perform a ''cost-benefit'' analysis comparing my preferred solution against alternatives, focusing on objective metrics like complexity, performance, and maintenance. If the data suggests a different approach is better, I prioritize the project''s success over my own attachment to a specific idea.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4c6d4d18-22a8-49c1-8e8f-fdfa4756f5c8', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'How does the autoloader mechanism influence the scalability of large PHP applications?', N'Senior', N'Autoloading allows the engine to load class definitions on-demand, preventing the need to include every file on every request. This keeps the memory footprint low and reduces disk I/O, though it requires an efficient implementation like Composer''s class map to avoid frequent filesystem lookups.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6947e266-74df-4f03-bf12-fdfc7fdc3ddf', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'Why are Go''s error handling patterns often criticized, and what is the rationale behind them?', N'Middle', N'Critics often cite the repetition of ''if err != nil'' checks as verbose. However, Go''s designers prioritize explicit error handling over exceptions because it forces developers to address failure scenarios directly, leading to more robust and readable code paths.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5cf20695-069e-4c1e-af5f-fdff0d6a735f', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'What does ''ActiveRecord::Base'' provide to a Rails model?', N'Middle', N'It provides the implementation of the Active Record pattern, which maps database tables to Ruby objects. It includes functionality for CRUD operations, validation logic, association management, and query interface methods that abstract complex SQL into readable Ruby code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5bc55f55-e204-4f7e-916c-fdff2c4681ce', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'What is the purpose of the ''noexcept'' specification?', N'Middle', N'The noexcept specifier informs the compiler that a function will not throw any exceptions. This allows the compiler to perform specific optimizations and helps manage exception-safe code, as certain operations, like moving objects, can be optimized if the move constructor is marked noexcept.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a7a6ed33-8882-4b89-980b-fe0011f62404', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'How does Gin handle recovery from panics in a production environment?', N'Middle', N'Gin provides a Recovery middleware that catches any panics occurring during request processing to prevent the entire server process from crashing. It typically logs the stack trace and returns a 500 Internal Server Error to the client, ensuring service availability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2699b753-180a-4787-bcad-fe006948ed5e', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'What is the ''final'' keyword used for in Dart?', N'Intern', N'The ''final'' keyword is used to declare variables that can be set only once. Once a final variable is assigned a value, it cannot be changed for the remainder of the program''s execution.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fd4f6ac2-c431-463e-9fdd-fe01b040ce35', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'How does Astro manage asset bundling for multiple framework islands on the same page?', N'Senior', N'Astro uses Vite as its underlying build tool, which manages the dependency graph and code splitting for multiple frameworks independently. It ensures that shared dependencies are deduplicated where possible and that each island only loads the runtime necessary for its specific framework.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8d78cdb4-1cee-433e-8c97-fe026c9cba85', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'What is schema flexibility in the context of NoSQL?', N'Fresher', N'Schema flexibility means that a NoSQL database does not require a predefined structure before adding data. This allows developers to insert data with different fields or formats into the same collection, making it easier to evolve the data model as application requirements change over time.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e8989670-3bbe-4073-bef1-fe02e6513880', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'What are the implications of using ''Sequence'' versus ''Iterable'' for large data processing?', N'Senior', N'Iterables are eager, creating intermediate collections for every transformation, which increases memory consumption. Sequences are lazy, processing elements one by one through the entire pipeline, which is more memory-efficient for large datasets but incurs a slight overhead for small lists.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2284f80f-4825-4d76-9e88-fe039e4a7509', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'How does Preact handle prop updates?', N'Middle', N'Preact performs a shallow comparison of props to determine if a component needs to re-render. It is highly optimized to skip unnecessary updates, and developers can further control this behavior using lifecycle methods or the memo utility to prevent re-renders when props haven''t changed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'38da97f2-81d4-4157-bd4d-fe0a9595e9bf', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'What are the trade-offs of using ''ThreadLocal<T>'' compared to ''AsyncLocal<T>''?', N'Senior', N'ThreadLocal provides isolated state for a specific thread, which is efficient but fails in modern asynchronous code where logical operations jump between threads. AsyncLocal flows state across asynchronous call stacks, ensuring data remains accessible regardless of which underlying thread executes the code, though it introduces a small performance overhead for state propagation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1c5512bb-88bb-4a9a-ba43-fe0b7dae3d86', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'Why is it important to define success metrics before performing a trade-off analysis?', N'Intern', N'Defining metrics provides an objective baseline to compare different options against. Without clear success criteria, trade-offs become based on subjective opinions rather than data, making it difficult to justify why one design choice was selected over another.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
