INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'45afbec9-03f3-4664-9bd9-fe0d59277bb8', N'a000805c-e41f-42a9-af12-66b45348f77b', N'What is the ''Kernel'' in AdonisJS?', N'Junior', N'The Kernel manages the global and named middleware stacks. It determines the order in which middleware is executed for every incoming HTTP request.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2d379e56-c315-4a14-8b70-fe0ef127ddfa', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'Explain the concept of ''placeholder selectors'' and their role in optimizing CSS size.', N'Senior', N'Placeholder selectors, identified by the % symbol, are styles that do not render in the CSS until they are explicitly extended. This is a highly efficient way to define shared base styles that are only included in the output when they are actually referenced, preventing unused CSS from being generated.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'435c6796-da86-4836-9e5f-fe0f919f77d7', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'How does jQuery handle the ''Document Ready'' event, and why is it important?', N'Middle', N'The ready event ensures that the DOM has been fully parsed and is ready for manipulation before any script executes. This prevents errors caused by attempting to interact with elements that have not yet been rendered in the browser''s document tree.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
