INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'55af94d8-3ba7-4486-b76c-fe118085ce74', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'Describe the security implications of Laravel''s mass assignment protection.', N'Senior', N'Mass assignment protection prevents attackers from injecting malicious input into sensitive database columns by requiring developers to explicitly whitelist fillable fields. Without this protection, an attacker could potentially update fields like ''is_admin'' or ''user_id'' by simply adding them to the request payload.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
