INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7ab17461-3f3c-480c-a352-fe127450c067', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'How do you access DOM elements directly in Preact?', N'Junior', N'You use the ''useRef'' hook to create a reference, which you then attach to a JSX element using the ''ref'' attribute. Once the component mounts, the ''current'' property of the ref will point to the actual DOM node.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'77e74160-78b4-4138-9b97-fe13da31c42e', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is currying function?', N'Intern', N'Currying is the process of taking a function with multiple arguments and turning it into a sequence of functions each with only a single argument. In other words, when a function, instead of taking all arguments at one time, takes the first one and return a new function that takes the second one and returns a new function which takes the third one, and so forth, until all arguments have been fulfilled. *Note: Curried functions are great to improve code re-usability and functional composition.* &#9885; Try this example on CodeSandbox', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2532ff06-6609-4898-9d80-fe148ea2afd3', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'What is esbuild in the context of Vite?', N'Intern', N'esbuild is an extremely fast JavaScript bundler and minifier written in Go. Vite uses it to pre-bundle dependencies and transform TypeScript or JSX code, which is significantly faster than traditional JavaScript-based tools.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dbab03d7-df8c-447d-8fc7-fe17928c3509', N'075b8862-431c-4678-9767-f55359758a4a', N'What is the purpose of ''customRef'' in the Vue reactivity system?', N'Senior', N'CustomRef allows developers to explicitly control the dependency-tracking and trigger-update mechanisms for a reactive property. It is useful for implementing advanced features like debounced inputs or asynchronous fetching, where standard reactivity behavior needs to be augmented with custom logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e64f96b1-5189-4f6b-808c-fe1865c6be77', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'What are pipes in the context of NestJS?', N'Intern', N'Pipes are a feature of NestJS that allows for validation or transformation of data before it is passed to a route handler and can either return the arguments as is, modify them, or throw an exception. A pipe is a class annotated with the @Injectable() decorator, which implements the PipeTransform interface Validation: This is the most common use case for pipes. They can be used to validate incoming data to ensure it matches a certain data schema. If the data is invalid, the pipe can throw an exception to prevent the route handler from being executed. Transformation: Pipes can transform incoming data into a desired format. For example, you might want to automatically convert incoming strings to numbers, or convert an entity''s ID into the entity itself.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'db68592b-97b1-41ac-b0dd-fe1880de42bc', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'How does the ''content-visibility'' property change the way browsers render off-screen elements?', N'Senior', N'The content-visibility property allows the browser to skip the rendering work—including layout and painting—for elements that are not currently in the viewport. This significantly improves initial load times and responsiveness for long, content-heavy pages by deferring work until the user scrolls.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'10262b91-43f6-4d4c-9124-fe19b7ce3aed', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'How does SolidJS handle context propagation in a reactive tree?', N'Senior', N'Context in SolidJS is provided via a scoped provider that stores a value, which children consume through a lookup mechanism. Because SolidJS uses a fixed reactive tree, the context lookup is efficient and ensures that any reactive updates to the context value propagate automatically to the consumers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0b6fafff-71ff-4490-85fd-fe1a0af9febf', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'How does Rails handle file uploads?', N'Fresher', N'Rails typically handles file uploads through dedicated libraries like Active Storage. This feature provides a way to upload files to various storage services and associate those files with ActiveRecord objects seamlessly.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bdb1a8aa-bc4b-40a5-b0ec-fe1b50ab8285', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What are the basic types available in TypeScript?', N'Intern', N'TypeScript provides an assortment of basic types for different kinds of data, such as numbers, strings, boolean values, arrays, tuples and more. Common Basic Types in TypeScript - Boolean: Represents true/false values. - Number: Applies to both integer and floating-point numbers. - String: Refers to textual data. - Array: Offers a flexible way to work with structured data. - Tuple: Enables the definition of arrays with a fixed number of elements, each potentially of a different data type. - Enum: Provides a set of named constants such as days or colors. - Any: Offers a dynamic type, which can be used to bypass type-checking. It''s typically best to be avoided, as it defeats the purpose of using TypeScript, which is primarily focused on static typing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fe0bb466-16d5-4dd3-8394-fe204a754acc', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'Discuss the trade-offs of using Alpine.js in an environment with high-frequency updates, such as a real-time dashboard.', N'Senior', N'Alpine is not optimized for high-frequency updates because every change triggers a DOM update scan. In a real-time dashboard, frequent state changes could result in excessive CPU usage and UI stuttering as the framework reconciles the changes. For such use cases, a more specialized library or a virtual DOM approach would be more efficient at batching and throttling updates.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'94601156-7843-491b-b8fe-fe20fe33d134', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'What is the benefit of using the spread operator in Dart?', N'Junior', N'The spread operator allows you to insert all elements of one collection into another collection easily. It provides a concise and readable syntax for merging lists, sets, or maps.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'823e31e7-1078-4224-9dcb-fe2278349ba6', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'What are the advantages and drawbacks of using channels for communication versus shared memory with mutexes?', N'Middle', N'Channels follow the philosophy of communicating by sharing memory, which helps avoid race conditions by passing ownership of data between goroutines. Mutexes are generally faster for protecting low-level shared state, but they are more prone to complex deadlocks and race conditions if not managed carefully.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'711974af-8268-4318-bef6-fe25d84c7507', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'What criteria do you use to determine the optimal caching strategy for a read-heavy application?', N'Senior', N'Analyze the access patterns and data volatility to decide between write-through, write-behind, or cache-aside strategies. Ensure that cache invalidation policies, such as TTL or event-driven purging, are clearly defined to prevent stale data issues.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ff80efce-ace5-4637-a495-fe2a3daa8711', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'What is the proper placement for error boundaries?', N'Intern', N'The granularity of error boundaries usage is up to the developer based on project needs. You can follow either of these approaches, 1. You can wrap top-level route components to display a generic error message for the entire application. 2. You can also wrap individual components in an error boundary to protect them from crashing the rest of the application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'804c0c9b-ce54-402e-a8bb-fe2bebffb64d', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'How does Remix resolve the ''layout shift'' issue often associated with client-side data fetching?', N'Senior', N'Because Remix loaders block the initial render until data is available, the server sends a fully populated HTML document. This eliminates the need for ''loading spinners'' on the initial page load, providing a seamless visual experience without layout shifts.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0bf99ff8-bb10-4b5a-a910-fe2ce3f0dd1f', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'What makes Fiber suitable for high-performance microservices?', N'Fresher', N'Fiber''s low memory footprint, high throughput, and minimalist API make it highly efficient for microservices. It allows developers to build lightweight services that can handle large volumes of requests with minimal overhead.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c92e047d-c9fe-4ff4-b66a-fe2d5f5d1be9', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'Why would an architect choose Litestar over a framework with more ''magic'' and implicit behavior?', N'Senior', N'An architect chooses Litestar for its explicit, type-safe design that prioritizes clarity over hidden framework magic. This predictability makes it easier to trace execution flow and debug complex issues in production, which is critical for long-term project stability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4792a86d-f08a-44cb-a172-fe2da7e79b3e', N'954a0331-deff-4399-b588-96f39fec001d', N'Why Use Directives?', N'Fresher', N'Directives provide a declarative approach to organizing your code, making it more intuitive and easier to maintain, with a clear separation of UI and application logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0a72deeb-ef19-40a7-97f1-fe2e02bd0f41', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'What is the difference between ''Task'' and ''Thread'' in C#?', N'Junior', N'A Thread represents a direct OS-level execution unit, which is resource-intensive to manage. A Task is a higher-level abstraction that represents an asynchronous operation, managed by the Task Parallel Library and optimized for scalability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
