INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a4e4c7bc-1819-45ee-afc1-fe310a971f74', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'How does Micronaut manage database migrations?', N'Middle', N'Micronaut integrates seamlessly with tools like Flyway or Liquibase. It can trigger migrations automatically on application startup, ensuring that the database schema is always in sync with the application code before the server begins accepting traffic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c08d9d66-9a70-4e5b-97e7-fe3117b0e192', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'How does Remix handle navigation differently compared to standard browser behavior?', N'Middle', N'Remix uses an enhanced navigation system that intercepts link clicks and form submissions to fetch only the necessary data for the next route rather than reloading the entire page. This provides a fast, app-like experience while maintaining full compatibility with standard browser functionality like back and forward buttons.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
