INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0e5e884f-d8aa-4ae7-bcdf-fe324afc3a5b', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'What is the primary architectural goal of Astro?', N'Intern', N'The primary goal of Astro is to achieve high performance by using a server-first approach. It focuses on reducing the amount of client-side JavaScript sent to the user, which improves page load times.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1fa0b117-ab3e-42a2-bcef-fe325c032333', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'What is the function of the Zend Engine''s Garbage Collector in the context of circular references?', N'Senior', N'The PHP garbage collector uses a cycle collection algorithm to identify and clean up circular references that reference counting alone cannot resolve. By tracking potential root nodes in a buffer, the engine periodically scans for unreachable memory structures that form closed loops, preventing memory exhaustion in long-running processes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4f9de6e7-b0d6-4920-a83c-fe334005be88', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'What is the role of esbuild in the Vite ecosystem?', N'Junior', N'Esbuild is a high-performance JavaScript bundler written in Go that Vite uses to pre-bundle dependencies. It is significantly faster than JavaScript-based tools, allowing Vite to handle dependency pre-bundling extremely quickly.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd6dfd557-745f-42b5-a8ca-fe336321059b', N'954a0331-deff-4399-b588-96f39fec001d', N'How do Angular Modules (NgModule) and Standalone Components differ in terms of dependency management and architectural complexity?', N'Senior', N'NgModules act as a central configuration layer that aggregates components, directives, and pipes, often leading to ''module sprawl'' and complex dependency graphs. Standalone components simplify architecture by making components self-contained, requiring explicit imports for dependencies, which improves modularity and makes the dependency graph more transparent and easier to tree-shake.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0ddb62d1-e2c8-417b-9797-fe3a31778fe0', N'074508f7-35bd-405f-8cc6-b41377b2d92c', N'How do you maintain order in a distributed system where messages are processed in parallel?', N'Senior', N'Strict ordering requires using a single consumer or partitioning by a specific key so that all related messages go to the same instance. If parallel processing is required, ordering can only be maintained by using sequence numbers and having the consumer buffer and re-sort messages before final processing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd67c84bd-1110-4ead-999c-fe3f098aca8a', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'How do you serve static files in Gin?', N'Intern', N'Gin provides a dedicated method to serve static files from a specific directory. By mapping a URL path to a local folder, the framework automatically handles serving assets like images, CSS, and JavaScript files.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ba71efcc-f4b6-4fde-9ee0-fe3ff265415a', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'If a feature seems simple but turns out to be complex, how do you handle the change in scope?', N'Fresher', N'I would document the newly discovered complexities and assess their impact on the overall timeline. I would then inform my team or manager about the shift in scope to determine if the priority of the task needs adjustment.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c7c6d3c1-d74a-45fe-8ab7-fe402897afbd', N'954a0331-deff-4399-b588-96f39fec001d', N'What is standalone component?', N'Intern', N'A standalone component is a type of component which is not part of any Angular module. It provides a simplified way to build Angular applications.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9151f547-3384-4af0-87c1-fe40b2304250', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'How does Chi handle the 404 and 405 error scenarios differently than the standard library?', N'Middle', N'Chi provides built-in handlers for ''Not Found'' and ''Method Not Allowed'' cases that are easily customizable. Unlike the standard library, which requires manual implementation of these edge cases, Chi allows developers to define global behavior for these errors within the router configuration.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f1167aeb-e7c0-420b-be5a-fe443178b4b4', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'Why is it often easier to maintain a Tailwind project compared to a standard CSS project?', N'Fresher', N'Because styles are applied directly to HTML, you don''t need to jump back and forth between HTML files and large CSS stylesheets to understand the layout. Since utility classes are global and predictable, you eliminate the risk of accidentally breaking styles in other parts of the application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cf3706da-678e-405e-b02a-fe468a79d4a2', N'075b8862-431c-4678-9767-f55359758a4a', N'What are the security implications of using ''v-html'' in Vue, and how do you mitigate them?', N'Senior', N'V-html injects raw HTML into the DOM, which makes the application highly vulnerable to Cross-Site Scripting (XSS) attacks. Mitigation involves sanitizing all user-provided strings through a library like DOMPurify or, preferably, avoiding raw HTML rendering entirely by using standard component slots and text binding.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3ea73e2e-78a8-4a7e-bde0-fe46ff73d2e8', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'When should you choose a NoSQL database over a SQL database?', N'Junior', N'NoSQL is often preferred when the data structure is highly dynamic, frequently changing, or when you need to scale horizontally across many servers. It is also suitable for handling massive amounts of unstructured data that do not fit neatly into rows and columns.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0c389e73-b93e-4147-ae37-fe47eb4e7b19', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'Explain the concept of ''write-ahead logging'' in NoSQL databases.', N'Middle', N'Write-ahead logging is a technique where modifications are recorded in a persistent log before being applied to the actual data files. This ensures data integrity and allows the database to recover to a consistent state in the event of a crash.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd40c2397-e587-4a61-b535-fe484616bd6e', N'954a0331-deff-4399-b588-96f39fec001d', N'What is the role of Dependency Injection in Angular?', N'Middle', N'Dependency Injection is a design pattern that allows components to receive their dependencies from an external source rather than creating them internally. It promotes modularity, makes code easier to test by allowing mock objects, and centralizes service management.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e71dcf31-4e60-426a-9adf-fe492553d245', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'What is the primary role of a Context object in Echo?', N'Intern', N'The Context object represents the state of a single HTTP request and response cycle. It provides methods to read request data, such as headers and parameters, and to send responses back to the client.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b0402a5c-9fea-43c6-959a-fe4ae7fe197b', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What is the ''any'' type, and why is it generally discouraged?', N'Junior', N'The ''any'' type tells the TypeScript compiler to stop checking types for a specific variable, effectively reverting it to JavaScript behavior. It is discouraged because it bypasses the safety benefits of TypeScript, increasing the likelihood of runtime errors and making the codebase harder to debug.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3def3d16-7a91-43ee-9dd1-fe4b6760f23a', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'What is the primary purpose of a load balancer in a web architecture?', N'Intern', N'A load balancer acts as a traffic cop that distributes incoming network requests across multiple servers. Its main purpose is to ensure no single server becomes overwhelmed, which improves application responsiveness and prevents downtime. If one server fails, the load balancer directs traffic to the remaining healthy servers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2a637cf4-19bb-4b03-bbf7-fe4cfd83a3f6', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'What are the limitations of using a Client Component inside a Server Component?', N'Middle', N'You can import a Client Component into a Server Component, but the Client Component cannot accept Server Components as direct children unless they are passed as props (like the children prop). This restriction exists because Server Components must be rendered on the server, while Client Components require client-side hydration.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'83facb21-b527-41e6-acf4-fe4ef2de4cce', N'91fb4eff-ac6a-48b9-8ba4-2bbdf6237429', N'Explain the trade-offs between sampling and full-trace ingestion in observability.', N'Senior', N'Full-trace ingestion provides complete visibility but incurs massive storage and network overhead. Sampling reduces costs and data volume significantly but risks missing rare, intermittent bugs that only occur in edge cases.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c2795ad2-a671-4df2-b93e-fe4ff7b63c5d', N'f2e963ff-7635-4429-a389-4d92535fb972', N'How do ''picture'' and ''source'' elements improve performance compared to standard image tags?', N'Senior', N'These elements enable responsive image delivery by allowing the browser to select the most appropriate asset based on screen resolution, density, or file format support. This prevents the wasteful downloading of large assets on smaller devices and allows for the usage of modern formats like WebP or AVIF with graceful fallbacks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a922b4e5-8c9f-49f1-9c2d-fe4ff9347d0f', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'Why is it considered bad practice to hardcode sensitive information like API keys in your application?', N'Fresher', N'Hardcoding credentials makes them visible to anyone with access to the source code, which significantly increases the risk of unauthorized access if the code is accidentally exposed. It is much safer to store these values in environment variables or a dedicated secret management service.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5c773dca-be21-4c0f-8f51-fe53597be013', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'What are the architectural implications of implementing sharding in a relational database?', N'Senior', N'Sharding distributes data across multiple physical nodes, enabling horizontal scalability of throughput and storage capacity. However, it introduces significant complexity in managing cross-shard joins, global transaction consistency, and the potential for hotspots if the shard key is not chosen to ensure uniform data distribution.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'acf4d7f7-5a78-4a96-940a-fe586d827771', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'Explain the role of the Gossip protocol in a Cassandra cluster.', N'Middle', N'Gossip is a peer-to-peer communication protocol used by nodes to exchange information about themselves and other nodes in the cluster. It enables nodes to detect failures, share schema changes, and maintain an up-to-date view of the cluster topology.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8a531438-f7d6-4ef8-b9de-fe5f5199a345', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'What is the difference between physical and logical logging in a database?', N'Middle', N'Physical logging records the exact byte-level changes made to data pages, which is fast to recover but takes more space. Logical logging records the high-level operations, such as row updates, which is more compact but requires re-executing the logic during recovery, making it slower.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'48d024ed-870e-4628-876a-fe5f9076f9f0', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'Explain why jQuery''s ''Deferred'' objects are considered an anti-pattern in modern development.', N'Senior', N'jQuery Deferred objects do not strictly adhere to the Promises/A+ specification, leading to subtle differences in error handling and chaining behavior. Modern applications should use native Promise objects or async/await, which provide predictable, interoperable, and standard-compliant asynchronous flow control.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f1b2ca43-e7ef-40fb-b088-fe604fbecdee', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'What is the primary architectural focus of Astro?', N'Fresher', N'Astro is a web framework designed for content-driven websites, focusing on performance by shipping minimal JavaScript to the browser. It achieves this primarily through its island architecture, which renders pages as static HTML by default.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'06d9a9d2-0afd-4372-8230-fe609ffefe22', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'Why might a node experience ''GC Pressure'' in a high-throughput Cassandra cluster?', N'Senior', N'GC pressure often results from the creation of many short-lived objects during heavy read/write operations, specifically during compaction or large object allocation. Tuning the JVM garbage collector and optimizing heap sizing are critical to maintaining stable latency in these environments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'001b140c-a259-413a-8bc5-fe620bf3d755', N'18ebabb7-555b-4ba1-beb6-844b8ee55dbd', N'When should you prefer a ''Write-Around'' caching strategy over ''Write-Through''?', N'Senior', N'Write-Around is preferred when you have high-volume write workloads where the written data is rarely read back immediately. This avoids ''polluting'' the cache with data that is unlikely to be accessed again, preserving memory for more frequently requested items.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4ce953b5-38b3-43a5-81cc-fe651a3eab83', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'Explain the concept of ''Action Batching'' and why it might be necessary.', N'Senior', N'Batching allows multiple actions to be processed in a single render cycle, preventing the UI from flickering or performing unnecessary intermediate updates. This is crucial for performance when a single user interaction triggers a sequence of related state changes that should be treated as a single unit of work.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'133d76de-7143-4f47-b092-fe658acacda6', N'd5b12859-0c9f-4e2f-9b3a-1ccb6c5080e5', N'What is a connection pooler and how does it help with database scaling?', N'Middle', N'A connection pooler maintains a cache of open database connections that can be reused for subsequent requests. This reduces the overhead of creating and destroying connections for every request, allowing the database to support more concurrent users.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7feabde1-7e8c-4ee2-a7ea-fe6b9b9e3899', N'a2838158-7305-480a-b22b-4dc35776b400', N'What is a distributed lock and when is it necessary?', N'Middle', N'A distributed lock is a mechanism to coordinate access to a shared resource across multiple nodes in a system. It is necessary in scenarios where concurrent updates to the same data could lead to race conditions or data corruption.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ee287fb7-9cc4-4999-9624-fe6d52c0625a', N'4c000000-0000-0000-0000-000000000005', N'What is database indexing and how does it affect system performance?', N'Middle', N'Indexing is a data structure technique that speeds up data retrieval operations on a database table at the cost of slower write performance and increased storage. Effective indexing is essential for high-performance read operations but must be balanced against the overhead of maintaining indices during updates.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a2e8c143-fb5b-44ab-a8dd-fe6d7e86f9bb', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'Why use ''Embedded Schemas'' in Ecto?', N'Middle', N'Embedded schemas allow you to define structured data that lives inside a JSONB column in a database. They are useful for storing complex, nested attributes without creating separate tables, while still benefiting from Ecto''s casting and validation features.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3f906a45-eedb-4ea8-9148-fe6f2228eeb6', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'Why is SEO better in Next.js compared to a standard React app?', N'Fresher', N'Because Next.js renders content on the server, search engine crawlers receive the complete HTML immediately. In a standard client-side React app, the crawler might see an empty page before the JavaScript executes, which can hinder indexing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd9b5c99f-db99-4424-9b34-fe75b3543d63', N'f2e963ff-7635-4429-a389-4d92535fb972', N'How does the ''inputmode'' attribute affect the mobile user experience?', N'Senior', N'Inputmode informs the mobile browser which virtual keyboard layout to display to the user, such as numeric, email, or URL specific keys. This significantly reduces user friction and input errors compared to a generic text keyboard, improving overall form conversion rates.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'31d4aa2c-d26e-4b19-9781-fe791bca4b85', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'How would you handle high-latency database operations within a Rocket handler to avoid blocking the executor?', N'Senior', N'You must offload blocking I/O operations to a dedicated thread pool using specialized blocking tasks provided by the async runtime. This prevents the primary request-handling threads from stalling, ensuring the server remains responsive to other incoming traffic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'87aa6234-0acc-48f4-8d94-fe7b20ee2e03', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'When should you ask for help during a task?', N'Fresher', N'I ask for help when I have spent a reasonable amount of time investigating, documenting my steps, and trying different hypotheses without success. Being stuck on a problem for too long without progress is inefficient, so asking for guidance is a professional way to unblock myself. I always explain what I have already tried so the person helping can avoid repeating my steps.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1a76fe85-2c7f-4057-bf0d-fe7b4a2328af', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'What is a Case Class?', N'Intern', N'A Case Class is a special type of class that is optimized for use with pattern matching and immutable data. It automatically generates useful methods like equality checks, string representations, and copy constructors.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
