INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8b057f99-2293-4c95-8904-fe7e9df01377', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'What is the difference between ''render'' and ''redirect''?', N'Intern', N'Render displays a view template without changing the browser''s URL, keeping the current request cycle intact. Redirect sends an instruction to the browser to make an entirely new request to a different URL.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
