INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'eb027809-5fb5-4c77-9a4a-fe9e0d4a04d3', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'What is the purpose of a header file?', N'Junior', N'Header files are used to declare classes, functions, and variables, providing an interface that other parts of the program can include. They allow multiple source files to share common definitions without needing to redefine them in every location.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'46c06757-2705-4919-ad6a-fea126c51cb6', N'074508f7-35bd-405f-8cc6-b41377b2d92c', N'Why would you choose an asynchronous messaging pattern over synchronous HTTP REST calls for inter-service communication?', N'Middle', N'Asynchronous messaging decouples services, allowing the producer to continue processing without waiting for the consumer to finish. It improves system resilience by providing a buffer during traffic spikes and allows for easier horizontal scaling of individual components.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7badc0d5-3061-4104-839e-fea31c6249af', N'f2e963ff-7635-4429-a389-4d92535fb972', N'What is the significance of the ''viewport'' meta tag in the context of mobile optimization?', N'Senior', N'The viewport meta tag provides instructions to the browser on how to control the page''s dimensions and scaling on mobile devices. Without it, browsers often render the page at a desktop width and then scale it down, resulting in poor readability and necessitating intrusive user zooming.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'de6e6742-4124-4873-b68d-fea42dd36e3a', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'What is a docstring?', N'Intern', N'A docstring is a documentation string that we use to explain what a construct does. We place it as the first thing under a function, class, or a method, to describe what it does. We declare a docstring using three sets of single or double quotes. Hi To get a function''s docstring, we use its doc attribute. ''\n\tThis function prints Hi\n\t'' A docstring, unlike a comment, is retained at runtime.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ef824d5d-eada-465c-885a-fea9a59192db', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'How does the Laravel Service Container manage class dependencies?', N'Middle', N'The Service Container is a powerful tool for managing class dependencies and performing dependency injection. It resolves objects by automatically injecting their required dependencies through the constructor or methods, allowing for decoupled and testable code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'802d075b-167b-44d2-8309-feabdfd1d7b0', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'What is the impact of Vite''s ''experimental'' features on build stability?', N'Senior', N'Experimental features in Vite often involve advanced optimizations or new integration patterns that may not have full plugin support or stable APIs. In a production-critical environment, relying on these features requires rigorous testing, as they may undergo breaking changes in minor updates.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'43b3eef0-19b6-4bc3-b3a8-feae0928b2b3', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'What is a Sort Key in DynamoDB?', N'Intern', N'A sort key is the second part of a composite primary key. It allows you to store and query related items together, organized by the sort key value, which enables efficient range queries.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8ef101d7-3bc0-4a14-a6c8-feaeb87f536b', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'How do you ensure data integrity across multiple microservices without distributed transactions?', N'Senior', N'Implement the Saga pattern using either choreography or orchestration to manage distributed business processes. This approach handles failures through compensating transactions, ensuring eventual consistency without the locking overhead of two-phase commits.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fec2e1f4-3f01-4754-9ed1-feb982c4b240', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'What is the purpose of the ''axum::body::Body'' type?', N'Intern', N'The Body type represents the stream of data associated with an HTTP request or response. It is a fundamental type that allows Axum to handle both small payloads and large streaming data efficiently.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'850d9db9-9551-46ca-ac0c-feba54608fe7', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'How do namespaces help in managing large C++ codebases?', N'Middle', N'Namespaces provide a mechanism to encapsulate identifiers, preventing naming collisions between different libraries or modules. They allow developers to group related functionality and manage scope effectively without polluting the global namespace.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dc81fbce-e632-4b8a-be17-febd60bad1a7', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'Explain how Redis handles memory allocation and the risks of memory over-provisioning.', N'Senior', N'Redis relies on the operating system''s memory management; if the system runs out of physical RAM, it may swap memory to disk, leading to catastrophic latency increases. Proper capacity planning must include a buffer for memory overhead, such as fragmentation and replication buffers, to avoid swapping.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f898d715-7845-4d5e-bc22-febe9380912b', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'What does it mean for Hono to be ''runtime agnostic''?', N'Intern', N'Being runtime agnostic means Hono is not tied to a specific JavaScript engine or environment like Node.js. It uses standard Web APIs, allowing the same code to run seamlessly across different platforms like Cloudflare Workers, Fastly Compute, Bun, and Deno.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fc6dee16-db97-40d5-b750-febeb372296e', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'How does technical debt impact your ability to estimate future tasks?', N'Junior', N'Technical debt adds overhead to every new task because it often requires extra time for refactoring or working around brittle code. I incorporate the expected time to address or navigate this debt into my estimates to ensure they remain realistic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'823704d6-8ffd-4f0f-a7d2-febef57fe8bb', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'What does it mean for Java to be a strongly typed language?', N'Intern', N'Being strongly typed means that the Java compiler enforces strict rules regarding data types to prevent type errors. Every variable must be declared with a specific data type, and the language does not allow implicit conversions between incompatible types. This feature helps developers catch potential bugs during the compilation phase rather than at runtime.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bb5b5a74-b52e-4c8f-b664-fec1cc892808', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'How does the ''sync.Pool'' implementation mitigate GC pressure?', N'Senior', N'sync.Pool provides a mechanism to cache and reuse allocated objects that would otherwise be garbage collected. This reduces the allocation rate in high-throughput systems, thereby lowering the frequency and duration of garbage collection cycles.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'adaffc97-4dfe-4985-a93b-fec3c6b868d6', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'Discuss the trade-offs of using ClassLoaders to achieve modularity.', N'Senior', N'Custom ClassLoaders allow for isolation and dynamic loading of components, enabling complex frameworks like OSGi or plugin architectures. However, they introduce significant complexity, potential for class-cast exceptions due to namespace conflicts, and memory leaks if classloader instances are not garbage collected properly.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ad351ac2-2226-4348-9d67-fec51214e3f2', N'fcd5873e-c89a-47d6-bb4c-c60b57c2ede1', N'Explain the concept of API Gateway.', N'Middle', N'An API Gateway acts as a single entry point for a group of microservices, managing requests by routing, rate limiting, and authentication. It simplifies the client-side experience by abstracting the internal service structure and providing a consistent interface.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ad96e0aa-e138-47fc-8de7-fec5898c8d08', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is difference between Classic Inheritance and Prototypical Inheritance?', N'Fresher', N'1. Class Inheritance: Instances inherit from classes (like a blueprint — a description of the class), and create sub-class relationships: hierarchical class taxonomies. Instances are typically instantiated via constructor functions with the new keyword. Class inheritance may or may not use the class keyword from ES6. 2. Prototypal Inheritance: Instances inherit directly from other objects. Instances are typically instantiated via factory functions or Object.create(). Instances may be composed from many different objects, allowing for easy selective inheritance. Features * Classes: create tight coupling or hierarchies/taxonomies. * Prototypes: mentions of concatenative inheritance, prototype delegation, functional inheritance, object composition.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5a08a23f-ee2b-4504-891f-fec8fbc967db', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'What is a default value in a database?', N'Intern', N'A default value is a pre-defined value that is automatically inserted into a column if no value is provided during a record creation. This helps ensure that critical fields are populated even if the user provides no input.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fd0d942b-0ad6-49bb-a8e8-fec948ba94b5', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'Explain the trade-offs of using PHP attributes (annotations) for metadata configuration.', N'Middle', N'Attributes allow developers to embed metadata directly into code, which improves readability and keeps configuration close to the relevant logic. However, over-reliance on attributes can make the code harder to trace, as the behavior triggered by those attributes is often hidden in framework-level reflection logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6181b848-439b-4638-9b5c-feca655af2c4', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'What is the benefit of ''Live Coding'' in Quarkus?', N'Fresher', N'Live Coding allows developers to see the effect of their code changes immediately without waiting for a manual rebuild or application restart. This creates a highly productive feedback loop during the development process.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a7263988-356d-4da0-b72d-fecb1e0399ad', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'How do JVM intrinsic methods influence the execution of standard library code?', N'Senior', N'Intrinsics are hand-optimized, platform-specific machine code sequences that replace calls to standard library methods like System.arraycopy or Math.sin. By bypassing the generic bytecode, these methods allow the JVM to perform operations at hardware-level efficiency that would be impossible to achieve through pure Java code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5769ce7f-3220-4b0d-8a75-fecd81f22f17', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'What is the purpose of the ''debug'' tag in Svelte?', N'Junior', N'The {@debug} tag allows you to inspect the state of variables in the browser console. It triggers a debugger statement whenever the variables listed inside it change.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6e09648b-0825-4a30-b04f-fecd9df15ac6', N'9a0e3785-3b73-4abc-ab01-df75bf097dff', N'Explain the concept of ''Eventual Consistency'' and why it is necessary in microservices.', N'Senior', N'Eventual consistency acknowledges that in a distributed system, achieving global state consistency via strong ACID transactions is blocked by the CAP theorem''s trade-off between consistency and availability. By accepting eventual consistency, you favor higher availability and partition tolerance, using reconciliation processes to ensure data converges over time.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f0c67e3c-ce19-478d-8f8f-feced64e76b8', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'What is the difference between a mutex and a channel?', N'Junior', N'A mutex is a low-level synchronization primitive used to protect shared data by ensuring only one goroutine accesses it at a time. Channels are higher-level tools designed for passing data between goroutines to coordinate their work.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9b36af28-81d4-4ae9-a23d-fecefd422a7a', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'Explain the concept of ''batching'' in SolidJS and why it is critical for performance.', N'Senior', N'Batching ensures that multiple signal updates are processed together, triggering observers only once at the end of the execution block. This prevents unnecessary intermediate DOM updates or redundant side effects when multiple related pieces of state change simultaneously.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fa9424d5-0c37-4538-8261-fed06d747815', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'What is the significance of the self keyword in Ruby?', N'Middle', N'The ''self'' keyword refers to the current object executing the code. Its value changes depending on the context; inside an instance method it refers to the instance, while inside a class definition it refers to the class object itself.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'24801ecf-07a1-4033-b55e-fed39b51ea23', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'Explain the architectural trade-offs of using Echo''s ''Context'' object compared to standard ''http.Request'' and ''http.ResponseWriter''.', N'Senior', N'The Echo Context provides a unified interface for data access and response writing, which improves developer productivity and reduces boilerplate. However, it introduces a dependency on the framework''s abstractions, making it harder to swap the underlying server engine or integrate with libraries expecting raw standard library interfaces.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bb3709e3-9b17-451d-9d78-fed40af368a5', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'What are ''Control Flow'' components in SolidJS and why are they preferred?', N'Middle', N'Control flow components like For, Show, and Switch are specialized components used for conditional rendering and lists. They are preferred because they provide efficient, granular updates to the DOM without re-rendering the parent component or recreating existing DOM elements.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0daeb705-0c43-4cb0-9f5f-fed4ad87d69a', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'Explain the ''import.meta.glob'' feature and its impact on build performance.', N'Senior', N'This feature allows dynamic importing of multiple files based on patterns, which is essential for tasks like automated route generation or dynamic component loading. During build, Vite statically analyzes these globs to generate efficient code-split chunks, ensuring that only the necessary modules are loaded at runtime.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'918dd329-4ccc-44c1-b56f-fed649c938d6', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'Explain the significance of the `loading.js` file convention in the App Router.', N'Senior', N'The `loading.js` file automatically wraps the page content in a React Suspense boundary. It simplifies the implementation of loading states by allowing developers to define a UI that appears immediately while the underlying route segment is still fetching data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fcedee77-f0dd-4340-a673-fed7ba9c395a', N'075b8862-431c-4678-9767-f55359758a4a', N'How do you test a Vue component?', N'Middle', N'Testing typically involves using tools like Vue Test Utils and Vitest to mount components and simulate user interactions. Tests should focus on verifying the rendered output, component state changes, and emitted events rather than internal implementation details.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'90a0aed1-420a-4972-8bc5-feda312ca9f7', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'What is the purpose of the ''Injectable'' decorator?', N'Junior', N'The Injectable decorator marks a class as a provider that can be managed by the Nest IoC container. It tells NestJS that this class is a dependency that can be injected into other classes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6c99558a-fadb-4144-b35b-fedd905f7ad8', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'Explain the concept of ''Library Mode'' in Vite and when you would use it.', N'Senior', N'Library Mode is designed for building packages meant to be consumed by other projects. It configures Vite to output formats like UMD or ESM, disables HTML generation, and ensures that external dependencies are not bundled into the library itself.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2f3f48c5-b6d8-4c87-b190-fee16fb2fc36', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'What are higher-order functions in Swift?', N'Junior', N'Higher-order functions are functions that take other functions as arguments or return a function as their result. Common examples include map, filter, and reduce, which are used to process collections efficiently.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd02b145f-2b62-414a-b21c-fee3a98a6056', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'How do you optimize the Service Container for production environments?', N'Senior', N'Optimization involves dumping the container into a highly efficient, cached PHP file that eliminates the overhead of parsing YAML or XML files. Additionally, disabling debug mode and using autowiring with strictly defined interfaces prevents unnecessary runtime reflection.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f0272a79-7d0d-4d9c-b694-fee408698abc', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'What is a primary key in Cassandra?', N'Intern', N'A primary key in Cassandra consists of a partition key and an optional set of clustering columns. The partition key determines the node location, while clustering columns determine the sorting order of data within that partition.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'13803f5e-e21c-4501-9751-fee41d2ebf20', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'How does Vite differ from traditional bundlers like Webpack?', N'Intern', N'Traditional bundlers process the entire application before starting the server, which can be slow as the project grows. Vite leverages native browser ES modules to serve files on demand, allowing the server to start almost instantly regardless of project size.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'39071d6f-cbaf-4056-9e54-fee6dd564ccb', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'Why Use JSX in 2026?', N'Fresher', N'* Ecosystem Alignment: The entire React ecosystem (Server Components, Suspense, Hooks) is built around JSX. Deviating from JSX restricts access to the latest framework features and community-maintained UI libraries. * Compile-Time Verification: JSX allows build tools to detect missing props or invalid tag structures before the code ever reaches the browser, drastically reducing runtime errors. * Declarative Consistency: JSX provides a unified language for both Client Components and React Server Components (RSC), allowing for a seamless transition between server-side rendering and client-side interactivity. * Tooling Optimization: The 2026 build stack is optimized specifically for JSX.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a4676fc5-2096-4f3e-9292-fee82142d473', N'8d34dfc0-4a64-4128-b41a-cafa62ddad41', N'What is the purpose of a Bastion host in network architecture?', N'Middle', N'A Bastion host is a hardened server that serves as the only point of entry into a private network from an external network. It acts as a gateway, providing a controlled and audited channel for administrators to access internal resources securely.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'602a2fc0-4152-4ec8-8295-fee8f13a271d', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'What is a NoSQL database?', N'Intern', N'NoSQL databases are non-relational data management systems that do not use a fixed table structure. They are designed to handle large volumes of unstructured or semi-structured data and offer high flexibility and scalability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c6989cfe-8f4c-424f-a417-fee92acaaeec', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'What is the difference between a database and a table?', N'Intern', N'A database is an organized collection of structured information or data, typically stored electronically. A table is a specific object within that database that holds data in a grid format consisting of rows and columns.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'885b82b1-10f9-434e-b099-feea69235fe0', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is an Unary operator', N'Intern', N'The unary(+) operator is used to convert a variable to a number.If the variable cannot be converted, it will still become a number but with the value NaN. Let''s see this behavior in an action.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c5176cde-f334-4fcd-918a-fef8bdc8a00c', N'55404b9c-91b6-4b62-9dc7-63248e8ea1df', N'How does ''Database Denormalization'' impact read scalability in a high-traffic environment?', N'Senior', N'Denormalization reduces the need for complex, expensive joins by storing pre-computed or redundant data in a single table. While this increases storage requirements and update complexity, it significantly improves read performance by minimizing the number of lookups required per request.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dc46fb72-fad4-4ce8-87d8-fefa2cc75d56', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'Explain the role of the ''load'' function in SvelteKit and its trade-offs regarding data fetching.', N'Senior', N'The load function is a server-side or universal function that prepares data for a route before it renders. The primary trade-off is the balance between server-side latency and client-side data fetching; running it on the server prevents waterfalls and improves SEO, but universal load functions may run on both, requiring careful handling of sensitive server-side logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ecf179f0-f245-4f3c-8171-fefbd36c5026', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'What are the limitations of Echo''s context binding when dealing with multi-part form data in large file uploads?', N'Senior', N'Echo''s binding mechanism for multi-part data can be memory-intensive because it may load parts of the request into memory before processing. For large file uploads, it is often more efficient to use raw standard library request parsing to stream data directly to storage, bypassing the overhead of the binding reflection.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a2fc8e88-28e0-4daa-b741-fefcce71be7b', N'9a0e3785-3b73-4abc-ab01-df75bf097dff', N'How do you manage configuration across a large number of microservices?', N'Senior', N'Use a centralized configuration store that supports dynamic updates, such as Consul, Etcd, or environment-specific secret managers. These tools allow for configuration injection at runtime without requiring code changes or redeployments, while maintaining strict security for sensitive credentials.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'44c1be26-ffc7-44be-9b0b-ff02348ab31b', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'What is the primary difference between a Class and an Object in Java?', N'Fresher', N'A class is a blueprint or template used to create objects, defining the properties and behaviors that the objects will have. An object is an actual instance of a class that occupies memory and holds specific values for the properties defined in the class.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'34ad2da1-8af0-462a-bcb7-ff0290fd96fd', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'Why is it generally recommended to avoid using ''@import'' within CSS files in production?', N'Senior', N'The @import rule forces the browser to download files sequentially, creating a blocking chain that delays the discovery of further resources. Unlike link tags, which allow parallel downloading of stylesheets, @import prevents the browser from optimizing the critical rendering path effectively.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'709ff937-d748-4be5-bae7-ff060e783e68', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'What is the ''utility-first'' philosophy in the context of design consistency?', N'Middle', N'The utility-first philosophy relies on a strict set of design tokens—such as spacing, colors, and typography scales—defined in the configuration. By forcing developers to use these pre-defined values rather than arbitrary pixel values, the project naturally maintains a consistent visual language.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'45fff0ce-44ce-494f-841c-ff06217bc258', N'a2838158-7305-480a-b22b-4dc35776b400', N'How do bloom filters help in query performance?', N'Middle', N'A bloom filter is a space-efficient data structure used to test whether an element is a member of a set. It can provide a definitive ''no'' quickly, allowing a system to skip unnecessary database lookups or disk reads for items that definitely do not exist.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd8fdafea-8cdf-4ce0-9992-ff092f0280cc', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'What is a mixin in Ruby?', N'Intern', N'A mixin is a way to achieve multiple inheritance-like functionality by including modules into a class. By including a module, all the methods defined in that module become available to the class as if they were its own.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a4329e3a-127c-4d80-8a89-ff09df00f587', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'Why is Actix considered high-performance?', N'Fresher', N'Actix is high-performance because it is built on the Rust language, which provides zero-cost abstractions and manual memory management without a garbage collector. Additionally, its asynchronous design minimizes overhead and maximizes CPU efficiency during high-concurrency tasks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dfaa4ece-4060-46e4-9ef7-ff139fe3e808', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'What is the difference between ''Signal'' and ''Store'' in terms of reactivity granularity?', N'Senior', N'A Signal provides a single value with direct subscription, while a Store is a nested reactive object that allows for fine-grained updates to deep properties. Stores are designed to handle complex state trees by tracking access to specific sub-properties, enabling localized updates without re-triggering the entire object''s observers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'98c540c8-911b-400b-b050-ff13db40e339', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'What is a route handler in Fastify?', N'Intern', N'A route handler is the function that contains the core logic for processing a specific request path and HTTP method. It receives the request and reply objects as arguments and is responsible for returning the response.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd9e84129-d69b-4025-b116-ff1df028b7cd', N'4c000000-0000-0000-0000-000000000005', N'Why is idempotency important in distributed systems?', N'Middle', N'Idempotency ensures that performing the same operation multiple times results in the same state as performing it once. This is crucial for handling retries in network communication, preventing side effects like double-charging a customer or duplicate record creation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'75dd2435-26e1-4de5-aeb5-ff1e6da35da4', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'What are the ACID properties in database management?', N'Fresher', N'ACID stands for Atomicity, Consistency, Isolation, and Durability. These properties ensure that database transactions are processed reliably, maintaining data integrity even in the event of errors, power failures, or crashes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'22538211-2e21-4a7b-a161-ff1f298a6f2b', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'How does Kotlin''s delegation pattern work?', N'Middle', N'Delegation allows a class to delegate specific functionality to a secondary object instead of implementing it itself. Using the ''by'' keyword, Kotlin provides native support for property and class delegation, reducing boilerplate and promoting composition over inheritance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
