INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e3eade27-58dd-405f-857b-ff1ffcbd88c9', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'How does the ''PropertyDeclaration'' interface help with performance?', N'Middle', N'It allows developers to define options for properties like ''attribute'', ''reflect'', and ''converter''. By specifying these, Lit avoids unnecessary work, such as reflecting properties that do not need to be synced to the DOM.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'137b7b58-741c-4f70-ae62-ff24748368c3', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'How does Next.js handle metadata?', N'Intern', N'Next.js provides a built-in metadata API that allows you to define page titles, descriptions, and Open Graph tags. This makes it easy to manage SEO information for individual pages in a centralized way.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fa25158e-f576-48bd-84e4-ff24b5632600', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'What is an Entity in the context of Doctrine ORM?', N'Junior', N'An Entity is a plain PHP object that represents a row in a database table. Doctrine maps the properties of these objects to columns in the database, allowing developers to interact with database records using object-oriented code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'76ed8dd5-2380-4918-b6ae-ff2841c61d58', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'What are the trade-offs between using a generator and a list for large datasets?', N'Middle', N'Generators produce items on demand using lazy evaluation, which keeps memory usage low regardless of dataset size. In contrast, lists load all elements into memory at once, which is faster for repeated access but risks memory exhaustion for very large data collections.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'23434a55-ab30-436a-82fa-ff2c25a3e4b5', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'What is the difference between ''as?'', ''as!'', and ''as'' in Swift?', N'Fresher', N'The ''as'' operator is for safe upcasting, ''as?'' performs a conditional cast that returns an optional, and ''as!'' performs a forced cast that triggers a runtime error if the cast fails. Use forced casting only when you are certain the type conversion will succeed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f732bc81-86bb-4cbd-b7a7-ff2c7fd8d2cf', N'954a0331-deff-4399-b588-96f39fec001d', N'What is the difference between OnPush and Default change detection strategies?', N'Middle', N'The Default strategy checks the entire component tree for changes whenever any asynchronous event occurs. The OnPush strategy optimizes performance by only triggering change detection when an input reference changes, an event originates from the component, or an observable emits a value via the async pipe.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'de6f29aa-3721-4c3c-873e-ff2cad5afd2e', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'What are the trade-offs of implementing a caching layer in front of a database?', N'Junior', N'Caching drastically improves read performance and reduces database load, but it introduces the risk of data inconsistency. You must carefully manage cache invalidation strategies to ensure users do not see stale or incorrect information.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6e025d10-49c6-4182-acea-ff31b948e83d', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'How does Chi manage resource constraints during high-load scenarios?', N'Senior', N'Chi''s lightweight footprint ensures that the router itself does not consume significant CPU or memory, allowing the Go scheduler to prioritize goroutines processing actual business logic. When combined with request timeout middleware, it prevents runaway requests from exhausting server resources.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2555d6c2-9068-4d9e-99b8-ff326e5185fc', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'Explain the architectural trade-offs of using a single-threaded event loop compared to a multi-threaded model for I/O-bound operations.', N'Senior', N'The single-threaded event loop eliminates overhead from context switching and lock contention, leading to high throughput for I/O-bound tasks. However, it requires non-blocking primitives to avoid stalling the entire process, and it cannot leverage multi-core CPUs for CPU-bound tasks without offloading to worker threads or clusters.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'99610d8d-5dfa-4091-bba9-ff32945b4584', N'954a0331-deff-4399-b588-96f39fec001d', N'Describe the function of an Angular module (NgModule) and why it is used.', N'Middle', N'An NgModule acts as a container that groups related components, directives, pipes, and services into a cohesive functional unit. It defines the compilation context and manages the visibility of these elements through exports and imports.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ef56441c-9e25-4ed8-af5d-ff38021e78bd', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'What is ''hot module replacement'' (HMR) and how does it differ from a standard live reload?', N'Middle', N'HMR updates modules in the browser during runtime without requiring a full page refresh. Unlike a standard live reload, which reloads the entire application and discards the current state, HMR preserves the application state while injecting the updated code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e00cd08b-cd8d-4dfd-b9a0-ff38879887ef', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'Discuss the trade-offs of using a database-level trigger versus application-level logic for data validation.', N'Senior', N'Triggers ensure data integrity regardless of the source of the write but can become hidden bottlenecks and make debugging difficult. Application-level logic is more scalable, easier to test, and version-control-friendly, but it risks data corruption if multiple services write to the database without enforcing the same rules.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2236feb3-e917-4f9a-b46d-ff38da294a49', N'074508f7-35bd-405f-8cc6-b41377b2d92c', N'What is the purpose of an ''idempotency key'' in a messaging-based system?', N'Senior', N'An idempotency key allows a consumer to track whether a message has already been processed successfully, preventing duplicate effects from multiple deliveries of the same message. It is essential when the system guarantees at-least-once delivery but the business logic requires exactly-once state changes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4228dd53-f355-4e14-bd03-ff3ccc880ecb', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'When estimating, how do you handle the risk of ''optimism bias''?', N'Fresher', N'Optimism bias is the tendency to assume everything will go perfectly, leading to underestimation. I counter this by explicitly listing potential risks or obstacles and considering the ''worst-case'' scenarios. By consciously factoring in time for common interruptions, I can produce a more balanced and safer estimate.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1dfe1bfe-e923-41be-b648-ff3eb06ec26c', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'What is the scope of a local variable?', N'Fresher', N'The scope of a local variable is restricted to the block or function in which it is declared. It is created when the block is entered and destroyed automatically when the block is exited.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3e6a8d32-40de-45b2-a43f-ff4465869537', N'd5b12859-0c9f-4e2f-9b3a-1ccb6c5080e5', N'What is the difference between active-active and active-passive database setups?', N'Middle', N'In active-passive, only one node handles writes while the other stands by as a failover. In active-active, multiple nodes handle writes simultaneously, which increases availability but introduces significant complexity regarding conflict resolution and data synchronization.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e2fcffee-9595-4ddf-9605-ff44731fbbce', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'Why might you use a ''Problem Details'' response for API errors?', N'Middle', N'Problem Details is an IETF standard for representing error information in HTTP API responses. It provides a consistent, machine-readable format for clients to understand what went wrong, including error types, titles, status codes, and trace identifiers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'40aa3e95-2d5b-4d5e-9b5b-ff44dfe7003b', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'When would you prefer Svelte over a framework like React in a professional project?', N'Middle', N'Svelte is an excellent choice for performance-critical applications, projects with small bundle size requirements, or teams that prefer a less verbose syntax. Its lower learning curve and reduced boilerplate can lead to faster development cycles for many developers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
