INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f259021a-3ed5-4b85-8c9a-ff4a08c6025a', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'How do you evaluate the trade-off between developer velocity and code quality?', N'Senior', N'I view these as dynamic vectors rather than static opposites; high code quality is a prerequisite for long-term velocity. I advocate for automated testing and CI/CD pipelines to maintain quality standards without manual intervention, thereby ensuring that shipping speed does not compromise system stability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a89c597b-70d2-43b6-a927-ff4c559905fa', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'What is the event modifier in Alpine.js?', N'Intern', N'Event modifiers are suffixes added to directives like x-on that change the behavior of the event listener. Examples include .prevent to stop the default behavior or .stop to prevent event bubbling.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e9d2eed9-f24a-4a34-8b81-ff4d4a69b9a6', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'How does Go handle errors compared to languages with exception handling?', N'Junior', N'Go treats errors as values rather than exceptions. Instead of using try-catch blocks, functions typically return an error as the last return value, which the caller is expected to check explicitly.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'936e96c3-03b9-42e8-b231-ff4f0a68adab', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'How do you ensure you are not repeating the same mistakes?', N'Fresher', N'I keep a personal journal or log of challenges I have faced and how I resolved them. By reflecting on these experiences, I can identify patterns in my work and apply lessons learned to avoid similar pitfalls in the future.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'91baa4fb-4573-4f07-b5f7-ff504e76eca6', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'What is referencing in MongoDB?', N'Intern', N'Referencing involves storing the ID of one document inside another to create a relationship, similar to a foreign key in SQL. This is useful for normalizing data and avoiding the duplication of information across multiple documents.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a1fd3861-caf2-44ee-b1c5-ff532c79cc91', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'What is the _source field in an Elasticsearch document?', N'Fresher', N'The _source field stores the original JSON document that was indexed. It allows you to retrieve the full content of the document when searching without needing to query a separate database.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
