INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'facb843c-52a4-44f7-85dc-ff57521d4783', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'What is the purpose of the @Recover annotation?', N'Fresher', N'The @Recover annotation is used to define fallback methods for a service. If a method fails or throws an exception, the framework can automatically invoke the recovery method to provide a default value or alternative logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1427b046-f9dd-4eaa-84f8-ff57b6347fca', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'What is your approach to logging and monitoring in a production system?', N'Junior', N'I ensure that logs are centralized and structured to make searching and filtering efficient during incidents. I set up monitoring and alerts for key performance indicators like error rates, latency, and resource usage so that issues are detected and addressed before they significantly impact users.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2ca9a5ae-3f44-4647-bdf2-ff582ec23857', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'What is the fundamental difference between SQL and NoSQL databases regarding their data structure?', N'Fresher', N'SQL databases are relational and use structured schemas with tables, rows, and columns to organize data. In contrast, NoSQL databases are non-relational and use flexible data models such as documents, key-value pairs, graphs, or wide-column stores, allowing them to handle unstructured or semi-structured data more efficiently.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bf3e7382-0edb-463b-847f-ff583976e665', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'What is the significance of the 10GB partition size limit?', N'Senior', N'The 10GB limit defines the physical boundaries of a partition; once data exceeds this, DynamoDB triggers a split to maintain performance. This constraint ensures that no single physical node becomes overwhelmed by excessive data volume or query load.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1a97d566-7259-40ff-8546-ff58b1028f3b', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'What are attributes in R?', N'Intern', N'Attributes are metadata attached to R objects that provide additional information about the object. Common attributes include names, dimensions, and classes, which describe how the object should be interpreted.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f7d2e9a2-f75b-40b7-b119-ff5aea7168da', N'd5b12859-0c9f-4e2f-9b3a-1ccb6c5080e5', N'Why would you use read replicas in a database architecture?', N'Middle', N'Read replicas allow you to offload read-heavy traffic from the primary database node to secondary instances. This improves overall system throughput and read performance while providing a level of redundancy for failover scenarios.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b6db52d2-567d-4273-93f5-ff5d14846ce5', N'd5b12859-0c9f-4e2f-9b3a-1ccb6c5080e5', N'What is the role of a load balancer in database scaling?', N'Middle', N'A load balancer distributes incoming queries across multiple database instances to ensure no single node is overwhelmed. It helps in managing traffic spikes and provides a mechanism to route traffic away from failing nodes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fc1c1ccb-b52c-4a1d-b99f-ff5d794956aa', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'What is a route parameter in Fiber?', N'Intern', N'A route parameter is a dynamic segment of a URL path defined with a colon prefix, such as :id. Fiber allows developers to extract these values directly from the request context to identify specific resources.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
