INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a1aa42a3-c811-452e-9e86-ff76c9559de4', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What is the main purpose of using TypeScript instead of plain JavaScript?', N'Junior', N'TypeScript introduces static typing to JavaScript, which allows developers to define the types of variables, function parameters, and return values. This helps catch potential errors during development before the code is even executed, leading to more reliable and maintainable applications.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'20484cb7-7f16-4017-be08-ff77cb82b489', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'How do you decide if an estimate is ''good enough'' for a given scenario?', N'Intern', N'The quality of an estimate depends on the cost of being wrong versus the cost of getting a more precise number. If the decision being made is low-stakes, a quick ''back-of-the-envelope'' calculation is sufficient, but if the decision involves significant resources, more time should be invested in gathering data and refining the calculation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'340173f4-2e9d-49b1-8c9f-ff7b93b93d9a', N'075b8862-431c-4678-9767-f55359758a4a', N'What is the difference between ''computed'' properties and ''watchers'' regarding execution flow and side effects?', N'Senior', N'Computed properties are declarative, cached, and intended to derive new data from existing state without side effects. Watchers are imperative, designed to handle asynchronous operations or perform side effects in response to specific data changes, making them unsuitable for pure data derivation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
