INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'82b178db-6387-4887-a32e-ff7e239b7d89', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'What are Alpine.js transitions?', N'Junior', N'Alpine.js provides transition directives that allow you to easily add CSS-based animations when an element is shown or hidden. By using x-transition, you can define the entering and leaving states of an element to create smooth visual effects.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8dd43bef-c811-46c0-835f-ff845652962a', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'Explain the difference between ''Leader-based'' and ''Leaderless'' replication.', N'Middle', N'In leader-based replication, one node handles all writes and propagates them to followers, ensuring a clear source of truth. In leaderless replication, clients write to multiple nodes simultaneously, which increases write availability but introduces complexity in resolving conflicts during reads.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'501f7cba-b86f-405d-8ee8-ff8460174b55', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'What is the Oplog in MongoDB?', N'Intern', N'The Oplog (operations log) is a capped collection that stores a rolling record of all operations that modify the data stored in the database. It is essential for replication, as secondaries use it to synchronize their data with the primary.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'edf813d2-ca89-432f-9fc9-ff85446518ef', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'How does Rocket handle static files?', N'Intern', N'Rocket includes built-in support for serving static files, such as images, CSS, or JavaScript files. You can mount a specific directory to a URL path, and Rocket will automatically serve files from that folder.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'87d8d5c2-b986-47c8-a2cc-ff88933eb6d5', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'How does Micronaut achieve fault tolerance in microservices without external dependencies?', N'Senior', N'Micronaut provides built-in support for resilience patterns such as retries, circuit breakers, and fallbacks using the @Retryable and @CircuitBreaker annotations. These are implemented via compile-time proxies, ensuring minimal performance overhead compared to runtime aspect-oriented programming.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'55e377d9-baa8-4119-a74f-ff8dbc8d3f8c', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'How does Tailwind impact the readability of HTML templates for developers not familiar with the framework?', N'Senior', N'For uninitiated developers, the initial learning curve and the visual noise of long class strings can hinder readability. This is typically addressed by adopting component-based architectures where the utility-heavy markup is hidden within reusable UI components.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0fe927d3-7dfc-4a06-a6b1-ff91e8d78b69', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'What does the ''willUpdate'' lifecycle hook do?', N'Intern', N'The willUpdate method is called before the component updates its DOM. It is useful for performing calculations or state changes based on property updates before the rendering occurs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd826d3f7-f130-43fd-a4ac-ff92404e3369', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'How do ''C Extensions'' affect the portability and stability of a Ruby application?', N'Senior', N'C extensions allow Ruby to interface with native libraries for performance or OS-level access, but they bypass the safety and memory management guarantees of the Ruby VM. They can introduce segmentation faults and make the application dependent on specific platform architectures, complicating deployment and maintenance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'90eeb121-34f2-4697-9786-ff93ac4dfae0', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'Describe your approach to disaster recovery for a mission-critical system.', N'Senior', N'I would define Recovery Time Objectives (RTO) and Recovery Point Objectives (RPO), then implement a multi-region active-passive or active-active strategy. Regular, automated drills are essential to ensure that failover processes work as expected and that backups are restorable.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3550b5dd-0d20-4c58-8899-ff947240f9ad', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'What are the performance implications of using complex Pydantic models?', N'Middle', N'Extremely complex Pydantic models with deep nesting or custom validators can increase CPU overhead during request parsing and response serialization. While usually negligible, for high-throughput services, it is best to keep models flat and minimize expensive validation logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'61b6b4c9-1e20-4dc0-9bc5-ff94eee1322a', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'What are the architectural considerations when choosing between Streams and ChangeNotifier for state management?', N'Senior', N'Streams provide a robust, reactive abstraction for event-driven data flow across multiple listeners, which is ideal for complex asynchronous data pipelines. Conversely, ChangeNotifier is a lightweight, synchronous observer pattern better suited for simple UI state propagation where low overhead and ease of implementation are prioritized.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'abc91778-4cb9-4f94-b64a-ff95289cb280', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'Why is it important to consider the ''Total Cost of Ownership'' when choosing a new library or tool?', N'Middle', N'Initial implementation speed is only one factor; I must also consider the maintenance burden, potential vendor lock-in, security patching frequency, and the cost of training the team. A tool that saves time now but requires extensive custom upkeep later may ultimately be more expensive for the organization.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'344465cc-d429-4a52-b850-ff95a219f209', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'What is CSRF protection in Laravel?', N'Intern', N'CSRF, or Cross-Site Request Forgery, protection is a security feature that prevents unauthorized commands from being executed on your application by a malicious website. Laravel automatically generates a CSRF token for each active user session, which must be verified for any state-changing requests like POST, PUT, or DELETE.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'459896cd-d3c8-4587-a2fa-ff95e2a6cb77', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'Explain the purpose of the settings.py file in a Django project.', N'Fresher', N'The settings.py file contains all the configuration for a Django project. This includes database connections, installed applications, middleware settings, security keys, and static file paths required for the project to run.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'358997de-2af1-4e42-b3b8-ff9631d4e26f', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'Discuss the strategy for implementing multi-tenancy in a Laravel application, specifically regarding data isolation.', N'Senior', N'Multi-tenancy can be implemented via column-based filtering (shared database) or separate database instances (isolated). Column-based approaches are easier to maintain but require strict middleware-enforced global scopes to prevent data leaks, whereas separate databases offer stronger security and easier schema migration per tenant at the cost of higher operational complexity.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5de26fc6-7e4f-4a80-a89c-ff9e633faeb0', N'd5b12859-0c9f-4e2f-9b3a-1ccb6c5080e5', N'What is the difference between synchronous and asynchronous replication?', N'Middle', N'Synchronous replication ensures data is written to all replicas before confirming success, providing strong consistency at the cost of higher latency. Asynchronous replication returns success immediately after writing to the primary, offering lower latency but risking data loss if a node fails before syncing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6eab006a-a4bc-4628-be73-ffa34b0f3c15', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'How does Qwik avoid the ''hydration tax'' found in frameworks like React?', N'Middle', N'Qwik avoids hydration by serializing the application state and the framework''s execution state directly into the HTML. By attaching event listeners globally via delegation, it delays the loading and execution of JavaScript until a user interaction occurs, effectively eliminating the need to hydrate the entire component tree upfront.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'946682fc-f408-4ba9-8a2b-ffa5f3d5b260', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'Describe the performance implications of using too many Alpine.js components on a single page.', N'Middle', N'Each Alpine component initializes its own reactivity system and observers, which can lead to memory overhead and performance degradation if overused. On a page with hundreds of active components, the browser may experience increased CPU usage due to the constant tracking of state changes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'65fa9181-8dd3-4dc2-bafd-ffaaba06b20e', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'What is the role of the entry point in Webpack?', N'Fresher', N'The entry point tells Webpack which module to use as the starting point to begin building its internal dependency graph. From this file, Webpack figures out which other modules and libraries the project depends on.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8117a30c-d865-4be0-8172-ffacd5ab9ded', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'Why might you use a centralized error handling pattern in Express?', N'Middle', N'Centralized error handling ensures that all errors across the application are logged, formatted, and responded to in a consistent manner. This simplifies maintenance and debugging, as you can manage global error logic, such as sending notifications to monitoring services, in one single place.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9a077253-184f-4067-99b7-ffadcfbdc2c1', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'Why is it necessary to implement a dedicated rate-limiting layer outside of Express in high-load scenarios?', N'Senior', N'Implementing rate limiting within Express consumes application resources to process rejected requests. Offloading this to a load balancer, WAF, or ingress controller prevents malicious or excessive traffic from even reaching the application layer, preserving server capacity.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'073e40d7-4347-47c4-92a5-ffb21a1b2cfc', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'What is the purpose of the request object in Flask?', N'Intern', N'The request object contains all the data sent by the client to the server. This includes form data, query string arguments, cookies, and HTTP headers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9f80c54d-cf60-481a-b5a9-ffb2851d5910', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'What is the difference between factory and abstract factory pattern?', N'Fresher', N'The Factory Method is usually categorised by a switch statement where each case returns a different class, using the same root interface so that the calling code never needs to make decisions about the implementation. Example: credit card validator factory which returns a different validator for each card type. Abstract Factory patterns work around a super-factory which creates other factories. This factory is also called as factory of factories. This type of design pattern comes under creational pattern as this pattern provides one of the best ways to create an object. In Abstract Factory pattern an interface is responsible for creating a factory of related objects without explicitly specifying their classes. Each generated factory can give the objects as per the Factory pattern.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f5a49d4b-8759-4575-8f0f-ffb2cdd417fe', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'Why is it important to use context.Context for managing long-running goroutines in a web server?', N'Senior', N'Context provides a standardized mechanism for propagation of cancellation signals and request-scoped deadlines across API boundaries. Without it, orphan goroutines may continue processing requests after the client has disconnected, leading to resource leaks and unnecessary load on downstream services.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c5134b5f-e862-4a4f-b66f-ffb30e37e993', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'How does Nuxt optimize images and assets for performance out of the box?', N'Senior', N'Nuxt provides the Nuxt Image module, which handles on-the-fly resizing, format conversion (e.g., WebP), and lazy loading. By leveraging providers like Vercel or Cloudinary, it ensures that assets are delivered in the most efficient format based on the user''s browser capabilities.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4f75a34d-ac0f-4527-9da2-ffb5089f46e8', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'What are Rails environments and why are they used?', N'Fresher', N'Rails environments, such as development, test, and production, allow the application to behave differently based on the stage of the software lifecycle. This ensures that configurations like database connections, logging, and error reporting are tailored specifically to the needs of developers or end-users.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'85089ce4-4050-4912-be2d-ffb50b74fed7', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'Discuss the trade-offs of using Alpine.js for complex state management compared to Redux or Pinia.', N'Senior', N'Alpine is optimized for local component state rather than global application-wide state. While global stores can be implemented via Alpine.store, it lacks the structured middleware, dev-tooling, and strict unidirectional data flow patterns that larger state management libraries provide for complex enterprise applications.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'982bf880-e98f-4463-9efc-ffb73a61bd79', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'What is the architectural utility of ''context functions'' introduced in later Scala versions?', N'Senior', N'Context functions simplify the syntax for passing implicit parameters, reducing the need for explicit boilerplate. They improve modularity by allowing the developer to define reusable functional logic that requires a specific environment context without explicitly threading that context through every method call.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'09cd8524-d8e0-4b55-859a-ffb7490bfb4b', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'How does Gin facilitate form data processing?', N'Intern', N'Gin provides built-in support for parsing multipart and form-encoded data. It allows developers to extract form fields and uploaded files directly from the request context.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'48b1c8e9-8ece-4c7c-b6fa-ffb979edd38b', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'How does Echo handle concurrent request processing, and what is the role of the underlying http.Server?', N'Senior', N'Echo relies on the standard library''s http.Server, which spawns a new goroutine for every incoming connection. This allows Echo to handle thousands of concurrent requests efficiently, provided the application logic within the handlers does not block the event loop or exceed system thread limits.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f63fb443-271a-4b49-b43c-ffbacc687108', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'What is the ''Outlet'' component used for?', N'Fresher', N'The Outlet component is used in parent route layouts to determine where the child route component should be rendered. It acts as a placeholder that gets filled in based on the current URL path.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'46fd1e3c-baed-41a3-940c-ffbad73a76d2', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'Why are String Refs legacy?', N'Fresher', N'If you worked with React before, you might be familiar with an older API where the ref attribute is a string, like ref={''textInput''}, and the DOM node is accessed as this.refs.textInput. We advise against it because _string refs have below issues_, and are considered legacy. String refs were removed in React v16. 1. They _force React to keep track of currently executing component_. This is problematic because it makes react module stateful, and thus causes weird errors when react module is duplicated in the bundle. 2. They are _not composable_ — if a library puts a ref on the passed child, the user can''t put another ref on it. Callback refs are perfectly composable. 3. They _don''t work with static analysis_ like Flow.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9d685ed6-3348-42e4-b0d4-ffbae38080af', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'Describe the role of Type Guards in TypeScript.', N'Middle', N'Type guards are expressions that perform a runtime check which guarantees the type in some scope. By using user-defined type predicates, you can help the compiler refine the type of a variable during conditional logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd013a65c-bdc5-493b-92ee-ffbb8ae82a1e', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'How would you implement rate limiting in Litestar efficiently?', N'Middle', N'Rate limiting is best implemented via middleware that tracks request counts in a distributed cache like Redis. By checking the request source against the cache before the handler executes, you can reject unauthorized traffic early in the request lifecycle.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'af583671-4c72-4b50-9101-ffbc29bf0c1c', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'What is an iterator in Ruby?', N'Intern', N'An iterator is a method that allows you to traverse a collection of objects, such as arrays or hashes. Iterators like ''each'' allow you to perform an action on every element in the collection sequentially.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8cb0735c-b5d8-45fb-97c4-ffc23d7c9b7f', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'Why would you create an index on a PostgreSQL table?', N'Junior', N'An index is created to speed up data retrieval operations by providing a faster way to look up specific rows. Without an index, the database must perform a sequential scan of the entire table, which is much slower for large datasets.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4f28f049-5897-441b-8fbc-ffc43db5991c', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'What is the purpose of @Inject?', N'Intern', N'The @Inject annotation is used to request a dependency from the Bean Context. It tells the framework to automatically provide the required object instance into the field, constructor, or method where it is placed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7f3619c9-e0e0-4f51-9f35-ffc4bbdc8ebc', N'954a0331-deff-4399-b588-96f39fec001d', N'What is lazy loading and how do you use it in Angular?', N'Fresher', N'Lazy loading in Angular is a technique used to load parts of your application code only when they are needed, typically when a user navigates to a specific route. Instead of loading the entire application bundle upfront, lazy loading splits the application into smaller bundles and loads them on demand. The primary benefit is significantly improving the application''s initial load time because the browser only downloads the code required for the initial view. You implement lazy loading in Angular primarily through the router configuration.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'306066aa-2cb2-4d42-807c-ffc7f3ad54d0', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'What is the ''Request'' object in Axum?', N'Fresher', N'The Request object represents an incoming HTTP request, containing metadata like headers, the method, and the URI. While users typically use extractors to access parts of this, the underlying request provides full access to the raw HTTP data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'97a97515-843c-404b-b6cf-ffce26997429', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'How would you implement a distributed lock in Laravel to prevent race conditions during concurrent processes?', N'Senior', N'You can use Laravel''s Cache lock mechanism, which leverages atomic operations provided by Redis or Memcached to ensure that only one process can execute a specific block of code at a time. This is critical for preventing issues like double-billing or duplicate records in high-concurrency environments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'996f45c4-d019-4679-91c4-ffcf20bb7773', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'How does Spring handle database transactions?', N'Junior', N'Spring provides the @Transactional annotation to manage database transactions declaratively. When applied to a method, it ensures that all database operations within that method either succeed as a unit or rollback if an error occurs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'604f763f-186e-4e83-984f-ffd07f1eb364', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'How do you destroy a session?', N'Fresher', N'A session can be destroyed by calling the session_destroy function, which deletes all data associated with the current session. It is often preceded by session_unset to clear all session variables first.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8d20e37a-7728-4a4c-a445-ffd1125a1720', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'Why would you use an ''Async Provider'' in a NestJS module?', N'Middle', N'Async providers are required when a service needs to wait for an asynchronous operation to complete, such as establishing a database connection or fetching configuration from a remote server, before being made available to the application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2ad8b003-3ab9-4698-bda2-ffd1c0659d13', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'What is the purpose of the ''return'' statement?', N'Intern', N'The return statement terminates the execution of a function and optionally passes a value back to the calling function. It is essential for signaling that a function has completed its specific task.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ba537039-bc44-4935-96c2-ffd47390054f', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'Explain the trade-off of using Litestar''s automatic data validation and serialization.', N'Middle', N'The trade-off is between developer velocity and performance overhead. While automatic validation using Pydantic or msgspec ensures data integrity and reduces manual checks, the runtime cost of schema validation can impact high-throughput systems compared to manually optimized parsing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'eac6f675-6d3d-4cf0-bc14-ffd6c1cc6394', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'Explain the role of the Nitro engine in a Nuxt 3 application.', N'Middle', N'Nitro is the server engine that powers Nuxt, responsible for handling server-side rendering, API routes, and deployment abstractions. It is designed to be platform-agnostic, allowing the same codebase to be deployed to various environments like Node.js, Vercel, or edge workers by automatically handling the necessary build-time transformations and environment-specific adapters.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f239522e-9ec9-46df-ace2-ffd6ead92654', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'What is the primary architectural difference between SvelteKit''s SSR and traditional SPA hydration?', N'Senior', N'In traditional SPAs, the browser downloads a minimal HTML shell and hydrates the entire application state on the client. SvelteKit''s SSR generates fully populated HTML on the server, which is then sent to the client, where it undergoes a process called hydration to attach event listeners and regain interactivity without re-rendering the initial markup.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0a19013e-2cef-461b-920b-ffd8cc0c8d87', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'What is the difference between a Job and a Queue in Laravel?', N'Junior', N'A Job represents a specific task that needs to be performed, such as sending an email or processing a file. A Queue provides a way to defer the execution of these time-consuming tasks to a background process, allowing the user to receive a response immediately without waiting for the task to finish.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5fc50090-9fe9-4d90-94d5-ffd9e63f5e72', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'Describe the trade-offs of Svelte''s lack of a Virtual DOM in terms of scalability for large-scale applications.', N'Senior', N'Without a virtual DOM, Svelte apps avoid the overhead of building and diffing trees, which is beneficial for performance. However, because it generates specialized code for each component, very large applications might face issues with larger bundle sizes compared to framework-as-a-service models that share a single runtime library.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'93556bd3-09b9-4bcc-b6df-ffe061366379', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'Explain the trade-offs of using semi-synchronous replication.', N'Senior', N'Semi-synchronous replication ensures that at least one replica has acknowledged receiving the transaction before the primary commits, reducing the window for data loss. However, it introduces latency to the primary''s commit operation, as the primary must wait for a network round-trip from the replica.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1908f4d3-7323-4806-8b25-ffe12d32cee1', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'Why is it recommended to make objects immutable in Java?', N'Middle', N'Immutable objects are inherently thread-safe because their state cannot be changed after construction, eliminating the need for synchronization. They are also easier to reason about, as they cannot enter inconsistent states, and are safe to share as keys in HashMaps. The trade-off is the memory overhead incurred by creating new objects for every state change.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a56405a0-ba9c-463d-83d4-ffe17d64fdab', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'How do ''Endpoint'' files in SvelteKit differ from ''Page'' files?', N'Middle', N'Endpoints are used to handle API requests that return raw data, such as JSON or images, rather than rendering a UI. Pages are intended to return HTML, while endpoints allow the application to act as its own backend API.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7e94af54-68c2-4596-8824-ffe2023e5fa6', N'210c7148-726e-4e8b-bf12-40be36e55130', N'What is the purpose of the interior mutability pattern, and how does it reconcile with Rust''s strict borrowing rules?', N'Senior', N'Interior mutability allows for mutation of data even when there are only immutable references to the container, by moving the borrow checking from compile-time to runtime. Patterns like Cell or RefCell achieve this, enabling complex data structures like graphs or doubly linked lists that would otherwise violate the standard aliasing XOR mutation rules.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c6279498-a854-4011-bcff-ffe5a1435406', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'What is the @use rule and why is it preferred over @import?', N'Intern', N'The @use rule is the modern way to load Sass modules and is preferred because it namespaces functions and variables. This prevents naming conflicts and makes it clear exactly where a piece of code originated, unlike @import which makes all variables global.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'edb9d72f-b504-4e0f-a09c-ffe686a3d95c', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'What is the difference between a Route and a Component?', N'Intern', N'A route handles data fetching and application state related to the URL, while a component focuses on UI rendering and user interaction. Components are generally more focused on presentation, whereas routes act as the controller for a view.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0ddf0422-5306-4c50-8547-ffe6d4dd1639', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'How do you determine the priority of tasks when everything seems urgent?', N'Fresher', N'I categorize tasks based on their impact on the final goal and their dependencies. I would focus on tasks that unblock the highest number of other activities or provide the most critical value, and then communicate with stakeholders to align on the sequence of execution.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9eba5efc-c6de-4cbd-9dbf-ffea214d3749', N'f2e963ff-7635-4429-a389-4d92535fb972', N'How does the ''defer'' attribute on a script tag affect the Document Object Model construction?', N'Senior', N'The defer attribute signals the browser to download the script in parallel without blocking HTML parsing. The script execution is deferred until the HTML document is fully parsed, ensuring that the DOM is ready and the script execution order is preserved.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'71eaa879-f432-4291-bc31-ffeba464c361', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'What is the role of the ''Global'' scope in NestJS?', N'Junior', N'A global module or filter is registered once and becomes available throughout the entire application. This avoids the need to manually import the component into every individual module.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'86c08104-0989-4818-8c9d-ffed46d6b81d', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'How does R''s memory management affect the scalability of large-scale data processing?', N'Senior', N'R historically relies on in-memory data structures, which imposes a hard limit based on total system RAM. Scaling requires offloading data to external databases or memory-mapped files, as the internal object headers and pointer overhead can consume significant memory compared to raw binary storage.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8bc22b51-e14a-4266-b61c-fff06cb9fa0c', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'How does Dart''s ''Future.microtask'' influence the scheduling of asynchronous work?', N'Senior', N'Microtasks are scheduled to run immediately after the current code execution finishes but before the event loop processes the next event. This mechanism allows developers to perform ''cleanup'' or ''deferred setup'' work that must occur before the system moves on to the next set of external events.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fb7ec8ff-7093-4523-af1e-fff1539f35aa', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'What happens if you use useLayoutEffect for non-layout logic?', N'Junior', N'Using useLayoutEffect for logic unrelated to layout or visual DOM changes (such as logging, data fetching, or analytics) is not recommended. It can lead to performance issues or even unexpected behavior. Example: Anti-pattern The above usage delays the paint of the UI just to send a network request, which could (and should) be done after paint using useEffect.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'aeaedde4-454f-4265-a1a4-fffafd97cfa9', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'What is a namespace and why is it useful?', N'Junior', N'A namespace is a declarative region that provides a scope for identifiers like variables, functions, and classes. It helps prevent name collisions in large projects by grouping related code under a unique prefix.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7739e1c2-279b-4afc-8a9c-fffd30ab646a', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'How does the Go compiler implement method sets for interfaces?', N'Senior', N'The compiler generates a method table (itab) for types that satisfy an interface. This table maps interface method signatures to the concrete method implementations of the underlying type, allowing the runtime to perform efficient dynamic dispatch.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
